provider "aws" {
  region = "us-east-1"
}

variable "base_name" {
  type        = string
  description = "Base name prefix for the CloudTrail S3 bucket"
  default     = "benchmark"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudTrailServiceEncryption"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"]
    }
  }
}

resource "aws_kms_key" "cloudtrail_key" {
  description             = "KMS key used to encrypt CloudTrail log files stored in S3"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  name          = "alias/${var.base_name}-cloudtrail-key"
  target_key_id = aws_kms_key.cloudtrail_key.key_id
}

resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = "${var.base_name}-cloudtrail-${data.aws_region.current.name}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_bucket_pab" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket_encryption" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket_policy" {
  statement {
    sid     = "AWSCloudTrailAclCheck"
    effect  = "Allow"
    actions = ["s3:GetBucketAcl"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    resources = [aws_s3_bucket.cloudtrail_bucket.arn]
  }

  statement {
    sid     = "AWSCloudTrailWrite"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    resources = ["${aws_s3_bucket.cloudtrail_bucket.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_bucket_policy" {
  bucket     = aws_s3_bucket.cloudtrail_bucket.id
  policy     = data.aws_iam_policy_document.cloudtrail_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_bucket_pab]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_name" {
  description = "The human-readable name of the application"
  type        = string
  default     = "Trilium Notes"
}

variable "app" {
  description = "Short application identifier"
  type        = string
  default     = "trilium"
}

variable "module" {
  description = "Module identifier"
  type        = string
  default     = "log"
}

variable "stage" {
  description = "Deployment environment or stage"
  type        = string
  default     = "production"
}

variable "log_retention" {
  description = "Specifies the number of days you want to retain log events in the specified log group"
  type        = number
  default     = 120
}

locals {
  base_prefix = "cwlg-${var.app}-${var.module}-${var.stage}"
  common_tags = {
    AppName = var.app_name
    App     = var.app
    Module  = var.module
    Stage   = var.stage
  }
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "${local.base_prefix}-app"
  retention_in_days = var.log_retention

  tags = merge(
    local.common_tags,
    {
      Name = "${local.base_prefix}-app"
    }
  )
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = "${local.base_prefix}-proxy"
  retention_in_days = var.log_retention

  tags = merge(
    local.common_tags,
    {
      Name = "${local.base_prefix}-proxy"
    }
  )
}

output "app_log_group_name" {
  description = "The name of the application CloudWatch log group"
  value       = aws_cloudwatch_log_group.app.name
}

output "app_log_group_arn" {
  description = "The ARN of the application CloudWatch log group"
  value       = aws_cloudwatch_log_group.app.arn
}

output "proxy_log_group_name" {
  description = "The name of the reverse proxy CloudWatch log group"
  value       = aws_cloudwatch_log_group.proxy.name
}

output "proxy_log_group_arn" {
  description = "The ARN of the reverse proxy CloudWatch log group"
  value       = aws_cloudwatch_log_group.proxy.arn
}

