provider "aws" {
  region = "us-east-1"
}

variable "key_prefix" {
  description = "Prefix for the AWS key pair name"
  type        = string
  default     = "key"
}

resource "random_pet" "key_suffix" {
  length    = 2
  separator = "-"
}

locals {
  key_name = "${var.key_prefix}-${random_pet.key_suffix.id}"
}

resource "tls_private_key" "ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "ssh_key_pair" {
  key_name   = local.key_name
  public_key = tls_private_key.ssh_key.public_key_openssh

  provisioner "local-exec" {
    command = <<-EOT
      cat <<'EOF' > "../${local.key_name}.pem"
${tls_private_key.ssh_key.private_key_pem}EOF
      chmod 600 "../${local.key_name}.pem"
    EOT
  }
}

output "key_pair_name" {
  description = "The name of the generated AWS key pair"
  value       = aws_key_pair.ssh_key_pair.key_name
}

output "key_pair_fingerprint" {
  description = "The fingerprint of the generated AWS key pair"
  value       = aws_key_pair.ssh_key_pair.fingerprint
}

