variable "tags" {
  type        = map(string)
  description = "A map of tags to assign to the resources"
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

resource "aws_ecr_repository" "illumidesk" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
  }

  tags = var.tags
}

resource "aws_ecr_lifecycle_policy" "illumidesk" {
  repository = aws_ecr_repository.illumidesk.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when the total image count exceeds 30"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

output "ecr_repository_arn" {
  description = "Full ARN of the ECR repository"
  value       = aws_ecr_repository.illumidesk.arn
}

output "ecr_repository_url" {
  description = "The URL of the ECR repository"
  value       = aws_ecr_repository.illumidesk.repository_url
}

output "ecr_repository_registry_id" {
  description = "The registry ID where the ECR repository was created"
  value       = aws_ecr_repository.illumidesk.registry_id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for deployment and stored credentials"
  default     = "us-east-1"
}

variable "secret_name" {
  type        = string
  description = "Name of the AWS Secrets Manager secret storing Cognito credentials"
  default     = "lambda-auth-credentials"
}

variable "default_username" {
  type        = string
  description = "Default username for Lambda authentication"
  default     = "techlanches"
}

variable "default_email" {
  type        = string
  description = "Default email address for the initial administrative account"
  default     = "g12.4soat.fiap@outlook.com"
}

variable "default_password" {
  type        = string
  description = "Default password for the initial administrative account"
  default     = "Test1234@"
  sensitive   = true
}

resource "aws_cognito_user_pool" "tech_lanches_clientes_pool" {
  name                     = "tech-lanches-clientes-pool"
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]
  alias_attributes         = ["email", "preferred_username"]

  username_configuration {
    case_sensitive = false
  }

  tags = {
    Name = "tech_lanches_clientes_pool"
  }
}

resource "aws_cognito_user_pool_client" "pool_client" {
  name         = "pool-client"
  user_pool_id = aws_cognito_user_pool.tech_lanches_clientes_pool.id

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH"
  ]
}

resource "aws_secretsmanager_secret" "lambda_auth_credentials" {
  name                    = var.secret_name
  recovery_window_in_days = 0

  tags = {
    Name = var.secret_name
  }
}

resource "aws_secretsmanager_secret_version" "lambda_auth_credentials" {
  secret_id = aws_secretsmanager_secret.lambda_auth_credentials.id
  secret_string = jsonencode({
    region              = var.aws_region
    user_pool_id        = aws_cognito_user_pool.tech_lanches_clientes_pool.id
    user_pool_client_id = aws_cognito_user_pool_client.pool_client.id
    username            = var.default_username
    email               = var.default_email
    password            = var.default_password
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for infrastructure deployment"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count             = length(var.subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "main-subnet-${count.index + 1}"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_api_gateway_rest_api" "hello_world_api" {
  name        = "HelloWorldAPI"
  description = "API Gateway for Hello World Lambda"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "hello" {
  rest_api_id = aws_api_gateway_rest_api.hello_world_api.id
  parent_id   = aws_api_gateway_rest_api.hello_world_api.root_resource_id
  path_part   = "hello"
}

resource "aws_api_gateway_method" "hello_any" {
  rest_api_id   = aws_api_gateway_rest_api.hello_world_api.id
  resource_id   = aws_api_gateway_resource.hello.id
  http_method   = "ANY"
  authorization = "NONE"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  environment               = "production"
  delay_seconds             = 90
  max_message_size          = 2048
  message_retention_seconds = 86400
  receive_wait_time_seconds = 10
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSQSServiceUsage"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "sqs_key" {
  description             = "Customer managed KMS key for SQS test queues"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Environment = local.environment
  }
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/sqs-test-encryption-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

resource "aws_sqs_queue" "test_sqs" {
  name                              = "test-sqs"
  delay_seconds                     = local.delay_seconds
  max_message_size                  = local.max_message_size
  message_retention_seconds         = local.message_retention_seconds
  receive_wait_time_seconds         = local.receive_wait_time_seconds
  kms_master_key_id                 = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = local.environment
  }
}

resource "aws_sqs_queue" "test_sqs1" {
  name                              = "test-sqs1"
  delay_seconds                     = local.delay_seconds
  max_message_size                  = local.max_message_size
  message_retention_seconds         = local.message_retention_seconds
  receive_wait_time_seconds         = local.receive_wait_time_seconds
  kms_master_key_id                 = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = local.environment
  }
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for SQS encryption"
  value       = aws_kms_key.sqs_key.arn
}

output "kms_key_alias_arn" {
  description = "ARN of the KMS key alias"
  value       = aws_kms_alias.sqs_key_alias.arn
}

output "test_sqs_url" {
  description = "URL of the test-sqs queue"
  value       = aws_sqs_queue.test_sqs.url
}

output "test_sqs_arn" {
  description = "ARN of the test-sqs queue"
  value       = aws_sqs_queue.test_sqs.arn
}

output "test_sqs1_url" {
  description = "URL of the test-sqs1 queue"
  value       = aws_sqs_queue.test_sqs1.url
}

output "test_sqs1_arn" {
  description = "ARN of the test-sqs1 queue"
  value       = aws_sqs_queue.test_sqs1.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "random" {}

variable "base_bucket_name" {
  type        = string
  description = "Base name for the S3 bucket"
  default     = "doc-io-files"
}

variable "force_destroy" {
  type        = bool
  description = "Controls whether to force destroy the bucket even if it contains objects"
  default     = true
}

variable "allowed_account_id" {
  type        = string
  description = "AWS Account ID granted full access to the bucket and its objects"
  default     = "566373416292"
}

data "aws_caller_identity" "current" {}

resource "random_integer" "bucket_prefix" {
  min = 1
  max = 50000
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAllowedAccountUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.allowed_account_id}:root"]
    }
  }
}

resource "aws_kms_key" "doc_io_bucket_key" {
  description             = "Customer-managed KMS key for document I/O S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "doc_io_bucket_key_alias" {
  name          = "alias/doc-io-files-key"
  target_key_id = aws_kms_key.doc_io_bucket_key.key_id
}

resource "aws_s3_bucket" "doc_io_bucket" {
  bucket        = "${random_integer.bucket_prefix.result}-${var.base_bucket_name}"
  force_destroy = var.force_destroy
}

resource "aws_s3_bucket_versioning" "doc_io_bucket_versioning" {
  bucket = aws_s3_bucket.doc_io_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_bucket_encryption" {
  bucket = aws_s3_bucket.doc_io_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.doc_io_bucket_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "doc_io_bucket_public_access_block" {
  bucket = aws_s3_bucket.doc_io_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "doc_io_bucket_access" {
  statement {
    sid    = "AllowAccountFullS3Access"
    effect = "Allow"
    actions = [
      "s3:*"
    ]
    resources = [
      aws_s3_bucket.doc_io_bucket.arn,
      "${aws_s3_bucket.doc_io_bucket.arn}/*"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.allowed_account_id}:root"]
    }
  }
}

resource "aws_s3_bucket_policy" "doc_io_bucket_policy" {
  bucket     = aws_s3_bucket.doc_io_bucket.id
  policy     = data.aws_iam_policy_document.doc_io_bucket_access.json
  depends_on = [aws_s3_bucket_public_access_block.doc_io_bucket_public_access_block]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "terraform-remote-state"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_kms_key" "state_key" {
  description             = "KMS key used to encrypt Terraform remote state S3 bucket and DynamoDB lock table"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "${local.name_prefix}-kms-key"
  }
}

resource "aws_kms_alias" "state_key_alias" {
  name          = "alias/${local.name_prefix}-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.state_key.key_id
}

resource "aws_s3_bucket" "state_bucket" {
  bucket        = "${local.name_prefix}-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-bucket"
  }
}

resource "aws_s3_bucket_versioning" "state_versioning" {
  bucket = aws_s3_bucket.state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_encryption" {
  bucket = aws_s3_bucket.state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state_public_access_block" {
  bucket = aws_s3_bucket.state_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "state_bucket_ssl_only" {
  bucket = aws_s3_bucket.state_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state_bucket.arn,
          "${aws_s3_bucket.state_bucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_dynamodb_table" "state_locks" {
  name         = "${local.name_prefix}-locks-${random_id.suffix.hex}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state_key.arn
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-locks-table"
  }
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket used for Terraform remote state"
  value       = aws_s3_bucket.state_bucket.id
}

output "s3_bucket_arn" {
  description = "ARN of the S3 bucket used for Terraform remote state"
  value       = aws_s3_bucket.state_bucket.arn
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking"
  value       = aws_dynamodb_table.state_locks.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table used for Terraform state locking"
  value       = aws_dynamodb_table.state_locks.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS Key used to encrypt Terraform remote state resources"
  value       = aws_kms_key.state_key.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowEventBridgeToGenerateDataKeyAndDecrypt"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "incident_response" {
  description             = "KMS Key for incident-response SNS topic server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "incident-response-kms-key"
  }
}

resource "aws_kms_alias" "incident_response" {
  name          = "alias/incident-response-key"
  target_key_id = aws_kms_key.incident_response.key_id
}

resource "aws_sns_topic" "incident_response" {
  name              = "incident-response"
  kms_master_key_id = aws_kms_key.incident_response.arn

  tags = {
    Name = "incident-response"
  }
}

data "aws_iam_policy_document" "sns_topic_policy" {
  policy_id = "__default_policy_ID"

  statement {
    sid    = "__default_statement_ID"
    effect = "Allow"

    actions = [
      "sns:Subscribe",
      "sns:SetTopicAttributes",
      "sns:RemovePermission",
      "sns:Receive",
      "sns:Publish",
      "sns:ListSubscriptionsByTopic",
      "sns:GetTopicAttributes",
      "sns:DeleteTopic",
      "sns:AddPermission"
    ]

    resources = [aws_sns_topic.incident_response.arn]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAWSEvents"
    effect = "Allow"

    actions = [
      "sns:Publish"
    ]

    resources = [aws_sns_topic.incident_response.arn]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "incident_response" {
  arn    = aws_sns_topic.incident_response.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_iam_service_linked_role" "opensearch" {
  aws_service_name = "es.amazonaws.com"
  description      = "Service-linked role for Amazon OpenSearch Service"
}

data "aws_iam_policy_document" "elasticsearch_log_publishing" {
  statement {
    sid    = "ElasticsearchLogPublishing"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["es.amazonaws.com"]
    }

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutLogEventsBatch",
    ]

    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"
    ]
  }
}

resource "aws_cloudwatch_log_resource_policy" "elasticsearch_log_publishing_policy" {
  policy_name     = "elasticsearch-log-publishing-policy"
  policy_document = data.aws_iam_policy_document.elasticsearch_log_publishing.json
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "identity_pool" {
  name = "identity pool"
}

data "aws_iam_policy_document" "user_group_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = ["us-east-1:12345678-dead-beef-cafe-123456790ab"]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

