terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "api_name" {
  type        = string
  description = "The name of the API Gateway REST API"
  default     = "terraform-api-gateway-example"
}

resource "aws_api_gateway_rest_api" "movies_api" {
  name        = var.api_name
  description = "API Gateway REST API for testing mock web endpoint responses"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "movies" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  parent_id   = aws_api_gateway_rest_api.movies_api.root_resource_id
  path_part   = "movies"
}

resource "aws_api_gateway_method" "get_movies" {
  rest_api_id   = aws_api_gateway_rest_api.movies_api.id
  resource_id   = aws_api_gateway_resource.movies.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "get_movies_mock" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.get_movies.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_api_gateway_method_response" "get_movies_200" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.get_movies.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_movies_mock_200" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.get_movies.http_method
  status_code = aws_api_gateway_method_response.get_movies_200.status_code

  response_templates = {
    "application/json" = jsonencode({
      message = "Hello from the movies API!"
    })
  }

  depends_on = [
    aws_api_gateway_integration.get_movies_mock
  ]
}

resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.movies.id,
      aws_api_gateway_method.get_movies.id,
      aws_api_gateway_integration.get_movies_mock.id,
      aws_api_gateway_method_response.get_movies_200.id,
      aws_api_gateway_integration_response.get_movies_mock_200.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration_response.get_movies_mock_200
  ]
}

resource "aws_api_gateway_stage" "prod" {
  deployment_id = aws_api_gateway_deployment.deployment.id
  rest_api_id   = aws_api_gateway_rest_api.movies_api.id
  stage_name    = "prod"
}

output "endpoint_url" {
  description = "URL to invoke the mock movies endpoint"
  value       = "${aws_api_gateway_stage.prod.invoke_url}/${aws_api_gateway_resource.movies.path_part}"
}

