      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "target_regions" {
  description = "List of AWS regions permitted for network interface operations in the IAM policy"
  type        = list(string)
  default     = ["*"]
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "powerscale_node_runtime_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "powerscale_node_runtime_policy" {
  statement {
    sid    = "AssignPrivateIpAddressesToEni"
    effect = "Allow"
    actions = [
      "ec2:AssignPrivateIpAddresses"
    ]
    resources = [
      for region in var.target_regions : "arn:aws:ec2:${region}:${data.aws_caller_identity.current.account_id}:network-interface/*"
    ]
  }
}

resource "aws_iam_policy" "powerscale_node_runtime_policy" {
  name        = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-policy"
  description = "IAM policy for PowerScale node runtime operations"
  policy      = data.aws_iam_policy_document.powerscale_node_runtime_policy.json
}

resource "aws_iam_role" "powerscale_node_runtime_role" {
  name               = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-role"
  description        = "IAM role for PowerScale node runtime EC2 instances"
  assume_role_policy = data.aws_iam_policy_document.powerscale_node_runtime_assume_role.json
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime_attach" {
  role       = aws_iam_role.powerscale_node_runtime_role.name
  policy_arn = aws_iam_policy.powerscale_node_runtime_policy.arn
}

resource "aws_iam_instance_profile" "powerscale_node_runtime_instance_profile" {
  name = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime_role.name
}

