}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  user_name  = "TJ"
}

resource "aws_iam_user" "tj" {
  name = local.user_name
  path = "/"

  tags = {
    Name        = local.user_name
    Environment = "Management"
    ManagedBy   = "Terraform"
  }
}

data "aws_iam_policy_document" "glacier_efs_ec2" {
  # Read-only EC2 actions that do not support resource-level permissions
  statement {
    sid    = "EC2DescribeRead"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeImages",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeVolumes",
      "ec2:DescribeTags"
    ]
    resources = ["*"]
  }

  # EC2 instance lifecycle actions scoped to instances within the account
  statement {
    sid    = "EC2InstanceManagement"
    effect = "Allow"
    actions = [
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:RebootInstances"
    ]
    resources = [
      "arn:aws:ec2:${local.region}:${local.account_id}:instance/*"
    ]
  }

  # EC2 RunInstances permissions scoped across required resources
  statement {
    sid    = "EC2RunInstancesScoped"
    effect = "Allow"
    actions = [
      "ec2:RunInstances"
    ]
    resources = [
      "arn:aws:ec2:${local.region}:${local.account_id}:instance/*",
      "arn:aws:ec2:${local.region}:${local.account_id}:volume/*",
      "arn:aws:ec2:${local.region}:${local.account_id}:security-group/*",
      "arn:aws:ec2:${local.region}:${local.account_id}:network-interface/*",
      "arn:aws:ec2:${local.region}:${local.account_id}:subnet/*",
      "arn:aws:ec2:${local.region}::image/*",
      "arn:aws:ec2:${local.region}:${local.account_id}:key-pair/*"
    ]
  }

  # EFS discovery actions that do not support resource-level permissions
  statement {
    sid    = "EFSDescribeActions"
    effect = "Allow"
    actions = [
      "elasticfilesystem:DescribeMountTargets",
      "elasticfilesystem:DescribeFileSystems"
    ]
    resources = ["*"]
  }

  # EFS client mount and write operations scoped to file system resources
  statement {
    sid    = "EFSClientMountWrite"
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite"
    ]
    resources = [
      "arn:aws:elasticfilesystem:${local.region}:${local.account_id}:file-system/*"
    ]
  }

  # Glacier account-level read/list actions
  statement {
    sid    = "GlacierListVaults"
    effect = "Allow"
    actions = [
      "glacier:ListVaults"
    ]
    resources = [
      "arn:aws:glacier:${local.region}:${local.account_id}:vaults/"
    ]
  }

  # Glacier vault management and multipart upload actions scoped to vaults
  statement {
    sid    = "GlacierVaultAndMultipartUpload"
    effect = "Allow"
    actions = [
      "glacier:DescribeVault",
      "glacier:InitiateMultipartUpload",
      "glacier:UploadMultipartPart",
      "glacier:CompleteMultipartUpload",
      "glacier:AbortMultipartUpload",
      "glacier:ListMultipartUploads",
      "glacier:ListParts"
    ]
    resources = [
      "arn:aws:glacier:${local.region}:${local.account_id}:vaults/*"
    ]
  }
}

resource "aws_iam_policy" "glacier_efs_ec2" {
  name        = "GlacierEFSEC2"
  path        = "/"
  description = "IAM policy providing EC2 management, EFS client-mount access, and Glacier vault/multipart-upload permissions"
  policy      = data.aws_iam_policy_document.glacier_efs_ec2.json

  tags = {
    Name        = "GlacierEFSEC2"
    Environment = "Management"
    ManagedBy   = "Terraform"
  }
}

resource "aws_iam_user_policy_attachment" "tj_glacier_efs_ec2" {
  user       = aws_iam_user.tj.name
  policy_arn = aws_iam_policy.glacier_efs_ec2.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  description = "The name of the IAM role. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null
}

variable "role_name_prefix" {
  description = "Creates a unique friendly name beginning with the specified prefix. Conflicts with role_name."
  type        = string
  default     = "ec2-instance-role-"
}

variable "role_path" {
  description = "Path to the IAM role and instance profile."
  type        = string
  default     = "/"
}

variable "role_description" {
  description = "Description of the IAM role."
  type        = string
  default     = "IAM role for EC2 instances with partition-aware trust policy."
}

variable "managed_policy_arns" {
  description = "List of IAM managed policy ARNs to attach to the role."
  type        = list(string)
  default     = []
}

variable "inline_policies" {
  description = "Map of inline policy names to policy JSON documents to attach to the role."
  type        = map(string)
  default     = {}
}

variable "tags" {
  description = "A map of tags to assign to the IAM role and instance profile."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "this" {
  name               = var.role_name
  name_prefix        = var.role_name != null ? null : var.role_name_prefix
  path               = var.role_path
  description        = var.role_description
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "this" {
  name        = var.role_name
  name_prefix = var.role_name != null ? null : var.role_name_prefix
  role        = aws_iam_role.this.name
  path        = var.role_path
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.this.name
  policy_arn = each.value
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.this.name
  policy = each.value
}

output "iam_role_arn" {
  description = "ARN of the provisioned IAM role."
  value       = aws_iam_role.this.arn
}

output "iam_role_name" {
  description = "Name of the provisioned IAM role."
  value       = aws_iam_role.this.name
}

output "iam_instance_profile_arn" {
  description = "ARN of the provisioned IAM instance profile."
  value       = aws_iam_instance_profile.this.arn
}

output "iam_instance_profile_name" {
  description = "Name of the provisioned IAM instance profile."
  value       = aws_iam_instance_profile.this.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
