terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "trusted_monitoring_account_ids" {
  type        = list(string)
  description = "List of AWS account IDs permitted to assume the IAM role for Grafana workspace data sources."
  default     = []
}

variable "workspace_name" {
  type        = string
  description = "Target AWS Managed Grafana workspace name."
  default     = "Grafana"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = lower(replace(var.workspace_name, " ", "-"))
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
  partition   = data.aws_partition.current.partition

  effective_monitoring_account_ids = length(var.trusted_monitoring_account_ids) > 0 ? var.trusted_monitoring_account_ids : [local.account_id]

  trusted_principal_arns = [
    for id in local.effective_monitoring_account_ids :
    "arn:${local.partition}:iam::${id}:root"
  ]
}

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    sid     = "GrafanaAccountAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = local.trusted_principal_arns
    }

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "grafana_data_source_role" {
  name        = "${local.name_prefix}-workspace-datasource-role"
  description = "IAM role allowing AWS Managed Grafana workspace ${var.workspace_name} to query AMP and CloudWatch metrics"

  assume_role_policy = data.aws_iam_policy_document.grafana_assume_role.json

  tags = {
    Workspace = var.workspace_name
    ManagedBy = "Terraform"
  }
}

data "aws_iam_policy_document" "grafana_metrics_query" {
  statement {
    sid    = "AllowAmazonManagedPrometheusQueries"
    effect = "Allow"
    actions = [
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata"
    ]
    resources = [
      "arn:${local.partition}:aps:${local.region}:${local.account_id}:workspace/*"
    ]
  }

  statement {
    sid    = "AllowCloudWatchMetricQueries"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarmsForMetric",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsForGrafana"
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
      "logs:GetLogGroupFields",
      "logs:StartQuery",
      "logs:StopQuery",
      "logs:GetQueryResults",
      "logs:GetLogEvents"
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
    ]
  }

  statement {
    sid    = "AllowTagResourceDiscovery"
    effect = "Allow"
    actions = [
      "tag:GetResources",
      "tag:GetTagKeys",
      "tag:GetTagValues"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_metrics_query_policy" {
  name        = "${local.name_prefix}-metrics-query-policy"
  description = "Provides least-privilege permissions for Grafana to query CloudWatch and Amazon Managed Service for Prometheus metrics"
  policy      = data.aws_iam_policy_document.grafana_metrics_query.json

  tags = {
    Workspace = var.workspace_name
    ManagedBy = "Terraform"
  }
}

resource "aws_iam_role_policy_attachment" "grafana_metrics_query_attachment" {
  role       = aws_iam_role.grafana_data_source_role.name
  policy_arn = aws_iam_policy.grafana_metrics_query_policy.arn
}

output "grafana_data_source_role_arn" {
  description = "ARN of the IAM role assumed by AWS Managed Grafana to access metrics data sources"
  value       = aws_iam_role.grafana_data_source_role.arn
}

