}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_name = "trade-tariff-development-vpc"
  vpc_cidr = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-public-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-public-2"
  }
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-private-1"
  }
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-private-2"
  }
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${local.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_1.id

  tags = {
    Name = "${local.vpc_name}-nat-gw"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH and outbound traffic only within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic strictly restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow-ssh"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "repository_name" {
  type        = string
  description = "Name of the Amazon ECR repository"
  default     = "app-container-repo"
}

variable "image_tag_mutability" {
  type        = string
  description = "The tag mutability setting for the repository (MUTABLE or IMMUTABLE)"
  default     = "IMMUTABLE"
}

variable "scan_on_push" {
  type        = bool
  description = "Indicates whether images are scanned after being pushed to the repository"
  default     = true
}

variable "use_kms_encryption" {
  type        = bool
  description = "Whether to use customer-managed KMS encryption instead of default AES256"
  default     = false
}

variable "kms_key_arn" {
  type        = string
  description = "Existing KMS key ARN to use for encryption. If null and use_kms_encryption is true, a new key is created"
  default     = null
}

variable "pull_principals" {
  type        = list(string)
  description = "List of AWS Principal ARNs granted read-only pull access to the repository"
  default     = []
}

variable "enable_lifecycle_policy" {
  type        = bool
  description = "Whether to attach an image lifecycle management policy"
  default     = false
}

variable "untagged_image_retention_days" {
  type        = number
  description = "Number of days to retain untagged images before deletion"
  default     = 14
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  create_kms_key = var.use_kms_encryption && var.kms_key_arn == null
  kms_key_arn    = var.use_kms_encryption ? (var.kms_key_arn != null ? var.kms_key_arn : aws_kms_key.ecr[0].arn) : null
}

data "aws_iam_policy_document" "kms_key_policy" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowECRServiceAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["ecr.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "ecr" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Customer-managed KMS key for ECR repository ${var.repository_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = {
    Name = "${var.repository_name}-kms-key"
  }
}

resource "aws_kms_alias" "ecr" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/ecr/${var.repository_name}"
  target_key_id = aws_kms_key.ecr[0].key_id
}

resource "aws_ecr_repository" "main" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = var.use_kms_encryption ? "KMS" : "AES256"
    kms_key         = local.kms_key_arn
  }

  tags = {
    Name = var.repository_name
  }
}

data "aws_iam_policy_document" "pull_access" {
  count = length(var.pull_principals) > 0 ? 1 : 0

  statement {
    sid    = "AllowPullAccess"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]

    principals {
      type        = "AWS"
      identifiers = var.pull_principals
    }
  }
}

resource "aws_ecr_repository_policy" "main" {
  count      = length(var.pull_principals) > 0 ? 1 : 0
  repository = aws_ecr_repository.main.name
  policy     = data.aws_iam_policy_document.pull_access[0].json
}

resource "aws_ecr_lifecycle_policy" "main" {
  count      = var.enable_lifecycle_policy ? 1 : 0
  repository = aws_ecr_repository.main.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than ${var.untagged_image_retention_days} days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = var.untagged_image_retention_days
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

output "repository_arn" {
  description = "The ARN of the ECR repository"
  value       = aws_ecr_repository.main.arn
}

output "repository_url" {
  description = "The URL of the ECR repository"
  value       = aws_ecr_repository.main.repository_url
}

output "repository_registry_id" {
  description = "The registry ID where the ECR repository was created"
  value       = aws_ecr_repository.main.registry_id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "environment" {
  type        = string
  description = "Deployment environment name (e.g., prod, staging, dev)."
  default     = "prod"
}

variable "queue_base_name" {
  type        = string
  description = "Base name for the SQS queue."
  default     = "app-event-pipeline"
}

variable "is_fifo_queue" {
  type        = bool
  description = "Whether to create a FIFO queue. If true, the queue name will end in .fifo."
  default     = false
}

variable "content_based_deduplication" {
  type        = bool
  description = "Enables content-based deduplication for FIFO queues."
  default     = false
}

variable "sender_principal_arn" {
  type        = string
  description = "Optional ARN of an AWS principal permitted to send messages to the queue."
  default     = ""
}

variable "visibility_timeout_seconds" {
  type        = number
  description = "The visibility timeout for the queue in seconds."
  default     = 30
}

variable "message_retention_seconds" {
  type        = number
  description = "The number of seconds Amazon SQS retains a message."
  default     = 345600 # 4 days
}

variable "extra_tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources."
  default     = {}
}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  name_prefix = "${var.environment}-${var.queue_base_name}"
  queue_name  = var.is_fifo_queue ? "${local.name_prefix}.fifo" : local.name_prefix

  standard_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "Terraform"
      Service     = "SQS"
    },
    var.extra_tags
  )
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key for Queue Encryption
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootAccountFullAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  dynamic "statement" {
    for_each = var.sender_principal_arn != "" ? [var.sender_principal_arn] : []
    content {
      sid    = "AllowSenderPrincipalKmsUsage"
      effect = "Allow"
      actions = [
        "kms:GenerateDataKey",
        "kms:Decrypt"
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }
    }
  }
}

resource "aws_kms_key" "sqs_key" {
  description             = "KMS CMK for SQS queue ${local.queue_name} encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = merge(
    local.standard_tags,
    {
      Name = "${local.name_prefix}-sqs-key"
    }
  )
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/${local.name_prefix}-sqs"
  target_key_id = aws_kms_key.sqs_key.key_id
}

# -----------------------------------------------------------------------------
# Amazon SQS Queue
# -----------------------------------------------------------------------------
resource "aws_sqs_queue" "queue" {
  name                        = local.queue_name
  fifo_queue                  = var.is_fifo_queue
  content_based_deduplication = var.is_fifo_queue ? var.content_based_deduplication : null

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds

  kms_master_key_id                 = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(
    local.standard_tags,
    {
      Name = local.queue_name
    }
  )
}

# -----------------------------------------------------------------------------
# SQS Queue Access Policy (Conditional)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "queue_policy_doc" {
  count = var.sender_principal_arn != "" ? 1 : 0

  statement {
    sid       = "AllowSenderPrincipalSendMessage"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.queue.arn]

    principals {
      type        = "AWS"
      identifiers = [var.sender_principal_arn]
    }
  }

  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.queue.arn]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_sqs_queue_policy" "queue_policy" {
  count     = var.sender_principal_arn != "" ? 1 : 0
  queue_url = aws_sqs_queue.queue.id
  policy    = data.aws_iam_policy_document.queue_policy_doc[0].json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "queue_id" {
  description = "The URL for the created Amazon SQS queue (matches queue_url)."
  value       = aws_sqs_queue.queue.id
}

output "queue_arn" {
  description = "The ARN of the Amazon SQS queue."
  value       = aws_sqs_queue.queue.arn
}

output "queue_url" {
  description = "The URL of the Amazon SQS queue."
  value       = aws_sqs_queue.queue.url
}

output "queue_name" {
  description = "The computed name of the Amazon SQS queue."
  value       = aws_sqs_queue.queue.name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for queue encryption."
  value       = aws_kms_key.sqs_key.arn
}

output "kms_key_alias" {
  description = "The alias of the KMS key used for queue encryption."
  value       = aws_kms_alias.sqs_key_alias.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region for resource provisioning."
  type        = string
  default     = "us-east-1"
}

variable "create_cluster" {
  description = "Controls whether the primary Aurora DSQL cluster should be created."
  type        = bool
  default     = true
}

variable "deletion_protection_enabled" {
  description = "Indicates whether deletion protection is enabled for the Aurora DSQL cluster."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key to encrypt the DSQL cluster. If not specified and manage_kms_key is true, a new key is created."
  type        = string
  default     = null
}

variable "manage_kms_key" {
  description = "Controls whether to create a customer managed KMS key for Aurora DSQL cluster encryption."
  type        = bool
  default     = true
}

variable "kms_key_deletion_window_in_days" {
  description = "The waiting period, specified in number of days, before KMS key deletion."
  type        = number
  default     = 30
}

variable "enable_peering" {
  description = "Whether to create peering relationships for the Aurora DSQL cluster."
  type        = bool
  default     = false
}

variable "peer_clusters" {
  description = "List of target peer cluster identifiers or ARNs to peer with."
  type        = list(string)
  default     = []
}

variable "peering_witness_region" {
  description = "Witness region required for cluster peering."
  type        = string
  default     = "us-east-1"
}

variable "peering_create_timeout" {
  description = "Timeout string for the creation of cluster peering connections (e.g., '30m', '1h')."
  type        = string
  default     = "30m"
}

variable "tags" {
  description = "A mapping of tags to assign to all resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
    Service     = "aurora-dsql"
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  create_kms_key = var.create_cluster && var.manage_kms_key && var.kms_key_arn == null
  kms_key_arn    = local.create_kms_key ? aws_kms_key.dsql[0].arn : var.kms_key_arn

  should_create_peering = var.create_cluster && var.enable_peering && length(var.peer_clusters) > 0 && var.peering_witness_region != null
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_key_policy" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowDSQLServiceEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:RetireGrant",
      "kms:RevokeGrant"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["dsql.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "dsql" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Customer managed KMS key for Aurora DSQL cluster encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = merge(
    var.tags,
    {
      Name = "aurora-dsql-kms-key"
    }
  )
}

resource "aws_kms_alias" "dsql" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/aurora-dsql"
  target_key_id = aws_kms_key.dsql[0].key_id
}

# -----------------------------------------------------------------------------
# Aurora DSQL Cluster
# -----------------------------------------------------------------------------

resource "aws_dsql_cluster" "primary" {
  count                       = var.create_cluster ? 1 : 0
  kms_encryption_key          = local.kms_key_arn != null ? local.kms_key_arn : "AWS_OWNED_KMS_KEY"
  deletion_protection_enabled = var.deletion_protection_enabled

  tags = merge(
    var.tags,
    {
      Name = "aurora-dsql-cluster-primary"
    }
  )
}

# -----------------------------------------------------------------------------
# Aurora DSQL Cluster Peering
# -----------------------------------------------------------------------------

resource "aws_dsql_cluster_peering" "peering" {
  count          = local.should_create_peering ? 1 : 0
  identifier     = aws_dsql_cluster.primary[0].identifier
  clusters       = toset(var.peer_clusters)
  witness_region = var.peering_witness_region

  timeouts {
    create = var.peering_create_timeout
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cluster_id" {
  description = "The identifier of the primary Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.primary[0].identifier, null)
}

output "cluster_arn" {
  description = "The ARN of the primary Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.primary[0].arn, null)
}

output "kms_key_arn" {
  description = "The ARN of the KMS key utilized for Aurora DSQL cluster encryption."
  value       = local.kms_key_arn
}

output "peering_connections" {
  description = "Details of the cluster peering relationship if enabled."
  value = local.should_create_peering ? {
    identifier     = aws_dsql_cluster_peering.peering[0].identifier
    clusters       = aws_dsql_cluster_peering.peering[0].clusters
    witness_region = aws_dsql_cluster_peering.peering[0].witness_region
  } : null
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Input Variables
# ------------------------------------------------------------------------------

variable "bucket_name" {
  type        = string
  description = "The name of the S3 bucket. If omitted or null, Terraform assigns a unique name."
  default     = null
}

variable "object_lock_enabled" {
  type        = bool
  description = "Indicates whether this bucket has an Object Lock configuration enabled."
  default     = false
}

variable "force_destroy" {
  type        = bool
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  default     = false
}

variable "tags" {
  type        = map(string)
  description = "A map of tags to assign to the bucket and related resources."
  default     = {}
}

variable "custom_bucket_policies" {
  type = object({
    policy_id = optional(string, "CustomBucketPolicy")
    version   = optional(string, "2012-10-17")
    statements = list(object({
      sid       = optional(string)
      effect    = optional(string, "Allow")
      actions   = list(string)
      resources = optional(list(string))
      principals = optional(list(object({
        type        = string
        identifiers = list(string)
      })), [])
    }))
  })
  description = "Custom S3 bucket policy configuration containing statements and principals."
  default     = null
}

# ------------------------------------------------------------------------------
# KMS Key for Bucket Encryption
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "storage_key" {
  description             = "Customer Managed Key for S3 storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = var.tags
}

resource "aws_kms_alias" "storage_key_alias" {
  name_prefix   = "alias/s3-storage-"
  target_key_id = aws_kms_key.storage_key.key_id
}

# ------------------------------------------------------------------------------
# S3 Storage Bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "storage_bucket" {
  bucket              = var.bucket_name
  object_lock_enabled = var.object_lock_enabled
  force_destroy       = var.force_destroy
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "storage_bucket" {
  bucket = aws_s3_bucket.storage_bucket.id

  versioning_configuration {
    status = var.object_lock_enabled ? "Enabled" : "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "storage_bucket" {
  bucket = aws_s3_bucket.storage_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.storage_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "storage_bucket" {
  bucket = aws_s3_bucket.storage_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# S3 Bucket Policy (Conditional)
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "custom_policy" {
  count = var.custom_bucket_policies != null && length(try(var.custom_bucket_policies.statements, [])) > 0 ? 1 : 0

  policy_id = var.custom_bucket_policies.policy_id
  version   = var.custom_bucket_policies.version

  dynamic "statement" {
    for_each = var.custom_bucket_policies.statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect != null ? statement.value.effect : "Allow"
      actions   = statement.value.actions
      resources = statement.value.resources != null ? statement.value.resources : [
        aws_s3_bucket.storage_bucket.arn,
        "${aws_s3_bucket.storage_bucket.arn}/*"
      ]

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "storage_bucket" {
  count  = var.custom_bucket_policies != null && length(try(var.custom_bucket_policies.statements, [])) > 0 ? 1 : 0
  bucket = aws_s3_bucket.storage_bucket.id
  policy = data.aws_iam_policy_document.custom_policy[0].json

  depends_on = [aws_s3_bucket_public_access_block.storage_bucket]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.storage_bucket.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.storage_bucket.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.storage_bucket.bucket_domain_name
}

output "kms_key_arn" {
  description = "The ARN of the Customer Managed KMS Key used for encrypting the bucket."
  value       = aws_kms_key.storage_key.arn
}

output "kms_key_alias" {
  description = "The alias assigned to the Customer Managed KMS Key."
  value       = aws_kms_alias.storage_key_alias.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  kms_key_id = var.create_sns_topic && var.enable_default_kms_key && var.kms_master_key_id == null ? aws_kms_key.sns[0].arn : var.kms_master_key_id

  # Determine feedback role ARN: use user-specified, or created role if enabled
  effective_feedback_role_arn = var.create_feedback_role ? (length(aws_iam_role.sns_feedback) > 0 ? aws_iam_role.sns_feedback[0].arn : null) : var.feedback_role_arn
}

variable "create_sns_topic" {
  description = "Whether to create the SNS topic and associated resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. If omitted, Terraform will assign a random name with name_prefix"
  type        = string
  default     = "app-notifications-topic"
}

variable "name_prefix" {
  description = "The prefix of the SNS topic name. Conflicts with name"
  type        = string
  default     = null
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = "Application Notifications"
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "enable_default_kms_key" {
  description = "Whether to create a dedicated AWS KMS customer managed key for SNS encryption if kms_master_key_id is not specified"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an already-existing customer master key (CMK) for Amazon SNS, or an AWS-managed CMK (e.g., alias/aws/sns)"
  type        = string
  default     = null
}

variable "create_feedback_role" {
  description = "Whether to create an IAM role for SNS delivery status feedback logging"
  type        = bool
  default     = true
}

variable "feedback_role_arn" {
  description = "Existing IAM role ARN for SNS delivery status logging. Used if create_feedback_role is false"
  type        = string
  default     = null
}

variable "feedback_sqs_success_sample_rate" {
  description = "The percentage of successful SQS message deliveries to log"
  type        = number
  default     = 100
}

variable "feedback_lambda_success_sample_rate" {
  description = "The percentage of successful Lambda message deliveries to log"
  type        = number
  default     = 100
}

variable "feedback_http_success_sample_rate" {
  description = "The percentage of successful HTTP/S message deliveries to log"
  type        = number
  default     = 100
}

variable "feedback_firehose_success_sample_rate" {
  description = "The percentage of successful Kinesis Firehose deliveries to log"
  type        = number
  default     = 100
}

variable "feedback_application_success_sample_rate" {
  description = "The percentage of successful application message deliveries to log"
  type        = number
  default     = 100
}

variable "create_topic_policy" {
  description = "Whether to attach an IAM resource policy to the SNS topic"
  type        = bool
  default     = true
}

variable "allowed_aws_services_for_sns_publish" {
  description = "List of AWS service principals allowed to publish to the SNS topic (e.g., s3.amazonaws.com, cloudwatch.amazonaws.com)"
  type        = list(string)
  default     = ["cloudwatch.amazonaws.com", "events.amazonaws.com"]
}

variable "allowed_iam_principals_for_sns_publish" {
  description = "List of IAM principal ARNs allowed to publish to the SNS topic"
  type        = list(string)
  default     = []
}

variable "custom_topic_policy_statements" {
  description = "List of additional custom policy statements to merge into the SNS topic policy"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "subscriptions" {
  description = "Map of SNS topic subscriptions to create"
  type = map(object({
    protocol                        = string
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    confirmation_timeout_in_minutes = optional(number, null)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, null)
    filter_policy_scope             = optional(string, "MessageAttributes")
    dead_letter_queue_arn           = optional(string, null)
    redrive_policy                  = optional(string, null)
    subscription_role_arn           = optional(string, null)
  }))
  default = {}
}

variable "tags" {
  description = "A mapping of tags to assign to the resources"
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key for SNS
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  count = var.create_sns_topic && var.enable_default_kms_key && var.kms_master_key_id == null ? 1 : 0

  statement {
    sid       = "EnableRootIAMKeyAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSNSKeyUseForServices"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type = "Service"
      identifiers = [
        "sns.amazonaws.com",
        "cloudwatch.amazonaws.com",
        "events.amazonaws.com"
      ]
    }
  }
}

resource "aws_kms_key" "sns" {
  count                   = var.create_sns_topic && var.enable_default_kms_key && var.kms_master_key_id == null ? 1 : 0
  description             = "KMS Key for SNS Topic ${var.name != null ? var.name : "managed-topic"}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = var.tags
}

resource "aws_kms_alias" "sns" {
  count         = var.create_sns_topic && var.enable_default_kms_key && var.kms_master_key_id == null ? 1 : 0
  name          = "alias/sns/${var.name != null ? var.name : "managed-topic"}"
  target_key_id = aws_kms_key.sns[0].key_id
}

# -----------------------------------------------------------------------------
# IAM Role and Policy for CloudWatch SNS Delivery Feedback
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "sns_feedback_assume_role" {
  count = var.create_sns_topic && var.create_feedback_role ? 1 : 0

  statement {
    sid     = "SNSServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sns_feedback" {
  count              = var.create_sns_topic && var.create_feedback_role ? 1 : 0
  name_prefix        = "sns-feedback-${substr(coalesce(var.name, "topic"), 0, 20)}-"
  assume_role_policy = data.aws_iam_policy_document.sns_feedback_assume_role[0].json
  description        = "IAM role granting SNS permission to write delivery feedback logs to CloudWatch Logs"

  tags = var.tags
}

data "aws_iam_policy_document" "sns_feedback_logging" {
  count = var.create_sns_topic && var.create_feedback_role ? 1 : 0

  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutMetricFilter",
      "logs:PutRetentionPolicy"
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:sns/*"
    ]
  }
}

resource "aws_iam_policy" "sns_feedback" {
  count       = var.create_sns_topic && var.create_feedback_role ? 1 : 0
  name_prefix = "sns-feedback-policy-"
  description = "Allows SNS delivery feedback writing to CloudWatch log groups"
  policy      = data.aws_iam_policy_document.sns_feedback_logging[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "sns_feedback" {
  count      = var.create_sns_topic && var.create_feedback_role ? 1 : 0
  role       = aws_iam_role.sns_feedback[0].name
  policy_arn = aws_iam_policy.sns_feedback[0].arn
}

# -----------------------------------------------------------------------------
# Amazon SNS Topic
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  count = var.create_sns_topic ? 1 : 0

  name        = var.name_prefix == null ? var.name : null
  name_prefix = var.name_prefix

  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  kms_master_key_id           = local.kms_key_id

  # Delivery Feedback Configuration
  sqs_success_feedback_role_arn    = local.effective_feedback_role_arn
  sqs_failure_feedback_role_arn    = local.effective_feedback_role_arn
  sqs_success_feedback_sample_rate = var.feedback_sqs_success_sample_rate

  lambda_success_feedback_role_arn    = local.effective_feedback_role_arn
  lambda_failure_feedback_role_arn    = local.effective_feedback_role_arn
  lambda_success_feedback_sample_rate = var.feedback_lambda_success_sample_rate

  http_success_feedback_role_arn    = local.effective_feedback_role_arn
  http_failure_feedback_role_arn    = local.effective_feedback_role_arn
  http_success_feedback_sample_rate = var.feedback_http_success_sample_rate

  firehose_success_feedback_role_arn    = local.effective_feedback_role_arn
  firehose_failure_feedback_role_arn    = local.effective_feedback_role_arn
  firehose_success_feedback_sample_rate = var.feedback_firehose_success_sample_rate

  application_success_feedback_role_arn    = local.effective_feedback_role_arn
  application_failure_feedback_role_arn    = local.effective_feedback_role_arn
  application_success_feedback_sample_rate = var.feedback_application_success_sample_rate

  tags = var.tags
}

# -----------------------------------------------------------------------------
# SNS Topic IAM Policy
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "topic_policy" {
  count = var.create_sns_topic && var.create_topic_policy ? 1 : 0

  statement {
    sid    = "DefaultOwnerAccess"
    effect = "Allow"
    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish"
    ]
    resources = [aws_sns_topic.this[0].arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [local.account_id]
    }
  }

  dynamic "statement" {
    for_each = length(var.allowed_aws_services_for_sns_publish) > 0 ? [1] : []
    content {
      sid     = "AllowAWSServicesPublish"
      effect  = "Allow"
      actions = ["SNS:Publish"]
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "Service"
        identifiers = var.allowed_aws_services_for_sns_publish
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.allowed_iam_principals_for_sns_publish) > 0 ? [1] : []
    content {
      sid     = "AllowIAMPrincipalsPublish"
      effect  = "Allow"
      actions = ["SNS:Publish"]
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = var.allowed_iam_principals_for_sns_publish
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_topic_policy_statements
    content {
      sid       = try(statement.value.sid, null)
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources != null ? statement.value.resources : [aws_sns_topic.this[0].arn]

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count  = var.create_sns_topic && var.create_topic_policy ? 1 : 0
  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.topic_policy[0].json
}

# -----------------------------------------------------------------------------
# Topic Subscriptions
# -----------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "this" {
  for_each = var.create_sns_topic ? var.subscriptions : {}

  topic_arn                       = aws_sns_topic.this[0].arn
  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  subscription_role_arn           = each.value.subscription_role_arn

  redrive_policy = each.value.redrive_policy != null ? each.value.redrive_policy : (
    each.value.dead_letter_queue_arn != null ? jsonencode({
      deadLetterTargetArn = each.value.dead_letter_queue_arn
    }) : null
  )
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "topic_arn" {
  description = "ARN of the Amazon SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the Amazon SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the Amazon SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the SNS topic"
  value       = local.kms_key_id
}

output "feedback_role_arn" {
  description = "The IAM role ARN configured for SNS delivery status feedback"
  value       = local.effective_feedback_role_arn
}

output "subscription_arns" {
  description = "Map of subscription keys to their respective ARNs"
  value = {
    for k, sub in aws_sns_topic_subscription.this : k => sub.arn
  }
}

output "topic_policy_json" {
  description = "The JSON policy document applied to the SNS topic"
  value       = try(aws_sns_topic_policy.this[0].policy, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ansible-vpc"
  }
}

resource "aws_internet_gateway" "ansible_vpc_igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-igw"
  }
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-private-subnet-1"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-public-subnet-1"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ansible_vpc_igw.id
  }

  tags = {
    Name = "ansible-vpc-public-rt"
  }
}

resource "aws_route_table_association" "public_rta" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-private-rt"
  }
}

resource "aws_route_table_association" "private_rta" {
  subnet_id      = aws_subnet.private_subnet_1.id
  route_table_id = aws_route_table.private_rt.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "tgw_hub_spoke"

  vpc_configs = {
    vpc_a = {
      cidr_block = "10.0.0.0/16"
      subnets = {
        subnet_a1 = { cidr = "10.0.1.0/24", az_index = 0 }
        subnet_a2 = { cidr = "10.0.2.0/24", az_index = 1 }
      }
      peer_cidr = "10.1.0.0/16"
    }
    vpc_b = {
      cidr_block = "10.1.0.0/16"
      subnets = {
        subnet_b1 = { cidr = "10.1.1.0/24", az_index = 0 }
        subnet_b2 = { cidr = "10.1.2.0/24", az_index = 1 }
      }
      peer_cidr = "10.0.0.0/16"
    }
  }

  flattened_subnets = merge([
    for vpc_key, vpc_val in local.vpc_configs : {
      for subnet_key, subnet_val in vpc_val.subnets : "${vpc_key}_${subnet_key}" => {
        vpc_key  = vpc_key
        cidr     = subnet_val.cidr
        az_index = subnet_val.az_index
      }
    }
  ]...)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_ec2_transit_gateway" "main" {
  description                     = "Centralized Transit Gateway for inter-VPC network routing"
  amazon_side_asn                 = 64512
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  auto_accept_shared_attachments  = "disable"

  tags = {
    Name = "${local.name_prefix}_tgw"
  }
}

resource "aws_vpc" "vpcs" {
  for_each = local.vpc_configs

  cidr_block           = each.value.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}_${each.key}"
  }
}

resource "aws_subnet" "subnets" {
  for_each = local.flattened_subnets

  vpc_id            = aws_vpc.vpcs[each.value.vpc_key].id
  cidr_block        = each.value.cidr
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  tags = {
    Name = "${local.name_prefix}_${each.key}"
  }
}

resource "aws_ec2_transit_gateway_vpc_attachment" "attachments" {
  for_each = local.vpc_configs

  transit_gateway_id = aws_ec2_transit_gateway.main.id
  vpc_id             = aws_vpc.vpcs[each.key].id
  subnet_ids = [
    for subnet_key, subnet_meta in local.flattened_subnets :
    aws_subnet.subnets[subnet_key].id
    if subnet_meta.vpc_key == each.key
  ]

  dns_support = "enable"

  tags = {
    Name = "${local.name_prefix}_tgw_attachment_${each.key}"
  }
}

resource "aws_route_table" "route_tables" {
  for_each = local.vpc_configs

  vpc_id = aws_vpc.vpcs[each.key].id

  tags = {
    Name = "${local.name_prefix}_rt_${each.key}"
  }
}

resource "aws_route" "inter_vpc_routes" {
  for_each = local.vpc_configs

  route_table_id         = aws_route_table.route_tables[each.key].id
  destination_cidr_block = each.value.peer_cidr
  transit_gateway_id     = aws_ec2_transit_gateway.main.id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.attachments]
}

resource "aws_route_table_association" "associations" {
  for_each = local.flattened_subnets

  subnet_id      = aws_subnet.subnets[each.key].id
  route_table_id = aws_route_table.route_tables[each.value.vpc_key].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dragondrop-ecs-vpc"
  }
}

resource "aws_subnet" "ecs_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "dragondrop-ecs-subnet"
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dragondrop-ecs-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "dragondrop-ecs-rt"
  }
}

resource "aws_route_table_association" "subnet_assoc" {
