  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "dragondrop_compute_ecs_fargate_sg" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for ECS Fargate allowing outbound access only within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic strictly within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "dragondrop-compute-ecs-fargate-sg"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_dynamodb_table" "raw_metrics" {
  name             = "raw_metrics"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "uuid"
  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  attribute {
    name = "uuid"
    type = "S"
  }

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "raw_metrics"
    Environment = "production"
  }
}

resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "aggregate_metrics"
    Environment = "production"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  type        = string
  description = "The EC2 instance type"
  default     = "t3.micro"
}

variable "server_name" {
  type        = string
  description = "The name tag for the server"
  default     = "demo"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.server_name}-public-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.server_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "${var.server_name}-web-sg"
  description = "Allow inbound HTTP from anywhere and restrict egress to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "${var.server_name}-web-sg"
  }
}

resource "aws_kms_key" "ebs" {
  description         = "KMS key for EC2 instance EBS root volume encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EC2 Service to Use the Key"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
            "kms:ViaService"    = "ec2.us-east-1.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow EC2 to Create Grant"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
            "kms:ViaService"    = "ec2.us-east-1.amazonaws.com"
          }
          Bool = {
            "kms:GrantIsForAWSResource" = "true"
          }
        }
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-ebs-kms-key"
  }
}

resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    kms_key_id  = aws_kms_key.ebs.arn
    volume_type = "gp3"
  }

  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd
              systemctl start httpd
              systemctl enable httpd
              echo "<h1>Hello from ${var.server_name}</h1>" > /var/www/html/index.html
              EOF

  tags = {
    Name = var.server_name
  }
}

resource "aws_eip" "web" {
  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip"
  }
}

resource "aws_eip_association" "web" {
  instance_id   = aws_instance.web.id
  allocation_id = aws_eip.web.id
}

output "elastic_ip" {
  description = "The public Elastic IP address of the web server"
  value       = aws_eip.web.public_ip
}

output "instance_id" {
  description = "The ID of the EC2 instance"
  value       = aws_instance.web.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSNSToUseKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "sns_encryption" {
  description             = "Customer-managed KMS key for SNS topics encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "sns_encryption_alias" {
  name          = "alias/sns-integration-testing-key"
  target_key_id = aws_kms_key.sns_encryption.key_id
}

resource "aws_sns_topic" "topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns_encryption.arn
}

resource "aws_sns_topic" "topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns_encryption.arn
}

data "aws_iam_policy_document" "sns_topic_policy_doc" {
  statement {
    sid    = "AllowPublicSnsActionsOnTopicOne"
    effect = "Allow"
    actions = [
      "sns:Publish",
      "sns:Subscribe",
      "sns:Receive",
      "sns:GetTopicAttributes",
      "sns:SetTopicAttributes",
      "sns:AddPermission",
      "sns:RemovePermission",
      "sns:DeleteTopic",
      "sns:ListSubscriptionsByTopic"
    ]
    resources = [
      aws_sns_topic.topic_with_policy.arn
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_sns_topic_policy" "topic_policy" {
  arn    = aws_sns_topic.topic_with_policy.arn
  policy = data.aws_iam_policy_document.sns_topic_policy_doc.json
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns_encryption.arn
  delivery_policy = jsonencode({
    "http" = {
      "defaultHealthyRetryPolicy" = {
        "minDelayTarget"     = 20,
        "maxDelayTarget"     = 20,
        "numRetries"         = 3,
        "numMaxDelayRetries" = 0,
        "numNoDelayRetries"  = 0,
        "numMinDelayRetries" = 0,
        "backoffFunction"    = "linear"
      },
      "disableSubscriptionOverrides" = false,
      "defaultThrottlePolicy" = {
        "maxReceivesPerSecond" = 10
      }
    }
  })
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for SNS encryption"
  value       = aws_kms_key.sns_encryption.arn
}

output "topic_with_policy_arn" {
  description = "ARN of my-topic-with-policy"
  value       = aws_sns_topic.topic_with_policy.arn
}

output "topic_with_policy2_arn" {
  description = "ARN of my-topic-with-policy2"
  value       = aws_sns_topic.topic_with_policy2.arn
}

output "user_updates_topic_arn" {
  description = "ARN of user-updates-topic"
  value       = aws_sns_topic.user_updates_topic.arn
}

