  }
}

# Management Tier Subnet
resource "aws_subnet" "management" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-management"
  }
}

# Tier 2 - Availability Zone 2 Subnets (Duplicate set)
resource "aws_subnet" "web_2" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-web-2"
  }
}

resource "aws_subnet" "app_2" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.5.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-app-2"
  }
}

resource "aws_subnet" "database_2" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.6.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-database-2"
  }
}

# Route Tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
