    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

# Public Subnet Associations
resource "aws_route_table_association" "public_web_1" {
  subnet_id      = aws_subnet.web_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_management" {
  subnet_id      = aws_subnet.management.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_web_2" {
  subnet_id      = aws_subnet.web_2.id
  route_table_id = aws_route_table.public.id
}

# Private Subnet Associations
resource "aws_route_table_association" "private_app_1" {
  subnet_id      = aws_subnet.app_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_database_1" {
  subnet_id      = aws_subnet.database_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_app_2" {
  subnet_id      = aws_subnet.app_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_database_2" {
  subnet_id      = aws_subnet.database_2.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "key_type" {
  description = "The type of KMS key to create. Valid values: standard, external, replica, replica_external."
  type        = string
  default     = "standard"
  validation {
    condition     = contains(["standard", "external", "replica", "replica_external"], var.key_type)
    error_message = "The key_type value must be one of: standard, external, replica, replica_external."
  }
}

variable "description" {
  description = "The description of the key as viewed in AWS console."
  type        = string
  default     = "Managed KMS Key created via Terraform"
}

variable "deletion_window_in_days" {
  description = "Duration in days after which the key is deleted upon destruction of the resource. Must be between 7 and 30 days inclusive."
  type        = number
  default     = 30
}

variable "key_usage" {
  description = "Specifies the intended use of the key. Valid values: ENCRYPT_DECRYPT, SIGN_VERIFY, or GENERATE_VERIFY_MAC."
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Specifies whether the key contains a symmetric key or an asymmetric key pair and the encryption algorithms or signing algorithms supported."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "multi_region" {
  description = "Indicates whether the KMS key is a multi-Region (true) or regional (false) key."
  type        = bool
  default     = false
}

variable "enable_key_rotation" {
  description = "Specifies whether key rotation is enabled. Defaults to true for standard symmetric keys."
  type        = bool
  default     = true
}

variable "primary_key_arn" {
  description = "The ARN of the primary key when creating a replica or replica_external key."
  type        = string
  default     = null
}

variable "key_material_base64" {
  description = "Base64 encoded 256-bit symmetric encryption key material to import into external key."
  type        = string
  default     = null
  sensitive   = true
}

variable "valid_to" {
  description = "Time at which the imported key material expires in RFC3339 format."
  type        = string
  default     = null
}

# Policy Configuration Variables
variable "enable_default_root_policy" {
  description = "Specifies whether to enable the default root account full access policy."
  type        = bool
  default     = true
}

variable "key_administrators" {
  description = "A list of IAM ARNs for principals permitted to administer the KMS key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "A list of IAM ARNs for principals permitted to use the KMS key for standard encryption and decryption."
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "A list of IAM ARNs for AWS service roles permitted to use the key."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_public_encryption_users" {
  description = "A list of IAM ARNs permitted to perform asymmetric public encryption operations."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_sign_verify_users" {
  description = "A list of IAM ARNs permitted to perform asymmetric signing and verification operations."
  type        = list(string)
  default     = []
}

variable "key_hmac_users" {
  description = "A list of IAM ARNs permitted to perform HMAC operations."
  type        = list(string)
  default     = []
}

variable "enable_autoscaling" {
  description = "Specifies whether to allow Amazon EC2 Auto Scaling service linked role to use the key."
  type        = bool
  default     = false
}

variable "enable_route53_dnssec" {
  description = "Specifies whether to allow Route 53 to use the key for DNSSEC signing."
  type        = bool
  default     = false
}

variable "custom_policy_override_json" {
  description = "An optional custom JSON policy string to override or append to the KMS key policy."
  type        = string
  default     = null
}

# Aliases and Grants Configuration
variable "aliases" {
  description = "Map of alias configurations to create. Key is alias identifier. Attributes: name, name_prefix."
  type = map(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = {}
}

variable "grants" {
  description = "Map of KMS grants to create. Key is arbitrary grant identifier."
  type = map(object({
    grantee_principal         = string
    operations                = list(string)
    retiring_principal        = optional(string)
    grant_creation_tokens     = optional(list(string))
    encryption_context_subset = optional(map(string))
    encryption_context_equals = optional(map(string))
  }))
  default = {}
}

variable "tags" {
  description = "A mapping of tags to assign to the KMS resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"

  is_standard         = var.key_type == "standard"
  is_external         = var.key_type == "external"
  is_replica          = var.key_type == "replica"
  is_replica_external = var.key_type == "replica_external"

  # Determine key rotation eligibility
  enable_rotation = local.is_standard && var.key_usage == "ENCRYPT_DECRYPT" && var.customer_master_key_spec == "SYMMETRIC_DEFAULT" ? var.enable_key_rotation : false

  active_key_arn = try(
    aws_kms_key.standard[0].arn,
    aws_kms_external_key.external[0].arn,
    aws_kms_replica_key.replica[0].arn,
    aws_kms_replica_external_key.replica_external[0].arn,
    ""
  )

  active_key_id = try(
    aws_kms_key.standard[0].id,
    aws_kms_external_key.external[0].id,
    aws_kms_replica_key.replica[0].id,
    aws_kms_replica_external_key.replica_external[0].id,
    ""
  )
}

# -----------------------------------------------------------------------------
# Key Policy Construction
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_policy" {
  # Default Root Account Delegation
  dynamic "statement" {
    for_each = var.enable_default_root_policy ? [1] : []
    content {
      sid       = "EnableRootPermissions"
      effect    = "Allow"
      actions   = ["kms:*"]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = [local.root_arn]
      }
    }
  }

  # Key Administrators
  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []
    content {
      sid    = "AllowKeyAdministration"
      effect = "Allow"
      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion",
        "kms:RotateKeyOnDemand"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
    }
  }

  # Standard Key Users (Symmetric Encrypt/Decrypt/DataKey)
  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid    = "AllowStandardKeyUsage"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
    }
  }

  # Service Users (AWS Service Principals or IAM Roles)
  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []
    content {
      sid    = "AllowServiceKeyUsage"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey",
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:RevokeGrant"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_service_users
      }
    }
  }

  # Asymmetric Public Encryption Operations
  dynamic "statement" {
    for_each = length(var.key_asymmetric_public_encryption_users) > 0 ? [1] : []
    content {
      sid    = "AllowAsymmetricPublicEncryption"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:DescribeKey",
        "kms:GetPublicKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_public_encryption_users
      }
    }
  }

  # Asymmetric Sign / Verify Operations
  dynamic "statement" {
    for_each = length(var.key_asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "AllowAsymmetricSignVerify"
      effect = "Allow"
      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign",
        "kms:Verify"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_sign_verify_users
      }
    }
  }

  # HMAC Operations
  dynamic "statement" {
    for_each = length(var.key_hmac_users) > 0 ? [1] : []
    content {
      sid    = "AllowHmacOperations"
      effect = "Allow"
      actions = [
        "kms:DescribeKey",
        "kms:GenerateMac",
        "kms:VerifyMac"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_hmac_users
      }
    }
  }

  # EC2 Auto Scaling Permissions
  dynamic "statement" {
    for_each = var.enable_autoscaling ? [1] : []
    content {
      sid    = "AllowAutoScalingServiceLinkedRole"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_autoscaling ? [1] : []
    content {
      sid    = "AllowAutoScalingToCreateGrant"
      effect = "Allow"
      actions = [
        "kms:CreateGrant"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"]
      }
      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  # Route 53 DNSSEC Signing Service Permissions
  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []
    content {
      sid    = "AllowRoute53DNSSECSigning"
      effect = "Allow"
      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign"
      ]
      resources = ["*"]
      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }
      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []
    content {
      sid    = "AllowRoute53DNSSECCreateGrant"
      effect = "Allow"
      actions = [
        "kms:CreateGrant"
      ]
      resources = ["*"]
      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }
      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }
}

data "aws_iam_policy_document" "final_kms_policy" {
  source_policy_documents   = [data.aws_iam_policy_document.kms_policy.json]
  override_policy_documents = var.custom_policy_override_json != null ? [var.custom_policy_override_json] : []
}

# -----------------------------------------------------------------------------
# Standard KMS Key
# -----------------------------------------------------------------------------
resource "aws_kms_key" "standard" {
  count                    = local.is_standard ? 1 : 0
  description              = var.description
  deletion_window_in_days  = var.deletion_window_in_days
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  policy                   = data.aws_iam_policy_document.final_kms_policy.json
  multi_region             = var.multi_region
  enable_key_rotation      = local.enable_rotation
  tags                     = var.tags
}

# -----------------------------------------------------------------------------
# External KMS Key (Imported Key Material)
# -----------------------------------------------------------------------------
resource "aws_kms_external_key" "external" {
  count                   = local.is_external ? 1 : 0
  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  policy                  = data.aws_iam_policy_document.final_kms_policy.json
  multi_region            = var.multi_region
  tags                    = var.tags
}

# -----------------------------------------------------------------------------
# Replica KMS Key
# -----------------------------------------------------------------------------
resource "aws_kms_replica_key" "replica" {
  count                   = local.is_replica ? 1 : 0
  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_key_arn
  policy                  = data.aws_iam_policy_document.final_kms_policy.json
  tags                    = var.tags
}

# -----------------------------------------------------------------------------
# Replica External KMS Key
# -----------------------------------------------------------------------------
resource "aws_kms_replica_external_key" "replica_external" {
  count                   = local.is_replica_external ? 1 : 0
  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_key_arn
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  policy                  = data.aws_iam_policy_document.final_kms_policy.json
  tags                    = var.tags
}

# -----------------------------------------------------------------------------
# KMS Key Aliases
# -----------------------------------------------------------------------------
resource "aws_kms_alias" "this" {
  for_each      = var.aliases
  name          = each.value.name != null ? (startswith(each.value.name, "alias/") ? each.value.name : "alias/${each.value.name}") : null
  name_prefix   = each.value.name_prefix != null ? (startswith(each.value.name_prefix, "alias/") ? each.value.name_prefix : "alias/${each.value.name_prefix}") : null
  target_key_id = local.active_key_id
}

# -----------------------------------------------------------------------------
# KMS Key Grants
# -----------------------------------------------------------------------------
resource "aws_kms_grant" "this" {
  for_each              = var.grants
  name                  = each.key
  key_id                = local.active_key_id
  grantee_principal     = each.value.grantee_principal
  operations            = each.value.operations
  retiring_principal    = each.value.retiring_principal
  grant_creation_tokens = each.value.grant_creation_tokens

  dynamic "constraints" {
    for_each = (each.value.encryption_context_subset != null || each.value.encryption_context_equals != null) ? [1] : []
    content {
      encryption_context_subset = each.value.encryption_context_subset
      encryption_context_equals = each.value.encryption_context_equals
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "key_arn" {
  description = "The Amazon Resource Name (ARN) of the provisioned KMS key."
  value       = local.active_key_arn
}

output "key_id" {
  description = "The globally unique identifier (Key ID) for the KMS key."
  value       = local.active_key_id
}

output "key_policy" {
  description = "The IAM policy document applied to the KMS key."
  value       = data.aws_iam_policy_document.final_kms_policy.json
}

output "aliases" {
  description = "Map of created KMS aliases and their associated attributes."
  value = {
    for k, v in aws_kms_alias.this : k => {
      arn           = v.arn
      name          = v.name
      target_key_id = v.target_key_id
    }
  }
}

output "grants" {
  description = "Map of created KMS grants and their associated identifiers and tokens."
  value = {
    for k, v in aws_kms_grant.this : k => {
      grant_id    = v.grant_id
      grant_token = v.grant_token
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

variable "topic_name" {
  type        = string
  description = "Name of the SNS topic. If FIFO, the name must end in .fifo."
  default     = "app-notifications"
}

variable "display_name" {
  type        = string
  description = "Display name for the SNS topic."
  default     = "Application Notifications"
}

variable "fifo_topic" {
  type        = bool
  description = "Whether the SNS topic is a FIFO topic. If true, topic_name must end with .fifo."
  default     = false
}

variable "content_based_deduplication" {
  type        = bool
  description = "Enables content-based deduplication for FIFO topics."
  default     = false
}

variable "create_kms_key" {
  type        = bool
  description = "Whether to create a dedicated AWS KMS customer managed key for this SNS topic."
  default     = true
}

variable "kms_master_key_id" {
  type        = string
  description = "Existing KMS key ID or ARN to use for encryption if create_kms_key is false. Defaults to AWS managed key alias/aws/sns if left blank."
  default     = ""
}

variable "application_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Application endpoint successful delivery status feedback."
  default     = null
}

variable "application_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of successful Application deliveries to log (0-100)."
  default     = null
}

variable "application_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Application endpoint failed delivery status feedback."
  default     = null
}

variable "http_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for HTTP/S endpoint successful delivery status feedback."
  default     = null
}

variable "http_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of successful HTTP/S deliveries to log (0-100)."
  default     = null
}

variable "http_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for HTTP/S endpoint failed delivery status feedback."
  default     = null
}

variable "lambda_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Lambda endpoint successful delivery status feedback."
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of successful Lambda deliveries to log (0-100)."
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Lambda endpoint failed delivery status feedback."
  default     = null
}

variable "sqs_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for SQS endpoint successful delivery status feedback."
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of successful SQS deliveries to log (0-100)."
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for SQS endpoint failed delivery status feedback."
  default     = null
}

variable "firehose_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Firehose endpoint successful delivery status feedback."
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of successful Firehose deliveries to log (0-100)."
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Firehose endpoint failed delivery status feedback."
  default     = null
}

variable "topic_policy_json" {
  type        = string
  description = "Custom JSON policy document to attach to the SNS topic. If null, no topic policy resource is created."
  default     = null
}

variable "subscriptions" {
  type = map(object({
    protocol               = string
    endpoint               = string
    endpoint_auto_confirms = optional(bool, false)
    raw_message_delivery   = optional(bool, false)
    filter_policy          = optional(string, null)
    filter_policy_scope    = optional(string, null)
    redrive_policy         = optional(string, null)
  }))
  description = "Map of SNS topic subscriptions to create."
  default     = {}
}

variable "tags" {
  type        = map(string)
  description = "Tags to assign to resources created by this configuration."
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.id

  # Resolved topic name ensuring FIFO extension if requested
  resolved_topic_name = var.fifo_topic && !endswith(var.topic_name, ".fifo") ? "${var.topic_name}.fifo" : var.topic_name

  # KMS alias name sanitized of .fifo suffix if present
  kms_alias_name = "alias/sns/${trimsuffix(local.resolved_topic_name, ".fifo")}"

  # Resolved KMS key: newly created key ARN > explicit key ID/ARN > default AWS managed SNS key
  resolved_kms_key_id = var.create_kms_key ? aws_kms_key.sns[0].arn : (
    var.kms_master_key_id != "" ? var.kms_master_key_id : "alias/aws/sns"
  )
}

data "aws_iam_policy_document" "kms_key_policy" {
  count = var.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSNSServiceEncryption"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsServiceEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:aws:logs:${local.region}:${local.account_id}:*"]
    }
  }
}

resource "aws_kms_key" "sns" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "Dedicated KMS customer managed key for SNS topic ${local.resolved_topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = merge(
    var.tags,
    {
      Name = "${local.resolved_topic_name}-key"
    }
  )
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.sns[0].key_id
}

resource "aws_sns_topic" "this" {
  name                        = local.resolved_topic_name
  display_name                = var.fifo_topic ? null : var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  kms_master_key_id           = local.resolved_kms_key_id

  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn

  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn

  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn

  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn

  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn

  tags = merge(
    var.tags,
    {
      Name = local.resolved_topic_name
    }
  )
}

resource "aws_sns_topic_policy" "custom" {
  count  = var.topic_policy_json != null ? 1 : 0
  arn    = aws_sns_topic.this.arn
  policy = var.topic_policy_json
}

resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn              = aws_sns_topic.this.arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  endpoint_auto_confirms = each.value.endpoint_auto_confirms
  raw_message_delivery   = each.value.raw_message_delivery
  filter_policy          = each.value.filter_policy
  filter_policy_scope    = each.value.filter_policy_scope
  redrive_policy         = each.value.redrive_policy
}

output "topic_arn" {
  description = "The ARN of the SNS topic."
  value       = aws_sns_topic.this.arn
}

output "topic_id" {
  description = "The ID of the SNS topic."
  value       = aws_sns_topic.this.id
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = aws_sns_topic.this.name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key created for the SNS topic, if created."
  value       = var.create_kms_key ? aws_kms_key.sns[0].arn : null
}

output "kms_alias_arn" {
  description = "The ARN of the KMS key alias, if KMS key was created."
  value       = var.create_kms_key ? aws_kms_alias.sns[0].arn : null
}

output "kms_master_key_id" {
  description = "The KMS master key ID or ARN used for SNS server-side encryption."
  value       = local.resolved_kms_key_id
}

output "subscription_arns" {
  description = "A map of subscription identifiers to their respective ARNs."
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create_developer_group" {
  description = "Toggle to create the IAM developer group"
  type        = bool
  default     = true
}

variable "create_developer_group_policy" {
  description = "Toggle to create the IAM read-only and S3 read/write policy"
  type        = bool
  default     = true
}

variable "create_developer_group_policy_attachment" {
  description = "Toggle to attach the developer policy to the developer group"
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Toggle to create IAM users"
  type        = bool
  default     = true
}

variable "create_ec2_console_screenshot_policy" {
  description = "Toggle to create the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachments" {
  description = "Toggle to attach the EC2 screenshot policy to IAM users"
  type        = bool
  default     = true
}

variable "create_group_membership" {
  description = "Toggle to associate IAM users with the developer group"
  type        = bool
  default     = true
}

variable "create_instance_role" {
  description = "Toggle to create the EC2 instance role and policy attachment"
  type        = bool
  default     = true
}

variable "developer_group_name" {
  description = "Name of the developer IAM group"
  type        = string
  default     = "developers"
}

variable "iam_user_list" {
  description = "List of IAM usernames to create"
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "developer_policy_name" {
  description = "Name of the IAM read-only and S3 access policy"
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "screenshot_policy_name" {
  description = "Name of the EC2 console screenshot policy"
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "instance_role_name" {
  description = "Name of the EC2 instance role"
  type        = string
  default     = "instance_role"
}

variable "default_tags" {
  description = "Default tags to apply to supported resources"
  type        = map(string)
  default = {
    user_created_by = "terraform"
  }
}

data "aws_partition" "current" {}

resource "aws_iam_group" "developers" {
  count = var.create_developer_group ? 1 : 0
  name  = var.developer_group_name
}

resource "aws_iam_user" "users" {
  for_each      = var.create_iam_users ? toset(var.iam_user_list) : toset([])
  name          = each.value
  force_destroy = true
  tags          = var.default_tags
}

resource "aws_iam_policy" "developer_policy" {
  count       = var.create_developer_group_policy ? 1 : 0
  name        = var.developer_policy_name
  description = "Policy providing IAM read-only actions and S3 object read/write access"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "IAMReadOnlyAccess"
        Effect = "Allow"
        Action = [
          "iam:GenerateCredentialReport",
          "iam:GenerateServiceLastAccessedDetails",
          "iam:Get*",
          "iam:List*",
          "iam:SimulateCustomPolicy",
          "iam:SimulatePrincipalPolicy"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ListBuckets"
        Effect = "Allow"
        Action = [
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::*",
          "arn:${data.aws_partition.current.partition}:s3:::*/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_attachment" {
  count      = (var.create_developer_group && var.create_developer_group_policy && var.create_developer_group_policy_attachment) ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.developer_policy[0].arn
}

resource "aws_iam_policy" "screenshot_policy" {
  count       = var.create_ec2_console_screenshot_policy ? 1 : 0
  name        = var.screenshot_policy_name
  description = "Policy allowing ec2:GetConsoleScreenshot"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2GetConsoleScreenshot"
        Effect = "Allow"
        Action = [
          "ec2:GetConsoleScreenshot"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "screenshot_attachments" {
  for_each   = (var.create_iam_users && var.create_ec2_console_screenshot_policy && var.create_user_policy_attachments) ? aws_iam_user.users : {}
  user       = each.value.name
  policy_arn = aws_iam_policy.screenshot_policy[0].arn
}

resource "aws_iam_group_membership" "developers" {
  count = (var.create_developer_group && var.create_iam_users && var.create_group_membership) ? 1 : 0
  name  = "${var.developer_group_name}-membership"
  group = aws_iam_group.developers[0].name
  users = [for u in aws_iam_user.users : u.name]
}

resource "aws_iam_role" "instance_role" {
  count = var.create_instance_role ? 1 : 0
  name  = var.instance_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.default_tags
}

resource "aws_iam_role_policy_attachment" "instance_role_readonly" {
  count      = var.create_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name     = "eks-multi-cluster-vpc"
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)
  private_subnets = [
    for i in range(3) : cidrsubnet(local.vpc_cidr, 4, i)
  ]
  public_subnets = [
    for i in range(3) : cidrsubnet(local.vpc_cidr, 8, 48 + i)
  ]
  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  enable_nat_gateway = true
  single_nat_gateway = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Security group for cluster1 additional networking"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.tags,
    {
      Name = "cluster1_additional_sg"
    }
  )
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Security group for cluster2 additional networking"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.tags,
    {
      Name = "cluster2_additional_sg"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_ingress_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  description                  = "Allow all ingress traffic from cluster2 security group"
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "cluster1_egress_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  description                  = "Allow all egress traffic to cluster2 security group"
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_ingress_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  description                  = "Allow all ingress traffic from cluster1 security group"
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "cluster2_egress_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  description                  = "Allow all egress traffic to cluster1 security group"
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "pool_name" {
  type        = string
  description = "Name of the Cognito User Pool"
  default     = "Pool name"
}

variable "alias_attributes" {
  type        = list(string)
  description = "Attributes supported as an alias for this user pool"
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  type        = list(string)
  description = "The attributes to be auto-verified"
  default     = []
}

variable "email_verification_message" {
  type        = string
  description = "A string representing the email verification message"
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  type        = string
  description = "A string representing the email verification subject"
  default     = "Some subject"
}

variable "mfa_configuration" {
  type        = string
  description = "Multi-Factor Authentication (MFA) configuration"
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  type        = string
  description = "A string representing the SMS authentication message"
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  type        = string
  description = "A string representing the SMS verification message"
  default     = "SMS verification message {####}"
}

variable "verification_message_template_default_email_option" {
  type        = string
  description = "Default email option for verification template (CONFIRM_WITH_LINK or CONFIRM_WITH_CODE)"
  default     = "CONFIRM_WITH_CODE"
}

variable "verification_email_subject_by_link" {
  type        = string
  description = "The subject line for the email message template by link"
  default     = null
}

variable "verification_email_message_by_link" {
  type        = string
  description = "The email message template by link"
  default     = null
}

variable "sms_configuration" {
  type = object({
    external_id    = string
    sns_caller_arn = string
    sns_region     = optional(string)
  })
  description = "Configuration for SMS text messages"
  default = {
    external_id    = ""
    sns_caller_arn = ""
    sns_region     = null
  }
}

variable "recovery_mechanisms" {
  type = list(object({
    name     = string
    priority = number
  }))
  description = "List of user recovery mechanisms"
  default = [
    {
      name     = "verified_phone_number"
      priority = 1
    },
    {
      name     = "verified_email"
      priority = 2
    }
  ]
}

variable "admin_create_user_config" {
  type        = bool
  description = "Set to true if only the administrator is allowed to create user profiles"
  default     = false
}

variable "software_token_mfa_enabled" {
  type        = bool
  description = "Whether software token MFA is enabled"
  default     = true
}

variable "case_sensitive" {
  type        = bool
  description = "Whether username case sensitivity is enabled"
  default     = null
}

variable "device_configuration" {
  type = object({
    challenge_required_on_new_device      = optional(bool)
    device_only_remembered_on_user_prompt = optional(bool)
  })
  description = "Device tracking configuration"
  default     = null
}

variable "lambda_config" {
  type = object({
    create_auth_challenge          = optional(string)
    custom_message                 = optional(string)
    define_auth_challenge          = optional(string)
    post_authentication            = optional(string)
    post_confirmation              = optional(string)
    pre_authentication             = optional(string)
    pre_sign_up                    = optional(string)
    pre_token_generation           = optional(string)
    user_migration                 = optional(string)
    verify_auth_challenge_response = optional(string)
    kms_key_id                     = optional(string)
    custom_email_sender = optional(object({
      lambda_arn     = string
      lambda_version = string
    }))
    custom_sms_sender = optional(object({
      lambda_arn     = string
      lambda_version = string
    }))
  })
  description = "Lambda trigger configuration map"
  default     = {}
}

variable "schema_attributes" {
  type = list(object({
    name                     = string
    attribute_data_type      = string
    developer_only_attribute = optional(bool, false)
    mutable                  = optional(bool, true)
    required                 = optional(bool, true)
    string_attribute_constraints = optional(object({
      min_length = optional(string)
      max_length = optional(string)
    }))
    number_attribute_constraints = optional(object({
      min_value = optional(string)
      max_value = optional(string)
    }))
  }))
  description = "Custom or standard schema definitions"
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      mutable             = true
      required            = true
      string_attribute_constraints = {
        min_length = "1"
        max_length = "2048"
      }
    }
  ]
}

variable "client_names" {
  type        = list(string)
  description = "List of user pool client application names"
  default     = []
}

variable "generate_secret" {
  type        = bool
  description = "Should an application secret be generated"
  default     = false
}

variable "token_validities" {
  type = object({
    access_token  = number
    id_token      = number
    refresh_token = number
  })
  description = "Token validity durations"
  default = {
    access_token  = 120
    id_token      = 120
    refresh_token = 7
  }
}

variable "token_validity_units" {
  type = object({
    access_token  = string
    id_token      = string
    refresh_token = string
  })
  description = "Units for token validities"
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "enable_token_revocation" {
  type        = bool
  description = "Enables or disables token revocation"
  default     = true
}

variable "allowed_oauth_flows_user_pool_client" {
  type        = bool
  description = "Whether the client is allowed to follow OAuth protocol flows"
  default     = false
}

variable "explicit_auth_flows" {
  type        = list(string)
  description = "List of authentication flows"
  default = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH"
  ]
}

variable "prevent_user_existence_errors" {
  type        = string
  description = "Error masking setting when user does not exist"
  default     = "LEGACY"
}

variable "allowed_oauth_flows" {
  type        = list(string)
  description = "List of allowed OAuth flows"
  default     = []
}

variable "allowed_oauth_scopes" {
  type        = list(string)
  description = "List of allowed OAuth scopes"
  default     = []
}

variable "callback_urls" {
  type        = list(string)
  description = "List of allowed callback URLs"
  default     = []
}

variable "logout_urls" {
  type        = list(string)
  description = "List of allowed logout URLs"
  default     = []
}

variable "supported_identity_providers" {
  type        = list(string)
  description = "List of provider names"
  default     = []
}

variable "read_attributes" {
  type        = list(string)
  description = "List of user pool attributes the client can read"
  default     = []
}

variable "write_attributes" {
  type        = list(string)
  description = "List of user pool attributes the client can write"
  default     = []
}

variable "user_group_name" {
  type        = string
  description = "The name of the Cognito user group"
  default     = null
}

variable "user_group_precedence" {
  type        = number
  description = "The precedence of the user group"
  default     = 0
}

variable "user_group_role_arn" {
  type        = string
  description = "The ARN of the IAM role associated with the user group"
  default     = null
}

variable "domain" {
  type        = string
  description = "Cognito User Pool domain name or prefix"
  default     = null
}

variable "certificate_arn" {
  type        = string
  description = "The ARN of an ACM certificate for custom domain"
  default     = null
}

variable "create_route53_record" {
  type        = bool
  description = "Whether to create a Route 53 alias record for custom domain"
  default     = false
}

variable "route53_zone_id" {
  type        = string
  description = "Route 53 hosted zone ID for domain alias record"
  default     = null
}

locals {
  has_sms_config = (
    var.sms_configuration != null &&
    lookup(var.sms_configuration, "external_id", "") != "" &&
    lookup(var.sms_configuration, "sns_caller_arn", "") != ""
  )
  has_group_name  = var.user_group_name != null && var.user_group_name != ""
  has_domain_name = var.domain != null && var.domain != ""
  cloudfront_zone = "Z2FDTNDATAQYW2"
}

resource "aws_cognito_user_pool" "this" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  sms_authentication_message = var.sms_authentication_message

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_config
  }

  verification_message_template {
    default_email_option  = var.verification_message_template_default_email_option
    email_message         = var.email_verification_message
    email_subject         = var.email_verification_subject
    email_message_by_link = var.verification_email_message_by_link
    email_subject_by_link = var.verification_email_subject_by_link
    sms_message           = var.sms_verification_message
  }

  dynamic "user_attribute_update_settings" {
    for_each = contains(var.auto_verified_attributes, "email") ? [1] : []
    content {
      attributes_require_verification_before_update = ["email"]
    }
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms
      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive != null ? [1] : []
    content {
      case_sensitive = var.case_sensitive
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = lookup(device_configuration.value, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(device_configuration.value, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "sms_configuration" {
    for_each = local.has_sms_config ? [var.sms_configuration] : []
    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
      sns_region     = lookup(sms_configuration.value, "sns_region", null)
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) > 0 ? [var.lambda_config] : []
    content {
      create_auth_challenge          = lookup(lambda_config.value, "create_auth_challenge", null)
      custom_message                 = lookup(lambda_config.value, "custom_message", null)
      define_auth_challenge          = lookup(lambda_config.value, "define_auth_challenge", null)
      kms_key_id                     = lookup(lambda_config.value, "kms_key_id", null)
      post_authentication            = lookup(lambda_config.value, "post_authentication", null)
      post_confirmation              = lookup(lambda_config.value, "post_confirmation", null)
      pre_authentication             = lookup(lambda_config.value, "pre_authentication", null)
      pre_sign_up                    = lookup(lambda_config.value, "pre_sign_up", null)
      pre_token_generation           = lookup(lambda_config.value, "pre_token_generation", null)
      user_migration                 = lookup(lambda_config.value, "user_migration", null)
      verify_auth_challenge_response = lookup(lambda_config.value, "verify_auth_challenge_response", null)

      dynamic "custom_email_sender" {
        for_each = lookup(lambda_config.value, "custom_email_sender", null) != null ? [lambda_config.value.custom_email_sender] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = custom_email_sender.value.lambda_version
        }
      }

      dynamic "custom_sms_sender" {
        for_each = lookup(lambda_config.value, "custom_sms_sender", null) != null ? [lambda_config.value.custom_sms_sender] : []
        content {
          lambda_arn     = custom_sms_sender.value.lambda_arn
          lambda_version = custom_sms_sender.value.lambda_version
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.schema_attributes
    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = lookup(schema.value, "developer_only_attribute", false)
      mutable                  = lookup(schema.value, "mutable", true)
      name                     = schema.value.name
      required                 = lookup(schema.value, "required", false)

      dynamic "string_attribute_constraints" {
        for_each = lookup(schema.value, "string_attribute_constraints", null) != null ? [schema.value.string_attribute_constraints] : []
        content {
          min_length = lookup(string_attribute_constraints.value, "min_length", null)
          max_length = lookup(string_attribute_constraints.value, "max_length", null)
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = lookup(schema.value, "number_attribute_constraints", null) != null ? [schema.value.number_attribute_constraints] : []
        content {
          min_value = lookup(number_attribute_constraints.value, "min_value", null)
          max_value = lookup(number_attribute_constraints.value, "max_value", null)
        }
      }
    }
  }
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_names)

  name                                 = each.value
  user_pool_id                         = aws_cognito_user_pool.this.id
  generate_secret                      = var.generate_secret
  access_token_validity                = var.token_validities.access_token
  id_token_validity                    = var.token_validities.id_token
  refresh_token_validity               = var.token_validities.refresh_token
  enable_token_revocation              = var.enable_token_revocation
  allowed_oauth_flows_user_pool_client = var.allowed_oauth_flows_user_pool_client
  explicit_auth_flows                  = var.explicit_auth_flows
  prevent_user_existence_errors        = var.prevent_user_existence_errors
  allowed_oauth_flows                  = var.allowed_oauth_flows
  allowed_oauth_scopes                 = var.allowed_oauth_scopes
  callback_urls                        = var.callback_urls
  logout_urls                          = var.logout_urls
  supported_identity_providers         = var.supported_identity_providers
  read_attributes                      = var.read_attributes
  write_attributes                     = var.write_attributes

  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }
}

resource "aws_cognito_user_group" "this" {
  count = local.has_group_name ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn
}

resource "aws_cognito_user_pool_domain" "this" {
  count = local.has_domain_name ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.certificate_arn
}

resource "aws_route53_record" "domain" {
  count = (var.create_route53_record && local.has_domain_name && var.route53_zone_id != null && var.route53_zone_id != "") ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = local.cloudfront_zone
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  type        = string
  description = "Name tag for the VPC"
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  type        = string
  description = "Name tag for the Internet Gateway"
  default     = "devops-project-igw"
}

variable "route_table_name" {
  type        = string
  description = "Name tag for the route table"
  default     = "DevOps-project-RT"
}

variable "public_subnet_id_name" {
  type        = string
  description = "Identifier name for the public subnet"
  default     = "subnet_a"
}

variable "nat_gw_name" {
  type        = string
  description = "Name tag for the NAT Gateway"
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  type        = string
  description = "Public IPv4 pool for Elastic IP allocation"
  default     = "amazon"
}

variable "subnet_a_cidr" {
  type        = string
  description = "CIDR block for Subnet A"
  default     = "10.0.1.0/24"
}

variable "subnet_a_name" {
  type        = string
  description = "Name tag for Subnet A"
  default     = "Subnet-A-Public"
}

variable "subnet_a_map_public_ip" {
  type        = bool
  description = "Enable/disable public IP mapping on launch for Subnet A"
  default     = false
}

variable "subnet_b_cidr" {
  type        = string
  description = "CIDR block for Subnet B"
  default     = "10.0.2.0/24"
}

variable "subnet_b_name" {
  type        = string
  description = "Name tag for Subnet B"
  default     = "Subnet-B-Private"
}

variable "subnet_b_map_public_ip" {
  type        = bool
  description = "Enable/disable public IP mapping on launch for Subnet B"
  default     = false
}

variable "subnet_c_cidr" {
  type        = string
  description = "CIDR block for Subnet C"
  default     = "10.0.3.0/24"
}

variable "subnet_c_name" {
  type        = string
  description = "Name tag for Subnet C"
  default     = "Subnet-C-Private"
}

variable "subnet_c_map_public_ip" {
  type        = bool
  description = "Enable/disable public IP mapping on launch for Subnet C"
  default     = false
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = var.subnet_a_map_public_ip

  tags = {
    Name       = var.subnet_a_name
    Identifier = var.public_subnet_id_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = var.subnet_b_map_public_ip

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = var.subnet_c_map_public_ip

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool
  depends_on       = [aws_internet_gateway.igw]

  tags = {
    Name = "${var.nat_gw_name}-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id
  depends_on    = [aws_internet_gateway.igw]

  tags = {
    Name = var.nat_gw_name
  }
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Custom security group allowing egress only within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway"
  value       = aws_nat_gateway.nat.public_ip
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  type        = string
  description = "Name of the AWS Backup vault"
  default     = "my-backup-vault"
}

variable "backup_tag_key" {
  type        = string
  description = "Resource tag key used to assign resources to backup plans"
  default     = "backup"
}

variable "daily_schedule" {
  type        = string
  description = "Cron expression for daily backup schedule"
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  type        = string
  description = "Cron expression for weekly backup schedule"
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  type        = string
  description = "Cron expression for monthly backup schedule"
  default     = "cron(0 12 1 * ? *)"
}

variable "enable_continuous_backup" {
  type        = bool
  description = "Enable point-in-time recovery / continuous backup for supported resources in daily plan"
  default     = false
}

variable "enable_notifications" {
  type        = bool
  description = "Conditionally enable SNS notifications on the backup vault"
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  description = "The ARN of the SNS topic for backup vault notifications"
  default     = ""
}

variable "notification_events" {
  type        = list(string)
  description = "List of backup vault event types that trigger notifications"
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

variable "tags" {
  type        = map(string)
  description = "Default tags to apply to all supported backup resources"
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "aws_kms_key" "backup_vault_key" {
  description             = "Customer managed KMS key for AWS Backup vault encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAWSBackupServiceOperations"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "backup_vault_key_alias" {
  name          = "alias/${var.vault_name}-key"
  target_key_id = aws_kms_key.backup_vault_key.key_id
}

resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup_vault_key.arn
  tags        = var.tags
}

resource "aws_iam_role" "backup_role" {
  name = "${var.vault_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_policy_attach" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "daily" {
  name = "${var.vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_selection" "daily" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }
}

resource "aws_backup_plan" "weekly" {
  name = "${var.vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = 31
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_selection" "weekly" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }
}

resource "aws_backup_plan" "monthly" {
  name = "${var.vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = 366
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_selection" "monthly" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }
}

resource "aws_backup_vault_notifications" "notifications" {
  count               = var.enable_notifications && var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.notification_events
}

output "backup_vault_name" {
  description = "The name of the AWS Backup vault"
  value       = aws_backup_vault.main.name
}

output "backup_vault_arn" {
  description = "The ARN of the AWS Backup vault"
  value       = aws_backup_vault.main.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS key encrypting the AWS Backup vault"
  value       = aws_kms_key.backup_vault_key.arn
}

output "iam_role_arn" {
  description = "The ARN of the IAM role assumed by AWS Backup"
  value       = aws_iam_role.backup_role.arn
}

output "daily_plan_id" {
  description = "The ID of the daily backup plan"
  value       = aws_backup_plan.daily.id
}

output "daily_plan_arn" {
  description = "The ARN of the daily backup plan"
  value       = aws_backup_plan.daily.arn
}

output "weekly_plan_id" {
  description = "The ID of the weekly backup plan"
  value       = aws_backup_plan.weekly.id
}

output "weekly_plan_arn" {
  description = "The ARN of the weekly backup plan"
  value       = aws_backup_plan.weekly.arn
}

output "monthly_plan_id" {
  description = "The ID of the monthly backup plan"
  value       = aws_backup_plan.monthly.id
}

output "monthly_plan_arn" {
  description = "The ARN of the monthly backup plan"
  value       = aws_backup_plan.monthly.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for infrastructure deployment"
  default     = "us-east-1"
}

variable "env" {
  type        = string
  description = "Environment identifier"
  default     = "test"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets"
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets"
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  type        = map(string)
  description = "Common tags applied to all resources"
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.common_tags,
    {
      Name   = "${var.env}-vpc"
      Region = data.aws_region.current.name
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index + 1}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index + 1}"
    }
  )
}

resource "aws_route" "private_nat_gateway" {
  count                  = length(var.private_subnet_cidrs)
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnet_cidrs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create_eks" {
  description = "Controls whether the EKS cluster should be created."
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster. Defaults to 'eks-cluster' if empty."
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster."
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "The authentication mode for the EKS cluster access config."
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "subnet_ids" {
  description = "List of subnet IDs for worker nodes and control plane fallback."
  type        = list(string)
  default     = []
}

variable "control_plane_subnet_ids" {
  description = "List of subnet IDs explicitly dedicated for the control plane."
  type        = list(string)
  default     = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name = var.cluster_name != "" ? var.cluster_name : "eks-cluster"
  resolved_subnets = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : (
    length(var.subnet_ids) > 0 ? var.subnet_ids : aws_subnet.eks[*].id
  )
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "eks" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.cluster_name}-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-rt"
  }
}

resource "aws_route_table_association" "eks" {
  count          = 2
  subnet_id      = aws_subnet.eks[count.index].id
  route_table_id = aws_route_table.public.id
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json

  tags = {
    Name = "eks-cluster"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_eks_cluster" "main" {
  count    = var.create_eks ? 1 : 0
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids = local.resolved_subnets
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountId  = data.aws_caller_identity.current.account_id
    UserId     = data.aws_caller_identity.current.user_id
  }
}

data "aws_iam_policy_document" "cicd_user_permissions" {
  statement {
    sid    = "CodeBuildReadOnly"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:BatchGetProjects",
      "codebuild:BatchGetReportGroups",
      "codebuild:BatchGetReports",
      "codebuild:ListBuildBatches",
      "codebuild:ListBuildBatchesForProject",
      "codebuild:ListBuilds",
      "codebuild:ListBuildsForProject",
      "codebuild:ListProjects",
      "codebuild:ListReportGroups",
      "codebuild:ListReports",
      "codebuild:ListReportsForReportGroup"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeCommitReadOnly"
    effect = "Allow"
    actions = [
      "codecommit:BatchGetRepositories",
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:ListBranches",
      "codecommit:ListRepositories"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchMetricsReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EventBridgeReadOnly"
    effect = "Allow"
    actions = [
      "events:DescribeRule",
      "events:ListRuleNamesByTarget",
      "events:ListRules",
      "events:ListTargetsByRule"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsReadOnly"
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:FilterLogEvents",
      "logs:GetLogEvents"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeStarConnectionsUserAccess"
    effect = "Allow"
    actions = [
      "codestar-connections:GetConnection",
      "codestar-connections:ListConnections"
    ]
    resources = ["arn:aws:codestar-connections:*:*:connection/*"]
  }

  statement {
    sid    = "CodeStarNotificationsPowerUserAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:DescribeNotificationRule"
    ]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "codestar-notifications:NotificationsForResource"
      values   = ["arn:aws:codebuild:*"]
    }
  }

  statement {
    sid    = "CodeStarNotificationsListAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:ListEventTypes",
      "codestar-notifications:ListNotificationRules",
      "codestar-notifications:ListTargets"
    ]
    resources = ["*"]
  }
}

# Dev Environment User
resource "aws_iam_user" "dev_user" {
  name          = "DevUser-rwwise.dev"
  path          = "/system/"
  force_destroy = false
  tags          = local.common_tags
}

resource "aws_iam_access_key" "dev_access_key" {
  user   = aws_iam_user.dev_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "dev_user_policy" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev_user.name
  policy = data.aws_iam_policy_document.cicd_user_permissions.json
}

# Test Environment User
resource "aws_iam_user" "test_user" {
  name          = "TestUser-rwwise.dev"
  path          = "/system/"
  force_destroy = false
  tags          = local.common_tags
}

resource "aws_iam_access_key" "test_access_key" {
  user   = aws_iam_user.test_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "test_user_policy" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test_user.name
  policy = data.aws_iam_policy_document.cicd_user_permissions.json
}

# Prod Environment User
resource "aws_iam_user" "prod_user" {
  name          = "ProdUser-rwwise.dev"
  path          = "/system/"
  force_destroy = false
  tags          = local.common_tags
}

resource "aws_iam_access_key" "prod_access_key" {
  user   = aws_iam_user.prod_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "prod_user_policy" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod_user.name
  policy = data.aws_iam_policy_document.cicd_user_permissions.json
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.95.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

variable "name" {
  description = "The name of the EventBridge module and custom event bus. If null or empty, falls back to 'default'."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to assign to resources."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "Configuration map for the event bus, supporting optional event_source_name."
  type        = map(any)
  default     = {}
  validation {
    condition     = var.bus != null
    error_message = "The bus configuration map must not be null."
  }
}

variable "rules" {
  description = "List of EventBridge rules to create. Each item must contain at least a 'name' key, with optional 'description', 'event_pattern', and 'schedule_expression'."
  type        = list(any)
  default     = []
  validation {
    condition     = var.rules != null
    error_message = "The rules list must not be null."
  }
}

variable "targets" {
  description = "List of EventBridge targets to create. Each item must contain 'rule' and 'arn', and optionally 'target_id'."
  type        = list(any)
  default     = []
  validation {
    condition     = var.targets != null
    error_message = "The targets list must not be null."
  }
}

locals {
  effective_name     = (var.name != null && var.name != "") ? var.name : "default"
  create_custom_bus  = local.effective_name != "default"
  bus_name           = local.create_custom_bus ? aws_cloudwatch_event_bus.bus[0].name : "default"
  event_source_name  = lookup(var.bus, "event_source_name", null)

  rules_map = {
    for idx, rule in var.rules :
    rule.name => {
      name                = rule.name
      description         = lookup(rule, "description", null)
      event_pattern       = lookup(rule, "event_pattern", null)
      schedule_expression = lookup(rule, "schedule_expression", null)
    }
  }

  targets_map = {
    for idx, target in var.targets :
    "${target.rule}-${lookup(target, "target_id", tostring(idx))}" => {
      rule      = target.rule
      arn       = target.arn
      target_id = lookup(target, "target_id", null)
    }
  }
}

resource "aws_cloudwatch_event_bus" "bus" {
  count             = local.create_custom_bus ? 1 : 0
  name              = local.effective_name
  event_source_name = local.event_source_name
  tags              = var.tags
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

data "aws_iam_policy_document" "invoke_targets" {
  statement {
    sid    = "InvokeTargets"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "states:StartExecution"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "invoke" {
  name               = "${local.effective_name}-invoke"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  tags               = var.tags

  inline_policy {
    name   = "${local.effective_name}-invoke-targets"
    policy = data.aws_iam_policy_document.invoke_targets.json
  }
}

resource "aws_cloudwatch_event_rule" "rules" {
  for_each            = local.rules_map
  name                = each.value.name
  event_bus_name      = local.bus_name
  description         = each.value.description
  event_pattern       = each.value.event_pattern
  schedule_expression = each.value.schedule_expression
  tags                = var.tags
}

resource "aws_cloudwatch_event_target" "targets" {
  for_each       = local.targets_map
  event_bus_name = local.bus_name
  rule           = each.value.rule
  target_id      = each.value.target_id
  arn            = each.value.arn
  role_arn       = can(regex("stateMachine", each.value.arn)) ? aws_iam_role.invoke.arn : null

  depends_on = [aws_cloudwatch_event_rule.rules]
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "name" {
  type        = string
  description = "Base name identifier for backup resources"
  default     = "default"
}

variable "kms_key_arn" {
  type        = string
  description = "Server-side encryption KMS key ARN for the backup vault. Null uses the default AWS Backup key."
  default     = null
}

variable "vault_policy" {
  type        = string
  description = "Access policy document for the backup vault in JSON format."
  default     = ""
}

variable "schedule" {
  type        = string
  description = "CRON or rate expression specifying the backup frequency."
  default     = "cron(0 12 * * ? *)"
}

variable "start_window" {
  type        = number
  description = "The amount of time in minutes before a backup is canceled if it doesn't start."
  default     = 60
}

variable "completion_window" {
  type        = number
  description = "The amount of time in minutes AWS Backup attempts a backup before canceling, if not completed."
  default     = 120
}

variable "cold_storage_after" {
  type        = number
  description = "Number of days after creation that a recovery point moves to cold storage."
  default     = 30
}

variable "delete_after" {
  type        = number
  description = "Number of days after creation that a recovery point is deleted."
  default     = 120
}

variable "destination_vaults" {
  type = map(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number)
    delete_after          = optional(number)
  }))
  description = "Map of cross-vault copy action configurations."
  default     = {}
}

variable "selection_tag_type" {
  type        = string
  description = "An operation, such as STRINGEQUALS, that is applied to key-value pairs for resource selection."
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  type        = string
  description = "The key in a key-value pair to identify resources for backup selection."
  default     = "Backup"
}

variable "selection_tag_value" {
  type        = string
  description = "The value in a key-value pair to identify resources for backup selection."
  default     = "true"
}

variable "sns_topic_arn" {
  type        = string
  description = "The ARN of the SNS topic for backup vault notifications."
  default     = ""
}

variable "backup_vault_events" {
  type        = list(string)
  description = "An array of events that trigger a notification from the backup vault."
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  job_tag_value  = "${var.name}-backup"
  vault_name     = "vault-${var.name}-backup"
  plan_name      = "plan-${var.name}-backup"
  rule_name      = "rule-${var.name}-backup"
  selection_name = "selection-${var.name}-backup"
}

# -----------------------------------------------------------------------------
# IAM Service Role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AssumeRoleForAWSBackup"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name_prefix        = "aws-backup-"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Job = local.job_tag_value
  }
}

resource "aws_iam_role_policy_attachment" "backup_default" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# -----------------------------------------------------------------------------
# Backup Vault
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "main" {
  name        = local.vault_name
  kms_key_arn = var.kms_key_arn

  tags = {
    Job = local.job_tag_value
  }
}

resource "aws_backup_vault_policy" "main" {
  count             = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "main" {
  count               = var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

# -----------------------------------------------------------------------------
# Backup Plan & Rule
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "main" {
  name = local.plan_name

  rule {
    rule_name         = local.rule_name
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = {
      Job = local.job_tag_value
    }

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    dynamic "copy_action" {
      for_each = var.destination_vaults
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.cold_storage_after != null || copy_action.value.delete_after != null ? [1] : []
          content {
            cold_storage_after = copy_action.value.cold_storage_after
            delete_after       = copy_action.value.delete_after
          }
        }
      }
    }
  }

  tags = {
    Job = local.job_tag_value
  }
}

# -----------------------------------------------------------------------------
# Backup Selection
# -----------------------------------------------------------------------------

resource "aws_backup_selection" "main" {
  name         = local.selection_name
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn

  condition {}

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "backup_vault_id" {
  description = "The name of the backup vault"
  value       = aws_backup_vault.main.id
}

output "backup_vault_arn" {
  description = "The ARN of the backup vault"
  value       = aws_backup_vault.main.arn
}

output "backup_plan_id" {
  description = "The ID of the backup plan"
  value       = aws_backup_plan.main.id
}

output "backup_plan_arn" {
  description = "The ARN of the backup plan"
  value       = aws_backup_plan.main.arn
}

output "backup_role_arn" {
  description = "The ARN of the IAM role utilized by AWS Backup"
  value       = aws_iam_role.backup.arn
}

output "backup_selection_id" {
  description = "The identifier of the backup selection"
  value       = aws_backup_selection.main.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "create" {
  description = "Whether to create a new Transit Gateway or look up an existing one."
  type        = bool
  default     = true
}

variable "id" {
  description = "The ID of an existing Transit Gateway to look up when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "The name of the Transit Gateway, used for tagging and lookup filter when create is false."
  type        = string
  default     = "main-transit-gateway"
}

variable "description" {
  description = "Description of the Transit Gateway."
  type        = string
  default     = "Transit Gateway managed by Terraform"
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether attachment requests are automatically accepted."
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "Whether DNS support is enabled."
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "Whether Equal Cost Multipath (ECMP) routing is enabled for VPN connections."
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the transit gateway."
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrnetmask(cidr)) || can(cidrhost(cidr, 0))
    ])
    error_message = "All entries in transit_gateway_cidr_blocks must be valid IPv4 or IPv6 CIDR notations."
  }
}

variable "route_tables" {
  description = "Map of route tables to create or look up."
  type = map(object({
    create = optional(bool, true)
    tags   = optional(map(string), {})
  }))
  default = {}
}

variable "ram_resource_share_name" {
  description = "Name of the RAM resource share. Defaults to var.name if null."
  type        = string
  default     = null
}

variable "shared_principals" {
  description = "Map of external principals (e.g., AWS account IDs, OU ARNs) to share the Transit Gateway with."
  type = map(object({
    principal = string
  }))
  default = {}
}

variable "tags" {
  description = "Global tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "local_tags" {
  description = "Additional tags specific to the Transit Gateway resource."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  tgw_id = var.create ? aws_ec2_transit_gateway.this[0].id : (
    var.id != null ? data.aws_ec2_transit_gateway.by_id[0].id : data.aws_ec2_transit_gateway.by_name[0].id
  )

  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : (
    var.id != null ? data.aws_ec2_transit_gateway.by_id[0].arn : data.aws_ec2_transit_gateway.by_name[0].arn
  )

  tgw_name = var.name != null ? var.name : "tgw"

  merged_tgw_tags = merge(
    var.tags,
    var.local_tags,
    {
      "Name" = local.tgw_name
    }
  )

  route_tables_to_create = {
    for k, v in var.route_tables : k => v if coalesce(v.create, true)
  }

  route_tables_to_lookup = {
    for k, v in var.route_tables : k => v if !coalesce(v.create, true)
  }

  ram_share_name = coalesce(var.ram_resource_share_name, local.tgw_name)
  enable_ram     = length(var.shared_principals) > 0
}

# -----------------------------------------------------------------------------
# Transit Gateway (Resource or Data Source)
# -----------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description                     = var.description
  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = local.merged_tgw_tags
}

data "aws_ec2_transit_gateway" "by_id" {
  count = !var.create && var.id != null ? 1 : 0

  id = var.id
}

data "aws_ec2_transit_gateway" "by_name" {
  count = !var.create && var.id == null ? 1 : 0

  filter {
    name   = "tag:Name"
    values = [var.name]
  }
}

# -----------------------------------------------------------------------------
# Transit Gateway Route Tables
# -----------------------------------------------------------------------------

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_create

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.tags,
    {
      "Name" = coalesce(lookup(each.value.tags, "Name", null), each.key, local.tgw_name)
    }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_lookup

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(lookup(each.value.tags, "Name", null), each.key, local.tgw_name)]
  }
}

# -----------------------------------------------------------------------------
# AWS RAM Resource Sharing
# -----------------------------------------------------------------------------

resource "aws_ram_resource_share" "this" {
  count = local.enable_ram ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge(
    var.tags,
    {
      "Name" = local.ram_share_name
    }
  )
}

resource "aws_ram_resource_association" "this" {
  count = local.enable_ram ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = local.enable_ram ? var.shared_principals : {}

  principal          = each.value.principal
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "transit_gateway_id" {
  description = "The ID of the Transit Gateway."
  value       = local.tgw_id
}

output "transit_gateway_arn" {
  description = "The ARN of the Transit Gateway."
  value       = local.tgw_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of route table identifiers to their resolved IDs."
  value = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
  )
}

output "ram_resource_share_id" {
  description = "The ID of the RAM resource share, if created."
  value       = try(aws_ram_resource_share.this[0].id, null)
}

output "ram_resource_share_arn" {
  description = "The ARN of the RAM resource share, if created."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Shared KMS Key for AWS Backup Vaults
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowAWSBackupServiceKeyUse"
    effect    = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "backup_key" {
  description             = "Shared KMS key for tiered AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "backup-vaults-shared-key"
  }
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/aws-backup-tiered-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

# -----------------------------------------------------------------------------
# Shared IAM Role for AWS Backup
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role_policy" {
  statement {
    sid     = "AssumeRoleForBackupService"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "bronze_backup_role" {
  name               = "Bronze_Backup_Role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role_policy.json

  tags = {
    Name = "Bronze_Backup_Role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_service_role_policy_backup" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_service_role_policy_restores" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# -----------------------------------------------------------------------------
# Bronze Tier
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "bronze_vault" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "Bronze_Backup_Vault"
    Tier = "bronze"
  }
}

resource "aws_backup_plan" "bronze_plan" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze_vault.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }

  tags = {
    Name = "Bronze_Backup"
    Tier = "bronze"
  }
}

resource "aws_backup_selection" "bronze_selection" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze_plan.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

# -----------------------------------------------------------------------------
# Silver Tier
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "silver_vault" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "Silver_Backup_Vault"
    Tier = "silver"
  }
}

resource "aws_backup_plan" "silver_plan" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver_vault.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }

  tags = {
    Name = "Silver_Backup_Plan"
    Tier = "silver"
  }
}

resource "aws_backup_selection" "silver_selection" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver_plan.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

# -----------------------------------------------------------------------------
# Gold Tier
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "gold_vault" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "Gold_Backup_Vault"
    Tier = "gold"
  }
}

resource "aws_backup_plan" "gold_plan" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_vault.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_vault.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_vault.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }

  tags = {
    Name = "Gold_Backup"
    Tier = "gold"
  }
}

resource "aws_backup_selection" "gold_selection" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold_plan.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

# -----------------------------------------------------------------------------
# Premium Tier
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "premium_vault" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "Premium"
    Tier = "premium"
  }
}

resource "aws_backup_plan" "premium_plan" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium_vault.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium_vault.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium_vault.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium_vault.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }

  tags = {
    Name = "Premium"
    Tier = "premium"
  }
}

resource "aws_backup_selection" "premium_selection" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium_plan.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "aws_region" {
  description = "The AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "iam_role_name" {
  description = "The name of the IAM role created for Prisma Cloud integration."
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Boolean flag determining whether to attach the remediation (read-write) policy."
  type        = bool
  default     = false
}

provider "aws" {
  region = var.aws_region
}

provider "random" {}

resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    sid     = "PrismaCloudAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::188619942792:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.external_id.result]
    }
  }
}

resource "aws_iam_role" "prisma_cloud" {
  name               = var.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json

  tags = {
    Name    = var.iam_role_name
    Service = "PrismaCloud"
  }
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

data "aws_iam_policy_document" "prisma_read_only" {
  statement {
    sid    = "PrismaCloudReadOnlyPermissions"
    effect = "Allow"
    actions = [
      "apigateway:GET",
      "cognito-identity:ListTagsForResource",
      "cognito-idp:ListTagsForResource",
      "ecr:DescribeImages",
      "ecr:GetLifecyclePolicy",
      "elasticbeanstalk:ListTagsForResource",
      "elasticfilesystem:DescribeTags",
      "elasticmapreduce:ListSecurityConfigurations",
      "glacier:GetVaultLock",
      "glacier:ListTagsForVault",
      "glue:GetSecurityConfigurations",
      "logs:GetLogEvents",
      "mq:describeBroker",
      "mq:listBrokers",
      "ram:GetResourceShares",
      "secretsmanager:DescribeSecret",
      "sns:listSubscriptions",
      "sqs:SendMessage",
      "ssm:GetParameters",
      "ssm:ListTagsForResource",
      "wafv2:ListResourcesForWebACL",
      "wafv2:ListWebACLs"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "prisma_read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud.id
  policy = data.aws_iam_policy_document.prisma_read_only.json
}

data "aws_iam_policy_document" "prisma_remediation" {
  count = var.read_write ? 1 : 0

  statement {
    sid    = "PrismaCloudRemediationPermissions"
    effect = "Allow"
    actions = [
      "iam:UpdateAccountPasswordPolicy",
      "ec2:ModifyImageAttribute",
      "rds:ModifyDBSnapshotAttribute",
      "s3:PutBucketAcl",
      "ec2:RevokeSecurityGroupIngress"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "prisma_remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.id
  policy = data.aws_iam_policy_document.prisma_remediation[0].json
}

output "role_arn" {
  description = "The Amazon Resource Name (ARN) of the Prisma Cloud cross-account IAM role."
  value       = aws_iam_role.prisma_cloud.arn
}

output "role_name" {
  description = "The name of the Prisma Cloud cross-account IAM role."
  value       = aws_iam_role.prisma_cloud.name
}

output "external_id" {
  description = "The generated external ID required for the Prisma Cloud integration."
  value       = random_string.external_id.result
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  type        = string
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "development_be_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_internet_gateway" "development_be_ig" {
  vpc_id = aws_vpc.development_be_vpc.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_subnet" "development_be_public_subnet" {
  vpc_id                  = aws_vpc.development_be_vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "development_be_private_subnet" {
  vpc_id                  = aws_vpc.development_be_vpc.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_route_table" "development_be_public_rt" {
  vpc_id = aws_vpc.development_be_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.development_be_ig.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "development_be_public" {
  subnet_id      = aws_subnet.development_be_public_subnet.id
  route_table_id = aws_route_table.development_be_public_rt.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for HTTP and restricted SSH/egress access"
  vpc_id      = aws_vpc.development_be_vpc.id

  ingress {
    description = "Allow SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.development_be_vpc.cidr_block]
  }

  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic restricted to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.development_be_vpc.cidr_block]
  }

  tags = {
    Name = "development-be-sg"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.development_be_vpc.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.development_be_public_subnet.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.development_be_private_subnet.id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the SNS topic and associated resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. If omitted, Terraform will assign a random name."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether `name` is used as a prefix."
  type        = bool
  default     = false
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "display_name" {
  description = "The display name for the SNS topic."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "If given, will be used to verify the signature of the message. Cannot be used with FIFO topics."
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: PassThrough, Active."
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "The SNS delivery policy JSON string."
  type        = string
  default     = null
}

variable "application_feedback" {
  description = "Map of IAM role ARNs and sample rates for application delivery status feedback."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "firehose_feedback" {
  description = "Map of IAM role ARNs and sample rates for Firehose delivery status feedback."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "http_feedback" {
  description = "Map of IAM role ARNs and sample rates for HTTP/HTTPS delivery status feedback."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "lambda_feedback" {
  description = "Map of IAM role ARNs and sample rates for Lambda delivery status feedback."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "sqs_feedback" {
  description = "Map of IAM role ARNs and sample rates for SQS delivery status feedback."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is created from documents/statements."
  type        = bool
  default     = true
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to enable the default topic policy allowing account owner access."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "An external topic policy JSON string to apply if create_topic_policy is false."
  type        = string
  default     = null
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported topic policy."
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that take precedence over all other topic policy documents."
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "A map of dynamic policy statements to merge into the generated topic policy."
  type        = any
  default     = {}
}

variable "create_subscription" {
  description = "Determines whether to create subscriptions configured in the subscriptions map."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of subscription configurations to attach to the topic."
  type        = any
  default     = {}
}

variable "data_protection_policy" {
  description = "A valid JSON data protection policy string. Only applicable to non-FIFO topics."
  type        = string
  default     = null
}

variable "tags" {
  description = "A mapping of tags to assign to resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name        = var.name != null && var.fifo_topic && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name
  name_prefix = var.name != null && var.fifo_topic && !endswith(var.name, ".fifo") ? "${var.name}-" : var.name

  signature_version = var.fifo_topic ? null : var.signature_version
}

# -----------------------------------------------------------------------------
# SNS Topic
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : local.name
  name_prefix = var.use_name_prefix ? local.name_prefix : null

  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  signature_version           = local.signature_version
  tracing_config              = var.tracing_config
  delivery_policy             = var.delivery_policy

  application_failure_feedback_role_arn    = lookup(var.application_feedback, "failure_role_arn", null)
  application_success_feedback_role_arn    = lookup(var.application_feedback, "success_role_arn", null)
  application_success_feedback_sample_rate = lookup(var.application_feedback, "success_sample_rate", null)

  firehose_failure_feedback_role_arn    = lookup(var.firehose_feedback, "failure_role_arn", null)
  firehose_success_feedback_role_arn    = lookup(var.firehose_feedback, "success_role_arn", null)
  firehose_success_feedback_sample_rate = lookup(var.firehose_feedback, "success_sample_rate", null)

  http_failure_feedback_role_arn    = lookup(var.http_feedback, "failure_role_arn", null)
  http_success_feedback_role_arn    = lookup(var.http_feedback, "success_role_arn", null)
  http_success_feedback_sample_rate = lookup(var.http_feedback, "success_sample_rate", null)

  lambda_failure_feedback_role_arn    = lookup(var.lambda_feedback, "failure_role_arn", null)
  lambda_success_feedback_role_arn    = lookup(var.lambda_feedback, "success_role_arn", null)
  lambda_success_feedback_sample_rate = lookup(var.lambda_feedback, "success_sample_rate", null)

  sqs_failure_feedback_role_arn    = lookup(var.sqs_feedback, "failure_role_arn", null)
  sqs_success_feedback_role_arn    = lookup(var.sqs_feedback, "success_role_arn", null)
  sqs_success_feedback_sample_rate = lookup(var.sqs_feedback, "success_sample_rate", null)

  tags = var.tags
}

# -----------------------------------------------------------------------------
# SNS Topic Policy
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "default" {
  count = var.create && var.create_topic_policy && var.enable_default_topic_policy ? 1 : 0

  statement {
    sid    = "__default_statement_ID"
    effect = "Allow"

    actions = [
      "sns:GetTopicAttributes",
      "sns:SetTopicAttributes",
      "sns:AddPermission",
      "sns:RemovePermission",
      "sns:DeleteTopic",
      "sns:Subscribe",
      "sns:ListSubscriptionsByTopic",
      "sns:Publish",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    resources = [
      aws_sns_topic.this[0].arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents = concat(
    var.enable_default_topic_policy && length(data.aws_iam_policy_document.default) > 0 ? [data.aws_iam_policy_document.default[0].json] : [],
    var.source_topic_policy_documents
  )
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.topic_policy_statements
    content {
      sid           = lookup(statement.value, "sid", null)
      effect        = lookup(statement.value, "effect", "Allow")
      actions       = lookup(statement.value, "actions", null)
      not_actions   = lookup(statement.value, "not_actions", null)
      resources     = lookup(statement.value, "resources", [aws_sns_topic.this[0].arn])
      not_resources = lookup(statement.value, "not_resources", null)

      dynamic "principals" {
        for_each = lookup(statement.value, "principals", [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = lookup(statement.value, "not_principals", [])
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = lookup(statement.value, "conditions", lookup(statement.value, "condition", []))
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && (var.create_topic_policy || var.topic_policy != null) ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.this[0].json : var.topic_policy
}

# -----------------------------------------------------------------------------
# SNS Topic Subscriptions
# -----------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create && var.create_subscription ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn
  protocol  = each.value.protocol
  endpoint  = each.value.endpoint

  endpoint_auto_confirms          = lookup(each.value, "endpoint_auto_confirms", null)
  confirmation_timeout_in_minutes = lookup(each.value, "confirmation_timeout_in_minutes", null)
  raw_message_delivery            = lookup(each.value, "raw_message_delivery", null)
  filter_policy                   = lookup(each.value, "filter_policy", null)
  filter_policy_scope             = lookup(each.value, "filter_policy_scope", null)
  delivery_policy                 = lookup(each.value, "delivery_policy", null)
  redrive_policy                  = lookup(each.value, "redrive_policy", null)
  subscription_role_arn           = lookup(each.value, "subscription_role_arn", null)
}

# -----------------------------------------------------------------------------
# SNS Topic Data Protection Policy
# -----------------------------------------------------------------------------

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "topic_arn" {
  description = "The ARN of the SNS topic."
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_id" {
  description = "The ID of the SNS topic."
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_owner" {
  description = "The AWS Account ID of the SNS topic owner."
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_policy" {
  description = "The IAM policy document applied to the SNS topic."
  value       = try(aws_sns_topic_policy.this[0].policy, null)
}

output "subscriptions" {
  description = "Map of created SNS topic subscription resources."
  value       = aws_sns_topic_subscription.this
}

output "data_protection_policy_id" {
  description = "The ID of the SNS topic data protection policy."
  value       = try(aws_sns_topic_data_protection_policy.this[0].id, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "bucket_name" {
  description = "Optional custom bucket name. Defaults to 'corebucket-' with random hex if null."
  type        = string
  default     = null
}

variable "use_prefix" {
  description = "Whether to append an extra random string suffix to the bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who pays for the download and request fees. Defaults to 'BucketOwner'."
  type        = string
  default     = "BucketOwner"
}

variable "enable_encryption" {
  description = "Enable server-side encryption with AWS KMS."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "Custom KMS Key ARN to use. If empty and enable_encryption is true, a rotating CMK is created."
  type        = string
  default     = ""
}

variable "versioning_enabled" {
  description = "Enable versioning on the S3 bucket. Automatically enabled if replication or object lock is configured."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "MFA Delete status: 'Enabled' or 'Disabled'."
  type        = string
  default     = "Disabled"
}

variable "force_destroy" {
  description = "Boolean indicating whether to allow bucket deletion even if it contains objects."
  type        = bool
  default     = false
}

variable "block_public_access" {
  description = "Enforce blocking of all public access to the bucket."
  type        = bool
  default     = true
}

variable "bucket_policy_json" {
  description = "Optional additional bucket policy in JSON format."
  type        = string
  default     = ""
}

variable "transfer_acceleration_status" {
  description = "Transfer acceleration status: 'Enabled' or 'Suspended'."
  type        = string
  default     = "Suspended"
}

variable "logging_configuration" {
  description = "Map containing target_bucket and optional target_prefix for access logging."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "logs/")
  })
  default = null
}

variable "website_configuration" {
  description = "Configuration for static website hosting."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules for the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules for the bucket."
  type = list(object({
    id      = string
    status  = string
    prefix  = optional(string)
    tags    = optional(map(string))
    transitions = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })), [])
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })), [])
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Configuration for S3 Object Lock."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_rules" {
  description = "List of replication rules for cross-region replication."
  type = list(object({
    id                      = string
    status                  = string
    priority                = optional(number)
    destination_bucket      = string
    destination_kms_key_arn = optional(string)
    storage_class           = optional(string)
    prefix                  = optional(string)
  }))
  default = []
}

variable "replication_role_arn" {
  description = "Existing IAM role ARN for replication. If empty and replication_rules are provided, a role is created."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to all supported resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Random Identifiers & Dynamic Name Resolution
# -----------------------------------------------------------------------------
resource "random_id" "name" {
  byte_length = 4
}

resource "random_id" "suffix" {
  byte_length = 3
}

locals {
  base_bucket_name = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.name.hex}"
  resolved_bucket_name = lower(
    var.use_prefix ? "${local.base_bucket_name}-${random_id.suffix.hex}" : local.base_bucket_name
  )

  needs_cmk = var.enable_encryption && var.kms_key_arn == ""
  effective_kms_key_arn = var.enable_encryption ? (
    local.needs_cmk ? aws_kms_key.s3_cmk[0].arn : var.kms_key_arn
  ) : null

  has_replication = length(var.replication_rules) > 0
  has_object_lock = var.object_lock_configuration != null
  effective_versioning_enabled = var.versioning_enabled || local.has_replication || local.has_object_lock

  create_replication_role = local.has_replication && var.replication_role_arn == ""
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key (CMK)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  count = local.needs_cmk ? 1 : 0

  statement {
    sid       = "Enable IAM User Permissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "Allow S3 Use of Key"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "s3_cmk" {
  count                   = local.needs_cmk ? 1 : 0
  description             = "Customer Managed Key for S3 bucket ${local.resolved_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = merge(
    var.tags,
    {
      "Name"   = "${local.resolved_bucket_name}-key"
      "Bucket" = local.resolved_bucket_name
    }
  )
}

resource "aws_kms_alias" "s3_cmk" {
  count         = local.needs_cmk ? 1 : 0
  name          = "alias/${substr(local.resolved_bucket_name, 0, 28)}-key"
  target_key_id = aws_kms_key.s3_cmk[0].key_id
}

# -----------------------------------------------------------------------------
# Primary S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket              = local.resolved_bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = local.has_object_lock

  tags = merge(
    var.tags,
    {
      "Name" = local.resolved_bucket_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Request Payment Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  payer  = var.request_payer
}

# -----------------------------------------------------------------------------
# Server-Side Encryption Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.enable_encryption ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.effective_kms_key_arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Public Access Block
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = var.block_public_access
  block_public_policy     = var.block_public_access
  ignore_public_acls      = var.block_public_access
  restrict_public_buckets = var.block_public_access
}

# -----------------------------------------------------------------------------
# Versioning Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status     = local.effective_versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete
  }
}

# -----------------------------------------------------------------------------
# Bucket Policy (Enforce TLS + Optional Custom Policy)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "enforce_tls" {
  statement {
    sid     = "EnforceTLSRequestsOnly"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = var.bucket_policy_json != "" ? var.bucket_policy_json : data.aws_iam_policy_document.enforce_tls.json

  depends_on = [aws_s3_bucket_public_access_block.main]
}

# -----------------------------------------------------------------------------
# Transfer Acceleration Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  status = var.transfer_acceleration_status
}

# -----------------------------------------------------------------------------
# Logging Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "main" {
  count  = var.logging_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  target_bucket = var.logging_configuration.target_bucket
  target_prefix = var.logging_configuration.target_prefix
}

# -----------------------------------------------------------------------------
# Static Website Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "index_document" {
    for_each = var.website_configuration.index_document != null ? [var.website_configuration.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website_configuration.error_document != null ? [var.website_configuration.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_configuration.redirect_all_requests_to != null ? [var.website_configuration.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }

  routing_rules = var.website_configuration.routing_rules
}

# -----------------------------------------------------------------------------
# CORS Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = (rule.value.prefix != null || rule.value.tags != null) ? [1] : []
        content {
          dynamic "and" {
            for_each = (rule.value.prefix != null && rule.value.tags != null && length(rule.value.tags) > 0) ? [1] : []
            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }

          prefix = (rule.value.prefix != null && (rule.value.tags == null || length(rule.value.tags) == 0)) ? rule.value.prefix : null
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Object Lock Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count  = local.has_object_lock ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]
}

# -----------------------------------------------------------------------------
# Replication IAM Role & Policy
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_replication_role ? 1 : 0

  statement {
    sid     = "S3ReplicationAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count              = local.create_replication_role ? 1 : 0
  name               = "CoreS3ReplicationRole_${local.resolved_bucket_name}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = merge(
    var.tags,
    {
      "Name"   = "CoreS3ReplicationRole_${local.resolved_bucket_name}"
      "Bucket" = local.resolved_bucket_name
    }
  )
}

data "aws_iam_policy_document" "replication_policy" {
  count = local.create_replication_role ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.main.arn]
  }

  statement {
    sid    = "SourceBucketObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.main.arn}/*"]
  }

  statement {
    sid    = "DestinationBucketReplicationPermissions"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [
      for rule in var.replication_rules : "${rule.destination_bucket}/*"
    ]
  }

  dynamic "statement" {
    for_each = [for rule in var.replication_rules : rule.destination_kms_key_arn if rule.destination_kms_key_arn != null && rule.destination_kms_key_arn != ""]
    content {
      sid       = "KmsEncryptDestination"
      effect    = "Allow"
      actions   = ["kms:Encrypt"]
      resources = [statement.value]
    }
  }

  dynamic "statement" {
    for_each = var.enable_encryption ? [1] : []
    content {
      sid       = "KmsDecryptSource"
      effect    = "Allow"
      actions   = ["kms:Decrypt"]
      resources = [local.effective_kms_key_arn]
    }
  }
}

resource "aws_iam_policy" "replication" {
  count       = local.create_replication_role ? 1 : 0
  name        = "CoreS3ReplicationPolicy_${local.resolved_bucket_name}"
  description = "Allows S3 to replicate objects from ${local.resolved_bucket_name}"
  policy      = data.aws_iam_policy_document.replication_policy[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = local.create_replication_role ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# -----------------------------------------------------------------------------
# Replication Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "main" {
  count  = local.has_replication ? 1 : 0
  bucket = aws_s3_bucket.main.id
  role   = var.replication_role_arn != "" ? var.replication_role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.prefix != null ? [rule.value.prefix] : []
        content {
          prefix = filter.value
        }
      }

      destination {
        bucket        = rule.value.destination_bucket
        storage_class = rule.value.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.destination_kms_key_arn != null && rule.value.destination_kms_key_arn != "" ? [rule.value.destination_kms_key_arn] : []
          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = var.enable_encryption ? [1] : []
        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.main,
    aws_iam_role_policy_attachment.replication
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.main.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.main.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.main.bucket_domain_name
}

output "bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = aws_s3_bucket.main.hosted_zone_id
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption."
  value       = local.effective_kms_key_arn
}

output "replication_role_arn" {
  description = "The ARN of the replication IAM role, if created."
  value       = local.create_replication_role ? aws_iam_role.replication[0].arn : var.replication_role_arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "random_suffix" {
  description = "Whether to append a random alphanumeric suffix to resource names."
  type        = bool
  default     = true
}

variable "random_suffix_length" {
  description = "Length of the random suffix to append when random_suffix is enabled."
  type        = number
  default     = 4
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name."
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name_prefix" {
  description = "Prefix for the IAM user name."
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name_prefix" {
  description = "Prefix for the IAM policy name."
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload the image file to the S3 bucket."
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Name of the local image file to upload."
  type        = string
  default     = "my-file.qcow2"
}

variable "create_folder" {
  description = "Whether to prefix the S3 object key with s3_folder."
  type        = bool
  default     = true
}

variable "s3_folder" {
  description = "S3 folder prefix to prepend to the uploaded image key."
  type        = string
  default     = "my-folder"
}

variable "create_iam_user" {
  description = "Whether to create the scoped IAM user, access key, and policy."
  type        = bool
  default     = true
}

resource "random_string" "suffix" {
  count   = var.random_suffix ? 1 : 0
  length  = var.random_suffix_length
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  suffix          = var.random_suffix ? "-${random_string.suffix[0].result}" : ""
  bucket_name     = "${var.bucket_name_prefix}${local.suffix}"
  iam_user_name   = "${var.iam_user_name_prefix}${local.suffix}"
  iam_policy_name = "${var.iam_policy_name_prefix}${local.suffix}"
  resolved_s3_key = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

resource "aws_kms_key" "s3_key" {
  description             = "Customer managed KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "${local.bucket_name}-kms-key"
  }
}

resource "aws_kms_alias" "s3_key_alias" {
  name          = "alias/${local.bucket_name}-key"
  target_key_id = aws_kms_key.s3_key.key_id
}

resource "aws_s3_bucket" "image_datastore" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_versioning" "image_datastore" {
  bucket = aws_s3_bucket.image_datastore.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "image_datastore" {
  bucket = aws_s3_bucket.image_datastore.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "image_datastore" {
  bucket = aws_s3_bucket.image_datastore.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_object" "image" {
  count      = var.upload_image ? 1 : 0
  bucket     = aws_s3_bucket.image_datastore.id
  key        = local.resolved_s3_key
  source     = "${path.module}/${var.image_filename}"
  kms_key_id = aws_kms_key.s3_key.arn

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.image_datastore,
    aws_s3_bucket_public_access_block.image_datastore
  ]
}

resource "aws_iam_user" "s3_reader" {
  count         = var.create_iam_user ? 1 : 0
  name          = local.iam_user_name
  path          = "/"
  force_destroy = true

  tags = {
    Name = local.iam_user_name
  }
}

resource "aws_iam_access_key" "s3_reader" {
  count = var.create_iam_user ? 1 : 0
  user  = aws_iam_user.s3_reader[0].name
}

data "aws_iam_policy_document" "s3_reader_permissions" {
  count = var.create_iam_user ? 1 : 0

  statement {
    sid       = "AllowListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.image_datastore.arn]
  }

  statement {
    sid       = "AllowReadObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.image_datastore.arn}/*"]
  }

  statement {
    sid       = "AllowKmsDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.s3_key.arn]
  }
}

resource "aws_iam_policy" "s3_reader" {
  count       = var.create_iam_user ? 1 : 0
  name        = local.iam_policy_name
  description = "Read-only access policy to S3 image datastore and associated KMS key"
  policy      = data.aws_iam_policy_document.s3_reader_permissions[0].json

  tags = {
    Name = local.iam_policy_name
  }
}

resource "aws_iam_user_policy_attachment" "s3_reader_attach" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.s3_reader[0].name
  policy_arn = aws_iam_policy.s3_reader[0].arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = var.default_tags
  }
}

variable "default_tags" {
  type        = map(string)
  description = "Default tags applied to all resources"
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

locals {
  name_prefix = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.14.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                     = "${local.name_prefix}-public-subnet-${count.index + 1}"
    "kubernetes.io/role/elb" = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = "${local.name_prefix}-nat-gw"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "${local.name_prefix}-private-subnet-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# ELB Regional Account IDs for classic ELB logging
locals {
  elb_account_map = {
    us-east-1      = "127311923021"
    us-east-2      = "033677994240"
    us-west-1      = "027434742980"
    us-west-2      = "797873946194"
    ca-central-1   = "985666609251"
    eu-central-1   = "054676820928"
    eu-west-1      = "156460612806"
    eu-west-2      = "652711504416"
    eu-west-3      = "009996457667"
    eu-north-1     = "897822967062"
    eu-south-1     = "638102146993"
    ap-east-1      = "754344448648"
    ap-northeast-1 = "582318560864"
    ap-northeast-2 = "600734575887"
    ap-northeast-3 = "383597477817"
    ap-southeast-1 = "114774131450"
    ap-southeast-2 = "783225338198"
    ap-south-1     = "718504428378"
    me-south-1     = "076674570228"
    sa-east-1      = "507241528042"
  }
  current_elb_account = lookup(local.elb_account_map, data.aws_region.current.name, "127311923021")

  bucket_name = var.bucket != null ? var.bucket : (var.bucket_prefix != null ? null : "my-s3-bucket-${data.aws_caller_identity.current.account_id}")

  # Determine if policy needs to be created
  attach_any_policy = var.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    (var.attach_policy && var.policy != null)
  )

  # Check if custom KMS key should be created
  create_kms_key = var.create_bucket && var.kms_key_arn == null && var.server_side_encryption_configuration == null
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "create_bucket" {
  description = "Controls if S3 bucket should be created"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "The name of the bucket. If omitted, bucket_prefix will be used."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A mapping of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who pays for the download and request fees. Valid values: BucketOwner, Requester."
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Manages S3 Bucket Ownership Controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  type        = string
  default     = "ObjectWriter"
}

variable "acl" {
  description = "The canned ACL to apply. Valid values are private, public-read, public-read-write, aws-exec-read, authenticated-read, bucket-owner-read, etc."
  type        = string
  default     = "private"
}

variable "versioning" {
  description = "Map containing versioning configuration: enabled (bool), mfa_delete (bool)."
  type = object({
    status     = optional(string, "Enabled")
    mfa_delete = optional(string, "Disabled")
  })
  default = null
}

variable "kms_key_arn" {
  description = "External KMS master key ID used for the SSE-KMS encryption. If not provided and no server_side_encryption_configuration is supplied, a KMS key is created."
  type        = string
  default     = null
}

variable "server_side_encryption_configuration" {
  description = "Map containing server-side encryption configuration."
  type        = any
  default     = null
}

variable "logging" {
  description = "Map containing access logging configuration: target_bucket, target_prefix."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "logs/")
  })
  default = null
}

variable "website" {
  description = "Map containing static website hosting configuration."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = null
}

variable "cors_rule" {
  description = "List of maps containing CORS rules."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rule" {
  description = "List of maps containing configuration of object lifecycle management."
  type = list(object({
    id                                     = string
    status                                 = string
    abort_incomplete_multipart_upload_days = optional(number)
    filter_prefix                          = optional(string)
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transitions = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Map containing S3 object locking configuration."
  type = object({
    object_lock_enabled = string
    rule = optional(object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    }))
  })
  default = null
}

variable "replication_configuration" {
  description = "Map containing cross-region replication configuration."
  type = object({
    role = optional(string)
    rules = list(object({
      id       = optional(string)
      status   = string
      priority = optional(number)
      filter   = optional(string)
      destination = object({
        bucket        = string
        storage_class = optional(string)
        account       = optional(string)
      })
    }))
  })
  default = null
}

variable "attach_public_policy" {
  description = "Controls if S3 bucket public access block should be created and applied."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "attach_policy" {
  description = "Controls if a custom policy document should be attached to the bucket."
  type        = bool
  default     = false
}

variable "policy" {
  description = "A valid bucket policy JSON document."
  type        = string
  default     = null
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket should deny non-SSL/insecure transport."
  type        = bool
  default     = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket should permit classic ELB log delivery."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket should permit ALB/NLB log delivery."
  type        = bool
  default     = false
}

# -----------------------------------------------------------------------------
# Customer-Managed KMS Key (when no SSE or external key is provided)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "s3" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Customer managed KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = merge(var.tags, {
    Name = "s3-encryption-key"
  })
}

resource "aws_kms_alias" "s3" {
  count         = local.create_kms_key ? 1 : 0
  name_prefix   = "alias/s3-key-"
  target_key_id = aws_kms_key.s3[0].key_id
}

# -----------------------------------------------------------------------------
# Primary S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count         = var.create_bucket ? 1 : 0
  bucket        = var.bucket_prefix == null ? local.bucket_name : null
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_configuration != null ? true : false

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Bucket Acceleration & Request Payer
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.create_bucket && var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.create_bucket && var.request_payer != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

# -----------------------------------------------------------------------------
# Public Access Block
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.create_bucket && var.attach_public_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# -----------------------------------------------------------------------------
# Ownership Controls & Canned ACL
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.create_bucket && var.control_object_ownership ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_acl" "this" {
  count  = var.create_bucket && var.control_object_ownership && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# -----------------------------------------------------------------------------
# Versioning
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count  = var.create_bucket && var.versioning != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = var.versioning.status
    mfa_delete = var.versioning.mfa_delete
  }
}

# -----------------------------------------------------------------------------
# Server-Side Encryption
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = var.server_side_encryption_configuration != null ? lookup(var.server_side_encryption_configuration.rule.apply_server_side_encryption_by_default, "sse_algorithm", "aws:kms") : "aws:kms"
      kms_master_key_id = var.server_side_encryption_configuration != null ? lookup(var.server_side_encryption_configuration.rule.apply_server_side_encryption_by_default, "kms_master_key_id", null) : (
        var.kms_key_arn != null ? var.kms_key_arn : (
          local.create_kms_key ? aws_kms_key.s3[0].arn : null
        )
      )
    }
    bucket_key_enabled = var.server_side_encryption_configuration != null ? lookup(var.server_side_encryption_configuration.rule, "bucket_key_enabled", true) : true
  }
}

# -----------------------------------------------------------------------------
# Access Logging
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count  = var.create_bucket && var.logging != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# -----------------------------------------------------------------------------
# Static Website Hosting
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.create_bucket && var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = var.website.index_document != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }

  routing_rules = var.website.routing_rules
}

# -----------------------------------------------------------------------------
# CORS Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.create_bucket && length(var.cors_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle Management Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = rule.value.filter_prefix != null ? rule.value.filter_prefix : ""
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          date                         = expiration.value.date
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          date          = transition.value.date
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Object Lock Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.create_bucket && var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  object_lock_enabled = var.object_lock_configuration.object_lock_enabled

  dynamic "rule" {
    for_each = var.object_lock_configuration.rule != null ? [var.object_lock_configuration.rule] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = rule.value.default_retention.days
        years = rule.value.default_retention.years
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Cross-Region Replication IAM Role & Configuration
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "replication_assume_role" {
  count = var.create_bucket && var.replication_configuration != null && var.replication_configuration.role == null ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count              = var.create_bucket && var.replication_configuration != null && var.replication_configuration.role == null ? 1 : 0
  name_prefix        = "s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = var.tags
}

data "aws_iam_policy_document" "replication_policy" {
  count = var.create_bucket && var.replication_configuration != null && var.replication_configuration.role == null ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.this[0].arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.this[0].arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [
      for rule in var.replication_configuration.rules :
      "${rule.destination.bucket}/*"
    ]
  }
}

resource "aws_iam_policy" "replication" {
  count       = var.create_bucket && var.replication_configuration != null && var.replication_configuration.role == null ? 1 : 0
  name_prefix = "s3-replication-policy-"
  policy      = data.aws_iam_policy_document.replication_policy[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = var.create_bucket && var.replication_configuration != null && var.replication_configuration.role == null ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.create_bucket && var.replication_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role != null ? var.replication_configuration.role : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
        account       = rule.value.destination.account
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Bucket Policies Construction
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "combined" {
  count = local.attach_any_policy ? 1 : 0

  # Custom policy string if provided
  source_policy_documents = (var.attach_policy && var.policy != null) ? [var.policy] : []

  # Insecure transport denial
  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid       = "DenyInsecureTransport"
      effect    = "Deny"
      actions   = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Classic ELB log delivery policy
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid       = "ELBLogDeliveryWrite"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.current_elb_account}:root"]
      }
    }
  }

  # ALB / NLB log delivery policy
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid       = "AWSLogDeliveryWrite"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid       = "AWSLogDeliveryAclCheck"
      effect    = "Allow"
      actions   = ["s3:GetBucketAcl"]
      resources = [aws_s3_bucket.this[0].arn]

      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = local.attach_any_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "s3_bucket_arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = try(aws_s3_bucket.this[0].arn, null)
}

output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = try(aws_s3_bucket.this[0].id, null)
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name. Will be of format bucketname.s3.amazonaws.com."
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, null)
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = try(aws_s3_bucket.this[0].hosted_zone_id, null)
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption."
  value       = local.create_kms_key ? try(aws_kms_key.s3[0].arn, null) : var.kms_key_arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.awsRegion
}

variable "projectPrefix" {
  type        = string
  description = "Project prefix applied to resource names and tags"
  default     = "f5-dcec"
}

variable "resourceOwner" {
  type        = string
  description = "Owner of the deployed infrastructure resources"
  default     = "f5-user"
}

variable "buildSuffix" {
  type        = string
  description = "Suffix string identifier for build tracking"
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  type        = bool
  description = "Specify true to enable public IPv4 auto-assignment in public subnets"
  default     = false
}

variable "awsRegion" {
  type        = string
  description = "AWS region for infrastructure deployment"
  default     = "us-east-1"
}

variable "awsAz1" {
  type        = string
  description = "Primary availability zone name override"
  default     = null
}

variable "awsAz2" {
  type        = string
  description = "Secondary availability zone name override"
  default     = null
}

variable "vpcMainCidr" {
  type        = string
  description = "CIDR block for the core VPC"
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  type        = string
  description = "CIDR block for public subnet in AZ 1"
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  type        = string
  description = "CIDR block for public subnet in AZ 2"
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  type        = string
  description = "CIDR block for management subnet in AZ 1"
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  type        = string
  description = "CIDR block for management subnet in AZ 2"
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  type        = string
  description = "CIDR block for private subnet in AZ 1"
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  type        = string
  description = "CIDR block for private subnet in AZ 2"
  default     = "10.1.120.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])
  az2 = coalesce(var.awsAz2, var.awsAz1, data.aws_availability_zones.available.names[1])

  common_tags = {
    Name        = local.name_prefix
    Environment = "testing"
    Owner       = var.resourceOwner
    Project     = var.projectPrefix
    Build       = var.buildSuffix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-pub-a"
    Type = "Public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-pub-b"
    Type = "Public"
  })
}

resource "aws_subnet" "mgmt_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubMgmtACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-mgmt-a"
    Type = "Management"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubMgmtBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-mgmt-b"
    Type = "Management"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-priv-a"
    Type = "Private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-priv-b"
    Type = "Private"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt-main"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be deployed."
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

variable "resource_name" {
  type        = string
  description = "Base name used for prefixing resource identifiers."
  default     = "benchmark"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "rule_count" {
  type        = number
  description = "The number of path-based routing listener rules to create."
  default     = 1
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.resource_name}-vpc"
  }
}

resource "aws_subnet" "internal" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.resource_name}-subnet-${count.index}"
  }
}

resource "aws_security_group" "alb" {
  name        = "${var.resource_name}-alb-sg"
  description = "Allow all traffic within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all ingress within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all egress within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_name}-alb-sg"
  }
}

resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name  = "${var.resource_name}.internal"
    organization = var.resource_name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb_cert" {
  private_key      = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem

  tags = {
    Name = "${var.resource_name}-cert"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.resource_name}-tg"
  port                 = 8080
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "instance"
  deregistration_delay = 300

  health_check {
    enabled             = true
    path                = "/health"
    port                = "8081"
    protocol            = "HTTP"
    interval            = 60
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = "${var.resource_name}-tg"
  }
}

resource "aws_lb" "internal" {
  name                       = "${var.resource_name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.internal[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.resource_name}-alb"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb_cert.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name = "${var.resource_name}-https-listener"
  }
}

resource "aws_lb_listener_rule" "path_routing" {
  count        = var.rule_count
  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.resource_name}-rule-${count.index}"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "trail_name" {
  type        = string
  description = "The name of the CloudTrail trail."
  default     = "management_trail"
}

variable "is_organization_trail" {
  type        = bool
  description = "Whether the trail is an AWS Organizations trail."
  default     = false
}

variable "cloudwatch_log_group_name" {
  type        = string
  description = "The name of the CloudWatch Log Group for CloudTrail logs."
  default     = "cloudtrail_logs"
}

variable "enable_kms" {
  type        = bool
  description = "Whether to use customer managed KMS key encryption for CloudTrail and S3."
  default     = true
}

variable "kms_key_alias" {
  type        = string
  description = "The alias for the customer managed CloudTrail KMS key."
  default     = "alias/cloudtrail_key"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

resource "random_string" "suffix" {
  length  = 12
  numeric = true
  special = false
  upper   = false
  lower   = false
}

data "aws_iam_policy_document" "kms_policy" {
  count = var.enable_kms ? 1 : 0

  statement {
    sid    = "EnableRootAndAdminManagement"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"]
    }
    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowS3ToUseKMSKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAccountUsersToDecryptLogs"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudtrail" {
  count                   = var.enable_kms ? 1 : 0
  description             = "Customer managed KMS key for CloudTrail audit logging encryption."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_policy[0].json
}

resource "aws_kms_alias" "cloudtrail" {
  count         = var.enable_kms ? 1 : 0
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket = "cloudtrail-bucket-${random_string.suffix.result}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null
    }
  }
}

data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid    = "EnforceTLSRequestsOnly"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.cloudtrail.arn,
      "${aws_s3_bucket.cloudtrail.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket     = aws_s3_bucket.cloudtrail.id
  policy     = data.aws_iam_policy_document.s3_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 0
}

data "aws_iam_policy_document" "cloudwatch_assume_role" {
  statement {
    sid    = "CloudTrailAssumeRole"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cw_role" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.cloudwatch_assume_role.json
}

data "aws_iam_policy_document" "cloudwatch_delivery_policy" {
  statement {
    sid    = "AWSCloudTrailCreateLogStreamAndPutEvents"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cw_policy" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cw_role.id
  policy = data.aws_iam_policy_document.cloudwatch_delivery_policy.json
}

resource "aws_cloudtrail" "management" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cw_role.arn

  kms_key_id = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_iam_role_policy.cloudtrail_cw_policy
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type        = string
  default     = ""
  description = "Optional repository namespace prefix."
}

variable "repository_name" {
  type        = string
  default     = "ecr"
  description = "Base repository name. If empty or null, a generated petname is used."
}

variable "image_tag_mutability" {
  type        = string
  default     = "IMMUTABLE"
  description = "Image tag mutability setting (MUTABLE or IMMUTABLE)."
}

variable "scan_on_push" {
  type        = bool
  default     = true
  description = "Indicates whether images are scanned after being pushed to the repository."
}

variable "lifecycle_policy" {
  type        = string
  default     = null
  description = "Optional JSON string representing an ECR lifecycle policy."
}

variable "trusted_accounts" {
  type        = list(string)
  default     = []
  description = "List of AWS account IDs permitted read access to the ECR repository."
}

data "aws_caller_identity" "current" {}

resource "random_pet" "repository_suffix" {
  length    = 2
  separator = "-"
}

locals {
  base_name = (
    var.repository_name == null || var.repository_name == ""
    ? "ecr-${random_pet.repository_suffix.id}"
    : var.repository_name
  )
  full_repository_name = (
    var.namespace != null && var.namespace != ""
    ? "${var.namespace}/${local.base_name}"
    : local.base_name
  )
  trusted_account_arns = distinct(concat(
    ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"],
    [for account_id in var.trusted_accounts : "arn:aws:iam::${account_id}:root"]
  ))
}

resource "aws_ecr_repository" "app" {
  name                 = local.full_repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.full_repository_name
  }
}

resource "aws_ecr_lifecycle_policy" "app" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.app.name
  policy     = var.lifecycle_policy
}

data "aws_iam_policy_document" "ecr_read" {
  statement {
    sid    = "ECRRepositoryRead"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages"
    ]
    resources = [aws_ecr_repository.app.arn]
  }

  statement {
    sid    = "ECRAuthToken"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.base_name}-ecr-read"
  description = "IAM policy for reading images from the ${local.full_repository_name} ECR repository"
  policy      = data.aws_iam_policy_document.ecr_read.json
}

data "aws_iam_policy_document" "ecr_write" {
  statement {
    sid    = "ECRRepositoryWrite"
    effect = "Allow"
    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload"
    ]
    resources = [aws_ecr_repository.app.arn]
  }
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.base_name}-ecr-write"
  description = "IAM policy for pushing images to the ${local.full_repository_name} ECR repository"
  policy      = data.aws_iam_policy_document.ecr_write.json
}

data "aws_iam_policy_document" "repository_policy" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = local.trusted_account_arns
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages"
    ]
  }
}

resource "aws_ecr_repository_policy" "allow_cross_account_access" {
  repository = aws_ecr_repository.app.name
  policy     = data.aws_iam_policy_document.repository_policy.json
}

output "repository_arn" {
  description = "The ARN of the ECR repository."
  value       = aws_ecr_repository.app.arn
}

output "repository_url" {
  description = "The URL of the ECR repository."
  value       = aws_ecr_repository.app.repository_url
}

output "read_policy_arn" {
  description = "The ARN of the IAM read policy."
  value       = aws_iam_policy.ecr_read.arn
}

output "write_policy_arn" {
  description = "The ARN of the IAM write policy."
  value       = aws_iam_policy.ecr_write.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region for infrastructure deployment"
}

variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "Base CIDR block for the VPC"
}

variable "az_count" {
  type        = number
  default     = 2
  description = "Number of Availability Zones to utilize"
}

variable "enable_public_subnets" {
  type        = bool
  default     = true
  description = "Toggle to enable/disable public subnets"
}

variable "enable_nat_subnets" {
  type        = bool
  default     = false
  description = "Toggle to enable/disable NAT subnets"
}

variable "enable_private_subnets" {
  type        = bool
  default     = false
  description = "Toggle to enable/disable private subnets"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  selected_azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  public_count  = var.enable_public_subnets ? var.az_count : 0
  nat_count     = var.enable_nat_subnets ? var.az_count : 0
  private_count = var.enable_private_subnets ? var.az_count : 0

  total_subnets = local.public_count + local.nat_count + local.private_count

  # Calculate required additional prefix bits: ceil(log(total_subnets, 2))
  # Ensure at least 1 subnet bit is added if total_subnets > 0, otherwise default to 0
  newbits = local.total_subnets > 0 ? ceil(log(local.total_subnets, 2)) : 0

  # Offset assignments ensuring contiguous, non-overlapping subnet allocations
  public_offset  = 0
  nat_offset     = local.public_count
  private_offset = local.public_count + local.nat_count
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

# Public Subnets Tier
resource "aws_subnet" "public" {
  count                   = var.enable_public_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.public_offset + count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${local.selected_azs[count.index]}"
    Tier = "public"
  }
}

resource "aws_internet_gateway" "main" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = var.enable_public_subnets ? var.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_security_group" "public" {
  count       = var.enable_public_subnets ? 1 : 0
  name        = "public-tier-sg"
  description = "Security group for workloads in public subnets with restricted egress"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "public-workload-sg"
  }
}

# NAT Subnets Tier
resource "aws_subnet" "nat" {
  count                   = var.enable_nat_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.nat_offset + count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "nat-subnet-${local.selected_azs[count.index]}"
    Tier = "nat"
  }
}

# Private Subnets Tier
resource "aws_subnet" "private" {
  count                   = var.enable_private_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.private_offset + count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${local.selected_azs[count.index]}"
    Tier = "private"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "project" {
  type        = string
  description = "Project name tag and identifier"
  default     = "demo"
}

variable "environment" {
  type        = string
  description = "Deployment environment identifier"
  default     = "poc"
}

variable "vpc_name" {
  type        = string
  description = "Name identifier for the VPC"
  default     = "demo-dataflow"
}

variable "vpc_cidr" {
  type        = string
  description = "Primary CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the public subnets"
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the private subnets"
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_name" {
  type        = string
  description = "Key pair name for SSH access"
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  type        = string
  description = "EC2 instance type for the SSH bastion host"
  default     = "t3.nano"
}

variable "ebs_optimized" {
  type        = bool
  description = "Toggle EBS optimization for bastion instance"
  default     = false
}

variable "tags" {
  type        = map(string)
  description = "Common tags applied to all resources"
  default = {
    Project     = "demo"
    Environment = "poc"
    ManagedBy   = "Terraform"
  }
}

locals {
  name_prefix = "${var.project}-${var.environment}"
  common_tags = merge(
    var.tags,
    {
      Project     = var.project
      Environment = var.environment
      Region      = var.aws_region
    }
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = var.vpc_name
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "demogwInternet"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "demoPublicRouteTable"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
      Tier = "Public"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt"
    }
  )
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
      Tier = "Private"
    }
  )
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "tls_private_key" "bastion_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "bastion" {
  key_name   = var.key_name
  public_key = tls_private_key.bastion_key.public_key_openssh

  tags = merge(
    local.common_tags,
    {
      Name = var.key_name
    }
  )
}

resource "aws_secretsmanager_secret" "bastion_private_key" {
  name                    = "${local.name_prefix}-bastion-ssh-key"
  description             = "Private key for EC2 bastion host SSH access"
  recovery_window_in_days = 0

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-bastion-ssh-key"
    }
  )
}

resource "aws_secretsmanager_secret_version" "bastion_private_key" {
  secret_id     = aws_secretsmanager_secret.bastion_private_key.id
  secret_string = tls_private_key.bastion_key.private_key_pem
}

resource "aws_security_group" "bastion" {
  name        = "${local.name_prefix}-bastion-sg"
  description = "Security group for SSH bastion host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC network"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow egress to the VPC network"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-bastion-sg"
    }
  )
}

data "aws_iam_policy_document" "ebs_key_policy" {
  statement {
    sid       = "EnableRootAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowEC2AndAutoScalingToUseKMSKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["ec2.${var.aws_region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowAttachmentOfPersistentResources"
    effect = "Allow"
    actions = [
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "kms:GrantIsForAWSResource"
      values   = ["true"]
    }
  }
}

resource "aws_kms_key" "ebs_key" {
  description             = "Customer managed KMS key for EBS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.ebs_key_policy.json

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-ebs-key"
    }
  )
}

resource "aws_kms_alias" "ebs_key_alias" {
  name          = "alias/${local.name_prefix}-ebs-key"
  target_key_id = aws_kms_key.ebs_key.key_id
}

resource "aws_instance" "bastion" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = var.bastion_instance_type
  key_name                    = aws_key_pair.bastion.key_name
  subnet_id                   = aws_subnet.public[0].id
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  ebs_optimized               = var.ebs_optimized
  associate_public_ip_address = false

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs_key.arn
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-bastion"
    }
  )
}

resource "aws_eip" "bastion" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-bastion-eip"
    }
  )
}

resource "aws_eip_association" "bastion" {
  instance_id   = aws_instance.bastion.id
  allocation_id = aws_eip.bastion.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

variable "secondary_region" {
  type        = string
  description = "AWS region for the secondary cross-region backup vault"
  default     = "us-west-2"
}

variable "enable_daily_plan" {
  type        = bool
  description = "Controls whether the daily backup rule is included in the backup plan"
  default     = true
}

variable "enable_cross_account_copy" {
  type        = bool
  description = "Controls whether backups are copied to the cross-account destination vault"
  default     = true
}

variable "destination_account_id" {
  type        = string
  description = "AWS account ID of the destination account for cross-account backup copies"
  default     = "433568766270"
}

variable "excluded_rds_arns" {
  type        = list(string)
  description = "List of RDS instance or cluster ARNs to exclude from the backup plan"
  default     = []
}

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

locals {
  primary_vault_name   = "rds-primary-backup-vault"
  secondary_vault_name = "rds-secondary-backup-vault"
  dest_vault_arn       = "arn:${data.aws_partition.current.partition}:backup:${var.secondary_region}:${var.destination_account_id}:backup-vault:${local.secondary_vault_name}"
}

# --- KMS Key for Primary Backup Vault ---

resource "aws_kms_key" "backup_primary" {
  description             = "Customer managed KMS key for AWS Backup primary vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow AWS Backup to use the key"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "backup-primary-vault-key"
  }
}

resource "aws_kms_alias" "backup_primary" {
  name          = "alias/backup-primary-vault-key"
  target_key_id = aws_kms_key.backup_primary.key_id
}

# --- KMS Key for Secondary Backup Vault ---

resource "aws_kms_key" "backup_secondary" {
  provider                = aws.secondary
  description             = "Customer managed KMS key for AWS Backup secondary vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow AWS Backup to use the key"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "backup-secondary-vault-key"
  }
}

resource "aws_kms_alias" "backup_secondary" {
  provider      = aws.secondary
  name          = "alias/backup-secondary-vault-key"
  target_key_id = aws_kms_key.backup_secondary.key_id
}

# --- AWS Backup Vaults ---

resource "aws_backup_vault" "primary" {
  name        = local.primary_vault_name
  kms_key_arn = aws_kms_key.backup_primary.arn

  tags = {
    Name = "rds-primary-backup-vault"
  }
}

resource "aws_backup_vault" "secondary" {
  provider    = aws.secondary
  name        = local.secondary_vault_name
  kms_key_arn = aws_kms_key.backup_secondary.arn

  tags = {
    Name = "rds-secondary-backup-vault"
  }
}

# --- IAM Role for AWS Backup ---

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "aws-backup-rds-service-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "aws-backup-rds-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_policy_attach" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role.name
}

resource "aws_iam_role_policy_attachment" "restore_policy_attach" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
  role       = aws_iam_role.backup_role.name
}

# --- AWS Backup Plan ---

resource "aws_backup_plan" "rds_backup_plan" {
  name = "rds-backup-plan"

  # Daily Rule: runs at 2:00 AM UTC daily, retained 7 days
  dynamic "rule" {
    for_each = var.enable_daily_plan ? [1] : []
    content {
      rule_name                = "daily-backup-rule"
      target_vault_name        = aws_backup_vault.primary.name
      schedule                 = "cron(0 2 * * ? *)"
      start_window             = 60
      completion_window        = 180
      enable_continuous_backup = false

      lifecycle {
        delete_after = 7
      }

      # Cross-region copy to secondary vault in same account
      copy_action {
        destination_vault_arn = aws_backup_vault.secondary.arn
        lifecycle {
          delete_after = 7
        }
      }

      # Optional cross-account copy
      dynamic "copy_action" {
        for_each = var.enable_cross_account_copy ? [1] : []
        content {
          destination_vault_arn = local.dest_vault_arn
          lifecycle {
            delete_after = 7
          }
        }
      }
    }
  }

  # Weekly Rule: runs Saturdays at 2:00 AM UTC, retained 30 days
  rule {
    rule_name                = "weekly-backup-rule"
    target_vault_name        = aws_backup_vault.primary.name
    schedule                 = "cron(0 2 ? * 7 *)"
    start_window             = 60
    completion_window        = 180
    enable_continuous_backup = false

    lifecycle {
      delete_after = 30
    }

    # Cross-region copy to secondary vault in same account
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
      lifecycle {
        delete_after = 30
      }
    }

    # Optional cross-account copy
    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.dest_vault_arn
        lifecycle {
          delete_after = 30
        }
      }
    }
  }

  # Monthly Rule: runs on 1st of every month at 3:00 AM UTC, retained 365 days
  rule {
    rule_name                = "monthly-backup-rule"
    target_vault_name        = aws_backup_vault.primary.name
    schedule                 = "cron(0 3 1 * ? *)"
    start_window             = 60
    completion_window        = 180
    enable_continuous_backup = false

    lifecycle {
      delete_after = 365
    }

    # Cross-region copy to secondary vault in same account
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
      lifecycle {
        delete_after = 365
      }
    }

    # Optional cross-account copy
    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.dest_vault_arn
        lifecycle {
          delete_after = 365
        }
      }
    }
  }

  # Yearly Rule: runs on January 1st at 4:00 AM UTC, retained 2555 days (~7 years)
  rule {
    rule_name                = "yearly-backup-rule"
    target_vault_name        = aws_backup_vault.primary.name
    schedule                 = "cron(0 4 1 1 ? *)"
    start_window             = 60
    completion_window        = 180
    enable_continuous_backup = false

    lifecycle {
      delete_after = 2555
    }

    # Cross-region copy to secondary vault in same account
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
      lifecycle {
        delete_after = 2555
      }
    }

    # Optional cross-account copy
    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = local.dest_vault_arn
        lifecycle {
          delete_after = 2555
        }
      }
    }
  }

  tags = {
    Name = "rds-backup-plan"
  }
}

# --- AWS Backup Selection ---

resource "aws_backup_selection" "rds_selection" {
  name          = "rds-backup-selection"
  plan_id       = aws_backup_plan.rds_backup_plan.id
  iam_role_arn  = aws_iam_role.backup_role.arn
  not_resources = var.excluded_rds_arns

  resources = [
    "arn:${data.aws_partition.current.partition}:rds:*:*:db:*",
    "arn:${data.aws_partition.current.partition}:rds:*:*:cluster:*"
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "allow_users_to_change_password" {
  description = "Whether to allow users to change their own password."
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their password has expired."
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "The number of days that an IAM user password is valid."
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum length to require for IAM user passwords."
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "The number of previous passwords that IAM users are prevented from reusing."
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether to require lowercase characters for IAM user passwords."
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether to require numbers for IAM user passwords."
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether to require symbols for IAM user passwords."
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether to require uppercase characters for IAM user passwords."
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------------
# IAM Account Password Policy
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "strict" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
  require_uppercase_characters   = var.require_uppercase_characters
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "administrators" {
  name = "administrators"
  path = "/"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
  path = "/"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
  path = "/"
}

# -----------------------------------------------------------------------------
# IAM Policy Documents
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "developpers" {
  statement {
    sid       = "AllowDevEC2AndRDS"
    effect    = "Allow"
    resources = ["*"]
    actions = [
      "ec2:*",
      "rds:*"
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["dev"]
    }
  }
}

data "aws_iam_policy_document" "prod_users" {
  statement {
    sid       = "AllowProdEC2AndRDS"
    effect    = "Allow"
    resources = ["*"]
    actions = [
      "ec2:*",
      "rds:*"
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values = [
        "preprod",
        "prod"
      ]
    }
  }
}

data "aws_iam_policy_document" "administrators" {
  statement {
    sid       = "AllowNonSensitiveServices"
    effect    = "Allow"
    resources = ["*"]

    not_actions = [
      "iam:*",
      "organizations:*",
      "account:*"
    ]

    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceTag/security"
      values   = ["high"]
    }
  }

  statement {
    sid       = "AllowSpecificAdministrativeActions"
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "iam:CreateServiceLinkedRole",
      "iam:DeleteServiceLinkedRole",
      "iam:ListRoles",
      "organizations:DescribeOrganization",
      "account:ListRegions"
    ]
  }
}

# -----------------------------------------------------------------------------
# IAM Policies
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  path        = "/"
  description = "Policy granting full EC2 and RDS access on dev environment tagged resources."
  policy      = data.aws_iam_policy_document.developpers.json
}

resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  path        = "/"
  description = "Policy granting full EC2 and RDS access on preprod and prod environment tagged resources."
  policy      = data.aws_iam_policy_document.prod_users.json
}

resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  path        = "/"
  description = "Broad administrator policy excluding sensitive services unless tagged non-high security with specific delegated administration rights."
  policy      = data.aws_iam_policy_document.administrators.json
}

# -----------------------------------------------------------------------------
# IAM Group Policy Attachments
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "administrators" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for infrastructure deployment"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to resource names"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Instance tenancy option for the VPC"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "List of maps defining inbound network ACL rules"
  type = list(object({
    rule_number = number
    protocol    = string
    rule_action = string
    cidr_block  = string
    from_port   = number
    to_port     = number
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      rule_action = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 1024
      to_port     = 65535
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "List of maps defining outbound network ACL rules"
  type = list(object({
    rule_number = number
    protocol    = string
    rule_action = string
    cidr_block  = string
    from_port   = number
    to_port     = number
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      rule_action = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 443
      to_port     = 443
    }
  ]
}

locals {
  name_prefix = var.name_prefix
  region      = var.aws_region
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private[0].id, aws_route_table.private[1].id]

  tags = {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.private[0].id, aws_subnet.private[1].id]

  tags = {
    Name = "${local.name_prefix}-private-nacl"
  }
}

resource "aws_network_acl_rule" "inbound" {
  for_each = { for rule in var.public_inbound_acl_rules : rule.rule_number => rule }

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  egress         = false
  protocol       = each.value.protocol
  rule_action    = each.value.rule_action
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
}

resource "aws_network_acl_rule" "outbound" {
  for_each = { for rule in var.public_outbound_acl_rules : rule.rule_number => rule }

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  egress         = true
  protocol       = each.value.protocol
  rule_action    = each.value.rule_action
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region for provider configuration"
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Cloud Posse Null-Label Context Variables
# -----------------------------------------------------------------------------
variable "namespace" {
  type        = string
  default     = null
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'"
}

variable "tenant" {
  type        = string
  default     = null
  description = "A customer or tenant, If not used, will be omitted from the id"
}

variable "environment" {
  type        = string
  default     = null
  description = "Environment, e.g. 'uw2', 'us-west-2', OR 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "Stage, e.g. 'prod', 'staging', 'dev', or 'test'"
}

variable "name" {
  type        = string
  default     = "vpc"
  description = "Solution name, e.g. 'app' or 'jenkins'"
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter to be used between ID elements. Defaults to `-` (hyphen)"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes (e.g. `1`)"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`"
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = "Additional key-value pairs of tags for each resource"
}

# -----------------------------------------------------------------------------
# VPC Configuration Variables
# -----------------------------------------------------------------------------
variable "ipv4_cidr_block" {
  type        = string
  default     = "11.0.0.0/16"
  description = "The primary IPv4 CIDR block for the VPC. Ignored if ipv4_ipam_pool_id is set."
}

variable "ipv4_ipam_pool_id" {
  type        = string
  default     = null
  description = "The ID of an IPv4 IPAM pool you want to use for allocating this VPC's CIDR"
}

variable "ipv4_netmask_length" {
  type        = number
  default     = null
  description = "The netmask length of the IPv4 CIDR you want to allocate to this VPC from IPAM"
}

variable "instance_tenancy" {
  type        = string
  default     = "default"
  description = "A tenancy option for instances launched into the VPC"
}

variable "enable_dns_hostnames" {
  type        = bool
  default     = true
  description = "A boolean flag to enable/disable DNS hostnames in the VPC"
}

variable "enable_dns_support" {
  type        = bool
  default     = true
  description = "A boolean flag to enable/disable DNS support in the VPC"
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  default     = true
  description = "Requests an Amazon-provided IPv6 CIDR block with a /56 prefix length for the VPC"
}

variable "ipv6_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM Pool ID for a primary IPv6 CIDR allocation"
}

variable "ipv6_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length to request from the primary IPv6 IPAM pool"
}

variable "secondary_ipv4_cidr_blocks" {
  type = map(object({
    cidr_block          = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
    create_timeout      = optional(string, "10m")
    delete_timeout      = optional(string, "10m")
  }))
  default     = {}
  description = "Map of secondary IPv4 CIDR blocks and IPAM configurations to associate with the VPC"
}

variable "secondary_ipv6_cidr_blocks" {
  type = map(object({
    ipv6_cidr_block     = optional(string)
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
    create_timeout      = optional(string, "10m")
    delete_timeout      = optional(string, "10m")
  }))
  default     = {}
  description = "Map of secondary IPv6 CIDR blocks and IPAM configurations to associate with the VPC"
}

# -----------------------------------------------------------------------------
# Security & Default Resource Adoption Flags
# -----------------------------------------------------------------------------
variable "default_security_group_deny_all" {
  type        = bool
  default     = true
  description = "Whether to deny all traffic in the default security group by stripping all rules"
}

variable "adopt_default_route_table" {
  type        = bool
  default     = false
  description = "Whether to adopt and manage the default route table to strip unmanaged routes"
}

variable "adopt_default_network_acl" {
  type        = bool
  default     = false
  description = "Whether to adopt and manage the default network ACL"
}

# -----------------------------------------------------------------------------
# Gateways Configuration
# -----------------------------------------------------------------------------
variable "internet_gateway_enabled" {
  type        = bool
  default     = true
  description = "Controls if an Internet Gateway should be created and attached to the VPC"
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  default     = false
  description = "Controls if an Egress-Only Internet Gateway should be created for IPv6 traffic"
}

# -----------------------------------------------------------------------------
# Local Label and Tag Calculations
# -----------------------------------------------------------------------------
locals {
  id_elements = compact([
    var.namespace,
    var.tenant,
    var.environment,
    var.stage,
    var.name,
    join(var.delimiter, var.attributes)
  ])

  id = join(var.delimiter, local.id_elements)

  base_tags = {
    "Name"        = local.id
    "Namespace"   = var.namespace != null ? var.namespace : ""
    "Tenant"      = var.tenant != null ? var.tenant : ""
    "Environment" = var.environment != null ? var.environment : ""
    "Stage"       = var.stage != null ? var.stage : ""
  }

  cleaned_base_tags = {
    for k, v in local.base_tags : k => v if v != ""
  }

  tags = merge(
    local.cleaned_base_tags,
    var.additional_tag_map,
    var.tags
  )
}

# -----------------------------------------------------------------------------
# Core VPC
# -----------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block                       = var.ipv4_ipam_pool_id == null ? var.ipv4_cidr_block : null
  ipv4_ipam_pool_id                = var.ipv4_ipam_pool_id
  ipv4_netmask_length              = var.ipv4_netmask_length
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.ipv6_ipam_pool_id == null ? var.assign_generated_ipv6_cidr_block : null
  ipv6_ipam_pool_id                = var.ipv6_ipam_pool_id
  ipv6_netmask_length              = var.ipv6_netmask_length

  tags = local.tags
}

# -----------------------------------------------------------------------------
# Secondary IPv4 CIDR Block Associations
# -----------------------------------------------------------------------------
resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each = var.secondary_ipv4_cidr_blocks

  vpc_id              = aws_vpc.this.id
  cidr_block          = each.value.cidr_block
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

# -----------------------------------------------------------------------------
# Secondary IPv6 CIDR Block Associations
# -----------------------------------------------------------------------------
resource "aws_vpc_ipv6_cidr_block_association" "this" {
  for_each = var.secondary_ipv6_cidr_blocks

  vpc_id              = aws_vpc.this.id
  ipv6_cidr_block     = each.value.ipv6_cidr_block
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

# -----------------------------------------------------------------------------
# Default Security Group Management
# -----------------------------------------------------------------------------
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  dynamic "ingress" {
    for_each = var.default_security_group_deny_all ? [] : [1]
    content {
      protocol  = "-1"
      from_port = 0
      to_port   = 0
      self      = true
    }
  }

  dynamic "egress" {
    for_each = var.default_security_group_deny_all ? [] : [1]
    content {
      protocol         = "-1"
      from_port        = 0
      to_port          = 0
      cidr_blocks      = ["0.0.0.0/0"]
      ipv6_cidr_blocks = ["::/0"]
    }
  }

  tags = merge(
    local.tags,
    {
      "Name" = join(var.delimiter, compact([local.id, "default-sg"]))
    }
  )
}

# -----------------------------------------------------------------------------
# Default Route Table Adoption
# -----------------------------------------------------------------------------
resource "aws_default_route_table" "default" {
  count = var.adopt_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this.default_route_table_id
  route                  = []

  tags = merge(
    local.tags,
    {
      "Name" = join(var.delimiter, compact([local.id, "default-rt"]))
    }
  )
}

# -----------------------------------------------------------------------------
# Default Network ACL Adoption
# -----------------------------------------------------------------------------
resource "aws_default_network_acl" "default" {
  count = var.adopt_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = merge(
    local.tags,
    {
      "Name" = join(var.delimiter, compact([local.id, "default-nacl"]))
    }
  )
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(
    local.tags,
    {
      "Name" = join(var.delimiter, compact([local.id, "igw"]))
    }
  )
}

# -----------------------------------------------------------------------------
# IPv6 Egress-Only Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "this" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(
    local.tags,
    {
      "Name" = join(var.delimiter, compact([local.id, "eigw"]))
    }
  )
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  value       = aws_vpc.this.id
  description = "The ID of the VPC"
}

output "vpc_arn" {
  value       = aws_vpc.this.arn
  description = "The ARN of the VPC"
}

output "vpc_cidr_block" {
  value       = aws_vpc.this.cidr_block
  description = "The primary IPv4 CIDR block of the VPC"
}

output "vpc_ipv6_cidr_block" {
  value       = aws_vpc.this.ipv6_cidr_block
  description = "The primary IPv6 CIDR block assigned to the VPC"
}

output "vpc_secondary_ipv4_cidr_blocks" {
  value       = [for assoc in aws_vpc_ipv4_cidr_block_association.this : assoc.cidr_block]
  description = "List of secondary IPv4 CIDR blocks associated with the VPC"
}

output "vpc_secondary_ipv6_cidr_blocks" {
  value       = [for assoc in aws_vpc_ipv6_cidr_block_association.this : assoc.ipv6_cidr_block]
  description = "List of secondary IPv6 CIDR blocks associated with the VPC"
}

output "vpc_default_security_group_id" {
  value       = aws_vpc.this.default_security_group_id
  description = "The ID of the security group created by default on VPC creation"
}

output "vpc_default_route_table_id" {
  value       = aws_vpc.this.default_route_table_id
  description = "The ID of the route table created by default on VPC creation"
}

output "vpc_default_network_acl_id" {
  value       = aws_vpc.this.default_network_acl_id
  description = "The ID of the network ACL created by default on VPC creation"
}

output "internet_gateway_id" {
  value       = try(aws_internet_gateway.this[0].id, null)
  description = "The ID of the Internet Gateway"
}

output "egress_only_internet_gateway_id" {
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
  description = "The ID of the Egress-Only Internet Gateway"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "username" {
  type        = string
  description = "The name of the IAM user"
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  type        = string
  description = "The name of the IAM group"
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  type        = string
  description = "The name of the IAM group membership"
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  type        = string
  description = "The project tag to apply across resources"
  default     = "my-vpn-tag"
}

variable "policy_path" {
  type        = string
  description = "The path for the IAM policies"
  default     = "/my_vpn_infra/"
}

locals {
  common_tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_user" "infra_user" {
  name          = var.username
  force_destroy = true
  tags          = local.common_tags
}

resource "aws_iam_access_key" "infra_user_key" {
  user = aws_iam_user.infra_user.name
}

resource "aws_iam_group" "infra_group" {
  name = var.group_name
}

resource "aws_iam_group_membership" "infra_group_membership" {
  name  = var.membership_name
  users = [aws_iam_user.infra_user.name]
  group = aws_iam_group.infra_group.name
}

resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Basic STS caller identity access"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "STSGetCallerIdentity"
        Effect   = "Allow"
        Action   = "sts:GetCallerIdentity"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "Explicit EC2 resource creation permissions"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2ResourceCreation"
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "Comprehensive EC2 read and describe permissions"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2DescribeAndRead"
        Effect = "Allow"
        Action = [
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses",
          "ec2:DescribeAddressesAttribute",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeImages",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeLocalGatewayRouteTables",
          "ec2:DescribeLocalGatewayRouteTableVpcAssociations",
          "ec2:DescribeLocalGateways",
          "ec2:DescribeNatGateways",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeNetworkInterfaceAttribute",
          "ec2:DescribePrefixLists",
          "ec2:DescribeRegions",
          "ec2:DescribeReplaceRootVolumeTasks",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVolumesModifications",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeVpcs",
          "ec2:GetInstanceTypesFromInstanceRequirements"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "EC2 modification, attachment, and association permissions"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2UpdateAndAssociate"
        Effect = "Allow"
        Action = [
          "ec2:AssociateAddress",
          "ec2:AssociateRouteTable",
          "ec2:AttachInternetGateway",
          "ec2:AttachNetworkInterface",
          "ec2:AttachVolume",
          "ec2:DisassociateAddress",
          "ec2:DisassociateRouteTable",
          "ec2:DetachInternetGateway",
          "ec2:DetachNetworkInterface",
          "ec2:DetachVolume",
          "ec2:ModifyAddressAttribute",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyVolume",
          "ec2:ModifyVolumeAttribute",
          "ec2:ModifyVpcAttribute",
          "ec2:ReplaceRoute",
          "ec2:ReplaceRouteTableAssociation"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "EC2 deletion, revocation, and release permissions"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2DeleteAndRevoke"
        Effect = "Allow"
        Action = [
          "ec2:DeleteKeyPair",
          "ec2:DeleteLocalGatewayRouteTableVpcAssociation",
          "ec2:DeleteRoute",
          "ec2:DeleteRouteTable",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteSubnet",
          "ec2:DeleteTags",
          "ec2:DeleteVolume",
          "ec2:DeleteVpc",
          "ec2:DeleteInternetGateway",
          "ec2:ReleaseAddress",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "EC2 instance lifecycle management permissions"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2InstanceLifecycle"
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "DynamoDB state lock and S3 backend state storage permissions"
  tags        = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBStateLock"
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3StateStorage"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "basic_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

resource "aws_iam_group_policy_attachment" "create_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

resource "aws_iam_group_policy_attachment" "read_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

resource "aws_iam_group_policy_attachment" "update_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

resource "aws_iam_group_policy_attachment" "delete_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_group_policy_attachment" "instance_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

resource "aws_iam_group_policy_attachment" "terraform_backend_access_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "environment" {
  type        = string
  description = "Environment prefix used for resource naming and tagging"
  default     = "DEV"
}

variable "existing_vpc_id" {
  type        = string
  description = "Optional ID of an existing VPC. If omitted, a new VPC is provisioned."
  default     = ""
}

variable "vpc_cidr" {
  type        = string
  description = "Main CIDR block for the newly created VPC"
  default     = "10.0.0.0/16"
}

variable "craete_private_subnet" {
  type        = bool
  description = "Flag to enable creation of private subnets, NAT Gateway, and private routing"
  default     = false
}

variable "nat_eip_private_ip" {
  type        = string
  description = "Private IP address association for the Elastic IP attached to the NAT Gateway"
  default     = "10.0.0.5"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources"
  default     = {}
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  name_prefix      = lower(var.environment)
  effective_vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : try(aws_vpc.main[0].id, "")

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count = var.existing_vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = local.effective_vpc_id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

# -----------------------------------------------------------------------------
# Public Subnets and Routing
# -----------------------------------------------------------------------------
resource "aws_subnet" "public_1" {
  vpc_id                  = local.effective_vpc_id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-subnet-1"
      Tier = "Public"
    }
  )
}

resource "aws_subnet" "public_2" {
  vpc_id                  = local.effective_vpc_id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-subnet-2"
      Tier = "Public"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = local.effective_vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# NAT Gateway and Elastic IP (Conditional)
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = var.craete_private_subnet ? 1 : 0

  domain                    = "vpc"
  associate_with_private_ip = var.nat_eip_private_ip

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat-eip"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = var.craete_private_subnet ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public_1.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat-gw"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Private Subnets and Routing (Conditional)
# -----------------------------------------------------------------------------
resource "aws_subnet" "private_1" {
  count = var.craete_private_subnet ? 1 : 0

  vpc_id                  = local.effective_vpc_id
  cidr_block              = "10.0.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-subnet-1"
      Tier = "Private"
    }
  )
}

resource "aws_subnet" "private_2" {
  count = var.craete_private_subnet ? 1 : 0

  vpc_id                  = local.effective_vpc_id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-subnet-2"
      Tier = "Private"
    }
  )
}

resource "aws_route_table" "private" {
  count = var.craete_private_subnet ? 1 : 0

  vpc_id = local.effective_vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt"
    }
  )
}

resource "aws_route_table_association" "private_1" {
  count = var.craete_private_subnet ? 1 : 0

  subnet_id      = aws_subnet.private_1[0].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "private_2" {
  count = var.craete_private_subnet ? 1 : 0

  subnet_id      = aws_subnet.private_2[0].id
  route_table_id = aws_route_table.private[0].id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Whether to create SQS queue and associated resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SQS queue. If omitted, Terraform will assign a random name."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Creates a unique name beginning with the specified prefix. Conflicts with name."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue. If true, queue names will end with .fifo."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are messageGroup and queue."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are perQueue and perMessageGroupId."
  type        = string
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds."
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed."
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive before returning."
  type        = number
  default     = 0
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK. If null, SQS managed SSE will be used if enabled."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages."
  type        = number
  default     = 300
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys. Overridden if kms_master_key_id is set."
  type        = bool
  default     = true
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "The name of the dead-letter queue. Defaults to main queue name with -dlq suffix."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "Creates a unique dead-letter queue name beginning with the specified prefix."
  type        = string
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains messages in the DLQ."
  type        = number
  default     = 1209600
}

variable "max_receive_count" {
  description = "The number of times a message can be received before being moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to create a redrive allow policy for the dead-letter queue."
  type        = bool
  default     = true
}

variable "create_queue_policy" {
  description = "Whether to create and attach an IAM resource policy to the primary queue."
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document."
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document, taking precedence over standard statements."
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "Custom IAM policy statements to attach to the queue policy."
  type = list(object({
    sid        = optional(string)
    effect     = optional(string, "Allow")
    actions    = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
    resources = optional(list(string))
  }))
  default = []
}

variable "tags" {
  description = "A mapping of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

locals {
  # Base name without .fifo if provided
  base_name        = var.name != null ? (var.fifo_queue ? trimsuffix(var.name, ".fifo") : var.name) : null
  base_name_prefix = var.name_prefix != null ? (var.fifo_queue ? trimsuffix(var.name_prefix, ".fifo") : var.name_prefix) : null

  # Primary Queue names
  queue_name        = var.fifo_queue && local.base_name != null ? "${local.base_name}.fifo" : local.base_name
  queue_name_prefix = var.fifo_queue && local.base_name_prefix != null ? "${local.base_name_prefix}-" : local.base_name_prefix

  # DLQ naming calculation
  default_dlq_name        = local.base_name != null ? "${local.base_name}-dlq" : null
  default_dlq_name_prefix = local.base_name_prefix != null ? "${local.base_name_prefix}-dlq-" : null

  raw_dlq_name        = var.dlq_name != null ? (var.fifo_queue ? trimsuffix(var.dlq_name, ".fifo") : var.dlq_name) : local.default_dlq_name
  raw_dlq_name_prefix = var.dlq_name_prefix != null ? (var.fifo_queue ? trimsuffix(var.dlq_name_prefix, ".fifo") : var.dlq_name_prefix) : (var.dlq_name == null && local.base_name == null ? local.default_dlq_name_prefix : null)

  dlq_name        = var.fifo_queue && local.raw_dlq_name != null ? "${local.raw_dlq_name}.fifo" : local.raw_dlq_name
  dlq_name_prefix = var.fifo_queue && local.raw_dlq_name_prefix != null ? "${local.raw_dlq_name_prefix}-" : local.raw_dlq_name_prefix

  # SSE selection: SQS-managed SSE applies only if KMS CMK is omitted
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
}

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name_prefix == null ? local.dlq_name : null
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  message_retention_seconds = var.dlq_message_retention_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  tags = var.tags
}

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.queue_name_prefix == null ? local.queue_name : null
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags
}

resource "aws_sqs_queue_redrive_allow_policy" "this" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources != null ? statement.value.resources : [aws_sqs_queue.this[0].arn]

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

output "queue_id" {
  description = "The URL of the created Amazon SQS queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the Amazon SQS queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "The same as queue_id: the URL of the created Amazon SQS queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the created Amazon SQS queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_id" {
  description = "The URL of the created Amazon SQS dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "The ARN of the Amazon SQS dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "The URL of the created Amazon SQS dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dlq_name" {
  description = "The name of the created Amazon SQS dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

