terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "backup_name" {
  type        = string
  default     = "default-backup"
  description = "Name identifier for the backup vault and associated resources."
}

variable "account_type" {
  type        = string
  default     = "workload"
  description = "Account architecture type: 'workload' provisions backup plans, IAM roles, and selections; 'backup' provisions central vault infrastructure only."

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "The account_type variable must be strictly either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  type        = string
  default     = null
  description = "Optional KMS key ARN to encrypt the backup vault. If omitted, the default AWS Backup managed key is used."
}

variable "vault_policy" {
  type        = string
  default     = null
  description = "Optional JSON-formatted access policy string for the backup vault."
}

variable "min_retention_days" {
  type        = number
  default     = null
  description = "Minimum retention period in days for the backup vault lock. Setting this enables the vault lock configuration."
}

variable "max_retention_days" {
  type        = number
  default     = null
  description = "Optional maximum retention period in days for the backup vault lock."
}

variable "changeable_for_days" {
  type        = number
  default     = null
  description = "Optional number of days before the backup vault lock becomes immutable."
}

variable "enable_aws_backup_vault_notifications" {
  type        = bool
  default     = false
  description = "Controls whether to publish backup vault events to the specified SNS topic."
}

variable "notification_sns_topic_arn" {
  type        = string
  default     = ""
  description = "SNS topic ARN to receive backup vault event notifications."
}

variable "backup_vault_events" {
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
  description = "List of backup vault event types to publish to the notification SNS topic."
}

variable "rule_schedule" {
  type        = string
  default     = "cron(0 5 ? * * *)"
  description = "Cron or rate expression specifying the backup schedule."
}

variable "copy_actions" {
  type = list(object({
    destination_vault_arn = string
    lifecycle = optional(object({
      cold_storage_after = optional(number)
      delete_after       = optional(number)
    }))
  }))
  default     = []
  description = "List of cross-region or cross-account copy action configurations."
}

variable "selection_resources" {
  type        = list(string)
  default     = []
  description = "List of explicit resource ARNs to include in the backup selection."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to assign to resources."
}

locals {
  is_workload      = var.account_type == "workload"
  backup_plan_name = "plan-${var.backup_name}-backup"
}

resource "aws_backup_vault" "vault" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn
  tags        = var.tags
}

resource "aws_backup_vault_policy" "vault" {
  count             = var.vault_policy != null ? 1 : 0
  backup_vault_name = aws_backup_vault.vault.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "vault" {
  count               = var.min_retention_days != null ? 1 : 0
  backup_vault_name   = aws_backup_vault.vault.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "vault" {
  count               = var.enable_aws_backup_vault_notifications ? 1 : 0
  backup_vault_name   = aws_backup_vault.vault.name
  sns_topic_arn       = var.notification_sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

resource "aws_iam_role" "backup_role" {
  count       = local.is_workload ? 1 : 0
  name_prefix = "aws-backup-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_role" {
  count      = local.is_workload ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role[0].name
}

resource "aws_backup_plan" "plan" {
  count = local.is_workload ? 1 : 0
  name  = local.backup_plan_name

  rule {
    rule_name           = "default_backup_rule"
    target_vault_name   = aws_backup_vault.vault.name
    schedule            = var.rule_schedule
    start_window        = 60
    completion_window   = 120
    recovery_point_tags = var.tags

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
          content {
            cold_storage_after = lifecycle.value.cold_storage_after
            delete_after       = lifecycle.value.delete_after
          }
        }
      }
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "tag_selection" {
  count        = local.is_workload ? 1 : 0
  name         = "${var.backup_name}-tag-selection"
  plan_id      = aws_backup_plan.plan[0].id
  iam_role_arn = aws_iam_role.backup_role[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resource_selection" {
  count        = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0
  name         = "${var.backup_name}-resource-selection"
  plan_id      = aws_backup_plan.plan[0].id
  iam_role_arn = aws_iam_role.backup_role[0].arn

  resources = var.selection_resources
}

output "backup_vault_id" {
  description = "The name of the backup vault."
  value       = aws_backup_vault.vault.id
}

output "backup_vault_arn" {
  description = "The ARN of the backup vault."
  value       = aws_backup_vault.vault.arn
}

output "backup_plan_id" {
  description = "The ID of the backup plan if created."
  value       = local.is_workload ? aws_backup_plan.plan[0].id : null
}

output "backup_plan_arn" {
  description = "The ARN of the backup plan if created."
  value       = local.is_workload ? aws_backup_plan.plan[0].arn : null
}

output "backup_role_arn" {
  description = "The ARN of the IAM role used by AWS Backup if created."
  value       = local.is_workload ? aws_iam_role.backup_role[0].arn : null
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "custom_name" {
  type        = string
  description = "Optional custom name prefix for resources. Falls back to petname if null or empty."
  default     = ""
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

locals {
  name_prefix   = var.custom_name != null && var.custom_name != "" ? var.custom_name : "config-${random_pet.suffix.id}"
  account_id    = data.aws_caller_identity.current.account_id
  partition     = data.aws_partition.current.partition
  s3_key_prefix = "awsconfig/records"
}

# KMS Customer Managed Key for AWS Config SNS Topic, S3 Bucket, and Encryption
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowConfigAndSNS"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = ["*"]

    principals {
      type = "Service"
      identifiers = [
        "config.amazonaws.com",
        "sns.amazonaws.com"
      ]
    }
  }
}

resource "aws_kms_key" "config" {
  description             = "KMS Key for AWS Config notifications and delivery"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name        = "${local.name_prefix}-kms-key"
    Environment = "production"
  }
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.config.key_id
}

# SNS Topic for AWS Config notifications
resource "aws_sns_topic" "config_notifications" {
  name              = "${local.name_prefix}-notifications"
  kms_master_key_id = aws_kms_key.config.id

  tags = {
    Name        = "${local.name_prefix}-notifications"
    Environment = "production"
  }
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AWSConfigSNSPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      aws_sns_topic.config_notifications.arn
    ]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "config_notifications" {
  arn    = aws_sns_topic.config_notifications.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

# S3 Bucket for AWS Config Snapshots
resource "aws_s3_bucket" "config_bucket" {
  bucket        = "${local.name_prefix}-bucket-${local.account_id}"
  force_destroy = true

  tags = {
    Name        = "${local.name_prefix}-bucket"
    Environment = "production"
  }
}

resource "aws_s3_bucket_public_access_block" "config_bucket" {
  bucket                  = aws_s3_bucket.config_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.config.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "config_s3_bucket_policy" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl"
    ]
    resources = [
      aws_s3_bucket.config_bucket.arn
    ]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }

  statement {
    sid    = "AWSConfigBucketExistenceCheck"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.config_bucket.arn
    ]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.config_bucket.arn}/${local.s3_key_prefix}/AWSLogs/${local.account_id}/Config/*"
    ]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "config_bucket" {
  bucket     = aws_s3_bucket.config_bucket.id
  policy     = data.aws_iam_policy_document.config_s3_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.config_bucket]
}

# IAM Role for AWS Config Service
data "aws_iam_policy_document" "config_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config_role" {
  name               = "${local.name_prefix}-role"
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = {
    Name        = "${local.name_prefix}-role"
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "config_managed_policy" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_custom_policy" {
  statement {
    sid    = "AWSConfigS3Write"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]
    resources = [
      "${aws_s3_bucket.config_bucket.arn}/${local.s3_key_prefix}/AWSLogs/${local.account_id}/*"
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid    = "AWSConfigS3Check"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.config_bucket.arn
    ]
  }

  statement {
    sid    = "AWSConfigSNSPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      aws_sns_topic.config_notifications.arn
    ]
  }

  statement {
    sid    = "AWSConfigKMSDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = [
      aws_kms_key.config.arn
    ]
  }
}

resource "aws_iam_role_policy" "config_policy" {
  name   = "${local.name_prefix}-delivery-policy"
  role   = aws_iam_role.config_role.id
  policy = data.aws_iam_policy_document.config_custom_policy.json
}

# AWS Config Recorder and Delivery Channel
resource "aws_config_configuration_recorder" "main" {
  name     = "${local.name_prefix}-recorder"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "${local.name_prefix}-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config_bucket.bucket
  s3_key_prefix  = local.s3_key_prefix
  sns_topic_arn  = aws_sns_topic.config_notifications.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_config_configuration_recorder.main,
    aws_s3_bucket_policy.config_bucket
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.main
  ]
}

# AWS Config Managed Rules

# 1. cloudtrail-enabled (Periodic evaluation)
resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                        = "cloudtrail-enabled"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 2. iam-pw-policy (Periodic evaluation)
resource "aws_config_config_rule" "iam_pw_policy" {
  name                        = "iam-pw-policy"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 3. ec2-vpc (Configuration changes)
resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Instance"]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 4. root-mfa-enabled (Periodic evaluation)
resource "aws_config_config_rule" "root_mfa_enabled" {
  name                        = "root-mfa-enabled"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 5. acm-expiration-check (Periodic evaluation)
resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 6. ebs-inuse-check (Configuration changes)
resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Volume"]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 7. ec2-imdsv2-check (Configuration changes)
resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Instance"]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 8. rds-encrypted (Configuration changes)
resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  scope {
    compliance_resource_types = ["AWS::RDS::DBInstance"]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 9. rds-private (Configuration changes)
resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::RDS::DBInstance"]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 10. rds-private-snapshots (Configuration changes)
resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  scope {
    compliance_resource_types = [
      "AWS::RDS::DBSnapshot",
      "AWS::RDS::DBClusterSnapshot"
    ]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# 11. required-tags (Configuration changes scoped to S3 Buckets)
resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  depends_on = [aws_config_configuration_recorder_status.main]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  project_tag = "BJIT DevOps Task"
  author_tag  = "Ariful Islam"

  common_tags = {
    Project = local.project_tag
    Author  = local.author_tag
  }

  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "bjit-main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-igw"
  })
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-public-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-private-route-table-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [for rt in aws_route_table.private : rt.id]

  tags = merge(local.common_tags, {
    Name = "bjit-s3-gateway-endpoint"
  })
}

resource "aws_security_group" "alb_sg" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security group for API server Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTP and HTTPS inbound"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

resource "aws_security_group" "mariadb_rds_sg" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "Security group for MariaDB RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow MariaDB MySQL access from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

resource "aws_security_group" "redis_sg" {
  name        = "bjit-redis-SG"
  description = "Security group for Redis caching"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow Redis access from VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-redis-SG"
  })
}

resource "aws_security_group" "api_server_sg" {
  name        = "bjit-api-server-SG"
  description = "Security group for API servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow port 8080 from VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-SG"
  })
}

resource "aws_security_group" "file_server_sg" {
  name        = "bjit-file-server-SG"
  description = "Security group for file servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow port 8081 from VPC"
    from_port   = 8081
    to_port     = 8081
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
