terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "base_name" {
  type        = string
  description = "Base prefix for resource naming"
  default     = "benchmark"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  type        = list(string)
  description = "List of public subnet CIDR blocks"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  type        = list(string)
  description = "List of private subnet CIDR blocks"
  default     = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  has_private_subnets = var.subnet_private_cidrs != null && length(coalesce(var.subnet_private_cidrs, [])) > 0
  private_cidrs       = local.has_private_subnets ? var.subnet_private_cidrs : []
  num_private_subnets = length(local.private_cidrs)
  num_public_subnets  = length(var.subnet_public_cidrs)

  # Interface endpoints are placed in private subnets if available, otherwise in public subnets
  endpoint_subnet_ids = local.has_private_subnets ? aws_subnet.private[*].id : aws_subnet.public[*].id

  # Ingress CIDRs for ECR security group: all public CIDRs plus private CIDRs if defined
  ecr_ingress_cidrs = local.has_private_subnets ? concat(var.subnet_public_cidrs, local.private_cidrs) : var.subnet_public_cidrs
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

# -----------------------------------------------------------------------------
# Public Subnets & Routing
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                   = local.num_public_subnets
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + 1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.base_name}-public-subnet-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.num_public_subnets
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Private Subnets, NAT Gateways & Private Routing
# -----------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count                   = local.num_private_subnets
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + 1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.base_name}-private-subnet-${count.index + 1}"
    Tier = "private"
  }
}

resource "aws_eip" "nat" {
  count  = local.has_private_subnets ? local.num_public_subnets : 0
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = local.has_private_subnets ? local.num_public_subnets : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.base_name}-nat-gw-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = local.num_private_subnets
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index % local.num_public_subnets].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.num_private_subnets
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# -----------------------------------------------------------------------------
# VPC Gateway Endpoint for S3
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = concat(
    [aws_route_table.public.id],
    aws_route_table.private[*].id
  )

  tags = {
    Name = "${var.base_name}-s3-gateway-endpoint"
  }
}

# -----------------------------------------------------------------------------
# Security Group for ECR Interface VPC Endpoints
# -----------------------------------------------------------------------------
resource "aws_security_group" "ecr_endpoint" {
  name_prefix = "${var.base_name}-ecr-vpce-sg-"
  description = "Security group for ECR Interface VPC Endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS inbound from public and private subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = local.ecr_ingress_cidrs
  }

  egress {
    description = "Allow outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.base_name}-ecr-vpce-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# ECR Interface VPC Endpoints (API & Docker)
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids         = local.endpoint_subnet_ids
  security_group_ids = [aws_security_group.ecr_endpoint.id]

  tags = {
    Name = "${var.base_name}-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids         = local.endpoint_subnet_ids
  security_group_ids = [aws_security_group.ecr_endpoint.id]

  tags = {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
}

resource "aws_vpc" "project_vpc" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "project-vpc"
  }
}

resource "aws_subnet" "pub_sub_1" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pub-sub-1"
  }
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "pub-sub-2"
  }
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-1"
  }
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

