  route_table_id = aws_route_table.pub_rt_1.id
}

resource "aws_route_table_association" "pub_sub_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.pub_rt_2.id
}

resource "aws_route_table" "pvt_rt_1" {
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table" "pvt_rt_2" {
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_sub_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.pvt_rt_1.id
}

resource "aws_route_table_association" "pvt_sub_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.pvt_rt_2.id
}

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Allow inbound HTTP, HTTPS from anywhere, SSH from admin, and egress within VPC"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Outbound limited to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_tls"
  }
}

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private security group allowing traffic from allow_tls security group"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description     = "HTTP from public security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public security group"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Outbound strictly to public security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_region" "current" {}

locals {
  table_name        = "Pets"
  api_name          = "APIGW DynamoDB Serverless Pattern Demo"
  stage_name        = "v1"
  log_group_name    = "/aws/APIGW/terraform-APIGW-DynamoDB-Serverless-Pattern-Demo"
  api_key_name      = "apigw-dynamodb-terraform-api-key"
  usage_plan_name   = "apigw-dynamodb-terraform-usage-plan"
  dynamodb_endpoint = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action"
}

# -----------------------------------------------------------------------------
# DynamoDB Table
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "pets" {
  name           = local.table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    read_capacity      = 5
    write_capacity     = 5
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM Role and Policies for API Gateway to DynamoDB Integration
# -----------------------------------------------------------------------------
resource "aws_iam_role" "apigw_dynamodb_role" {
  name = "apigw-dynamodb-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "apigw_dynamodb_policy" {
  name        = "apigw-dynamodb-execution-policy"
  description = "Allows API Gateway to perform PutItem and Query operations on Pets table"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_dynamodb_attach" {
  role       = aws_iam_role.apigw_dynamodb_role.name
  policy_arn = aws_iam_policy.apigw_dynamodb_policy.arn
}

# -----------------------------------------------------------------------------
# API Gateway CloudWatch Account Role and Logging
# -----------------------------------------------------------------------------
resource "aws_iam_role" "apigw_cloudwatch_role" {
  name = "apigw-cloudwatch-global-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch_attach" {
  role       = aws_iam_role.apigw_cloudwatch_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "demo" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch_role.arn
}

resource "aws_cloudwatch_log_group" "api_logs" {
  name              = local.log_group_name
  retention_in_days = 30
}

resource "aws_cloudwatch_log_resource_policy" "api_gateway_logging_policy" {
  policy_name = "apigw-cloudwatch-log-delivery-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.api_logs.arn}:*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "demo" {
  name           = local.api_name
  api_key_source = "HEADER"
  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

# Resource: /pets
resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  parent_id   = aws_api_gateway_rest_api.demo.root_resource_id
  path_part   = "pets"
}

# Resource: /pets/{PetType}
resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# -----------------------------------------------------------------------------
# POST /pets (PutItem)
# -----------------------------------------------------------------------------
resource "aws_api_gateway_method" "post_pets" {
  rest_api_id      = aws_api_gateway_rest_api.demo.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id             = aws_api_gateway_rest_api.demo.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "${local.dynamodb_endpoint}/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_templates = {
    "application/json" = <<-VTL
      #set($inputRoot = $input.path('$'))
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "Item": {
          "id": {
            "S": "$context.requestId"
          },
          "PetType": {
            "S": "$inputRoot.PetType"
          },
          "PetName": {
            "S": "$inputRoot.PetName"
          },
          "PetPrice": {
            "N": "$inputRoot.PetPrice"
          },
          "PetBoolean": {
            "BOOL": true
          }
        }
      }
    VTL
  }
}

resource "aws_api_gateway_method_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets_200.status_code

  response_templates = {
    "application/json" = "{\"message\": \"Pet created successfully\", \"id\": \"$context.requestId\"}"
  }

  depends_on = [aws_api_gateway_integration.post_pets]
}

# -----------------------------------------------------------------------------
# GET /pets/{PetType} (Query)
# -----------------------------------------------------------------------------
resource "aws_api_gateway_method" "get_pets_by_type" {
  rest_api_id      = aws_api_gateway_rest_api.demo.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "get_pets_by_type" {
  rest_api_id             = aws_api_gateway_rest_api.demo.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pets_by_type.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "${local.dynamodb_endpoint}/Query"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_templates = {
    "application/json" = <<-VTL
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "IndexName": "PetType-index",
        "KeyConditionExpression": "PetType = :v1",
        "ExpressionAttributeValues": {
          ":v1": {
            "S": "$util.urlDecode($input.params('PetType'))"
          }
        }
      }
    VTL
  }
}

resource "aws_api_gateway_method_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = aws_api_gateway_method_response.get_pets_by_type_200.status_code

  response_templates = {
    "application/json" = <<-VTL
      #set($inputRoot = $input.path('$'))
      [
      #foreach($item in $inputRoot.Items)
        {
          "id": "$item.id.S",
          "PetType": "$item.PetType.S",
          "PetName": "$item.PetName.S",
          "PetPrice": $item.PetPrice.N
        }#if($foreach.hasNext),#end
      #end
      ]
    VTL
  }

  depends_on = [aws_api_gateway_integration.get_pets_by_type]
}

# -----------------------------------------------------------------------------
# Deployment, Stage, and Method Settings
# -----------------------------------------------------------------------------
resource "aws_api_gateway_deployment" "demo" {
  rest_api_id = aws_api_gateway_rest_api.demo.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.pets.id,
      aws_api_gateway_resource.pet_type.id,
      aws_api_gateway_method.post_pets.id,
      aws_api_gateway_integration.post_pets.id,
      aws_api_gateway_method_response.post_pets_200.id,
      aws_api_gateway_integration_response.post_pets_200.id,
      aws_api_gateway_method.get_pets_by_type.id,
      aws_api_gateway_integration.get_pets_by_type.id,
      aws_api_gateway_method_response.get_pets_by_type_200.id,
      aws_api_gateway_integration_response.get_pets_by_type_200.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration_response.post_pets_200,
    aws_api_gateway_integration_response.get_pets_by_type_200
  ]
}

resource "aws_api_gateway_stage" "v1" {
  deployment_id = aws_api_gateway_deployment.demo.id
  rest_api_id   = aws_api_gateway_rest_api.demo.id
  stage_name    = local.stage_name

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format          = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      user           = "$context.identity.user"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  depends_on = [
    aws_api_gateway_account.demo,
    aws_cloudwatch_log_resource_policy.api_gateway_logging_policy
  ]
}

resource "aws_api_gateway_method_settings" "all" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    logging_level      = "INFO"
    metrics_enabled    = true
    data_trace_enabled = false
  }
}

# -----------------------------------------------------------------------------
# API Key and Usage Plan
# -----------------------------------------------------------------------------
resource "aws_api_gateway_api_key" "demo" {
  name    = local.api_key_name
  enabled = true
}

resource "aws_api_gateway_usage_plan" "demo" {
  name = local.usage_plan_name

  api_stages {
    api_id = aws_api_gateway_rest_api.demo.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "demo" {
  key_id        = aws_api_gateway_api_key.demo.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.demo.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  type        = string
  default     = "sadcloud"
  description = "Base name for S3 resources"
}

variable "no_versioning" {
  type        = bool
  default     = false
  description = "Disable versioning on the primary bucket if set to true"
}

variable "no_default_encryption" {
  type        = bool
  default     = false
  description = "Disable KMS default encryption on the primary bucket if set to true"
}

variable "website_enabled" {
  type        = bool
  default     = false
  description = "Enable static website hosting on the primary bucket"
}

variable "no_logging" {
  type        = bool
  default     = false
  description = "Disable access logging and logging bucket creation if set to true"
}

variable "bucket_acl" {
  type        = string
  default     = "log-delivery-write"
  description = "Canned ACL to apply to the logging bucket"
}

variable "allow_cleartext" {
  type        = bool
  default     = false
  description = "When true, attach bucket policy to primary bucket denying non-SSL (cleartext) requests"
}

variable "s3_getobject_only" {
  type        = bool
  default     = false
  description = "Create a secondary bucket with public read-only access"
}

variable "s3_public" {
  type        = bool
  default     = false
  description = "Create a secondary bucket with full public read-write access"
}

# KMS Key for Primary Bucket
resource "aws_kms_key" "primary" {
  count                   = var.no_default_encryption ? 0 : 1
  description             = "Customer managed KMS key for primary S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

# KMS Key for Logging Bucket
resource "aws_kms_key" "logging" {
  count                   = var.no_logging ? 0 : 1
  description             = "Customer managed KMS key for logging S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

# Logging S3 Bucket
resource "aws_s3_bucket" "logging" {
  count         = var.no_logging ? 0 : 1
  bucket        = "${var.name}-logging"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count      = var.no_logging ? 0 : 1
  bucket     = aws_s3_bucket.logging[0].id
  acl        = var.bucket_acl
  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Primary S3 Bucket
resource "aws_s3_bucket" "primary" {
  bucket_prefix = "${var.name}-"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = var.no_versioning ? "Suspended" : "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "primary" {
  count         = var.no_logging ? 0 : 1
  bucket        = aws_s3_bucket.primary.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

resource "aws_s3_bucket_website_configuration" "primary" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "primary_deny_non_ssl" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Public Read-Only Secondary Bucket
resource "aws_s3_bucket" "getonly" {
  count         = var.s3_getobject_only ? 1 : 0
  bucket        = "${var.name}-getonly"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count      = var.s3_getobject_only ? 1 : 0
  bucket     = aws_s3_bucket.getonly[0].id
  depends_on = [aws_s3_bucket_public_access_block.getonly]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })
}

# Full Public Read-Write Secondary Bucket
resource "aws_s3_bucket" "public" {
  count         = var.s3_public ? 1 : 0
  bucket        = "${var.name}-public"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count      = var.s3_public ? 1 : 0
  bucket     = aws_s3_bucket.public[0].id
  depends_on = [aws_s3_bucket_public_access_block.public]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullPublicAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  service_role_path = "/service-role/"
  partition         = data.aws_partition.current.partition
  account_id        = data.aws_caller_identity.current.account_id
}

# ------------------------------------------------------------------------------
# 1. AWSElasticDisasterRecoveryAgentRole
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "agent_role_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }
  }
}

resource "aws_iam_role" "drs_agent_role" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = local.service_role_path
  assume_role_policy = data.aws_iam_policy_document.agent_role_assume.json
}

resource "aws_iam_role_policy_attachment" "drs_agent_role_attach" {
  role       = aws_iam_role.drs_agent_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy"
}

# ------------------------------------------------------------------------------
# 2. AWSElasticDisasterRecoveryFailbackRole
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "failback_role_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }
  }
}

resource "aws_iam_role" "drs_failback_role" {
  name               = "AWSElasticDisasterRecoveryFailbackRole"
  path               = local.service_role_path
  assume_role_policy = data.aws_iam_policy_document.failback_role_assume.json
}

resource "aws_iam_role_policy_attachment" "drs_failback_role_attach" {
  role       = aws_iam_role.drs_failback_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy"
}

# ------------------------------------------------------------------------------
# EC2 Service Assume Role Document (Shared across EC2-based DRS roles)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_service_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ------------------------------------------------------------------------------
# 3. AWSElasticDisasterRecoveryConversionServerRole
# ------------------------------------------------------------------------------
resource "aws_iam_role" "drs_conversion_server_role" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = local.service_role_path
  assume_role_policy = data.aws_iam_policy_document.ec2_service_assume.json
}

resource "aws_iam_role_policy_attachment" "drs_conversion_server_role_attach" {
  role       = aws_iam_role.drs_conversion_server_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy"
}

# ------------------------------------------------------------------------------
# 4. AWSElasticDisasterRecoveryRecoveryInstanceRole
# ------------------------------------------------------------------------------
resource "aws_iam_role" "drs_recovery_instance_role" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = local.service_role_path
  assume_role_policy = data.aws_iam_policy_document.ec2_service_assume.json
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_role_attach" {
  role       = aws_iam_role.drs_recovery_instance_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

# ------------------------------------------------------------------------------
# 5. AWSElasticDisasterRecoveryReplicationServerRole
# ------------------------------------------------------------------------------
resource "aws_iam_role" "drs_replication_server_role" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = local.service_role_path
  assume_role_policy = data.aws_iam_policy_document.ec2_service_assume.json
}

resource "aws_iam_role_policy_attachment" "drs_replication_server_role_attach" {
  role       = aws_iam_role.drs_replication_server_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy"
}

# ------------------------------------------------------------------------------
# 6. AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole
# ------------------------------------------------------------------------------
resource "aws_iam_role" "drs_recovery_instance_with_launch_actions_role" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = local.service_role_path
  assume_role_policy = data.aws_iam_policy_document.ec2_service_assume.json
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_role_attach_drs" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_role_attach_ssm" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ------------------------------------------------------------------------------
# 7. AWSElasticDisasterRecoveryInitializerRole and Custom InitializePolicy
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "initializer_role_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
  }
}

resource "aws_iam_role" "drs_initializer_role" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.initializer_role_assume.json
}

data "aws_iam_policy_document" "initialize_policy" {
  # Elastic Disaster Recovery Service Initialization & Management
  statement {
    sid    = "DRSServiceInitialization"
    effect = "Allow"
    actions = [
      "drs:InitializeService",
      "drs:GetServiceConfiguration",
      "drs:UpdateServiceConfiguration",
      "drs:DescribeRecoveryInstances",
      "drs:DescribeSourceServers",
      "drs:DescribeReplicationConfigurationTemplates",
      "drs:CreateReplicationConfigurationTemplate"
    ]
    resources = ["*"]
  }

  # EC2 Operations necessary for DRS environment initialization
  statement {
    sid    = "EC2OperationsForDRS"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshots",
      "ec2:DescribeLaunchTemplates",
      "ec2:DescribeLaunchTemplateVersions",
      "ec2:CreateSecurityGroup",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:CreateLaunchTemplate",
      "ec2:CreateLaunchTemplateVersion",
      "ec2:ModifyLaunchTemplate"
    ]
    resources = ["*"]
  }

  # Manage Instance Profiles for DRS EC2 Service Roles
  statement {
    sid    = "DRSInstanceProfileManagement"
    effect = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:GetInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:DeleteInstanceProfile",
      "iam:TagInstanceProfile"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:instance-profile${local.service_role_path}*"
    ]
  }

  # PassRole scoped to DRS service roles restricted to EC2 and DRS services
  statement {
    sid    = "PassRoleForDRS"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.drs_conversion_server_role.arn,
      aws_iam_role.drs_recovery_instance_role.arn,
      aws_iam_role.drs_replication_server_role.arn,
      aws_iam_role.drs_recovery_instance_with_launch_actions_role.arn,
      aws_iam_role.drs_agent_role.arn,
      aws_iam_role.drs_failback_role.arn
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values = [
        "ec2.amazonaws.com",
        "drs.amazonaws.com"
      ]
    }
  }

  # Create Service-Linked Role for AWS Elastic Disaster Recovery
  statement {
    sid    = "CreateDRSServiceLinkedRole"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
    ]

    condition {
      test     = "StringLike"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  # Attach specified DRS AWS-Managed Policies to DRS roles
  statement {
    sid    = "AttachDRSPoliciesToRoles"
    effect = "Allow"
    actions = [
      "iam:AttachRolePolicy",
      "iam:DetachRolePolicy"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role${local.service_role_path}AWSElasticDisasterRecovery*"
    ]

    condition {
      test     = "ArnEquals"
      variable = "iam:PolicyArn"
      values = [
        "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy",
        "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy",
        "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy",
        "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy",
        "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy",
        "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
      ]
    }
  }
}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = "/"
  description = "Permissions policy for AWS Elastic Disaster Recovery Initializer role"
  policy      = data.aws_iam_policy_document.initialize_policy.json
}

resource "aws_iam_role_policy_attachment" "drs_initializer_role_attach" {
  role       = aws_iam_role.drs_initializer_role.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the private subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_type" {
  type        = string
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "instance_count" {
  type        = number
  description = "Number of EC2 instances to provision"
  default     = 3
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS root volume encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name      = "ebs_encryption_key"
    Terraform = "true"
  }
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/ebs-encryption-key"
  target_key_id = aws_kms_key.ebs.key_id
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name      = "Private_Subnet_${count.index + 1}"
    Terraform = "true"
  }
}

resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow inbound SSH from VPC and HTTP/HTTPS from anywhere; restrict egress to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name      = "Terraform_SG_HTTP_HTTPS_SSH"
    Terraform = "true"
  }
}

resource "aws_instance" "compute" {
  count                  = var.instance_count
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp2"
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = true

    tags = {
      Name      = "Terraform_EBS_Volume1"
      Terraform = "true"
    }
  }

  tags = {
    Name      = "Terraform_Instance"
    Terraform = "true"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id
}

# -----------------------------------------------------------------------------
# Role 1: ecsServiceRole
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_service_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "ecs.amazonaws.com",
        "s3.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role" "ecs_service_role" {
  name               = "ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service_assume_role.json
}

data "aws_iam_policy_document" "ecs_task_role_policy" {
  statement {
    sid    = "ElasticLoadBalancingActions"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:DeregisterTargets",
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "elasticloadbalancing:RegisterTargets"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2NetworkingDiscovery"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRouteTables",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMParameterAccess"
    effect = "Allow"
    actions = [
      "ssm:GetParameters",
      "ssm:GetParameter",
      "ssm:GetParametersByPath"
    ]
    resources = [
      "arn:${local.partition}:ssm:${local.region}:${local.account_id}:parameter/*"
    ]
  }

  statement {
    sid    = "SecretsManagerAccess"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret"
    ]
    resources = [
      "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
    ]
  }

  statement {
    sid    = "KMSDecryption"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [
      "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
    ]
  }

  statement {
    sid    = "CodeDeployOperations"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:RegisterApplicationRevision"
    ]
    resources = [
      "arn:${local.partition}:codedeploy:${local.region}:${local.account_id}:*"
    ]
  }

  statement {
    sid    = "SNSPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      "arn:${local.partition}:sns:${local.region}:${local.account_id}:*"
    ]
  }

  statement {
    sid    = "CloudWatchMetricsAndLogs"
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricData",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaInvocations"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [
      "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
    ]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecsTaskRolePolicy"
  role   = aws_iam_role.ecs_service_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_policy.json
}

# -----------------------------------------------------------------------------
# Role 2: ecsExecTaskRole
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_tasks_and_s3_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "ecs-tasks.amazonaws.com",
        "s3.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role" "ecs_exec_task_role" {
  name               = "ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_and_s3_assume_role.json
}

data "aws_iam_policy_document" "ecs_exec_role_policy" {
  statement {
    sid    = "ECRAuthToken"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ECRImagePull"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage"
    ]
    resources = [
      "arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"
    ]
  }

  statement {
    sid    = "DescribeECSServices"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
    ]
  }

  statement {
    sid    = "SecretsManagerAccess"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
    ]
  }

  statement {
    sid    = "KMSDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
    ]
  }

  statement {
    sid    = "SSMParameters"
    effect = "Allow"
    actions = [
      "ssm:GetParameters"
    ]
    resources = [
      "arn:${local.partition}:ssm:${local.region}:${local.account_id}:parameter/*"
    ]
  }
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name   = "ecsExecRolePolicy"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_exec_role_policy.json
}

data "aws_iam_policy_document" "ecs_execution_additional" {
  statement {
    sid    = "ECSListAndDescribe"
    effect = "Allow"
    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = [
      "arn:${local.partition}:s3:::*/*"
    ]
  }
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_execution_additional.json
}

# -----------------------------------------------------------------------------
# Role 3: ecsTaskRole
# -----------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name               = "ecsTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_and_s3_assume_role.json
}

data "aws_iam_policy_document" "ecs_task_role_additional" {
  statement {
    sid    = "ECSListAndDescribe"
    effect = "Allow"
    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = [
      "arn:${local.partition}:s3:::*/*"
    ]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name   = "ecsTaskRole_additional"
  role   = aws_iam_role.ecs_task_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_additional.json
}

# -----------------------------------------------------------------------------
# Role 4: ecs_autoscale_role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_autoscale_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_autoscale_role" {
  name               = "ecs_autoscale_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_autoscale_assume_role.json
}

data "aws_iam_policy_document" "ecs_autoscale_role_policy" {
  statement {
    sid    = "ECSServiceScale"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:UpdateService"
    ]
    resources = [
      "arn:${local.partition}:ecs:${local.region}:${local.account_id}:service/*/*"
    ]
  }

  statement {
    sid    = "CloudWatchAlarmQuery"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name   = "ecs_autoscale_role_policy"
  role   = aws_iam_role.ecs_autoscale_role.id
  policy = data.aws_iam_policy_document.ecs_autoscale_role_policy.json
}

# -----------------------------------------------------------------------------
# Role 5: ecs_codedeploy_role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_codedeploy_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_codedeploy_role" {
  name               = "ecs_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_codedeploy_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_codedeploy_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy" {
  statement {
    sid    = "ECSTaskSetManagement"
    effect = "Allow"
    actions = [
      "ecs:CreateTaskSet",
      "ecs:DeleteTaskSet",
      "ecs:DescribeServices",
      "ecs:DescribeTaskSets",
      "ecs:ModifyListenerCertificates",
      "ecs:UpdateServicePrimaryTaskSet",
      "ecs:UpdateTaskSet"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ELBManagement"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:ModifyRule"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaLifecycleHooks"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [
      "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
    ]
  }

  statement {
    sid    = "CloudWatchAlarmQuery"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SNSPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      "arn:${local.partition}:sns:${local.region}:${local.account_id}:*"
    ]
  }

  statement {
    sid    = "S3ArtifactRetrieval"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion"
    ]
    resources = [
      "arn:${local.partition}:s3:::*/*"
    ]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy.json
}

data "aws_iam_policy_document" "ecs_codedeploy_pass_role_task" {
  statement {
    sid    = "PassRoleToECSTaskRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.ecs_task_role.arn
    ]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_pass_role_task.json
}

data "aws_iam_policy_document" "ecs_codedeploy_pass_role_task_exec" {
  statement {
    sid    = "PassRoleToECSExecTaskRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.ecs_exec_task_role.arn
    ]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_pass_role_task_exec.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "prod"
  external_subnets = [
    { cidr = "10.41.0.0/24", name = "Subnet0-1a" },
    { cidr = "10.41.1.0/24", name = "Subnet1-1b" },
    { cidr = "10.41.2.0/24", name = "Subnet2-1c" },
    { cidr = "10.41.3.0/24", name = "Subnet3-1d" }
  ]
  internal_subnets = [
    { cidr = "10.40.0.0/24", name = "Subnet0-1a" },
    { cidr = "10.40.1.0/24", name = "Subnet1-1b" },
    { cidr = "10.40.2.0/24", name = "Subnet2-1c" },
    { cidr = "10.40.3.0/24", name = "Subnet3-1d" }
  ]
}

# ==============================================================================
# External VPC & Networking
# ==============================================================================

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "Production External Default SG"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name        = "External Public Route Table"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_subnet" "external" {
  count                   = 4
  vpc_id                  = aws_vpc.external.id
  cidr_block              = local.external_subnets[count.index].cidr
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = local.external_subnets[count.index].name
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_route_table_association" "external" {
  count          = 4
  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id
  subnet_ids             = aws_subnet.external[*].id

  # Ingress: Rule 100 allow all traffic
  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Egress: Rule 100 allow ICMP
  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  # Egress: Rule 150 allow all traffic
  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production External Default NACL"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

# ==============================================================================
# Internal VPC & Networking
# ==============================================================================

resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name        = "Production Internal Default SG"
    purpose     = "Production Internal VPC"
    environment = local.environment
  }
}

resource "aws_subnet" "internal" {
  count                   = 4
  vpc_id                  = aws_vpc.internal.id
  cidr_block              = local.internal_subnets[count.index].cidr
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = local.internal_subnets[count.index].name
    purpose     = "Production Internal VPC"
    environment = local.environment
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id
  subnet_ids             = aws_subnet.internal[*].id

  # Ingress: Rule 100 allow ICMP
  ingress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  # Egress: Rule 100 allow ICMP
  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  # Egress: Rule 150 allow all traffic
  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production Internal Default NACL"
    purpose     = "Production Internal VPC"
    environment = local.environment
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "prefix" {
  description = "Resource prefix for naming resources"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional pre-existing ACM certificate ARN. If null, a self-signed certificate is provisioned."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional override for n8n WEBHOOK_URL"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS task instances"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Docker image for n8n"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "ECS Fargate capacity provider strategy type"
  type        = string
  default     = "FARGATE_SPOT"
}

locals {
  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  log_group_name       = "${var.prefix}-logs"
  webhook_url          = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.prefix}-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb-sg"
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP access from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS access from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs" {
  name        = "${var.prefix}-ecs-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow port 5678 from ALB"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.prefix}-ecs-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS access from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.prefix}-efs-sg"
  }
}

resource "aws_efs_file_system" "main" {
  creation_token = "${var.prefix}-efs"
  encrypted      = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.prefix}-efs"
  }
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    gid = 1000
    uid = 1000
  }

  root_directory {
    path = "/n8n"
    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "0777"
    }
  }

  tags = {
    Name = "${var.prefix}-efs-ap"
  }
}

resource "aws_efs_mount_target" "main" {
  count           = 3
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = "n8n.local"
    organization = "Self Signed"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  tags = {
    Name = "${var.prefix}-self-signed-cert"
  }
}

resource "aws_lb" "main" {
  name                       = "${var.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.prefix}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    port                = "5678"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    matcher             = "200"
  }

  tags = {
    Name = "${var.prefix}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name              = local.log_group_name
  retention_in_days = 1

  tags = {
    Name = local.log_group_name
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "task_execution" {
  name               = "${var.prefix}-task-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name = "${var.prefix}-task-execution-role"
  }
}

data "aws_iam_policy_document" "task_execution" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["${aws_cloudwatch_log_group.main.arn}:*"]
  }
}

resource "aws_iam_role_policy" "task_execution" {
  name   = "${var.prefix}-task-execution-policy"
  role   = aws_iam_role.task_execution.id
  policy = data.aws_iam_policy_document.task_execution.json
}

resource "aws_iam_role" "task" {
  name               = "${var.prefix}-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name = "${var.prefix}-task-role"
  }
}

data "aws_iam_policy_document" "task" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["${aws_cloudwatch_log_group.main.arn}:*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess"
    ]
    resources = [aws_efs_file_system.main.arn]
  }
}

resource "aws_iam_role_policy" "task" {
  name   = "${var.prefix}-task-policy"
  role   = aws_iam_role.task.id
  policy = data.aws_iam_policy_document.task.json
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.task_execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n-storage"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-storage"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "n8n"
        }
      }
    }
  ])

  tags = {
    Name = "${var.prefix}-task-def"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_ecs_service" "main" {
  name            = "${var.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
    aws_efs_mount_target.main,
    aws_ecs_cluster_capacity_providers.main
  ]

  tags = {
    Name = "${var.prefix}-service"
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.32.0.0/20"
}

resource "aws_vpc" "lambda_rds_dev" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  tags = {
    Name = "lambda-rds-dev-default-sg"
  }
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.lambda_rds_dev.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

resource "aws_subnet" "db_subnet_1" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "db_subnet_2" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "lambda_subnet" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "bastion_subnet" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion_subnet.id
