terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Whether to create SQS resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Base human-readable name for the SQS queue, stripped of any .fifo suffix"
  type        = string
  default     = "app-queue"
}

variable "use_name_prefix" {
  description = "Determines whether to use name as a prefix"
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at message group or queue level (messageGroup or queue)"
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "Specifies whether FIFO queue throughput quota applies to entire queue or per message group (perQueue or perMessageGroupId)"
  type        = string
  default     = "perQueue"
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds"
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message"
  type        = number
  default     = 345600
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain"
  type        = number
  default     = 262144
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed"
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive in seconds"
  type        = number
  default     = 0
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages"
  type        = number
  default     = 300
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue (DLQ)"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Custom name for the DLQ. If omitted, defaults to <name>-dlq"
  type        = string
  default     = null
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue"
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Determines whether to attach a redrive allow policy to the DLQ"
  type        = bool
  default     = true
}

variable "create_queue_policy" {
  description = "Whether to conditionally create an SQS queue policy for the main queue"
  type        = bool
  default     = false
}

variable "create_dlq_queue_policy" {
  description = "Whether to conditionally create an SQS queue policy for the DLQ"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A mapping of tags to assign to the resources"
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  stripped_name = trimsuffix(var.name, ".fifo")

  queue_name   = var.fifo_queue ? "${local.stripped_name}.fifo" : local.stripped_name
  queue_prefix = "${local.stripped_name}-"

  raw_dlq_base = var.dlq_name != null ? trimsuffix(var.dlq_name, ".fifo") : "${local.stripped_name}-dlq"
  dlq_name     = var.fifo_queue ? "${local.raw_dlq_base}.fifo" : local.raw_dlq_base
  dlq_prefix   = "${local.raw_dlq_base}-"

  main_queue_arn = "arn:aws:sqs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${local.queue_name}"

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [local.main_queue_arn]
  })
}

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = var.use_name_prefix ? null : local.dlq_name
  name_prefix = var.use_name_prefix ? local.dlq_prefix : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  sqs_managed_sse_enabled           = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  redrive_allow_policy = var.create_dlq_redrive_allow_policy ? local.redrive_allow_policy : null

  tags = var.tags
}

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : local.queue_name
  name_prefix = var.use_name_prefix ? local.queue_prefix : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  sqs_managed_sse_enabled           = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags
}

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  statement {
    sid       = "QueueOwnerAccess"
    effect    = "Allow"
    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.this[0].arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

data "aws_iam_policy_document" "dlq_queue_policy" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  statement {
    sid       = "DlqQueueOwnerAccess"
    effect    = "Allow"
    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.dlq[0].arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = data.aws_iam_policy_document.dlq_queue_policy[0].json
}

output "queue_id" {
  description = "The URL of the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "The URL of the SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_id" {
  description = "The URL of the created Amazon SQS dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "The ARN of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "The URL of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dlq_name" {
  description = "The name of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  type        = bool
  default     = true
  description = "Controls whether resources are created."
}

variable "function_name" {
  type        = string
  default     = "my-lambda-function"
  description = "Name of the target Lambda function."
}

variable "alias_name" {
  type        = string
  default     = "live"
  description = "Name of the Lambda function alias routing traffic."
}

variable "current_version" {
  type        = string
  default     = "1"
  description = "Current published version of the Lambda function."
}

variable "target_version" {
  type        = string
  default     = "2"
  description = "Target published version of the Lambda function for blue/green deployment."
}

variable "before_allow_traffic_hook_arn" {
  type        = string
  default     = null
  description = "ARN of the Lambda function hook executed before traffic shifting begins."
}

variable "after_allow_traffic_hook_arn" {
  type        = string
  default     = null
  description = "ARN of the Lambda function hook executed after traffic shifting finishes."
}

variable "create_app" {
  type        = bool
  default     = false
  description = "Whether to create a new CodeDeploy application for Lambda."
}

variable "use_existing_app" {
  type        = bool
  default     = false
  description = "Whether to use an existing CodeDeploy application instead of creating one."
}

variable "app_name" {
  type        = string
  default     = null
  description = "Name of the CodeDeploy application."
}

variable "create_deployment_group" {
  type        = bool
  default     = false
  description = "Whether to create a CodeDeploy deployment group."
}

variable "use_existing_deployment_group" {
  type        = bool
  default     = false
  description = "Whether to use an existing CodeDeploy deployment group."
}

variable "deployment_group_name" {
  type        = string
  default     = null
  description = "Name of the CodeDeploy deployment group."
}

variable "deployment_config_name" {
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
  description = "CodeDeploy deployment configuration for Lambda blue/green traffic shifting."
}

variable "auto_rollback_events" {
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
  description = "Event types that trigger an automatic rollback in CodeDeploy."
}

variable "alarm_names" {
  type        = list(string)
  default     = []
  description = "List of CloudWatch alarm names to monitor during deployment."
}

variable "trigger_configs" {
  type = list(object({
    trigger_events     = list(string)
    trigger_name       = string
    trigger_target_arn = string
  }))
  default     = []
  description = "Notification triggers for deployment lifecycle events."
}

variable "create_codedeploy_role" {
  type        = bool
  default     = true
  description = "Whether to create an IAM role for the CodeDeploy service."
}

variable "codedeploy_role_arn" {
  type        = string
  default     = null
  description = "Pre-existing CodeDeploy IAM role ARN if create_codedeploy_role is false."
}

variable "service_principals" {
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
  description = "Service principals allowed to assume the CodeDeploy role."
}

variable "attach_hooks_policy" {
  type        = bool
  default     = true
  description = "Whether to attach an inline IAM policy granting CodeDeploy invocation rights on Lambda hooks."
}

variable "attach_triggers_policy" {
  type        = bool
  default     = false
  description = "Whether to attach an inline IAM policy granting CodeDeploy publish rights on SNS notification topics."
}

variable "create_deployment" {
  type        = bool
  default     = false
  description = "Whether to generate deployment artifacts and manage deployment execution."
}

variable "aws_cli_command" {
  type        = string
  default     = "aws"
  description = "Path or binary name for the AWS CLI executable."
}

variable "get_deployment_sleep_timer" {
  type        = number
  default     = 5
  description = "Polling interval in seconds when checking CodeDeploy deployment status."
}

variable "save_deploy_script" {
  type        = bool
  default     = false
  description = "Whether to save the generated deployment bash script locally."
}

variable "deploy_script_path" {
  type        = string
  default     = "deploy_lambda.sh"
  description = "Local filesystem path where the deployment script will be written if save_deploy_script is true."
}

variable "run_deployment" {
  type        = bool
  default     = false
  description = "Whether to trigger the deployment via null_resource provisioner."
}

variable "force_deploy" {
  type        = string
  default     = ""
  description = "Arbitrary value used to force re-execution of the deployment trigger."
}

locals {
  app_name              = coalesce(var.app_name, "${var.function_name}-codedeploy-app")
  deployment_group_name = coalesce(var.deployment_group_name, "${var.function_name}-codedeploy-group")

  resolved_codedeploy_role_arn = var.create && var.create_codedeploy_role ? (
    length(aws_iam_role.codedeploy_lambda) > 0 ? aws_iam_role.codedeploy_lambda[0].arn : ""
  ) : var.codedeploy_role_arn

  hook_arns = compact([
    var.before_allow_traffic_hook_arn != null ? var.before_allow_traffic_hook_arn : "",
    var.after_allow_traffic_hook_arn != null ? var.after_allow_traffic_hook_arn : ""
  ])

  trigger_target_arns = distinct([
    for trigger in var.trigger_configs : trigger.trigger_target_arn
    if trigger.trigger_target_arn != null && trigger.trigger_target_arn != ""
  ])

  hooks_map = merge(
    var.before_allow_traffic_hook_arn != null ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
    var.after_allow_traffic_hook_arn != null ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {}
  )

  appspec_content_raw = {
    version = 0.0
    Resources = [
      {
        (var.function_name) = {
          Type = "AWS::Lambda::Function"
          Properties = merge(
            {
              Name           = var.function_name
              Alias          = var.alias_name
              CurrentVersion = var.current_version
              TargetVersion  = var.target_version
            },
            length(local.hooks_map) > 0 ? { Hooks = [local.hooks_map] } : {}
          )
        }
      }
    ]
  }

  appspec_json = jsonencode(local.appspec_content_raw)

  deploy_script_content = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    APP_NAME="${local.app_name}"
    DEPLOYMENT_GROUP="${local.deployment_group_name}"
    CONFIG_NAME="${var.deployment_config_name}"
    SLEEP_TIMER="${var.get_deployment_sleep_timer}"
    AWS_CLI="${var.aws_cli_command}"

    APPSPEC_CONTENT='${local.appspec_json}'

    echo "Creating CodeDeploy deployment for application: $APP_NAME, group: $DEPLOYMENT_GROUP..."

    DEPLOYMENT_ID=$($AWS_CLI codedeploy create-deployment \
      --application-name "$APP_NAME" \
      --deployment-group-name "$DEPLOYMENT_GROUP" \
      --deployment-config-name "$CONFIG_NAME" \
      --revision "{\"revisionType\": \"AppSpecContent\", \"appSpecContent\": {\"content\": $(echo "$APPSPEC_CONTENT" | jq -R -s .)}}" \
      --query "deploymentId" \
      --output text)

    echo "Deployment created successfully with ID: $DEPLOYMENT_ID"
    echo "Waiting for deployment to complete..."

    while true; do
      STATUS=$($AWS_CLI codedeploy get-deployment \
        --deployment-id "$DEPLOYMENT_ID" \
        --query "deploymentInfo.status" \
        --output text)

      echo "Current status: $STATUS"

      if [ "$STATUS" = "Succeeded" ]; then
        echo "Deployment $DEPLOYMENT_ID succeeded!"
        break
      elif [ "$STATUS" = "Failed" ] || [ "$STATUS" = "Stopped" ]; then
        echo "Deployment $DEPLOYMENT_ID terminated with status: $STATUS" >&2
        exit 1
      fi

      sleep "$SLEEP_TIMER"
    done
  EOT
}

data "aws_iam_policy_document" "codedeploy_assume_role" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.service_principals
    }
  }
}

resource "aws_iam_role" "codedeploy_lambda" {
  count              = var.create && var.create_codedeploy_role ? 1 : 0
  name_prefix        = "CodeDeployLambdaServiceRole-"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role[0].json
}

resource "aws_iam_role_policy_attachment" "codedeploy_managed" {
  count      = var.create && var.create_codedeploy_role ? 1 : 0
  role       = aws_iam_role.codedeploy_lambda[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "codedeploy_hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hook_arns) > 0 ? 1 : 0

  statement {
    sid       = "InvokeLambdaHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hook_arns
  }
}

resource "aws_iam_role_policy" "codedeploy_hooks" {
  count  = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hook_arns) > 0 ? 1 : 0
  name   = "CodeDeployLambdaHooksPolicy"
  role   = aws_iam_role.codedeploy_lambda[0].id
  policy = data.aws_iam_policy_document.codedeploy_hooks[0].json
}

data "aws_iam_policy_document" "codedeploy_triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(local.trigger_target_arns) > 0 ? 1 : 0

  statement {
    sid       = "PublishSNSDeploymentTriggers"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = local.trigger_target_arns
  }
}

resource "aws_iam_role_policy" "codedeploy_triggers" {
  count  = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(local.trigger_target_arns) > 0 ? 1 : 0
  name   = "CodeDeployNotificationTriggersPolicy"
  role   = aws_iam_role.codedeploy_lambda[0].id
  policy = data.aws_iam_policy_document.codedeploy_triggers[0].json
}

resource "aws_codedeploy_app" "lambda_app" {
  count            = var.create && var.create_app && !var.use_existing_app ? 1 : 0
  compute_platform = "Lambda"
  name             = local.app_name
}

resource "aws_codedeploy_deployment_group" "lambda_group" {
  count                  = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0
  app_name               = var.create_app && !var.use_existing_app ? aws_codedeploy_app.lambda_app[0].name : local.app_name
  deployment_group_name  = local.deployment_group_name
  service_role_arn       = local.resolved_codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = length(var.auto_rollback_events) > 0
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_names) > 0 ? [1] : []
    content {
      alarms  = var.alarm_names
      enabled = true
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_configs
    content {
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.codedeploy_managed
  ]
}

resource "local_file" "deploy_script" {
  count           = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0
  content         = local.deploy_script_content
  filename        = var.deploy_script_path
  file_permission = "0755"
}

resource "null_resource" "run_deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    appspec_content = local.appspec_json
    current_version = var.current_version
    target_version  = var.target_version
    force_deploy    = var.force_deploy
  }

  provisioner "local-exec" {
    command     = local.deploy_script_content
    interpreter = ["/usr/bin/env", "bash", "-c"]
  }

  depends_on = [
    aws_codedeploy_deployment_group.lambda_group,
    aws_codedeploy_app.lambda_app
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC."
  default     = "10.16.0.0/16"
}

variable "name_prefix" {
  type        = string
  description = "Prefix for the VPC and associated resource Name tags."
  default     = "tf-project"
}

variable "max_subnet_count" {
  type        = number
  description = "Maximum number of Availability Zones to select for subnet distribution."
  default     = 3
}

variable "web_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for web subnets."
  default     = ["10.16.1.0/24", "10.16.2.0/24"]
}

variable "app_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for application (private) subnets."
  default     = ["10.16.11.0/24", "10.16.12.0/24"]
}

variable "db_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for database (private) subnets."
  default     = ["10.16.21.0/24", "10.16.22.0/24"]
}

variable "reserved_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for reserved (private) subnets."
  default     = ["10.16.31.0/24", "10.16.32.0/24"]
}

variable "interface_vpc_endpoints" {
  type = map(object({
    service_name = string
  }))
  description = "Map of interface VPC endpoints to create."
  default     = {}
}

variable "gateway_vpc_endpoint_service_name" {
  type        = string
  description = "AWS Gateway endpoint service name (e.g., com.amazonaws.us-east-1.s3). Leave empty to skip."
  default     = ""
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

locals {
  vpc_name             = "${var.name_prefix}-${random_integer.vpc_suffix.result}"
  available_az_count   = length(data.aws_availability_zones.available.names)
  az_selection_limit   = min(var.max_subnet_count, local.available_az_count)
  has_web_subnets      = length(var.web_subnet_cidrs) > 0
  has_private_subnets  = (length(var.app_subnet_cidrs) + length(var.db_subnet_cidrs) + length(var.reserved_subnet_cidrs)) > 0
  has_gateway_endpoint = var.gateway_vpc_endpoint_service_name != "" && var.gateway_vpc_endpoint_service_name != null
  endpoint_subnet_ids  = length(aws_subnet.app) > 0 ? [for s in aws_subnet.app : s.id] : (length(aws_subnet.web) > 0 ? [for s in aws_subnet.web : s.id] : [])
}

resource "random_shuffle" "az" {
  input        = data.aws_availability_zones.available.names
  result_count = local.az_selection_limit
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "web" {
  count                   = length(var.web_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.web_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az.result[count.index % length(random_shuffle.az.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-web-${count.index + 1}"
    Tier = "Web"
  }
}

resource "aws_subnet" "app" {
  count                   = length(var.app_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.app_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az.result[count.index % length(random_shuffle.az.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-app-${count.index + 1}"
    Tier = "App"
  }
}

resource "aws_subnet" "db" {
  count                   = length(var.db_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.db_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az.result[count.index % length(random_shuffle.az.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-db-${count.index + 1}"
    Tier = "Database"
  }
}

resource "aws_subnet" "reserved" {
  count                   = length(var.reserved_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.reserved_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az.result[count.index % length(random_shuffle.az.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-reserved-${count.index + 1}"
    Tier = "Reserved"
  }
}

resource "aws_internet_gateway" "main" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

resource "aws_route_table" "public" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "web" {
  count          = length(var.web_subnet_cidrs)
  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count  = local.has_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "app" {
  count          = length(var.app_subnet_cidrs)
  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "db" {
  count          = length(var.db_subnet_cidrs)
  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count          = length(var.reserved_subnet_cidrs)
  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_security_group" "vpc_endpoints" {
  count       = length(var.interface_vpc_endpoints) > 0 ? 1 : 0
  name        = "${local.vpc_name}-vpce-sg"
  description = "Security group for interface VPC endpoints restricting ingress to VPC CIDR on port 443"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.vpc_name}-vpce-sg"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each            = var.interface_vpc_endpoints
  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints[0].id]
  private_dns_enabled = true

  tags = {
    Name = "${local.vpc_name}-vpce-${each.key}"
  }
}

resource "aws_vpc_endpoint" "gateway" {
  count             = (local.has_gateway_endpoint && local.has_private_subnets) ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_vpc_endpoint_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private[0].id]

  tags = {
    Name = "${local.vpc_name}-gateway-vpce"
  }
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "selected_availability_zones" {
  description = "List of availability zones selected for subnets."
  value       = random_shuffle.az.result
}

output "web_subnet_ids" {
  description = "IDs of the web public subnets."
  value       = aws_subnet.web[*].id
}

output "app_subnet_ids" {
  description = "IDs of the app private subnets."
  value       = aws_subnet.app[*].id
}

output "db_subnet_ids" {
  description = "IDs of the database private subnets."
  value       = aws_subnet.db[*].id
}

output "reserved_subnet_ids" {
  description = "IDs of the reserved private subnets."
  value       = aws_subnet.reserved[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_id" {
  description = "ID of the shared private route table."
  value       = try(aws_route_table.private[0].id, null)
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = try(aws_internet_gateway.main[0].id, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "internal_domain_name" {
  type        = string
  description = "Internal domain name for DHCP options and private Route 53 zone"
  default     = "internal"
}

variable "dns_servers" {
  type        = list(string)
  description = "DNS servers for DHCP options"
  default     = ["AmazonProvidedDNS", "8.8.8.8"]
}

variable "admin_ssh_cidrs" {
  type        = list(string)
  description = "Admin CIDR blocks permitted for Home SSH security group"
  default     = ["203.0.113.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# --- VPC & Internet Gateway ---

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

# --- DHCP Options & Association ---

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain_name
  domain_name_servers = var.dns_servers

  tags = {
    Name = "main-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

# --- Private Route 53 Zone ---

resource "aws_route53_zone" "internal" {
  name = var.internal_domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "internal-zone"
  }
}

# --- Subnets ---

resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved"
  }
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "sandbox"
  }
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "web"
  }
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "database"
  }
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/22"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "gameserver"
  }
}

# --- Route Tables & Associations ---

resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "reserved-rt"
  }
}

resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "sandbox-rt"
  }
}

resource "aws_route_table_association" "sandbox" {
  subnet_id      = aws_subnet.sandbox.id
  route_table_id = aws_route_table.sandbox.id
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "web-rt"
  }
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "database-rt"
  }
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "gameserver-rt"
  }
}

resource "aws_route_table_association" "gameserver" {
  subnet_id      = aws_subnet.gameserver.id
  route_table_id = aws_route_table.gameserver.id
}

# --- Network ACLs ---

# 1. Sandbox NACL: Allow all TCP in and out
resource "aws_network_acl" "sandbox" {
  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "sandbox-nacl"
  }
}

resource "aws_network_acl_association" "sandbox" {
  network_acl_id = aws_network_acl.sandbox.id
  subnet_id      = aws_subnet.sandbox.id
}

# 2. Web NACL: Inbound TCP 22, 80, 443, 32768-65535; Outbound all TCP
resource "aws_network_acl" "web" {
  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "web-nacl"
  }
}

resource "aws_network_acl_association" "web" {
  network_acl_id = aws_network_acl.web.id
  subnet_id      = aws_subnet.web.id
}

# 3. Database NACL: Only TCP to/from web (10.0.2.0/24) and gameserver (10.0.4.0/22)
resource "aws_network_acl" "database" {
  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "database-nacl"
  }
}

resource "aws_network_acl_association" "database" {
  network_acl_id = aws_network_acl.database.id
  subnet_id      = aws_subnet.database.id
}

# 4. Gameserver NACL: Inbound SSH (22), TCP/UDP 27015 & 27020, TCP/UDP 32768-65535; Outbound all TCP & UDP
resource "aws_network_acl" "gameserver" {
  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    protocol   = "udp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    protocol   = "udp"
    rule_no    = 140
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  ingress {
    protocol   = "udp"
    rule_no    = 160
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "udp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "gameserver-nacl"
  }
}

resource "aws_network_acl_association" "gameserver" {
  network_acl_id = aws_network_acl.gameserver.id
  subnet_id      = aws_subnet.gameserver.id
}

# --- Security Groups ---

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allows SSH from admin CIDRs and self, restricted egress to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_ssh_cidrs
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restricted egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allows SSH from VPC CIDR and self, restricted egress to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restricted egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Packer SSH"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "env" {
  description = "Environment name used to prefix resource Name tags (e.g., dev, prod)"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets across 3 AZs"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "app_subnet_cidrs" {
  description = "CIDR blocks for the private application subnets across 3 AZs"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "db_subnet_cidrs" {
  description = "CIDR blocks for the private database subnets across 3 AZs"
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}public-subnet-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_eip" "nat" {
  count      = 3
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}public-rt"
    Tier = "public"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "app" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.app_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}app-subnet-${count.index + 1}"
    Tier = "application"
  }
}

resource "aws_route_table" "app" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.name_prefix}app-rt-${count.index + 1}"
    Tier = "application"
  }
}

resource "aws_route_table_association" "app" {
  count          = 3
  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.app[count.index].id
}

resource "aws_subnet" "db" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.db_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}db-subnet-${count.index + 1}"
    Tier = "database"
  }
}

resource "aws_route_table" "db" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}db-rt"
    Tier = "database"
  }
}

resource "aws_route_table_association" "db" {
  count          = 3
  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.db.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Base name of the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Whether to prefix the bucket name with the AWS account alias"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to append a random alphanumeric suffix to the bucket name"
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional JSON-encoded custom bucket policy to extend"
  type        = string
  default     = null
}

variable "enable_s3_public_access_block" {
  description = "Whether to enable S3 Public Access Block configuration"
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership control setting for the bucket"
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "kms_master_key_id" {
  description = "The AWS KMS master key ID used for the SSE-KMS encryption. Defaults to null for AES256"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether to use an S3 Bucket Key for server-side encryption"
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning status of the bucket (Enabled, Suspended, or Disabled)"
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Whether to allow force destruction of the bucket and all objects"
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Whether to enable storage class analytics configuration and export"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Whether to enable S3 inventory reporting"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target bucket for S3 server access logging"
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled or Suspended). Null to leave unconfigured"
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Bucket canned ACL. Only applied if specified and object_ownership is not BucketOwnerEnforced"
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule configurations to apply to the bucket"
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

data "aws_caller_identity" "current" {}
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

resource "random_string" "suffix" {
  count   = var.use_random_suffix ? 1 : 0
  length  = 8
  special = false
  upper   = false
}

locals {
  account_id        = data.aws_caller_identity.current.account_id
  alias_prefix      = var.use_account_alias_prefix && length(data.aws_iam_account_alias.current) > 0 ? "${data.aws_iam_account_alias.current[0].account_alias}-" : ""
  suffix_part       = var.use_random_suffix ? "-${random_string.suffix[0].result}" : ""
  final_bucket_name = lower("${local.alias_prefix}${var.bucket_name}${local.suffix_part}")

  analytics_prefix = "_AWSBucketAnalytics/"
  inventory_prefix = "_AWSBucketInventory/"
}

resource "aws_s3_bucket" "this" {
  bucket        = local.final_bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket                                 = aws_s3_bucket.this.id
  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "abort-incomplete-multipart-uploads-and-noncurrent-versions"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  rule {
    id     = "analytics-export-lifecycle"
    status = var.enable_analytics ? "Enabled" : "Disabled"

    filter {
      prefix = local.analytics_prefix
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "inventory-report-lifecycle"
    status = var.enable_bucket_inventory ? "Enabled" : "Disabled"

    filter {
      prefix = local.inventory_prefix
    }

    expiration {
      days = 14
    }
  }
}

resource "aws_s3_bucket_analytics_configuration" "this" {
  count  = var.enable_analytics ? 1 : 0
  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketAnalytics"

  storage_class_analysis {
    data_export {
      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          prefix     = local.analytics_prefix
          format     = "CSV"
        }
      }
    }
  }
}

resource "aws_s3_bucket_inventory" "this" {
  count                    = var.enable_bucket_inventory ? 1 : 0
  bucket                   = aws_s3_bucket.this.id
  name                     = "EntireBucketInventory"
  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = local.inventory_prefix
      format     = "ORC"
      account_id = local.account_id

      encryption {
        dynamic "sse_s3" {
          for_each = var.kms_master_key_id == null ? [1] : []
          content {}
        }
        dynamic "sse_kms" {
          for_each = var.kms_master_key_id != null ? [1] : []
          content {
            key_id = var.kms_master_key_id
          }
        }
      }
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.transfer_acceleration != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

data "aws_iam_policy_document" "combined" {
  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []

  statement {
    sid     = "DenyNonTLSRequests"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3ServiceDataReportsWithOwnerFullControl"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.this.arn}/${local.analytics_prefix}*",
      "${aws_s3_bucket.this.arn}/${local.inventory_prefix}*"
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket     = aws_s3_bucket.this.id
  policy     = data.aws_iam_policy_document.combined.json
  depends_on = [aws_s3_bucket_public_access_block.this]
}

output "bucket_id" {
  description = "The ID of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name"
  value       = aws_s3_bucket.this.bucket_domain_name
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for the provider."
  default     = "us-east-1"
}

variable "bucket_name" {
  type        = string
  description = "Name of the S3 bucket."
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  type        = string
  description = "Environment tag value."
  default     = "Development"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to merge with standard tags."
  default     = {}
}

variable "sse_algorithm" {
  type        = string
  description = "Server-side encryption algorithm to use. Valid values: 'AES256', 'aws:kms', or 'none'."
  default     = "AES256"
}

variable "kms_master_key_id" {
  type        = string
  description = "The AWS KMS master key ID used for the SSE-KMS encryption. Only used if sse_algorithm is 'aws:kms'."
  default     = null
}

variable "bucket_key_enabled" {
  type        = bool
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE with KMS."
  default     = true
}

variable "enable_public_access_block" {
  type        = bool
  description = "Whether to create the aws_s3_bucket_public_access_block resource."
  default     = true
}

variable "block_public_acls" {
  type        = bool
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  default     = true
}

variable "block_public_policy" {
  type        = bool
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  default     = true
}

variable "ignore_public_acls" {
  type        = bool
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  default     = true
}

variable "restrict_public_buckets" {
  type        = bool
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  default     = true
}

variable "control_object_ownership" {
  type        = bool
  description = "Whether to manage S3 bucket ownership controls."
  default     = false
}

variable "object_ownership" {
  type        = string
  description = "Object ownership setting. Valid values: 'BucketOwnerPreferred', 'ObjectWriter', or 'BucketOwnerEnforced'."
  default     = "ObjectWriter"
}

variable "acl" {
  type        = string
  description = "The canned ACL to apply. Valid values include 'private', 'public-read', etc. Mutually exclusive with grants."
  default     = null
}

variable "grants" {
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
    email       = optional(string)
  }))
  description = "List of grant configurations for bucket ACL."
  default     = []
}

variable "versioning_status" {
  type        = string
  description = "Desired versioning status. Valid values: 'Enabled', 'Suspended', or 'Disabled'."
  default     = "Disabled"
}

variable "mfa_delete" {
  type        = string
  description = "Desired MFA delete status. Valid values: 'Enabled' or 'Disabled'."
  default     = "Disabled"
}

variable "bucket_logging" {
  type        = bool
  description = "Whether to enable bucket server access logging."
  default     = false
}

variable "logging_target_bucket" {
  type        = string
  description = "The name of the bucket where logs should be delivered."
  default     = null
}

variable "logging_target_prefix" {
  type        = string
  description = "A prefix for all log object keys."
  default     = "logs/"
}

variable "object_lock_enabled" {
  type        = bool
  description = "Indicates whether this bucket has an Object Lock configuration enabled."
  default     = false
}

variable "object_lock_mode" {
  type        = string
  description = "The default Object Lock retention mode. Valid values: 'GOVERNANCE' or 'COMPLIANCE'."
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  type        = number
  description = "The number of days that you want to specify for the default retention period."
  default     = 30
}

variable "object_lock_years" {
  type        = number
  description = "The number of years that you want to specify for the default retention period."
  default     = null
}

variable "website_enabled" {
  type        = bool
  description = "Whether to enable static website hosting configuration."
  default     = false
}

variable "website_index_document" {
  type        = string
  description = "The index document suffix for static website hosting."
  default     = "index.html"
}

variable "website_error_document" {
  type        = string
  description = "The error document for static website hosting."
  default     = "error.html"
}

variable "website_redirect_all_requests_to" {
  type = object({
    host_name = string
    protocol  = optional(string)
  })
  description = "Redirect all requests to this host."
  default     = null
}

variable "website_routing_rules" {
  type        = string
  description = "JSON array containing routing rules for website hosting."
  default     = null
}

variable "cors_rules" {
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  description = "List of CORS rules to apply to the bucket."
  default     = []
}

variable "lifecycle_rules" {
  type = list(object({
    id      = string
    enabled = bool
    prefix  = optional(string)
    tags    = optional(map(string))

    abort_incomplete_multipart_upload_days = optional(number)

    expiration = optional(object({
      date                         = optional(string)
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))

    transitions = optional(list(object({
      date          = optional(string)
      days          = optional(number)
      storage_class = string
    })))

    noncurrent_version_expiration = optional(object({
      newer_noncurrent_versions = optional(number)
      noncurrent_days           = optional(number)
    }))

    noncurrent_version_transitions = optional(list(object({
      newer_noncurrent_versions = optional(number)
      noncurrent_days           = optional(number)
      storage_class             = string
    })))
  }))
  description = "List of lifecycle rules to configure on the bucket."
  default     = []
}

variable "intelligent_tiering" {
  type = map(object({
    status = optional(string, "Enabled")
    prefix = optional(string)
    tags   = optional(map(string))
    tierings = list(object({
      access_tier = string
      days        = number
    }))
  }))
  description = "Map of S3 Intelligent-Tiering configurations."
  default     = {}
}

variable "metrics" {
  type = map(object({
    prefix = optional(string)
    tags   = optional(map(string))
  }))
  description = "Map of CloudWatch request metric configurations."
  default     = {}
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_canonical_user_id" "current" {}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  default_tags = {
    Environment     = var.environment
    ServiceProvider = "Rackspace"
  }
  merged_tags = merge(local.default_tags, var.tags)
}

# -----------------------------------------------------------------------------
# Primary S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  object_lock_enabled = var.object_lock_enabled
  tags                = local.merged_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Ownership Controls
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.control_object_ownership ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# -----------------------------------------------------------------------------
# Public Access Block
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.enable_public_access_block ? 1 : 0
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# -----------------------------------------------------------------------------
# Access Control List (ACL)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  count  = (var.acl != null || length(var.grants) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = length(var.grants) == 0 ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }

      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            id            = grant.value.id != null ? grant.value.id : (grant.value.type == "CanonicalUser" ? data.aws_canonical_user_id.current.id : null)
            type          = grant.value.type
            uri           = grant.value.uri
            email_address = grant.value.email
          }
          permission = grant.value.permissions[0]
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# -----------------------------------------------------------------------------
# Server-Side Encryption Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.sse_algorithm != "none" ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    bucket_key_enabled = var.sse_algorithm == "aws:kms" ? var.bucket_key_enabled : false

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? var.kms_master_key_id : null
    }
  }
}

# -----------------------------------------------------------------------------
# Versioning Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count  = var.versioning_status != "Disabled" || var.mfa_delete != "Disabled" ? 1 : 0
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning_status
    mfa_delete = var.mfa_delete
  }
}

# -----------------------------------------------------------------------------
# Server Access Logging
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count  = var.bucket_logging && var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

# -----------------------------------------------------------------------------
# Object Lock Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_years == null ? var.object_lock_days : null
      years = var.object_lock_years
    }
  }
}

# -----------------------------------------------------------------------------
# Website Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website_redirect_all_requests_to == null && var.website_index_document != null ? [1] : []
    content {
      suffix = var.website_index_document
    }
  }

  dynamic "error_document" {
    for_each = var.website_redirect_all_requests_to == null && var.website_error_document != null ? [1] : []
    content {
      key = var.website_error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all_requests_to != null ? [var.website_redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = redirect_all_requests_to.value.protocol
    }
  }

  routing_rules = var.website_routing_rules
}

# -----------------------------------------------------------------------------
# CORS Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null || (rule.value.tags != null && length(rule.value.tags) > 0) ? [1] : []
        content {
          dynamic "and" {
            for_each = (rule.value.prefix != null && rule.value.tags != null && length(rule.value.tags) > 0) || (rule.value.tags != null && length(rule.value.tags) > 1) ? [1] : []
            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }

          prefix = (rule.value.tags == null || length(rule.value.tags) == 0) ? rule.value.prefix : null

          dynamic "tag" {
            for_each = rule.value.prefix == null && rule.value.tags != null && length(rule.value.tags) == 1 ? rule.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          date                         = expiration.value.date
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          date          = transition.value.date
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Intelligent Tiering Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = var.intelligent_tiering

  bucket = aws_s3_bucket.this.id
  name   = each.key
  status = each.value.status

  dynamic "filter" {
    for_each = each.value.prefix != null || each.value.tags != null ? [1] : []
    content {
      prefix = each.value.prefix
      tags   = each.value.tags
    }
  }

  dynamic "tiering" {
    for_each = each.value.tierings
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Metrics Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_metric" "this" {
  for_each = var.metrics

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = each.value.prefix != null || each.value.tags != null ? [1] : []
    content {
      prefix = each.value.prefix
      tags   = each.value.tags
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = aws_s3_bucket.this.hosted_zone_id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  account_id = data.aws_caller_identity.current.account_id

  use_kms       = var.kms_key_arn != null && var.kms_key_arn != ""
  sse_algorithm = local.use_kms ? "aws:kms" : "AES256"

  enable_replication = length(var.replication_rules) > 0
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "bucket_name" {
  type        = string
  description = "Name of the S3 bucket. Must be between 3 and 63 characters, lowercase alphanumeric or hyphens."
  default     = null

  validation {
    condition     = var.bucket_name == null || can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.bucket_name))
    error_message = "The bucket_name must be between 3 and 63 characters, lowercase alphanumeric, hyphens, or periods, and cannot start or end with a hyphen or period."
  }
}

variable "bucket_prefix" {
  type        = string
  description = "Prefix for the S3 bucket name. Max length is 37 characters."
  default     = null

  validation {
    condition     = var.bucket_prefix == null || can(regex("^[a-z0-9][a-z0-9-]{0,36}$", var.bucket_prefix))
    error_message = "The bucket_prefix must be 37 characters or fewer and contain only lowercase alphanumeric characters and hyphens."
  }
}

variable "force_destroy" {
  type        = bool
  description = "A boolean that indicates all objects should be deleted from the bucket when the bucket is destroyed."
  default     = false
}

variable "object_ownership" {
  type        = string
  description = "Object ownership setting: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of: BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter."
  }
}

variable "block_public_acls" {
  type        = bool
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  default     = true
}

variable "block_public_policy" {
  type        = bool
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  default     = true
}

variable "ignore_public_acls" {
  type        = bool
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  default     = true
}

variable "restrict_public_buckets" {
  type        = bool
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  default     = true
}

variable "kms_key_arn" {
  type        = string
  description = "The KMS master key ID or ARN used for the SSE-KMS encryption. If not provided, defaults to AES256 (SSE-S3)."
  default     = null
}

variable "versioning_enabled" {
  type        = bool
  description = "Enable versioning. If false, versioning is set to Suspended."
  default     = false
}

variable "custom_bucket_policy_json" {
  type        = string
  description = "Optional custom bucket policy in JSON format to merge with default SSL-enforcement."
  default     = null
}

variable "logging_source_bucket_arns" {
  type        = list(string)
  description = "List of source bucket ARNs allowed to send access logs to this bucket if acting as a log delivery target."
  default     = []
}

variable "enable_eventbridge" {
  type        = bool
  description = "Whether to enable EventBridge notifications for the S3 bucket."
  default     = false
}

variable "logging_configuration" {
  type = object({
    target_bucket = string
    target_prefix = optional(string, "access-logs/")
  })
  description = "Access logging configuration for sending this bucket's access logs to a target bucket."
  default     = null
}

variable "object_lock_configuration" {
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  description = "Object lock retention configuration."
  default     = null

  validation {
    condition = var.object_lock_configuration == null || (
      can(contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_configuration.mode)) &&
      (var.object_lock_configuration.days != null || var.object_lock_configuration.years != null) &&
      !(var.object_lock_configuration.days != null && var.object_lock_configuration.years != null)
    )
    error_message = "Object lock mode must be GOVERNANCE or COMPLIANCE, and exactly one of days or years must be specified."
  }
}

variable "replication_rules" {
  type = list(object({
    id       = string
    priority = optional(number, 1)
    status   = optional(string, "Enabled")
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket        = string
      storage_class = optional(string, "STANDARD")
      account       = optional(string)
      encryption_configuration = optional(object({
        replica_kms_key_id = string
      }))
    })
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
    delete_marker_replication_status = optional(string, "Disabled")
  }))
  description = "List of cross-region replication rules."
  default     = []
}

variable "inventory_configurations" {
  type = list(object({
    name                     = string
    included_object_versions = optional(string, "All")
    frequency                = optional(string, "Weekly")
    destination_bucket_arn   = string
    destination_prefix       = optional(string, "inventory")
    destination_account_id   = optional(string)
    destination_format       = optional(string, "Parquet")
    destination_kms_key_arn  = optional(string)
    optional_fields          = optional(list(string), ["Size", "LastModifiedDate", "StorageClass", "ETag", "IsMultipartUploaded", "ReplicationStatus", "EncryptionStatus", "ObjectLockRetainUntilDate", "ObjectLockMode", "ObjectLockLegalHoldStatus"])
  }))
  description = "List of S3 inventory configurations."
  default     = []
}

variable "cors_rules" {
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string), ["*"])
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number, 3600)
  }))
  description = "CORS rules for the S3 bucket."
  default     = []
}

variable "lifecycle_rules" {
  type = list(object({
    id     = string
    status = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    transitions = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })), [])
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
      newer_versions  = optional(number)
    })), [])
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
      newer_versions  = optional(number)
    }))
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  description = "List of lifecycle rules for the S3 bucket."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Resource tags."
  default     = {}
}

# -----------------------------------------------------------------------------
# S3 Primary Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "enterprise_storage" {
  bucket        = var.bucket_prefix == null ? (var.bucket_name != null ? var.bucket_name : null) : null
  bucket_prefix = var.bucket_prefix != null ? var.bucket_prefix : (var.bucket_name == null ? "enterprise-storage-" : null)
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_configuration != null

  tags = merge(
    {
      Name = coalesce(var.bucket_name, var.bucket_prefix, "enterprise-storage")
    },
    var.tags
  )

  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = !(var.object_lock_configuration != null && var.logging_configuration != null && var.logging_configuration.target_bucket == (var.bucket_name != null ? var.bucket_name : ""))
      error_message = "A bucket configured with Object Lock cannot simultaneously be configured as its own server access logging destination."
    }
  }
}

# -----------------------------------------------------------------------------
# Bucket Ownership Controls
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "enterprise_storage" {
  bucket = aws_s3_bucket.enterprise_storage.id

  rule {
    object_ownership = var.object_ownership
  }
}

# -----------------------------------------------------------------------------
# Public Access Block
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "enterprise_storage" {
  bucket = aws_s3_bucket.enterprise_storage.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# -----------------------------------------------------------------------------
# Server-Side Encryption Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "enterprise_storage" {
  bucket = aws_s3_bucket.enterprise_storage.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.use_kms ? var.kms_key_arn : null
    }
    bucket_key_enabled = local.use_kms ? true : false
  }
}

# -----------------------------------------------------------------------------
# Bucket Versioning Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "enterprise_storage" {
  bucket = aws_s3_bucket.enterprise_storage.id

  versioning_configuration {
    status = var.versioning_enabled || local.enable_replication ? "Enabled" : "Suspended"
  }
}

# -----------------------------------------------------------------------------
# Bucket Object Lock Retention Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "enterprise_storage" {
  count = var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.enterprise_storage.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }

  depends_on = [aws_s3_bucket.enterprise_storage]
}

# -----------------------------------------------------------------------------
# Server Access Logging Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "enterprise_storage" {
  count = var.logging_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.enterprise_storage.id

  target_bucket = var.logging_configuration.target_bucket
  target_prefix = var.logging_configuration.target_prefix

  lifecycle {
    precondition {
      condition     = var.object_lock_configuration == null || var.logging_configuration.target_bucket != aws_s3_bucket.enterprise_storage.id
      error_message = "Cannot configure S3 access logging targeting the same bucket when object locking is active."
    }
  }
}

# -----------------------------------------------------------------------------
# Bucket Notifications (EventBridge)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_notification" "enterprise_storage" {
  count = var.enable_eventbridge ? 1 : 0

  bucket      = aws_s3_bucket.enterprise_storage.id
  eventbridge = true
}

# -----------------------------------------------------------------------------
# CORS Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "enterprise_storage" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.enterprise_storage.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle Management Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "enterprise_storage" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.enterprise_storage.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)

          dynamic "tag" {
            for_each = lookup(filter.value, "tags", null) != null ? [for k, v in filter.value.tags : { key = k, value = v }] : []
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions
        content {
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_versions
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_versions
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.enterprise_storage]
}

# -----------------------------------------------------------------------------
# Cross-Region Replication IAM Role and Policies
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "replication_assume_role" {
  count = local.enable_replication ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replication_policy" {
  count = local.enable_replication ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.enterprise_storage.arn]
  }

  statement {
    sid    = "SourceBucketObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.enterprise_storage.arn}/*"]
  }

  statement {
    sid    = "DestinationBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersionTagging"
    ]
    resources = [
      for rule in var.replication_rules : "${rule.destination.bucket}/*"
    ]
  }

  dynamic "statement" {
    for_each = local.use_kms ? [1] : []
    content {
      sid    = "SourceKmsDecrypt"
      effect = "Allow"
      actions = [
        "kms:Decrypt"
      ]
      resources = [var.kms_key_arn]
    }
  }

  dynamic "statement" {
    for_each = [
      for rule in var.replication_rules : rule.destination.encryption_configuration.replica_kms_key_id
      if try(rule.destination.encryption_configuration.replica_kms_key_id, null) != null
    ]
    content {
      sid    = "DestinationKmsEncrypt"
      effect = "Allow"
      actions = [
        "kms:Encrypt"
      ]
      resources = [statement.value]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.enable_replication ? 1 : 0

  name_prefix        = "s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = local.enable_replication ? 1 : 0

  name_prefix = "s3-replication-"
  policy      = data.aws_iam_policy_document.replication_policy[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.enable_replication ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# -----------------------------------------------------------------------------
# Cross-Region Replication Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "enterprise_storage" {
  count = local.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.enterprise_storage.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)

          dynamic "tag" {
            for_each = lookup(filter.value, "tags", null) != null ? [for k, v in filter.value.tags : { key = k, value = v }] : []
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication_status != null ? [rule.value.delete_marker_replication_status] : []
        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
        account       = rule.value.destination.account

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.encryption_configuration != null ? [rule.value.destination.encryption_configuration] : []
          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.enterprise_storage,
    aws_iam_role_policy_attachment.replication
  ]
}

# -----------------------------------------------------------------------------
# S3 Inventory Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "enterprise_storage" {
  for_each = { for inv in var.inventory_configurations : inv.name => inv }

  bucket = aws_s3_bucket.enterprise_storage.id
  name   = each.value.name

  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields

  schedule {
    frequency = each.value.frequency
  }

  destination {
    bucket {
      bucket_arn = each.value.destination_bucket_arn
      prefix     = each.value.destination_prefix
      format     = each.value.destination_format
      account_id = each.value.destination_account_id

      dynamic "encryption" {
        for_each = each.value.destination_kms_key_arn != null ? [1] : [0]
        content {
          dynamic "sse_kms" {
            for_each = encryption.value == 1 ? [1] : []
            content {
              key_id = each.value.destination_kms_key_arn
            }
          }
          dynamic "sse_s3" {
            for_each = encryption.value == 0 ? [1] : []
            content {}
          }
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Bucket Policy (Enforce SSL, Allow S3 Logging Service, Custom Policies)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "combined_bucket_policy" {
  source_policy_documents = var.custom_bucket_policy_json != null ? [var.custom_bucket_policy_json] : []

  # Enforce TLS 1.2+ / SSL connections
  statement {
    sid     = "EnforceTLSRequestsOnly"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.enterprise_storage.arn,
      "${aws_s3_bucket.enterprise_storage.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # Conditional Allow for AWS S3 Logging Service
  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []
    content {
      sid     = "S3ServerAccessLogsPolicy"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.enterprise_storage.arn}/*"
      ]

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "enterprise_storage" {
  bucket = aws_s3_bucket.enterprise_storage.id
  policy = data.aws_iam_policy_document.combined_bucket_policy.json

  depends_on = [
    aws_s3_bucket_public_access_block.enterprise_storage,
    aws_s3_bucket_ownership_controls.enterprise_storage
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.enterprise_storage.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.enterprise_storage.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.enterprise_storage.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.enterprise_storage.bucket_regional_domain_name
}

output "replication_role_arn" {
  description = "The ARN of the IAM role used for S3 cross-region replication."
  value       = try(aws_iam_role.replication[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.allowed_s3_region
}

variable "group_name_prefix" {
  type        = string
  description = "Prefix used for naming the IAM developer and administrator groups."
  default     = "app"
}

variable "allowed_s3_region" {
  type        = string
  description = "AWS region where developers are permitted to create S3 buckets."
  default     = "us-east-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the remote-state S3 bucket to restrict from developer access."
  default     = "app-terraform-remote-state"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 12
  require_symbols                = true
  require_numbers                = true
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  allow_users_to_change_password = true
}

resource "aws_s3_account_public_access_block" "account_wide" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

resource "aws_iam_policy" "manage_own_credentials" {
  name        = "${var.group_name_prefix}-manage-own-credentials"
  description = "Permits users to manage their own IAM access keys and virtual MFA devices, requiring MFA to deactivate or delete MFA devices."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowListOwnCredentialsAndMfa"
        Effect   = "Allow"
        Action   = [
          "iam:ListAccessKeys",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "*"
      },
      {
        Sid      = "AllowManageOwnAccessKeys"
        Effect   = "Allow"
        Action   = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:GetAccessKeyLastUsed",
          "iam:UpdateAccessKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid      = "AllowManageOwnVirtualMfaDevice"
        Effect   = "Allow"
        Action   = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice"
        ]
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        ]
      },
      {
        Sid      = "AllowDeactivateAndDeleteMfaOnlyWithMfa"
        Effect   = "Allow"
        Action   = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_manage_credentials" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_own_credentials.arn
}

resource "aws_iam_policy" "developer_s3_access" {
  name        = "${var.group_name_prefix}-developer-s3-access"
  description = "MFA-gated S3 access with region constraint on bucket creation and isolation of remote state bucket."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAllS3WithMfa"
        Effect   = "Allow"
        Action   = [
          "s3:ListAllMyBuckets",
          "s3:GetAccountPublicAccessBlock",
          "s3:GetBucket*",
          "s3:ListBucket*",
          "s3:GetObject*",
          "s3:PutObject*",
          "s3:DeleteObject*",
          "s3:CreateBucket"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid       = "DenyBucketCreationOutsideDesignatedRegion"
        Effect    = "Deny"
        Action    = "s3:CreateBucket"
        Resource  = "arn:aws:s3:::*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.allowed_s3_region
          }
        }
      },
      {
        Sid      = "DenyAccessToStateBucketAndObjects"
        Effect   = "Deny"
        Action   = "s3:*"
        Resource = [
          "arn:aws:s3:::${var.state_bucket_name}",
          "arn:aws:s3:::${var.state_bucket_name}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_access.arn
}

resource "aws_iam_policy" "developer_workload_access" {
  name        = "${var.group_name_prefix}-developer-workload-access"
  description = "MFA-gated access for EC2, ELB, CloudWatch, AutoScaling, and service-linked role creation."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowWorkloadServicesWithMfa"
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "AllowCreateServiceLinkedRoleWithMfa"
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/*"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = [
              "autoscaling.amazonaws.com",
              "ec2.amazonaws.com",
              "elasticloadbalancing.amazonaws.com"
            ]
          }
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_workload" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_workload_access.arn
}

resource "aws_iam_role" "admin" {
  name = "admin"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RootAssumeRoleWithMfa"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "admin_mfa_access" {
  name        = "${var.group_name_prefix}-admin-full-mfa-access"
  description = "Grants full administrative privileges conditioned on active MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdminAccessWithMfa"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_mfa" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_mfa_access.arn
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${var.group_name_prefix}-assume-admin-role"
  description = "Allows assuming the admin role conditioned on active MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeAdminRoleWithMfa"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_assume" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "Primary IPv4 CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnets_config" {
  type = list(object({
    name       = string
    cidr_block = string
    az_index   = number
    tier       = string
  }))
  description = "Configuration list for all 16 subnets across tiers and availability zones"
  default = [
    # Private Tier 1 (Subnets 0-3)
    { name = "subnet-0", cidr_block = "10.0.0.0/24", az_index = 0, tier = "private" },
    { name = "subnet-1", cidr_block = "10.0.1.0/24", az_index = 1, tier = "private" },
    { name = "subnet-2", cidr_block = "10.0.2.0/24", az_index = 2, tier = "private" },
    { name = "subnet-3", cidr_block = "10.0.3.0/24", az_index = 0, tier = "private" },
    # Private Tier 2 (Subnets 4-7)
    { name = "subnet-4", cidr_block = "10.0.4.0/24", az_index = 1, tier = "private" },
    { name = "subnet-5", cidr_block = "10.0.5.0/24", az_index = 2, tier = "private" },
    { name = "subnet-6", cidr_block = "10.0.6.0/24", az_index = 0, tier = "private" },
    { name = "subnet-7", cidr_block = "10.0.7.0/24", az_index = 1, tier = "private" },
    # Public Tier (Subnets 8-11)
    { name = "subnet-8", cidr_block = "10.0.8.0/24", az_index = 2, tier = "public" },
    { name = "subnet-9", cidr_block = "10.0.9.0/24", az_index = 0, tier = "public" },
    { name = "subnet-10", cidr_block = "10.0.10.0/24", az_index = 1, tier = "public" },
    { name = "subnet-11", cidr_block = "10.0.11.0/24", az_index = 2, tier = "public" },
    # Spare Tier (Subnets 12-15)
    { name = "subnet-12", cidr_block = "10.0.12.0/24", az_index = 0, tier = "spare" },
    { name = "subnet-13", cidr_block = "10.0.13.0/24", az_index = 1, tier = "spare" },
    { name = "subnet-14", cidr_block = "10.0.14.0/24", az_index = 2, tier = "spare" },
    { name = "subnet-15", cidr_block = "10.0.15.0/24", az_index = 0, tier = "spare" }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "my_deploy_me_vpc" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "igw_deploy_me" {
  vpc_id = aws_vpc.my_deploy_me_vpc.id

  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_subnet" "subnets" {
  count = length(var.subnets_config)

  vpc_id                  = aws_vpc.my_deploy_me_vpc.id
  cidr_block              = var.subnets_config[count.index].cidr_block
  availability_zone       = data.aws_availability_zones.available.names[var.subnets_config[count.index].az_index]
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnets_config[count.index].name
    Tier = var.subnets_config[count.index].tier
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "eip-deploy-me-natgw"
  }
}

resource "aws_nat_gateway" "deployme_natgw" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnets[0].id

  tags = {
    Name = "deployme-natgw"
  }

  depends_on = [aws_internet_gateway.igw_deploy_me]
}

# Private Route Table and Associations
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.my_deploy_me_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.deployme_natgw.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.my_deploy_me_vpc.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count          = 8
  subnet_id      = aws_subnet.subnets[count.index].id
  route_table_id = aws_route_table.private.id
}

# Public Route Table and Associations
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.my_deploy_me_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw_deploy_me.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw_deploy_me.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  count          = 4
  subnet_id      = aws_subnet.subnets[count.index + 8].id
  route_table_id = aws_route_table.public.id
}

# Spare Route Table and Associations
resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.my_deploy_me_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw_deploy_me.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw_deploy_me.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  count          = 4
  subnet_id      = aws_subnet.subnets[count.index + 12].id
  route_table_id = aws_route_table.spare.id
}

# Security Group
resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow inbound HTTP, HTTPS from anywhere, SSH from VPC CIDR, and outbound limited to VPC CIDR"
  vpc_id      = aws_vpc.my_deploy_me_vpc.id

  ingress {
    description      = "Allow HTTP inbound from anywhere"
    from_port        = 80
    to_port          = 80
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = []
  }

  ingress {
    description      = "Allow HTTPS inbound from anywhere"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = []
  }

  ingress {
    description      = "Allow SSH inbound from VPC CIDR block only"
    from_port        = 22
    to_port          = 22
    protocol         = "tcp"
    cidr_blocks      = [aws_vpc.my_deploy_me_vpc.cidr_block]
    ipv6_cidr_blocks = []
  }

  egress {
    description      = "Outbound traffic strictly limited to the VPC CIDR block"
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = [aws_vpc.my_deploy_me_vpc.cidr_block]
    ipv6_cidr_blocks = []
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

output "server_public_ip" {
  description = "Public IP address of the NAT Gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for resource provisioning."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "enable" {
  description = "Controls if network security resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the application or module."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment name (e.g. dev, prod, staging)."
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "Managed by tag identifier."
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Label order for name and tagging generation."
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL for module tracking."
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "vpc_cidr" {
  description = "CIDR block for the Greenfield VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "new_sg" {
  description = "Flag to determine if a new security group should be provisioned."
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "ID of an existing security group to apply rules to if new_sg is false."
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Flag to determine if a managed prefix list should be conditionally provisioned."
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family for the managed prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum entries allowed in the managed prefix list."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of entries for the managed prefix list."
  type = list(object({
    cidr        = string
    description = optional(string, null)
  }))
  default = []
}

variable "external_prefix_list_ids" {
  description = "List of external prefix list IDs to use instead of provisioning a new one."
  type        = list(string)
  default     = []
}

variable "ingress_cidr_rules" {
  description = "Map of ingress CIDR rules."
  type = map(object({
    from_port        = number
    to_port          = number
    protocol         = string
    description      = optional(string, null)
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
  }))
  default = {}
}

variable "ingress_self_rules" {
  description = "Map of self-referencing ingress rules."
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string, null)
  }))
  default = {}
}

variable "ingress_source_sg_rules" {
  description = "Map of source security group ingress rules."
  type = map(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    description              = optional(string, null)
    source_security_group_id = string
  }))
  default = {}
}

variable "ingress_prefix_list_rules" {
  description = "Map of prefix list ingress rules."
  type = map(object({
    from_port       = number
    to_port         = number
    protocol        = string
    description     = optional(string, null)
    prefix_list_ids = optional(list(string), null)
  }))
  default = {}
}

variable "egress_cidr_rules" {
  description = "Map of egress CIDR rules."
  type = map(object({
    from_port        = number
    to_port          = number
    protocol         = string
    description      = optional(string, null)
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
  }))
  default = {}
}

variable "egress_self_rules" {
  description = "Map of self-referencing egress rules."
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string, null)
  }))
  default = {}
}

variable "egress_source_sg_rules" {
  description = "Map of destination security group egress rules."
  type = map(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    description              = optional(string, null)
    source_security_group_id = string
  }))
  default = {}
}

variable "egress_prefix_list_rules" {
  description = "Map of prefix list egress rules."
  type = map(object({
    from_port       = number
    to_port         = number
    protocol        = string
    description     = optional(string, null)
    prefix_list_ids = optional(list(string), null)
  }))
  default = {}
}

# -----------------------------------------------------------------------------
# Greenfield Base VPC
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.name}-${var.environment}-vpc"
    Environment = var.environment
    ManagedBy   = var.managedby
  }
}

# -----------------------------------------------------------------------------
# Standard Labels Module
# -----------------------------------------------------------------------------
module "labels" {
  source      = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"
  enabled     = var.enable
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

# -----------------------------------------------------------------------------
# Managed Prefix List
# -----------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enable && var.prefix_list_enabled && length(var.external_prefix_list_ids) == 0 ? 1 : 0

  name           = "${module.labels.id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(
    module.labels.tags,
    {
      Name = "${module.labels.id}-prefix-list"
    }
  )
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "this" {
  count = var.enable && var.new_sg ? 1 : 0

  name        = "${module.labels.id}-sg"
  description = "Security group managed by module for ${module.labels.id}"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    module.labels.tags,
    {
      Name = "${module.labels.id}-sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Locals Resolution
# -----------------------------------------------------------------------------
locals {
  effective_sg_id          = var.new_sg ? try(aws_security_group.this[0].id, null) : var.existing_sg_id
  effective_prefix_list_id = length(var.external_prefix_list_ids) > 0 ? var.external_prefix_list_ids[0] : try(aws_ec2_managed_prefix_list.this[0].id, null)
  rule_enabled             = var.enable && (var.new_sg || var.existing_sg_id != null)
}

# -----------------------------------------------------------------------------
# Ingress Rules
# -----------------------------------------------------------------------------
resource "aws_security_group_rule" "ingress_cidr" {
  for_each = local.rule_enabled ? var.ingress_cidr_rules : {}

  type              = "ingress"
  security_group_id = local.effective_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  cidr_blocks       = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks  = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
}

resource "aws_security_group_rule" "ingress_self" {
  for_each = local.rule_enabled ? var.ingress_self_rules : {}

  type              = "ingress"
  security_group_id = local.effective_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  self              = true
}

resource "aws_security_group_rule" "ingress_source_sg" {
  for_each = local.rule_enabled ? var.ingress_source_sg_rules : {}

  type                     = "ingress"
  security_group_id        = local.effective_sg_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = each.value.description
  source_security_group_id = each.value.source_security_group_id
}

resource "aws_security_group_rule" "ingress_prefix_list" {
  for_each = local.rule_enabled ? var.ingress_prefix_list_rules : {}

  type              = "ingress"
  security_group_id = local.effective_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  prefix_list_ids   = each.value.prefix_list_ids != null ? each.value.prefix_list_ids : (local.effective_prefix_list_id != null ? [local.effective_prefix_list_id] : null)
}

# -----------------------------------------------------------------------------
# Egress Rules
# -----------------------------------------------------------------------------
resource "aws_security_group_rule" "egress_cidr" {
  for_each = local.rule_enabled ? var.egress_cidr_rules : {}

  type              = "egress"
  security_group_id = local.effective_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  cidr_blocks       = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks  = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
}

resource "aws_security_group_rule" "egress_self" {
  for_each = local.rule_enabled ? var.egress_self_rules : {}

  type              = "egress"
  security_group_id = local.effective_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  self              = true
}

resource "aws_security_group_rule" "egress_source_sg" {
  for_each = local.rule_enabled ? var.egress_source_sg_rules : {}

  type                     = "egress"
  security_group_id        = local.effective_sg_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = each.value.description
  source_security_group_id = each.value.source_security_group_id
}

resource "aws_security_group_rule" "egress_prefix_list" {
  for_each = local.rule_enabled ? var.egress_prefix_list_rules : {}

  type              = "egress"
  security_group_id = local.effective_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  prefix_list_ids   = each.value.prefix_list_ids != null ? each.value.prefix_list_ids : (local.effective_prefix_list_id != null ? [local.effective_prefix_list_id] : null)
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC created."
  value       = aws_vpc.main.id
}

output "security_group_id" {
  description = "The effective Security Group ID."
  value       = local.effective_sg_id
}

output "security_group_arn" {
  description = "The ARN of the provisioned Security Group."
  value       = try(aws_security_group.this[0].arn, null)
}

output "security_group_name" {
  description = "The name of the provisioned Security Group."
  value       = try(aws_security_group.this[0].name, null)
}

output "managed_prefix_list_id" {
  description = "The ID of the managed prefix list if created."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

output "managed_prefix_list_arn" {
  description = "The ARN of the managed prefix list if created."
  value       = try(aws_ec2_managed_prefix_list.this[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Deployment environment name used for resource naming"
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ==============================================================================
# Account-Wide IAM Password Policy
# ==============================================================================
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

# ==============================================================================
# Trust Policies
# ==============================================================================
data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "states_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

# ==============================================================================
# ECS Task Role
# ==============================================================================
resource "aws_iam_role" "ecs_task_role" {
  name               = "ecs-task-role-for-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_task_secrets_manager" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy_attachment" "ecs_task_s3" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

data "aws_iam_policy_document" "ecs_task_ssm_messages" {
  statement {
    effect = "Allow"
    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_ssm_messages" {
  name   = "ecs-task-ssmmessages-policy"
  role   = aws_iam_role.ecs_task_role.id
  policy = data.aws_iam_policy_document.ecs_task_ssm_messages.json
}

# ==============================================================================
# ECS Execution Role
# ==============================================================================
resource "aws_iam_role" "ecs_execution_role" {
  name               = "ecs-execution-role-for-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_execution_task_execution" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_container_service" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

data "aws_iam_policy_document" "ecs_execution_secrets_kms" {
  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:kms:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:key/*"
    ]
  }
}

resource "aws_iam_role_policy" "ecs_execution_secrets_kms" {
  name   = "ecs-execution-secrets-kms-policy"
  role   = aws_iam_role.ecs_execution_role.id
  policy = data.aws_iam_policy_document.ecs_execution_secrets_kms.json
}

# ==============================================================================
# EventBridge ECS Role
# ==============================================================================
resource "aws_iam_role" "ecs_events_role" {
  name               = "ecs_events_role-for-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.events_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_events_task_execution" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_events_container_service" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# ==============================================================================
# Lambda Execution Roles (Public and VPC)
# ==============================================================================
resource "aws_iam_role" "lambda_public_role" {
  name               = "lambda-public-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role_policy_attachment" "lambda_public_basic" {
  role       = aws_iam_role.lambda_public_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role" "lambda_vpc_role" {
  name               = "lambda-vpc-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_execution" {
  role       = aws_iam_role.lambda_vpc_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

data "aws_iam_policy_document" "lambda_vpc_custom" {
  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:*"
    ]
  }
}

resource "aws_iam_role_policy" "lambda_vpc_custom" {
  name   = "lambda-vpc-permissions-policy"
  role   = aws_iam_role.lambda_vpc_role.id
  policy = data.aws_iam_policy_document.lambda_vpc_custom.json
}

# ==============================================================================
# Step Functions Execution Role
# ==============================================================================
resource "aws_iam_role" "step_functions_execution_role" {
  name               = "step-functions-execution-role"
  assume_role_policy = data.aws_iam_policy_document.states_assume_role.json
}

data "aws_iam_policy_document" "step_functions_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogDelivery",
      "logs:GetLogDelivery",
      "logs:UpdateLogDelivery",
      "logs:DeleteLogDelivery",
      "logs:ListLogDeliveries",
      "logs:PutResourcePolicy",
      "logs:DescribeResourcePolicies",
      "logs:DescribeLogGroups"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "step_functions_policy" {
  name   = "step-functions-policy"
  role   = aws_iam_role.step_functions_execution_role.id
  policy = data.aws_iam_policy_document.step_functions_policy.json
}

# ==============================================================================
# EventBridge to Step Functions Execution Role
# ==============================================================================
resource "aws_iam_role" "eventbridge_step_functions_role" {
  name               = "eventbridge-step-functions-role"
  assume_role_policy = data.aws_iam_policy_document.events_assume_role.json
}

data "aws_iam_policy_document" "eventbridge_step_functions_policy" {
  statement {
    effect = "Allow"
    actions = [
      "states:StartExecution"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:states:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:stateMachine:*"
    ]
  }
}

resource "aws_iam_role_policy" "eventbridge_step_functions_policy" {
  name   = "eventbridge-step-functions-start-execution"
  role   = aws_iam_role.eventbridge_step_functions_role.id
  policy = data.aws_iam_policy_document.eventbridge_step_functions_policy.json
}

# ==============================================================================
# Human User Governance Policies
# ==============================================================================
data "aws_iam_policy_document" "developers_policy_limited_mfa" {
  statement {
    sid    = "S3ObjectAndBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::*/*"]
  }

  statement {
    sid    = "S3ListBucketsAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::*"]
  }

  statement {
    sid    = "MFASecretsManagerReadOnly"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "MFACloudWatchAndLogsReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "logs:Describe*",
      "logs:Get*",
      "logs:FilterLogEvents"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "MFAECSReadOnly"
    effect = "Allow"
    actions = [
      "ecs:Describe*",
      "ecs:List*"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "SelfServiceIAMManagement"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:UpdateUser",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UploadSSHPublicKey",
      "iam:UpdateSSHPublicKey",
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:ListMFADevices"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowAccountLevelMFAListing"
    effect = "Allow"
    actions = [
      "iam:ListVirtualMFADevices",
      "iam:ListUsers"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EnforceMFADenyAllExceptSelfService"
    effect = "Deny"
    not_actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ListUsers",
      "sts:GetSessionToken"
    ]
    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer governance policy with MFA enforcement and self-service IAM management"
  policy      = data.aws_iam_policy_document.developers_policy_limited_mfa.json
}

data "aws_iam_policy_document" "billing_policy_limited_mfa" {
  statement {
    sid    = "MFABillingAccess"
    effect = "Allow"
    actions = [
      "aws-portal:*",
      "ce:*",
      "cur:*",
      "budgets:*",
      "pricing:*",
      "payments:*",
      "tax:*"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "SelfServiceCredentialsAndMFAManagement"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:ListMFADevices"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowListingVirtualMFADevices"
    effect = "Allow"
    actions = [
      "iam:ListVirtualMFADevices",
      "iam:ListUsers"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Billing governance policy with MFA-conditioned financial API access and self-service MFA management"
  policy      = data.aws_iam_policy_document.billing_policy_limited_mfa.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "aws_region" {
  description = "The default AWS region for provisioning resources"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

variable "config" {
  description = "Path to the YAML configuration file defining the pipeline orchestration framework"
  type        = string
  default     = "pipelines.yaml"
}

variable "create_default_pipeline_role" {
  description = "Whether to create the default CodePipeline IAM role under path /terraforest/"
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

locals {
  raw_config = fileexists(var.config) ? yamldecode(file(var.config)) : {
    connections      = {}
    artifact_buckets = ["default-artifacts"]
    cache_buckets    = ["default-cache"]
    pipelines        = {}
  }

  connections_map      = try(local.raw_config.connections, {})
  artifact_bucket_keys = toset(try(local.raw_config.artifact_buckets, ["default-artifacts"]))
  cache_bucket_keys    = toset(try(local.raw_config.cache_buckets, ["default-cache"]))
  pipelines_map        = try(local.raw_config.pipelines, {})

  pipeline_triggers = flatten([
    for pipe_key, pipe in local.pipelines_map : [
      for trig_idx, trig in try(pipe.triggers, []) : {
        id           = "${pipe_key}-${trig_idx}"
        pipeline_key = pipe_key
        type         = trig.type
        schedule     = try(trig.schedule, null)
        pattern      = try(trig.pattern, null)
        repository   = try(trig.repository, null)
        branch       = try(trig.branch, null)
        tag_prefix   = try(trig.tag_prefix, null)
      }
    ]
  ])

  pipeline_triggers_map = {
    for trig in local.pipeline_triggers : trig.id => trig
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCodePipelineAndEventsUsage"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "events.amazonaws.com"
      ]
    }
    actions = [
      "kms:DescribeKey",
      "kms:GenerateDataKey*",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "artifact_encryption" {
  description             = "KMS key for CodePipeline artifacts and build cache bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name      = "terraforest-artifacts-kms-key"
    ManagedBy = "Terraform"
  }
}

resource "aws_kms_alias" "artifact_encryption" {
  name_prefix   = "alias/terraforest-s3-"
  target_key_id = aws_kms_key.artifact_encryption.key_id
}

resource "aws_s3_bucket" "artifacts" {
  for_each      = local.artifact_bucket_keys
  bucket        = "terraforest-art-${each.key}-${random_string.suffix.result}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.id}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "terraforest-artifacts-${each.key}"
    Environment = "CI-CD"
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  for_each = local.artifact_bucket_keys

  bucket = aws_s3_bucket.artifacts[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  for_each = local.artifact_bucket_keys

  bucket = aws_s3_bucket.artifacts[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifact_encryption.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  for_each = local.artifact_bucket_keys

  bucket = aws_s3_bucket.artifacts[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "caches" {
  for_each      = local.cache_bucket_keys
  bucket        = "terraforest-cch-${each.key}-${random_string.suffix.result}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.id}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "terraforest-cache-${each.key}"
    Environment = "CI-CD"
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket_versioning" "caches" {
  for_each = local.cache_bucket_keys

  bucket = aws_s3_bucket.caches[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "caches" {
  for_each = local.cache_bucket_keys

  bucket = aws_s3_bucket.caches[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifact_encryption.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "caches" {
  for_each = local.cache_bucket_keys

  bucket = aws_s3_bucket.caches[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_codestarconnections_connection" "external_repos" {
  for_each      = local.connections_map
  name          = each.key
  provider_type = each.value.provider_type
  host_arn      = try(each.value.host_arn, null)

  tags = {
    Name        = each.key
    ManagedBy   = "Terraform"
    Environment = "CI-CD"
  }
}

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "default_codepipeline" {
  count              = var.create_default_pipeline_role ? 1 : 0
  name_prefix        = "terraforest-pipe-"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json

  tags = {
    Name      = "terraforest-codepipeline-default-role"
    ManagedBy = "Terraform"
  }
}

data "aws_iam_policy_document" "default_codepipeline_permissions" {
  count = var.create_default_pipeline_role ? 1 : 0

  statement {
    sid    = "S3ArtifactStorage"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]
    resources = flatten([
      for b in aws_s3_bucket.artifacts : [
        b.arn,
        "${b.arn}/*"
      ]
    ])
  }

  statement {
    sid    = "KmsEncryptionAccess"
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
      "kms:GenerateDataKey*",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:Decrypt"
    ]
    resources = [
      aws_kms_key.artifact_encryption.arn
    ]
  }

  statement {
    sid    = "CodeCommitAccess"
    effect = "Allow"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:UploadArchive",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:CancelUploadArchive"
    ]
    resources = [
      "arn:aws:codecommit:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:*"
    ]
  }

  statement {
    sid    = "CodeBuildAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild",
      "codebuild:StopBuild",
      "codebuild:BatchGetBuildBatches",
      "codebuild:StartBuildBatch"
    ]
    resources = [
      "arn:aws:codebuild:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:project/*"
    ]
  }

  statement {
    sid    = "ECRAccess"
    effect = "Allow"
    actions = [
      "ecr:DescribeImages",
      "ecr:GetAuthorizationToken",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeStarConnectionsAccess"
    effect = "Allow"
    actions = [
      "codestar-connections:UseConnection"
    ]
    resources = length(aws_codestarconnections_connection.external_repos) > 0 ? [
      for conn in aws_codestarconnections_connection.external_repos : conn.arn
    ] : [
      "arn:aws:codestar-connections:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:connection/*"
    ]
  }

  statement {
    sid    = "LambdaActionAccess"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "lambda:ListFunctions"
    ]
    resources = [
      "arn:aws:lambda:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:function:*"
    ]
  }

  statement {
    sid    = "PassRoleAccess"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/terraforest/*",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/terrabits-*"
    ]
  }
}

resource "aws_iam_role_policy" "default_codepipeline_policy" {
  count  = var.create_default_pipeline_role ? 1 : 0
  name   = "terraforest-codepipeline-default-policy"
  role   = aws_iam_role.default_codepipeline[0].id
  policy = data.aws_iam_policy_document.default_codepipeline_permissions[0].json
}

data "aws_iam_policy_document" "eventbridge_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eventbridge_pipeline_role" {
  for_each           = local.pipelines_map
  name               = "terrabits-${each.key}-trigger-role"
  assume_role_policy = data.aws_iam_policy_document.eventbridge_assume_role.json

  tags = {
    Name      = "terrabits-${each.key}-trigger-role"
    Pipeline  = each.key
    ManagedBy = "Terraform"
  }
}

data "aws_iam_policy_document" "eventbridge_pipeline_policy" {
  for_each = local.pipelines_map

  statement {
    sid    = "StartPipelineExecution"
    effect = "Allow"
    actions = [
      "codepipeline:StartPipelineExecution"
    ]
    resources = [
      "arn:aws:codepipeline:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:${each.key}"
    ]
  }
}

resource "aws_iam_role_policy" "eventbridge_pipeline_policy" {
  for_each = local.pipelines_map
  name     = "terrabits-${each.key}-execution-policy"
  role     = aws_iam_role.eventbridge_pipeline_role[each.key].id
  policy   = data.aws_iam_policy_document.eventbridge_pipeline_policy[each.key].json
}

resource "aws_codepipeline" "pipelines" {
  for_each = local.pipelines_map
  name     = each.key
  role_arn = try(each.value.role_arn, (var.create_default_pipeline_role ? aws_iam_role.default_codepipeline[0].arn : null))

  artifact_store {
    location = aws_s3_bucket.artifacts[try(each.value.artifact_bucket_ref, tolist(local.artifact_bucket_keys)[0])].bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.artifact_encryption.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = each.value.stages
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions
        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = try(action.value.run_order, 1)
          input_artifacts  = try(action.value.input_artifacts, [])
          output_artifacts = try(action.value.output_artifacts, [])
          role_arn         = try(action.value.role_arn, null)
          configuration    = try(action.value.configuration, {})
        }
      }
    }
  }

  tags = {
    Name      = each.key
    ManagedBy = "Terraform"
  }
}

resource "aws_cloudwatch_event_rule" "pipeline_triggers" {
  for_each    = local.pipeline_triggers_map
  name        = "terrabits-${each.key}-rule"
  description = "Trigger rule for pipeline ${each.value.pipeline_key}"

  schedule_expression = each.value.type == "schedule" ? each.value.schedule : null

  event_pattern = each.value.type == "codecommit_branch" ? jsonencode({
    source      = ["aws.codecommit"],
    detail-type = ["CodeCommit Repository State Change"],
    resources   = ["arn:aws:codecommit:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:${each.value.repository}"],
    detail = {
      event         = ["referenceCreated", "referenceUpdated"],
      referenceType = ["branch"],
      referenceName = [each.value.branch]
    }
  }) : each.value.type == "codecommit_tag" ? jsonencode({
    source      = ["aws.codecommit"],
    detail-type = ["CodeCommit Repository State Change"],
    resources   = ["arn:aws:codecommit:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:${each.value.repository}"],
    detail = {
      event         = ["referenceCreated"],
      referenceType = ["tag"],
      referenceName = try(each.value.tag_prefix != null ? [{ "prefix" : each.value.tag_prefix }] : null, null)
    }
  }) : each.value.type == "custom" ? jsonencode(each.value.pattern) : null

  tags = {
    Name      = "terrabits-${each.key}-rule"
    Pipeline  = each.value.pipeline_key
    ManagedBy = "Terraform"
  }
}

resource "aws_cloudwatch_event_target" "pipeline_targets" {
  for_each = local.pipeline_triggers_map
  rule     = aws_cloudwatch_event_rule.pipeline_triggers[each.key].name
  arn      = aws_codepipeline.pipelines[each.value.pipeline_key].arn
  role_arn = aws_iam_role.eventbridge_pipeline_role[each.value.pipeline_key].arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

variable "server_name" {
  type        = string
  description = "Name identifier for the Transfer Family SFTP server and associated resources"
  default     = "sftp-efs-server"
}

variable "vpc_id" {
  type        = string
  description = "Optional VPC ID where Transfer Family endpoint and EFS mount targets will be deployed. If empty, server endpoint defaults to PUBLIC and no mount targets are created."
  default     = ""
}

variable "subnet_ids" {
  type        = list(string)
  description = "Optional list of Subnet IDs for EFS mount targets and Transfer Family VPC endpoint"
  default     = []
}

variable "is_public" {
  type        = bool
  description = "Whether the VPC endpoint should be internet-facing with allocated Elastic IPs. Only applies when vpc_id is provided."
  default     = false
}

variable "performance_mode" {
  type        = string
  description = "EFS file system performance mode: generalPurpose or maxIO"
  default     = "generalPurpose"
  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "Performance mode must be either generalPurpose or maxIO."
  }
}

variable "kms_key_arn" {
  type        = string
  description = "Optional KMS customer-managed key ARN for EFS encryption. If null, default AWS-managed key is used."
  default     = null
}

variable "sftp_users" {
  type = map(object({
    uid            = number
    gid            = number
    secondary_gids = optional(list(number), [])
    ssh_public_key = string
    restricted     = optional(bool, true)
    directory_path = optional(string, null)
  }))
  description = "Map of SFTP users to provision with their POSIX identities and SSH public keys"
  default     = {}
}

variable "additional_access_points" {
  type = map(object({
    path = string
    uid  = number
    gid  = number
  }))
  description = "Map of additional EFS access points for shared or dedicated storage paths"
  default     = {}
}

variable "custom_role_arn" {
  type        = string
  description = "Optional custom IAM role ARN for SFTP users. If empty, a role named <server_name>-role will be generated."
  default     = ""
}

variable "logging_enabled" {
  type        = bool
  description = "Whether to enable CloudWatch logging for the AWS Transfer Family server"
  default     = true
}

locals {
  is_vpc_endpoint = var.vpc_id != ""
  endpoint_type   = local.is_vpc_endpoint ? "VPC" : "PUBLIC"
  user_role_arn   = var.custom_role_arn != "" ? var.custom_role_arn : (length(aws_iam_role.sftp_user_role) > 0 ? aws_iam_role.sftp_user_role[0].arn : "")
}

# -----------------------------------------------------------------------------
# Amazon EFS File System
# -----------------------------------------------------------------------------
resource "aws_efs_file_system" "main" {
  creation_token   = var.server_name
  encrypted        = true
  kms_key_id       = var.kms_key_arn
  performance_mode = var.performance_mode
  throughput_mode  = "bursting"

  tags = {
    Name = var.server_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Security Groups (Optional based on VPC ID)
# -----------------------------------------------------------------------------
resource "aws_security_group" "sftp_server" {
  count       = local.is_vpc_endpoint ? 1 : 0
  name        = "${var.server_name}-sftp-sg"
  description = "Security group for AWS Transfer Family SFTP VPC endpoint"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${var.server_name}-sftp-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "sftp_ingress_port_22" {
  count             = local.is_vpc_endpoint ? 1 : 0
  security_group_id = aws_security_group.sftp_server[0].id
  description       = "Allow inbound SFTP traffic on port 22"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 22
  ip_protocol       = "tcp"
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "sftp_egress_to_efs" {
  count                        = local.is_vpc_endpoint ? 1 : 0
  security_group_id            = aws_security_group.sftp_server[0].id
  description                  = "Allow outbound NFS traffic to EFS mount targets"
  referenced_security_group_id = aws_security_group.efs_mount[0].id
  from_port                    = 2049
  ip_protocol                  = "tcp"
  to_port                      = 2049
}

resource "aws_security_group" "efs_mount" {
  count       = local.is_vpc_endpoint ? 1 : 0
  name        = "${var.server_name}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${var.server_name}-efs-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "efs_ingress_nfs" {
  count                        = local.is_vpc_endpoint ? 1 : 0
  security_group_id            = aws_security_group.efs_mount[0].id
  description                  = "Allow inbound NFS traffic from SFTP server"
  referenced_security_group_id = aws_security_group.sftp_server[0].id
  from_port                    = 2049
  ip_protocol                  = "tcp"
  to_port                      = 2049
}

resource "aws_vpc_security_group_egress_rule" "efs_egress_restrictive" {
  count             = local.is_vpc_endpoint ? 1 : 0
  security_group_id = aws_security_group.efs_mount[0].id
  description       = "Allow egress traffic within VPC"
  cidr_ipv4         = "127.0.0.1/32"
  ip_protocol       = "-1"
}

# -----------------------------------------------------------------------------
# EFS Mount Targets
# -----------------------------------------------------------------------------
resource "aws_efs_mount_target" "mount_targets" {
  for_each        = local.is_vpc_endpoint ? toset(var.subnet_ids) : toset([])
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = each.value
  security_groups = [aws_security_group.efs_mount[0].id]
}

# -----------------------------------------------------------------------------
# EFS Access Points (Users & Additional)
# -----------------------------------------------------------------------------
resource "aws_efs_access_point" "user_access_points" {
  for_each       = var.sftp_users
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid            = each.value.uid
    gid            = each.value.gid
    secondary_gids = each.value.secondary_gids
  }

  root_directory {
    path = each.value.directory_path != null ? each.value.directory_path : "/${each.key}"
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = {
    Name = "${var.server_name}-ap-${each.key}"
  }
}

resource "aws_efs_access_point" "additional_access_points" {
  for_each       = var.additional_access_points
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = each.value.path
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = {
    Name = "${var.server_name}-ap-${each.key}"
  }
}

# -----------------------------------------------------------------------------
# IAM Roles & Policies
# -----------------------------------------------------------------------------
# CloudWatch Logging Role
resource "aws_iam_role" "transfer_logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-transfer-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-transfer-logging-role"
  }
}

resource "aws_iam_role_policy" "transfer_logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-transfer-logging-policy"
  role  = aws_iam_role.transfer_logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "TransferLogsDelivery"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/transfer/*"
      }
    ]
  })
}

# SFTP Users Role
resource "aws_iam_role" "sftp_user_role" {
  count = var.custom_role_arn == "" ? 1 : 0
  name  = "${var.server_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-role"
  }
}

resource "aws_iam_role_policy" "sftp_user_efs_policy" {
  count = var.custom_role_arn == "" ? 1 : 0
  name  = "${var.server_name}-efs-access-policy"
  role  = aws_iam_role.sftp_user_role[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EFSFileSystemClientAccess"
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = concat(
          [aws_efs_file_system.main.arn],
          [for ap in aws_efs_access_point.user_access_points : ap.arn],
          [for ap in aws_efs_access_point.additional_access_points : ap.arn]
        )
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Elastic IPs for Public VPC Endpoint
# -----------------------------------------------------------------------------
resource "aws_eip" "transfer_eip" {
  count  = (local.is_vpc_endpoint && var.is_public) ? length(var.subnet_ids) : 0
  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip-${count.index + 1}"
  }
}

# -----------------------------------------------------------------------------
# AWS Transfer Family SFTP Server
# -----------------------------------------------------------------------------
resource "aws_transfer_server" "sftp" {
  identity_provider_type = "SERVICE_MANAGED"
  endpoint_type          = local.endpoint_type
  domain                 = "EFS"
  protocols              = ["SFTP"]
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  logging_role           = var.logging_enabled ? aws_iam_role.transfer_logging[0].arn : null

  dynamic "endpoint_details" {
    for_each = local.is_vpc_endpoint ? [1] : []
    content {
      vpc_id             = var.vpc_id
      subnet_ids         = var.subnet_ids
      security_group_ids = [aws_security_group.sftp_server[0].id]
      address_allocation_ids = var.is_public ? [
        for eip in aws_eip.transfer_eip : eip.id
      ] : null
    }
  }

  tags = {
    Name = var.server_name
  }
}

# -----------------------------------------------------------------------------
# AWS Transfer Family Users & SSH Keys
# -----------------------------------------------------------------------------
resource "aws_transfer_user" "users" {
  for_each            = var.sftp_users
  server_id           = aws_transfer_server.sftp.id
  user_name           = each.key
  role                = local.user_role_arn
  home_directory_type = each.value.restricted ? "LOGICAL" : "PATH"

  home_directory = each.value.restricted ? null : "/${aws_efs_file_system.main.id}${aws_efs_access_point.user_access_points[each.key].arn}"

  dynamic "home_directory_mappings" {
    for_each = each.value.restricted ? [1] : []
    content {
      entry  = "/"
      target = "/${aws_efs_file_system.main.id}/${aws_efs_access_point.user_access_points[each.key].id}"
    }
  }

  posix_profile {
    uid            = each.value.uid
    gid            = each.value.gid
    secondary_gids = each.value.secondary_gids
  }

  tags = {
    Name = "${var.server_name}-user-${each.key}"
  }
}

resource "aws_transfer_ssh_key" "user_keys" {
  for_each   = var.sftp_users
  server_id  = aws_transfer_server.sftp.id
  user_name  = aws_transfer_user.users[each.key].user_name
  body       = trimspace(each.value.ssh_public_key)
  depends_on = [aws_transfer_user.users]
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

################################################################################
# Variables
################################################################################

variable "create_bucket" {
  description = "Primary boolean toggle to control whether the S3 bucket should be created."
  type        = bool
  default     = true
}

variable "enabled" {
  description = "Secondary boolean toggle to control whether the S3 bucket should be created."
  type        = bool
  default     = true
}

variable "bucket" {
  description = "The name of the bucket. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A mapping of tags to assign to the bucket and KMS key."
  type        = map(string)
  default     = {}
}

variable "object_lock_enabled" {
  description = "Whether S3 bucket should have Object Lock configuration enabled."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Map of object lock configuration default retention settings."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced."
  type        = string
  default     = "ObjectWriter"
}

variable "acl" {
  description = "The canned ACL to apply. Valid values are private, public-read, public-read-write, aws-exec-read, authenticated-read, bucket-owner-read, etc."
  type        = string
  default     = null
}

variable "grant" {
  description = "An array of grant configurations for bucket ACL."
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []
}

variable "server_side_encryption_configuration" {
  description = "Map of server-side encryption configuration. If provided, overrides default customer-managed KMS encryption."
  type        = any
  default     = null
}

variable "kms_key_deletion_window_in_days" {
  description = "The waiting period, specified in days, before KMS key deletion. Must be between 7 and 30 inclusive."
  type        = number
  default     = 7
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket policy should deny requests made without secure transport (HTTPS)."
  type        = bool
  default     = false
}

variable "attach_deny_tls_lower_than_12_policy" {
  description = "Controls if S3 bucket policy should deny requests using TLS versions older than 1.2."
  type        = bool
  default     = false
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket policy should grant AWS Load Balancer service accounts permission to deliver access logs."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket policy should grant AWS ALB/NLB log delivery service principals permissions."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "A valid bucket policy JSON document to be merged with other policy rules."
  type        = string
  default     = null
}

variable "versioning" {
  description = "Map containing versioning configuration."
  type        = map(string)
  default     = {}
}

variable "logging" {
  description = "Map containing access logging configuration."
  type        = map(string)
  default     = {}
}

variable "cors_rule" {
  description = "List of maps containing CORS rules."
  type        = any
  default     = []
}

variable "website" {
  description = "Map containing static website hosting configuration."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who pays for the download and request fees. Can be BucketOwner or Requester."
  type        = string
  default     = null
}

variable "lifecycle_rule" {
  description = "List of maps containing lifecycle configuration rules."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map containing cross-region replication configuration."
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "Map containing intelligent tiering configurations."
  type        = any
  default     = {}
}

################################################################################
# Locals & Data Sources
################################################################################

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  elb_account_ids = {
    us-east-1      = "127311923021"
    us-east-2      = "033677994240"
    us-west-1      = "027434742980"
    us-west-2      = "797873946194"
    ca-central-1   = "985666415583"
    eu-central-1   = "054676820928"
    eu-west-1      = "156460612806"
    eu-west-2      = "652711504416"
    eu-west-3      = "009996457667"
    eu-north-1     = "897822965862"
    eu-south-1     = "638102146993"
    ap-east-1      = "754344448648"
    ap-northeast-1 = "582318560864"
    ap-northeast-2 = "600734575887"
    ap-northeast-3 = "383597477817"
    ap-southeast-1 = "114774125594"
    ap-southeast-2 = "783225384196"
    ap-southeast-3 = "589379963580"
    ap-south-1     = "718504426373"
    me-south-1     = "076674570225"
    sa-east-1      = "507241528045"
    af-south-1     = "098369211593"
  }

  elb_principal_account_id = lookup(local.elb_account_ids, data.aws_region.current.name, "127311923021")

  create_bucket  = var.create_bucket && var.enabled
  create_kms_key = local.create_bucket && var.server_side_encryption_configuration == null

  attach_bucket_policy = local.create_bucket && (
    var.attach_deny_insecure_transport_policy ||
    var.attach_deny_tls_lower_than_12_policy ||
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.custom_bucket_policy != null
  )
}

################################################################################
# KMS Key
################################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer-managed KMS key for S3 bucket SSE-KMS encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json

  tags = var.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name_prefix   = "alias/s3-bucket-"
  target_key_id = aws_kms_key.this[0].key_id
}

################################################################################
# S3 Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Server-Side Encryption Configuration
################################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.server_side_encryption_configuration != null ? [var.server_side_encryption_configuration] : []
    content {
      bucket_key_enabled = try(rule.value.bucket_key_enabled, null)

      dynamic "apply_server_side_encryption_by_default" {
        for_each = try([rule.value.apply_server_side_encryption_by_default], [])
        content {
          sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
          kms_master_key_id = try(apply_server_side_encryption_by_default.value.kms_master_key_id, null)
        }
      }
    }
  }

  dynamic "rule" {
    for_each = var.server_side_encryption_configuration == null ? [1] : []
    content {
      bucket_key_enabled = true

      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = aws_kms_key.this[0].arn
      }
    }
  }
}

################################################################################
# Bucket Policy
################################################################################

data "aws_iam_policy_document" "combined_policy" {
  count = local.attach_bucket_policy ? 1 : 0

  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []

  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid     = "DenyInsecureTransport"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_deny_tls_lower_than_12_policy ? [1] : []
    content {
      sid     = "DenyRequestsWithOldTLS"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid     = "AllowClassicELBLogDelivery"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.elb_principal_account_id}:root"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid     = "AllowLBLogDelivery"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "Service"
        identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = local.attach_bucket_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined_policy[0].json
}

################################################################################
# Public Access Block & Ownership Controls
################################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets

  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.this]
}

################################################################################
# Sub-Resources & Configurations
################################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_bucket && (var.acl != null || length(var.grant) > 0) ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = data.aws_caller_identity.current.account_id
  acl                   = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grant) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grant
        content {
          dynamic "grantee" {
            for_each = [grant.value]
            content {
              id   = try(grantee.value.id, null)
              type = grantee.value.type
              uri  = try(grantee.value.uri, null)
            }
          }
          permission = grant.value.permission
        }
      }

      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this
  ]
}

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(keys(var.versioning)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning["status"], "Enabled")
    mfa_delete = try(var.versioning["mfa_delete"], null)
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(keys(var.logging)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging["target_bucket"]
  target_prefix = try(var.logging["target_prefix"], null)
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = try(rule.value.id, "lifecycle_rule_${rule.key}")
      status = try(rule.value.status, "Enabled")

      dynamic "expiration" {
        for_each = try([rule.value.expiration], [])
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try([rule.value.noncurrent_version_expiration], [])
        content {
          noncurrent_days = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "filter" {
        for_each = try([rule.value.filter], [])
        content {
          prefix = try(filter.value.prefix, null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(keys(var.website)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try([var.website["index_document"]], [])
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try([var.website["error_document"]], [])
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try([var.website["redirect_all_requests_to"]], [])
    content {
      host_name = redirect_all_requests_to.value
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_enabled && var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = try(var.object_lock_configuration.days, null)
      years = try(var.object_lock_configuration.years, null)
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && length(keys(var.replication_configuration)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration["role"]

  dynamic "rule" {
    for_each = var.replication_configuration["rules"]
    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "destination" {
        for_each = [rule.value.destination]
        content {
          bucket        = destination.value.bucket
          storage_class = try(destination.value.storage_class, null)
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = local.create_bucket ? var.intelligent_tiering : {}

  bucket = aws_s3_bucket.this[0].id
  name   = each.key

  dynamic "tiering" {
    for_each = each.value.tierings
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

################################################################################
# Outputs
################################################################################

output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = try(aws_s3_bucket.this[0].id, null)
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = try(aws_s3_bucket.this[0].arn, null)
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name."
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, null)
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = try(aws_s3_bucket.this[0].bucket_regional_domain_name, null)
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = try(aws_s3_bucket.this[0].hosted_zone_id, null)
}

output "kms_key_arn" {
  description = "The ARN of the customer-managed KMS key created for SSE-KMS."
  value       = try(aws_kms_key.this[0].arn, null)
}

output "kms_key_id" {
  description = "The ID of the customer-managed KMS key created for SSE-KMS."
  value       = try(aws_kms_key.this[0].key_id, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "target_stack" {
  type        = string
  description = "Target deployment stack identifier"
  default     = "benchmark"
}

variable "stack_githash" {
  type        = string
  description = "Short git commit hash identifying the deployment"
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  type        = string
  description = "Full-length git commit hash identifying the deployment"
  default     = "benchmark000000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  type        = string
  description = "Name of the S3 deployment bucket storing application artifacts"
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  type        = string
  description = "S3 object key for the primary dataset"
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  type        = string
  description = "S3 object key for the destigmatized dataset"
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  type        = string
  description = "S3 object key for the genomic dataset"
  default     = "genomic_dataset.csv"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  wildfly_role_name    = "wildfly-deployment-s3-${var.target_stack}-${var.stack_githash}"
  httpd_role_name      = "httpd-deployment-s3-${var.target_stack}-${var.stack_githash}"
  auth_hpds_role_name  = "auth-hpds-deployment-s3-${var.target_stack}-${var.stack_githash}"
  open_hpds_role_name  = "open-hpds-deployment-s3-${var.target_stack}-${var.stack_githash}"
  dictionary_role_name = "dictionary-deployment-s3-${var.target_stack}-${var.stack_githash}"

  common_tags = {
    TargetStack = var.target_stack
    GitHash     = var.stack_githash
    GitHashLong = var.stack_githash_long
    ManagedBy   = "Terraform"
  }

  managed_policy_arns = [
    "arn:${local.partition}:iam::aws:policy/CloudWatchAgentServerPolicy",
    "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
  ]
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "stack_bucket_key" {
  description             = "Customer Managed Key for deployment S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "stack_bucket_key_alias" {
  name          = "alias/stack-bucket-${var.target_stack}-${var.stack_githash}"
  target_key_id = aws_kms_key.stack_bucket_key.key_id
}

resource "aws_s3_bucket" "stack_bucket" {
  bucket = var.stack_s3_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "stack_bucket_versioning" {
  bucket = aws_s3_bucket.stack_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "stack_bucket_encryption" {
  bucket = aws_s3_bucket.stack_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.stack_bucket_key.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "stack_bucket_public_block" {
  bucket = aws_s3_bucket.stack_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "ec2_assume_role_policy" {
  statement {
    sid     = "EC2ServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "wildfly" {
  name               = local.wildfly_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json
  tags               = local.common_tags
}

resource "aws_iam_instance_profile" "wildfly" {
  name = local.wildfly_role_name
  role = aws_iam_role.wildfly.name
  tags = local.common_tags
}

resource "aws_iam_role" "httpd" {
  name               = local.httpd_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json
  tags               = local.common_tags
}

resource "aws_iam_instance_profile" "httpd" {
  name = local.httpd_role_name
  role = aws_iam_role.httpd.name
  tags = local.common_tags
}

resource "aws_iam_role" "auth_hpds" {
  name               = local.auth_hpds_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json
  tags               = local.common_tags
}

resource "aws_iam_instance_profile" "auth_hpds" {
  name = local.auth_hpds_role_name
  role = aws_iam_role.auth_hpds.name
  tags = local.common_tags
}

resource "aws_iam_role" "open_hpds" {
  name               = local.open_hpds_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json
  tags               = local.common_tags
}

resource "aws_iam_instance_profile" "open_hpds" {
  name = local.open_hpds_role_name
  role = aws_iam_role.open_hpds.name
  tags = local.common_tags
}

resource "aws_iam_role" "dictionary" {
  name               = local.dictionary_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json
  tags               = local.common_tags
}

resource "aws_iam_instance_profile" "dictionary" {
  name = local.dictionary_role_name
  role = aws_iam_role.dictionary.name
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "wildfly_managed" {
  count      = length(local.managed_policy_arns)
  role       = aws_iam_role.wildfly.name
  policy_arn = local.managed_policy_arns[count.index]
}

resource "aws_iam_role_policy_attachment" "httpd_managed" {
  count      = length(local.managed_policy_arns)
  role       = aws_iam_role.httpd.name
  policy_arn = local.managed_policy_arns[count.index]
}

resource "aws_iam_role_policy_attachment" "auth_hpds_managed" {
  count      = length(local.managed_policy_arns)
  role       = aws_iam_role.auth_hpds.name
  policy_arn = local.managed_policy_arns[count.index]
}

resource "aws_iam_role_policy_attachment" "open_hpds_managed" {
  count      = length(local.managed_policy_arns)
  role       = aws_iam_role.open_hpds.name
  policy_arn = local.managed_policy_arns[count.index]
}

resource "aws_iam_role_policy_attachment" "dictionary_managed" {
  count      = length(local.managed_policy_arns)
  role       = aws_iam_role.dictionary.name
  policy_arn = local.managed_policy_arns[count.index]
}

data "aws_iam_policy_document" "wildfly_policy_doc" {
  statement {
    sid       = "AllowCloudWatchPutMetricData"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowEC2Tagging"
    effect    = "Allow"
    actions   = ["ec2:CreateTags"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*"]
  }

  statement {
    sid       = "AllowS3DeploymentArtifactsListing"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.stack_bucket.arn]
  }

  statement {
    sid    = "AllowS3DeploymentArtifactsWildfly"
    effect = "Allow"
    actions = [
      "s3:GetObject"
    ]
    resources = [
      "${aws_s3_bucket.stack_bucket.arn}/wildfly/*",
      "${aws_s3_bucket.stack_bucket.arn}/security-tools/*",
      "${aws_s3_bucket.stack_bucket.arn}/common/*",
      "${aws_s3_bucket.stack_bucket.arn}/ssl/*",
      "${aws_s3_bucket.stack_bucket.arn}/${var.stack_githash}/wildfly/*"
    ]
  }

  statement {
    sid    = "AllowKMSDecryptArtifacts"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.stack_bucket_key.arn]
  }
}

resource "aws_iam_role_policy" "wildfly_policy" {
  name   = "wildfly-tier-permissions"
  role   = aws_iam_role.wildfly.id
  policy = data.aws_iam_policy_document.wildfly_policy_doc.json
}

