terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Controls whether any resources should be created by this module."
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Controls whether a new security group should be created. If false, security_group_id must be provided."
  type        = bool
  default     = true
}

variable "security_group_id" {
  description = "Target security group ID to attach rules to when create_sg is false."
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID where the security group should be created. If null, the module provisioned VPC will be used."
  type        = string
  default     = null
}

variable "security_group_name" {
  description = "Name of the security group to create."
  type        = string
  default     = "custom-security-group"
}

variable "security_group_description" {
  description = "Description of the security group to create."
  type        = string
  default     = "Managed by Terraform"
}

variable "revoke_rules_on_delete" {
  description = "Whether to revoke security group rules before deleting the security group."
  type        = bool
  default     = true
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed EC2 prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_id" {
  description = "Pre-existing prefix list ID to use if not creating one."
  type        = string
  default     = null
}

variable "prefix_list_name" {
  description = "Name for the customer-managed prefix list."
  type        = string
  default     = "custom-prefix-list"
}

variable "prefix_list_address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"
  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "Address family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the prefix list can contain."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of entries for the customer-managed prefix list."
  type = list(object({
    cidr        = string
    description = optional(string, null)
  }))
  default = []
}

variable "ingress_rules" {
  description = "List of ingress rule definitions. Each rule must specify exactly one source: cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  type = list(object({
    key                          = string
    ip_protocol                  = string
    from_port                    = optional(number, null)
    to_port                      = optional(number, null)
    cidr_ipv4                    = optional(string, null)
    cidr_ipv6                    = optional(string, null)
    referenced_security_group_id = optional(string, null)
    prefix_list_id               = optional(string, null)
    description                  = optional(string, null)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rule definitions. If empty, a default allow-all-outbound IPv4 rule is provisioned."
  type = list(object({
    key                          = string
    ip_protocol                  = string
    from_port                    = optional(number, null)
    to_port                      = optional(number, null)
    cidr_ipv4                    = optional(string, null)
    cidr_ipv6                    = optional(string, null)
    referenced_security_group_id = optional(string, null)
    prefix_list_id               = optional(string, null)
    description                  = optional(string, null)
  }))
  default = []
}

variable "tags" {
  description = "A mapping of tags to assign to resources."
  type        = map(string)
  default     = {}
}

# Greenfield base networking resource
resource "aws_vpc" "main" {
  count                = var.create && var.create_sg && var.vpc_id == null ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.tags,
    {
      Name = "base-vpc"
    }
  )
}

# Customer-managed EC2 prefix list
resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.create && var.create_prefix_list && var.prefix_list_id == null ? 1 : 0
  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(
    var.tags,
    {
      Name = var.prefix_list_name
    }
  )
}

locals {
  target_vpc_id = var.vpc_id != null ? var.vpc_id : (length(aws_vpc.main) > 0 ? aws_vpc.main[0].id : null)

  resolved_prefix_list_id = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].id : var.prefix_list_id

  target_security_group_id = var.create ? (
    var.create_sg ? (length(aws_security_group.this) > 0 ? aws_security_group.this[0].id : null) : var.security_group_id
  ) : null

  target_security_group_arn = length(aws_security_group.this) > 0 ? aws_security_group.this[0].arn : null

  ingress_rules_map = var.create ? {
    for rule in var.ingress_rules : rule.key => rule
  } : {}

  default_egress_rules = [
    {
      key                          = "default_all_outbound"
      ip_protocol                  = "-1"
      from_port                    = null
      to_port                      = null
      cidr_ipv4                    = "0.0.0.0/0"
      cidr_ipv6                    = null
      referenced_security_group_id = null
      prefix_list_id               = null
      description                  = "Allow all outbound IPv4 traffic"
    }
  ]

  active_egress_rules_list = length(var.egress_rules) > 0 ? var.egress_rules : local.default_egress_rules

  egress_rules_map = var.create ? {
    for rule in local.active_egress_rules_list : rule.key => rule
  } : {}
}

# Target Security Group
resource "aws_security_group" "this" {
  count                  = var.create && var.create_sg ? 1 : 0
  name_prefix            = "${var.security_group_name}-"
  description            = var.security_group_description
  vpc_id                 = local.target_vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(
    var.tags,
    {
      Name = var.security_group_name
    }
  )
}

# Standalone Ingress Rules
resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.ingress_rules_map

  security_group_id            = local.target_security_group_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id != null ? each.value.prefix_list_id : (each.value.cidr_ipv4 == null && each.value.cidr_ipv6 == null && each.value.referenced_security_group_id == null ? local.resolved_prefix_list_id : null)
  description                  = each.value.description

  tags = var.tags
}

# Standalone Egress Rules
resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.egress_rules_map

  security_group_id            = local.target_security_group_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id != null ? each.value.prefix_list_id : (each.value.cidr_ipv4 == null && each.value.cidr_ipv6 == null && each.value.referenced_security_group_id == null && each.key != "default_all_outbound" ? local.resolved_prefix_list_id : null)
  description                  = each.value.description

  tags = var.tags
}

output "security_group_id" {
  description = "The ID of the security group targeted for rule associations."
  value       = local.target_security_group_id
}

output "security_group_arn" {
  description = "The ARN of the security group created by this module."
  value       = local.target_security_group_arn
}

output "prefix_list_id" {
  description = "The ID of the managed prefix list created or supplied."
  value       = local.resolved_prefix_list_id
}

output "ingress_rules" {
  description = "Map of created ingress rules."
  value       = aws_vpc_security_group_ingress_rule.this
}

output "egress_rules" {
  description = "Map of created egress rules."
  value       = aws_vpc_security_group_egress_rule.this
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  type        = string
  description = "Project name prefix for naming IAM resources"
  default     = "Cv-React-App"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# ------------------------------------------------------------------------------
# 1. EC2 CodeDeploy Role & Instance Profile
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project_name}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_ec2" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_s3" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_codedeploy_instance_profile" {
  name = "${var.project_name}_ec2_codedeploy_instance_profile"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# ------------------------------------------------------------------------------
# 2. CodeDeploy Service Role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "codedeploy_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project_name}_codedeploy_service_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_trust.json
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_role_codedeploy" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_role_s3" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

# ------------------------------------------------------------------------------
# 3. EC2 CloudWatch Agent Role & Instance Profile
# ------------------------------------------------------------------------------
resource "aws_iam_role" "cloudwatch_agent_role" {
  name               = "${var.project_name}_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_role_cw" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_role_s3" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "cloudwatch_agent_instance_profile" {
  name = "${var.project_name}_cloudwatch_agent_instance_profile"
  role = aws_iam_role.cloudwatch_agent_role.name
}

# ------------------------------------------------------------------------------
# 4. CodeBuild Role & Inline Policy
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "codebuild_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  assume_role_policy = data.aws_iam_policy_document.codebuild_trust.json
}

resource "aws_iam_role_policy_attachment" "codebuild_role_s3" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

data "aws_iam_policy_document" "codebuild_policy_doc" {
  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:${local.partition}:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*",
      "arn:${local.partition}:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*:*"
    ]
  }

  statement {
    sid    = "CodePipelineArtifactBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObjectAcl",
      "s3:PutObject"
    ]
    resources = [
      "arn:${local.partition}:s3:::codepipeline-us-east-1-*",
      "arn:${local.partition}:s3:::codepipeline-us-east-1-*/*"
    ]
  }

  statement {
    sid    = "CodeBuildReportPermissions"
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases"
    ]
    resources = [
      "arn:${local.partition}:codebuild:us-east-1:${local.account_id}:report-group/*"
    ]
  }
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name   = "CodeBuildServicePolicy"
  role   = aws_iam_role.codebuild_role.name
  policy = data.aws_iam_policy_document.codebuild_policy_doc.json
}

# ------------------------------------------------------------------------------
# 5. CodePipeline Role & Inline Policy
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "codepipeline_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com"
      ]
    }
    principals {
      type = "AWS"
      identifiers = [
        "arn:${local.partition}:iam::${local.account_id}:root"
      ]
    }
  }
}

resource "aws_iam_role" "codepipeline_role" {
  name               = "CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_trust.json
}

data "aws_iam_policy_document" "codepipeline_policy_doc" {
  statement {
    sid    = "CodeStarConnectionsAccess"
    effect = "Allow"
    actions = [
      "codestar-connections:UseConnection"
    ]
    resources = [
      "arn:${local.partition}:codestar-connections:*:${local.account_id}:connection/*"
    ]
  }

  statement {
    sid    = "S3ArtifactStorageAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:ListBucket"
    ]
    resources = [
      "arn:${local.partition}:s3:::codepipeline-*",
      "arn:${local.partition}:s3:::codepipeline-*/*",
      "arn:${local.partition}:s3:::${lower(var.project_name)}-*",
      "arn:${local.partition}:s3:::${lower(var.project_name)}-*/*"
    ]
  }

  statement {
    sid    = "CodeCommitAccess"
    effect = "Allow"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:UploadArchive",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:CancelUploadArchive",
      "codecommit:GitPull"
    ]
    resources = [
      "arn:${local.partition}:codecommit:*:${local.account_id}:*"
    ]
  }

  statement {
    sid    = "CodeDeployAccess"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:RegisterApplicationRevision"
    ]
    resources = [
      "arn:${local.partition}:codedeploy:*:${local.account_id}:application:*",
      "arn:${local.partition}:codedeploy:*:${local.account_id}:deploymentgroup:*/*",
      "arn:${local.partition}:codedeploy:*:${local.account_id}:deploymentconfig:*"
    ]
  }

  statement {
    sid    = "LambdaAccess"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [
      "arn:${local.partition}:lambda:*:${local.account_id}:function:*"
    ]
  }

  statement {
    sid    = "CodeBuildAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild"
    ]
    resources = [
      "arn:${local.partition}:codebuild:*:${local.account_id}:project/*"
    ]
  }

  statement {
    sid    = "CloudFormationAccess"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:UpdateStack",
      "cloudformation:CreateChangeSet",
      "cloudformation:DeleteChangeSet",
      "cloudformation:DescribeChangeSet",
      "cloudformation:ExecuteChangeSet",
      "cloudformation:SetStackPolicy",
      "cloudformation:ValidateTemplate"
    ]
    resources = [
      "arn:${local.partition}:cloudformation:*:${local.account_id}:stack/*/*"
    ]
  }

  statement {
    sid    = "IamPassRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.codebuild_role.arn,
      aws_iam_role.codedeploy_service_role.arn,
      aws_iam_role.ec2_codedeploy_role.arn
    ]
  }
}

resource "aws_iam_role_policy" "codepipeline_policy" {
  name   = "CodePipelineServicePolicy"
  role   = aws_iam_role.codepipeline_role.name
  policy = data.aws_iam_policy_document.codepipeline_policy_doc.json
}

