terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "CIDR block for the single public subnet"
  default     = "10.0.1.0/24"
}

variable "admin_cidr" {
  type        = string
  description = "CIDR block permitted for SSH access"
  default     = "203.0.113.0/24"
}

variable "ssh_public_key" {
  type        = string
  description = "Accepted SSH public key for the EC2 key pair"
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGbXv8j5Pqv5QZ3yP2Lh6Q2K+L8uM8tQ4W6kK9vG2Z5m admin@chaos.local"
}

variable "environment" {
  type        = string
  description = "Environment identifier tag"
  default     = "chaos-lab"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = "fis-chaos"
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Project     = "FIS-Chaos-Lab"
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC, Internet Gateway, Subnet, Routing
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name        = "${local.name_prefix}-public-subnet"
    FISTarget   = "true"
    TargetScope = "PublicSubnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key for FIS Log Bucket SSE-KMS
# -----------------------------------------------------------------------------

resource "aws_kms_key" "fis_logs" {
  description             = "KMS Key for AWS FIS Experiment S3 logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "fis-logs-key-policy"
    Statement = [
      {
        Sid    = "EnableRootIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowLogDeliveryOperations"
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowFISServiceOperations"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })
}

resource "aws_kms_alias" "fis_logs" {
  name_prefix   = "alias/${local.name_prefix}-logs-"
  target_key_id = aws_kms_key.fis_logs.key_id
}

# -----------------------------------------------------------------------------
# S3 Logging Bucket for FIS Experiments
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "fis_logs" {
  bucket_prefix = "${local.name_prefix}-logs-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-logs"
  })
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.fis_logs.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket     = aws_s3_bucket.fis_logs.id
  depends_on = [aws_s3_bucket_public_access_block.fis_logs]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLogDeliveryAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.fis_logs.arn
      },
      {
        Sid    = "AllowLogDeliveryWrite"
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.fis_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid    = "AllowFISDirectPutObject"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.fis_logs.arn}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# EC2 Security Group and Key Pair
# -----------------------------------------------------------------------------

resource "aws_key_pair" "admin" {
  key_name_prefix = "${local.name_prefix}-admin-key-"
  public_key      = var.ssh_public_key

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-admin-key"
  })
}

resource "aws_security_group" "ec2" {
  name_prefix = "${local.name_prefix}-ec2-sg-"
  description = "Security group for EC2 instances in chaos lab"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH administrative access"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Permit outbound traffic to VPC and admin CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr, var.admin_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# EC2 IAM Role and Instance Profile (SSM + ECS)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ec2_instance" {
  name_prefix = "${local.name_prefix}-ec2-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_instance_profile" "ec2" {
  name_prefix = "${local.name_prefix}-profile-"
  role        = aws_iam_role.ec2_instance.name

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Launch Template & Auto Scaling Group
# -----------------------------------------------------------------------------

resource "aws_launch_template" "main" {
  name_prefix   = "${local.name_prefix}-lt-"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = "t3.micro"
  key_name      = aws_key_pair.admin.key_name

  iam_instance_profile {
    arn = aws_iam_instance_profile.ec2.arn
  }

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.ec2.id]
    delete_on_termination       = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name      = "${local.name_prefix}-instance"
      FISTarget = "true"
      TargetASG = "${local.name_prefix}-asg"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, {
      Name      = "${local.name_prefix}-ebs"
      FISTarget = "true"
    })
  }

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "main" {
  name_prefix                = "${local.name_prefix}-asg-"
  vpc_zone_identifier        = [aws_subnet.public.id]
  min_size                   = 1
  max_size                   = 2
  desired_capacity           = 2
  wait_for_capacity_timeout  = "0"

  launch_template {
    id      = aws_launch_template.main.id
    version = "$Latest"
  }

  tag {
    key                 = "Name"
    value               = "${local.name_prefix}-asg-instance"
    propagate_at_launch = true
  }

  tag {
    key                 = "FISTarget"
    value               = "true"
    propagate_at_launch = true
  }

  tag {
    key                 = "Environment"
    value               = var.environment
    propagate_at_launch = true
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = [load_balancers, target_group_arns]
  }
}

# -----------------------------------------------------------------------------
# IAM Role for AWS Fault Injection Simulator (FIS)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "fis_execution" {
  name_prefix = "${local.name_prefix}-fis-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "fis_execution" {
  name_prefix = "${local.name_prefix}-fis-policy-"
  description = "Permissions for AWS FIS chaos experiment execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2ControlActions"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeVolumes",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:RebootInstances",
          "ec2:StopInstances",
          "ec2:StartInstances",
          "ec2:TerminateInstances",
          "ec2:PauseVolumeIO",
          "ec2:CreateNetworkInterfacePermission",
          "ec2:DeleteNetworkInterfacePermission",
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMExperimentActions"
        Effect = "Allow"
        Action = [
          "ssm:SendCommand",
          "ssm:CancelCommand",
          "ssm:ListCommands",
          "ssm:ListCommandInvocations",
          "ssm:GetCommandInvocation",
          "ssm:DescribeInstanceInformation"
        ]
        Resource = "*"
      },
      {
        Sid    = "LoggingBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.fis_logs.arn,
          "${aws_s3_bucket.fis_logs.arn}/*"
        ]
      },
      {
        Sid    = "KMSLogEncryption"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.fis_logs.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "fis_execution" {
  role       = aws_iam_role.fis_execution.name
  policy_arn = aws_iam_policy.fis_execution.arn
}

# -----------------------------------------------------------------------------
# FIS Experiment 1: EC2 DescribeImages API Internal-Error Fault
# -----------------------------------------------------------------------------

resource "aws_fis_experiment_template" "api_error" {
  description = "Inject internal errors into EC2 DescribeImages API calls from target instances"
  role_arn    = aws_iam_role.fis_execution.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "ec2-api-internal-error"
    action_id = "aws:fis:inject-api-internal-error"

    parameter {
      key   = "service"
      value = "ec2"
    }

    parameter {
      key   = "operations"
      value = "DescribeImages"
    }

    parameter {
      key   = "percentage"
      value = "100"
    }

    parameter {
      key   = "duration"
      value = "PT5M"
    }

    target {
      key   = "Roles"
      value = "InstanceIamRole"
    }
  }

  target {
    name           = "InstanceIamRole"
    resource_type  = "aws:iam:role"
    selection_mode = "ALL"

    resource_arns = [
      aws_iam_role.ec2_instance.arn
    ]
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "experiments/api-error"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-api-error"
  })
}

# -----------------------------------------------------------------------------
# FIS Experiment 2: EBS Volume I/O Pause
# -----------------------------------------------------------------------------

resource "aws_fis_experiment_template" "ebs_pause" {
  description = "Pause EBS Volume I/O on instances tagged for chaos testing"
  role_arn    = aws_iam_role.fis_execution.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "ebs-pause-io"
    action_id = "aws:ebs:pause-volume-io"

    parameter {
      key   = "duration"
      value = "PT2M"
    }

    target {
      key   = "Volumes"
      value = "EBSTargets"
    }
  }

  target {
    name           = "EBSTargets"
    resource_type  = "aws:ec2:ebs-volume"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = "FISTarget"
      value = "true"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "experiments/ebs-pause"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ebs-pause"
  })
}

# -----------------------------------------------------------------------------
# FIS Experiment 3: EC2 CPU Stress (via SSM)
# -----------------------------------------------------------------------------

resource "aws_fis_experiment_template" "cpu_stress" {
  description = "Stress EC2 instance CPU using SSM AWSFIS-Run-CPU-Stress document"
  role_arn    = aws_iam_role.fis_execution.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "ec2-cpu-stress"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.name}::document/AWSFIS-Run-CPU-Stress"
    }

    parameter {
      key   = "documentParameters"
      value = jsonencode({ "DurationSeconds" : "120", "CPU" : "0", "Workers" : "2" })
    }

    parameter {
      key   = "duration"
      value = "PT3M"
    }

    target {
      key   = "Instances"
      value = "EC2Targets"
    }
  }

  target {
    name           = "EC2Targets"
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = "FISTarget"
      value = "true"
    }

    filter {
      path   = "State.Name"
      values = ["running"]
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "experiments/cpu-stress"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cpu-stress"
  })
}

# -----------------------------------------------------------------------------
# FIS Experiment 4: EC2 Instance Termination
# -----------------------------------------------------------------------------

resource "aws_fis_experiment_template" "instance_termination" {
  description = "Terminate an EC2 instance in the ASG to test Auto Scaling self-healing"
  role_arn    = aws_iam_role.fis_execution.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "ec2-terminate"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "EC2Targets"
    }
  }

  target {
    name           = "EC2Targets"
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = "FISTarget"
      value = "true"
    }

    filter {
      path   = "State.Name"
      values = ["running"]
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "experiments/instance-termination"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-termination"
  })
}

# -----------------------------------------------------------------------------
# FIS Experiment 5: Subnet Network Disruption
# -----------------------------------------------------------------------------

resource "aws_fis_experiment_template" "network_disruption" {
  description = "Disrupt network connectivity across the public subnet"
  role_arn    = aws_iam_role.fis_execution.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "subnet-disrupt-connectivity"
    action_id = "aws:network:disrupt-connectivity"

    parameter {
      key   = "scope"
      value = "all"
    }

    parameter {
      key   = "duration"
      value = "PT3M"
    }

    target {
      key   = "Subnets"
      value = "SubnetTargets"
    }
  }

  target {
    name           = "SubnetTargets"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"

    resource_tag {
      key   = "FISTarget"
      value = "true"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "experiments/network-disruption"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-network-disruption"
  })
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region where infrastructure is deployed"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.region
}

variable "create_vpc" {
  description = "Controls if VPC should be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name prefix for VPC resources"
  type        = string
  default     = "main"
}

variable "cidr_block" {
  description = "The IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "The ID of an IPv4 IPAM pool you want to use for allocating this VPC's CIDR"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "The netmask length of the IPv4 CIDR you want to allocate to this VPC from an IPAM pool"
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "enable_dns_hostnames" {
  description = "Whether to enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether to enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "create_igw" {
  description = "Controls if an Internet Gateway should be created for the VPC"
  type        = bool
  default     = true
}

variable "enable_ipv6_egress_only_igw" {
  description = "Controls if an Egress-Only Internet Gateway should be created for IPv6"
  type        = bool
  default     = false
}

variable "public_subnets" {
  description = "Map of public subnet configurations"
  type = map(object({
    cidr_block              = string
    az_index                = number
    map_public_ip_on_launch = bool
  }))
  default = {
    "public-1" = {
      cidr_block              = "10.0.1.0/24"
      az_index                = 0
      map_public_ip_on_launch = false
    }
    "public-2" = {
      cidr_block              = "10.0.2.0/24"
      az_index                = 1
      map_public_ip_on_launch = false
    }
  }
}

variable "private_subnets" {
  description = "Map of private subnet configurations"
  type = map(object({
    cidr_block      = string
    az_index        = number
    nat_gateway_key = string
  }))
  default = {
    "private-1" = {
      cidr_block      = "10.0.10.0/24"
      az_index        = 0
      nat_gateway_key = "public-1"
    }
    "private-2" = {
      cidr_block      = "10.0.11.0/24"
      az_index        = 1
      nat_gateway_key = "public-2"
    }
  }
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways should be provisioned for private subnets"
  type        = bool
  default     = false
}

variable "single_nat_gateway" {
  description = "Controls if a single shared NAT Gateway should be created across all private subnets"
  type        = bool
  default     = false
}

variable "enable_private_dedicated_nacl" {
  description = "Whether to create dedicated network ACL for private subnets"
  type        = bool
  default     = true
}

variable "enable_dhcp_options" {
  description = "Controls if DHCP options set should be created and associated"
  type        = bool
  default     = false
}

variable "dhcp_options_domain_name_servers" {
  description = "List of name servers for DHCP options"
  type        = list(string)
  default     = ["AmazonProvidedDNS"]
}

variable "enable_flow_log" {
  description = "Whether to enable VPC Flow Logs"
  type        = bool
  default     = false
}

variable "flow_log_max_aggregation_interval" {
  description = "The maximum interval of time during which a flow of packets is captured and aggregated into a flow log record"
  type        = number
  default     = 600
}

variable "flow_log_log_format" {
  description = "The fields to include in the flow log record, in the order in which they should appear"
  type        = string
  default     = null
}

variable "flow_log_cloudwatch_log_group_retention_in_days" {
  description = "Specifies the number of days you want to retain log events in the specified log group"
  type        = number
  default     = 30
}

variable "manage_default_security_group" {
  description = "Controls if default security group should be adopted and secured"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Controls if default network ACL should be adopted and managed"
  type        = bool
  default     = false
}

variable "manage_default_route_table" {
  description = "Controls if default route table should be adopted and managed"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  name_prefix = var.name

  nat_gateway_keys = var.enable_nat_gateway && var.create_vpc ? (
    var.single_nat_gateway ? (
      length(keys(var.public_subnets)) > 0 ? [element(keys(var.public_subnets), 0)] : []
    ) : keys(var.public_subnets)
  ) : []

  default_tags = merge(
    {
      "Name" = local.name_prefix
    },
    var.tags
  )
}

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block          = var.ipv4_ipam_pool_id == null ? var.cidr_block : null
  ipv4_ipam_pool_id   = var.ipv4_ipam_pool_id
  ipv4_netmask_length = var.ipv4_netmask_length

  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = var.create_vpc ? toset(var.secondary_cidr_blocks) : toset([])

  vpc_id     = aws_vpc.this[0].id
  cidr_block = each.value
}

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.create_vpc && var.enable_ipv6_egress_only_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-eigw"
    }
  )
}

resource "aws_subnet" "public" {
  for_each = var.create_vpc ? var.public_subnets : {}

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = each.value.cidr_block
  availability_zone       = data.aws_availability_zones.available.names[each.value.az_index]
  map_public_ip_on_launch = false

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-${each.key}"
      "Tier" = "Public"
    }
  )
}

resource "aws_subnet" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = each.value.cidr_block
  availability_zone       = data.aws_availability_zones.available.names[each.value.az_index]
  map_public_ip_on_launch = false

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-${each.key}"
      "Tier" = "Private"
    }
  )
}

resource "aws_eip" "nat" {
  for_each = toset(local.nat_gateway_keys)

  domain = "vpc"

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-eip-${each.key}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  for_each = toset(local.nat_gateway_keys)

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-nat-${each.key}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-rt-public"
    }
  )
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = var.create_vpc ? var.public_subnets : {}

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-rt-${each.key}"
    }
  )
}

resource "aws_route" "private_nat_gateway" {
  for_each = {
    for k, v in var.private_subnets : k => v
    if var.create_vpc && var.enable_nat_gateway && length(local.nat_gateway_keys) > 0
  }

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id = var.single_nat_gateway ? (
    aws_nat_gateway.this[local.nat_gateway_keys[0]].id
  ) : (
    contains(local.nat_gateway_keys, each.value.nat_gateway_key) ?
    aws_nat_gateway.this[each.value.nat_gateway_key].id :
    aws_nat_gateway.this[local.nat_gateway_keys[0]].id
  )
}

resource "aws_route_table_association" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

resource "aws_network_acl" "private" {
  count = var.create_vpc && var.enable_private_dedicated_nacl && length(var.private_subnets) > 0 ? 1 : 0

  vpc_id     = aws_vpc.this[0].id
  subnet_ids = [for s in aws_subnet.private : s.id]

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-nacl-private"
    }
  )
}

resource "aws_network_acl_rule" "private_ingress" {
  count = var.create_vpc && var.enable_private_dedicated_nacl && length(var.private_subnets) > 0 ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress" {
  count = var.create_vpc && var.enable_private_dedicated_nacl && length(var.private_subnets) > 0 ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_vpc_dhcp_options" "this" {
  count = var.create_vpc && var.enable_dhcp_options ? 1 : 0

  domain_name_servers = var.dhcp_options_domain_name_servers

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-dhcp-options"
    }
  )
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = var.create_vpc && var.enable_dhcp_options ? 1 : 0

  vpc_id          = aws_vpc.this[0].id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

resource "aws_kms_key" "flow_logs" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  description             = "KMS key for VPC flow logs CloudWatch log group"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.default_tags
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name              = "/aws/vpc-flow-logs/${local.name_prefix}"
  retention_in_days = var.flow_log_cloudwatch_log_group_retention_in_days
  kms_key_id        = aws_kms_key.flow_logs[0].arn

  tags = local.default_tags
}

resource "aws_iam_role" "flow_logs" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name = "${local.name_prefix}-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VPCFlowLogsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.default_tags
}

resource "aws_iam_policy" "flow_logs" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name        = "${local.name_prefix}-vpc-flow-logs-policy"
  description = "IAM policy for publishing VPC flow logs to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSLogDeliveryWrite"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs[0].arn}:*"
      }
    ]
  })

  tags = local.default_tags
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  role       = aws_iam_role.flow_logs[0].name
  policy_arn = aws_iam_policy.flow_logs[0].arn
}

resource "aws_flow_log" "this" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  vpc_id                   = aws_vpc.this[0].id
  traffic_type             = "ALL"
  iam_role_arn             = aws_iam_role.flow_logs[0].arn
  log_destination          = aws_cloudwatch_log_group.flow_logs[0].arn
  log_destination_type     = "cloud-watch-logs"
  max_aggregation_interval = var.flow_log_max_aggregation_interval
  log_format               = var.flow_log_log_format

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-flow-log"
    }
  )
}

resource "aws_default_security_group" "this" {
  count = var.create_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-default-sg"
    }
  )
}

resource "aws_default_network_acl" "this" {
  count = var.create_vpc && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    protocol        = "tcp"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol        = "tcp"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 65535
  }

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-default-nacl"
    }
  )
}

resource "aws_default_route_table" "this" {
  count = var.create_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id

  tags = merge(
    local.default_tags,
    {
      "Name" = "${local.name_prefix}-default-rt"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "server_name" {
  type        = string
  default     = ""
  description = "Explicit name for the Transfer Server. If empty, a random name is generated."
}

variable "endpoint_type" {
  type        = string
  default     = "PUBLIC"
  description = "The type of endpoint that you want your SFTP server to connect to. Can be PUBLIC, VPC, or VPC_ENDPOINT."
  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "identity_provider_type" {
  type        = string
  default     = "SERVICE_MANAGED"
  description = "The mode of authentication for the server. Valid values are SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, or AWS_LAMBDA."
  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "AWS_LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, or AWS_LAMBDA."
  }
}

variable "api_gateway_invocation_url" {
  type        = string
  default     = ""
  description = "URL for the API Gateway endpoint when identity_provider_type is API_GATEWAY."
}

variable "logging_role_arn" {
  type        = string
  default     = ""
  description = "Explicit ARN of an IAM role that allows the service to write logs to CloudWatch. If not provided, one is created."
}

variable "security_policy_name" {
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
  description = "Specifies the name of the security policy for the server."
}

variable "banner" {
  type        = string
  default     = "Welcome to the secure Transfer Family SFTP service."
  description = "The message displayed to users when they connect."
}

variable "enable_route53_record" {
  type        = bool
  default     = false
  description = "Whether to provision a Route 53 CNAME record pointing to the Transfer Server endpoint."
}

variable "route53_domain_name" {
  type        = string
  default     = "example.com"
  description = "Domain name for the Route 53 hosted zone."
}

variable "route53_subdomain" {
  type        = string
  default     = "sftp"
  description = "Sub-domain prefix for the Route 53 record."
}

variable "sftp_users" {
  type = map(object({
    home_directory_path = string
  }))
  default = {
    "user1" = {
      home_directory_path = "home/user1"
    }
    "user2" = {
      home_directory_path = "home/user2"
    }
  }
  description = "Map of SFTP users and their S3 home directory relative paths."
}

variable "sftp_user_ssh_keys" {
  type = map(list(string))
  default = {
    "user1" = ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAICljV1k8L0N0Z090UHVibGljS2V5Rm9yVXNlcjFPbmx5AQ== user1@example.com"]
    "user2" = ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIG1kZ1k4L0N0Z090UHVibGljS2V5Rm9yVXNlcjJPbmx5Ag== user2@example.com"]
  }
  description = "Map of user names to lists of SSH public key bodies."
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

locals {
  server_identifier = var.server_name != "" ? var.server_name : random_pet.server_name.id
  is_vpc_mode       = var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT"
  user_ssh_key_pairs = flatten([
    for user, keys in var.sftp_user_ssh_keys : [
      for idx, key in keys : {
        key_id   = "${user}-${idx}"
        username = user
        key_body = key
      }
    ]
  ])
}

# --- CloudWatch Logging Role for Transfer Server ---

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "transfer_logging" {
  count              = var.logging_role_arn == "" ? 1 : 0
  name_prefix        = "${local.server_identifier}-logging-"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count      = var.logging_role_arn == "" ? 1 : 0
  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# --- CloudWatch Structured Logs Destination ---

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_identifier}"
  retention_in_days = 90
}

# --- Optional API Gateway Invocation IAM Role ---

data "aws_iam_policy_document" "transfer_apigw_policy" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  statement {
    sid    = "ApiGatewayInvoke"
    effect = "Allow"
    actions = [
      "execute-api:Invoke"
    ]
    resources = [
      "arn:aws:execute-api:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*/*"
    ]
  }

  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/transfer/*"
    ]
  }
}

resource "aws_iam_role" "transfer_apigw" {
  count              = var.identity_provider_type == "API_GATEWAY" ? 1 : 0
  name_prefix        = "${local.server_identifier}-apigw-"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
}

resource "aws_iam_role_policy" "transfer_apigw" {
  count  = var.identity_provider_type == "API_GATEWAY" ? 1 : 0
  name   = "${local.server_identifier}-apigw-policy"
  role   = aws_iam_role.transfer_apigw[0].id
  policy = data.aws_iam_policy_document.transfer_apigw_policy[0].json
}

# --- Greenfield VPC and Networking for VPC endpoint mode ---

resource "aws_vpc" "transfer_vpc" {
  count                = local.is_vpc_mode ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.server_identifier}-vpc"
  }
}

resource "aws_internet_gateway" "transfer_igw" {
  count  = local.is_vpc_mode ? 1 : 0
  vpc_id = aws_vpc.transfer_vpc[0].id

  tags = {
    Name = "${local.server_identifier}-igw"
  }
}

resource "aws_subnet" "transfer_subnets" {
  count                   = local.is_vpc_mode ? 2 : 0
  vpc_id                  = aws_vpc.transfer_vpc[0].id
  cidr_block              = cidrsubnet("10.0.0.0/16", 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.server_identifier}-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "transfer_public" {
  count  = local.is_vpc_mode ? 1 : 0
  vpc_id = aws_vpc.transfer_vpc[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.transfer_igw[0].id
  }

  tags = {
    Name = "${local.server_identifier}-public-rt"
  }
}

resource "aws_route_table_association" "transfer_subnets" {
  count          = local.is_vpc_mode ? 2 : 0
  subnet_id      = aws_subnet.transfer_subnets[count.index].id
  route_table_id = aws_route_table.transfer_public[0].id
}

resource "aws_eip" "transfer_eip" {
  count  = local.is_vpc_mode ? 2 : 0
  domain = "vpc"

  tags = {
    Name = "${local.server_identifier}-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.transfer_igw]
}

resource "aws_security_group" "transfer_sg" {
  count       = local.is_vpc_mode ? 1 : 0
  name_prefix = "${local.server_identifier}-sg-"
  description = "Allow inbound SFTP traffic on port 22"
  vpc_id      = aws_vpc.transfer_vpc[0].id

  ingress {
    description = "SFTP public inbound"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.server_identifier}-sg"
  }
}

# --- S3 Storage Bucket for Users ---

resource "aws_kms_key" "s3_key" {
  description             = "KMS Key for SFTP S3 bucket storage"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "${local.server_identifier}-kms-key"
  }
}

resource "aws_s3_bucket" "transfer_storage" {
  bucket_prefix = "${local.server_identifier}-sftp-data-"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.server_identifier}-storage"
  }
}

resource "aws_s3_bucket_versioning" "transfer_storage" {
  bucket = aws_s3_bucket.transfer_storage.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "transfer_storage" {
  bucket = aws_s3_bucket.transfer_storage.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "transfer_storage" {
  bucket = aws_s3_bucket.transfer_storage.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --- AWS Transfer Family Server ---

resource "aws_transfer_server" "sftp" {
  identity_provider_type = var.identity_provider_type
  endpoint_type          = var.endpoint_type
  protocols              = ["SFTP"]
  security_policy_name   = var.security_policy_name
  logging_role           = var.logging_role_arn != "" ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn
  url                    = var.identity_provider_type == "API_GATEWAY" ? var.api_gateway_invocation_url : null
  invocation_role        = var.identity_provider_type == "API_GATEWAY" ? aws_iam_role.transfer_apigw[0].arn : null
  structured_log_destinations = [
    aws_cloudwatch_log_group.transfer.arn
  ]

  post_authentication_login_banner = var.banner

  protocol_details {
    passive_ip                  = "AUTO"
    tls_session_resumption_mode = "ENFORCED"
  }

  dynamic "endpoint_details" {
    for_each = local.is_vpc_mode ? [1] : []
    content {
      vpc_id                 = aws_vpc.transfer_vpc[0].id
      subnet_ids             = aws_subnet.transfer_subnets[*].id
      security_group_ids     = [aws_security_group.transfer_sg[0].id]
      address_allocation_ids = aws_eip.transfer_eip[*].id
    }
  }

  tags = {
    Name = local.server_identifier
  }
}

# --- Optional Route 53 DNS Mapping ---

resource "aws_route53_zone" "primary" {
  count = var.enable_route53_record ? 1 : 0
  name  = var.route53_domain_name

  tags = {
    Name = "${local.server_identifier}-zone"
  }
}

resource "aws_route53_record" "sftp" {
  count   = var.enable_route53_record ? 1 : 0
  zone_id = aws_route53_zone.primary[0].zone_id
  name    = "${var.route53_subdomain}.${var.route53_domain_name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.sftp.endpoint]
}

# --- SFTP Users, Scoped IAM Roles, and SSH Keys ---

data "aws_iam_policy_document" "sftp_user_policy" {
  for_each = var.sftp_users

  statement {
    sid    = "AllowListingBucketPrefix"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.transfer_storage.arn
    ]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = [
        "${each.value.home_directory_path}/*",
        each.value.home_directory_path
      ]
    }
  }

  statement {
    sid    = "AllowObjectAccessInHome"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:PutObjectAcl"
    ]
    resources = [
      "${aws_s3_bucket.transfer_storage.arn}/${each.value.home_directory_path}/*"
    ]
  }

  statement {
    sid    = "AllowKmsAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*"
    ]
    resources = [
      aws_kms_key.s3_key.arn
    ]
  }
}

resource "aws_iam_role" "sftp_user" {
  for_each           = var.sftp_users
  name_prefix        = "${local.server_identifier}-${each.key}-"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
}

resource "aws_iam_policy" "sftp_user" {
  for_each    = var.sftp_users
  name_prefix = "${local.server_identifier}-${each.key}-policy-"
  policy      = data.aws_iam_policy_document.sftp_user_policy[each.key].json
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each   = var.sftp_users
  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

resource "aws_transfer_user" "sftp_user" {
  for_each       = var.sftp_users
  server_id      = aws_transfer_server.sftp.id
  user_name      = each.key
  role           = aws_iam_role.sftp_user[each.key].arn
  home_directory = "/${aws_s3_bucket.transfer_storage.id}/${each.value.home_directory_path}"

  tags = {
    Name = "${local.server_identifier}-${each.key}"
  }
}

resource "aws_transfer_ssh_key" "sftp_user_keys" {
  for_each   = { for pair in local.user_ssh_key_pairs : pair.key_id => pair if contains(keys(var.sftp_users), pair.username) }
  server_id  = aws_transfer_server.sftp.id
  user_name  = aws_transfer_user.sftp_user[each.value.username].user_name
  body       = each.value.key_body
  depends_on = [aws_transfer_user.sftp_user]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  cluster_name = "md-k8s"
  vpc_cidr     = "192.168.0.0/16"
  common_tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC and Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-vpc"
    }
  )
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-igw"
    }
  )
}

# Public Subnets
resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/19"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                     = "${local.cluster_name}-public-1"
      "kubernetes.io/role/elb" = "1"
    }
  )
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.32.0/19"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                     = "${local.cluster_name}-public-2"
      "kubernetes.io/role/elb" = "1"
    }
  )
}

resource "aws_subnet" "public_3" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.64.0/19"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                     = "${local.cluster_name}-public-3"
      "kubernetes.io/role/elb" = "1"
    }
  )
}

# Private Subnets
resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.96.0/19"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                              = "${local.cluster_name}-private-1"
      "kubernetes.io/role/internal-elb" = "1"
    }
  )
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.128.0/19"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                              = "${local.cluster_name}-private-2"
      "kubernetes.io/role/internal-elb" = "1"
    }
  )
}

resource "aws_subnet" "private_3" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.160.0/19"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                              = "${local.cluster_name}-private-3"
      "kubernetes.io/role/internal-elb" = "1"
    }
  )
}

# NAT Gateway and Elastic IP
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-nat-eip"
    }
  )
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_1.id

  depends_on = [aws_internet_gateway.igw]

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-nat"
    }
  )
}

# Routing
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_3" {
  subnet_id      = aws_subnet.public_3.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-private-rt"
    }
  )
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_3" {
  subnet_id      = aws_subnet.private_3.id
  route_table_id = aws_route_table.private.id
}

# DB Subnet Group
resource "aws_db_subnet_group" "private" {
  name        = "md-k8s-private-subnet-group"
  description = "Database subnet group covering private subnets for md-k8s"
  subnet_ids = [
    aws_subnet.private_1.id,
    aws_subnet.private_2.id,
    aws_subnet.private_3.id
  ]

  tags = merge(
    local.common_tags,
    {
      Name = "md-k8s-private-subnet-group"
    }
  )
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "control_plane" {
  name        = "${local.cluster_name}-control-plane-sg"
  description = "Control plane security group for ${local.cluster_name}"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-control-plane-sg"
    }
  )
}

resource "aws_security_group" "node_shared" {
  name        = "${local.cluster_name}-node-shared-sg"
  description = "Shared node security group for ${local.cluster_name}"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-node-shared-sg"
    }
  )
}

resource "aws_security_group_rule" "node_ingress_self" {
  description              = "Allow inter-node communication"
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.node_shared.id
  source_security_group_id = aws_security_group.node_shared.id
}

resource "aws_security_group_rule" "node_ingress_control_plane" {
  description              = "Allow traffic from control plane security group"
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.node_shared.id
  source_security_group_id = aws_security_group.control_plane.id
}

# -----------------------------------------------------------------------------
# KMS Key for Envelope Encryption
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "aws_kms_key" "eks_secrets" {
  description             = "KMS key for EKS secrets envelope encryption in ${local.cluster_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootKeyManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-kms-key"
    }
  )
}

resource "aws_kms_alias" "eks_secrets" {
  name          = "alias/md-k8s-eks-secrets"
  target_key_id = aws_kms_key.eks_secrets.key_id
}

# -----------------------------------------------------------------------------
# IAM Role and Policies for EKS Control Plane
# -----------------------------------------------------------------------------

resource "aws_iam_role" "cluster_role" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-cluster-role"
    }
  )
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster_role.name
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.cluster_role.name
}

resource "aws_iam_policy" "cluster_custom" {
  name        = "${local.cluster_name}-cluster-custom-policy"
  description = "Custom least-privilege policy for ${local.cluster_name} EC2 networking describe and CloudWatch metrics"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DescribeEC2Networking"
        Effect = "Allow"
        Action = [
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:DescribeRouteTables",
          "ec2:DescribeNetworkInterfaces"
        ]
        Resource = "*"
      },
      {
        Sid    = "PublishMetrics"
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "cloudwatch:namespace" = "ContainerInsights"
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cluster_custom" {
  policy_arn = aws_iam_policy.cluster_custom.arn
  role       = aws_iam_role.cluster_role.name
}

# -----------------------------------------------------------------------------
# Amazon EKS Cluster
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster_role.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.public_1.id,
      aws_subnet.public_2.id,
      aws_subnet.public_3.id,
      aws_subnet.private_1.id,
      aws_subnet.private_2.id,
      aws_subnet.private_3.id
    ]
    security_group_ids      = [aws_security_group.control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller,
    aws_iam_role_policy_attachment.cluster_custom
  ]

  tags = merge(
    local.common_tags,
    {
      Name = local.cluster_name
    }
  )
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "namespace" {
  type        = string
  description = "Namespace or organization prefix for resource naming."
  default     = "corp"
}

variable "environment" {
  type        = string
  description = "Environment identifier (e.g., prod, stage, dev)."
  default     = "prod"
}

variable "name" {
  type        = string
  description = "Base name for the S3 bucket and associated resources."
  default     = "general-data"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes to append to resource names."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources."
  default     = {}
}

variable "force_destroy" {
  type        = bool
  description = "Whether to allow bucket destruction even if non-empty."
  default     = false
}

variable "versioning_enabled" {
  type        = bool
  description = "Enable versioning on the S3 bucket."
  default     = true
}

variable "kms_enabled" {
  type        = bool
  description = "Use AWS KMS for default server-side encryption. If false, AES256 is used."
  default     = true
}

variable "kms_key_arn" {
  type        = string
  description = "Existing KMS Key ARN to use for S3 encryption. If null and kms_enabled is true, a dedicated key is created."
  default     = null
}

variable "kms_key_deletion_window_in_days" {
  type        = number
  description = "Key deletion window in days for the managed KMS key."
  default     = 30
}

variable "bucket_key_enabled" {
  type        = bool
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE-KMS."
  default     = true
}

variable "object_ownership" {
  type        = string
  description = "Object ownership control: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  default     = "BucketOwnerEnforced"
}

variable "object_lock_enabled" {
  type        = bool
  description = "Enable S3 Object Lock capability on the bucket (must be set at bucket creation)."
  default     = false
}

variable "object_lock_configuration" {
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  description = "Object Lock default retention settings. Mode must be GOVERNANCE or COMPLIANCE."
  default     = null
}

variable "acceleration_status" {
  type        = string
  description = "Transfer acceleration status for the bucket: Enabled or Suspended."
  default     = null
}

variable "request_payer" {
  type        = string
  description = "Specifies who pays for the download and request fees: BucketOwner or Requester."
  default     = "BucketOwner"
}

variable "cors_rules" {
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  description = "List of CORS rules to apply to the bucket."
  default     = []
}

variable "website_configuration" {
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  description = "Static website hosting configuration."
  default     = null
}

variable "lifecycle_rules" {
  type = list(object({
    id                                     = string
    enabled                                = bool
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    abort_incomplete_multipart_upload_days = optional(number)
    transitions = optional(list(object({
      days          = number
      storage_class = string
    })))
    expiration_days = optional(number)
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
    noncurrent_version_expiration_days = optional(number)
  }))
  description = "Lifecycle rules for object expiration, transitions, and multipart upload cleanup."
  default     = []
}

variable "access_logging_enabled" {
  type        = bool
  description = "Enable S3 server access logging."
  default     = false
}

variable "target_bucket" {
  type        = string
  description = "Target S3 bucket for access logs. If null and access_logging_enabled is true, a dedicated logging bucket is created."
  default     = null
}

variable "target_prefix" {
  type        = string
  description = "Prefix for server access logging."
  default     = "logs/"
}

variable "custom_policy_statements" {
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  description = "Custom IAM policy statements to append to the bucket policy."
  default     = []
}

# -----------------------------------------------------------------------------
# Local Values & Label Engine
# -----------------------------------------------------------------------------
locals {
  name_parts = compact(concat(
    [var.namespace, var.environment, var.name],
    var.attributes,
    [data.aws_caller_identity.current.account_id, data.aws_region.current.name]
  ))
  bucket_name = lower(substr(join("-", local.name_parts), 0, 63))

  log_bucket_name_parts = compact(concat(
    [var.namespace, var.environment, var.name, "logs"],
    var.attributes,
    [data.aws_caller_identity.current.account_id, data.aws_region.current.name]
  ))
  log_bucket_name = lower(substr(join("-", local.log_bucket_name_parts), 0, 63))

  base_tags = {
    Namespace   = var.namespace
    Environment = var.environment
    Name        = var.name
    ManagedBy   = "Terraform"
  }
  all_tags = merge(local.base_tags, var.tags)

  create_kms_key    = var.kms_enabled && var.kms_key_arn == null
  create_log_bucket = var.access_logging_enabled && var.target_bucket == null

  effective_kms_key_arn = var.kms_enabled ? (
    var.kms_key_arn != null ? var.kms_key_arn : (
      local.create_kms_key ? aws_kms_key.s3[0].arn : null
    )
  ) : null

  effective_log_target_bucket = var.access_logging_enabled ? (
    var.target_bucket != null ? var.target_bucket : (
      local.create_log_bucket ? aws_s3_bucket.log_bucket[0].id : null
    )
  ) : null
}

# -----------------------------------------------------------------------------
# KMS Customer-Managed Key (Optional)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "s3" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Dedicated customer-managed KMS key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json
  tags                    = merge(local.all_tags, { Name = "${local.bucket_name}-key" })
}

resource "aws_kms_alias" "s3" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/${substr(local.bucket_name, 0, 50)}-key"
  target_key_id = aws_kms_key.s3[0].key_id
}

# -----------------------------------------------------------------------------
# Dedicated Access Logging S3 Bucket (Optional)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "log_bucket" {
  count         = local.create_log_bucket ? 1 : 0
  bucket        = local.log_bucket_name
  force_destroy = var.force_destroy
  tags          = merge(local.all_tags, { Name = local.log_bucket_name, Role = "AccessLogs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  count                   = local.create_log_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.log_bucket[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  count  = local.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  count  = local.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  count  = local.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# -----------------------------------------------------------------------------
# Primary S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = merge(local.all_tags, { Name = local.bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

# Strict Public Access Block (Always Applied)
resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket Ownership Controls
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = var.object_ownership
  }
}

# Bucket Versioning
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# Server-Side Encryption Configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_enabled ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_enabled ? local.effective_kms_key_arn : null
    }
    bucket_key_enabled = var.kms_enabled ? var.bucket_key_enabled : false
  }
}

# Server Access Logging
resource "aws_s3_bucket_logging" "main" {
  count         = var.access_logging_enabled ? 1 : 0
  bucket        = aws_s3_bucket.main.id
  target_bucket = local.effective_log_target_bucket
  target_prefix = var.target_prefix
}

# Object Lock Configuration
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count  = var.object_lock_enabled && var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }
}

# Lifecycle Configuration
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null || rule.value.tags != null ? [1] : []
        content {
          dynamic "and" {
            for_each = rule.value.prefix != null && rule.value.tags != null && length(rule.value.tags) > 0 ? [1] : []
            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }

          prefix = rule.value.prefix != null && (rule.value.tags == null || length(coalesce(rule.value.tags, {})) == 0) ? rule.value.prefix : null
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "transition" {
        for_each = coalesce(rule.value.transitions, [])
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [1] : []
        content {
          days = rule.value.expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = coalesce(rule.value.noncurrent_version_transitions, [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }
    }
  }
}

# CORS Configuration
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Static Website Hosting Configuration
resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "index_document" {
    for_each = var.website_configuration.index_document != null ? [1] : []
    content {
      suffix = var.website_configuration.index_document
    }
  }

  dynamic "error_document" {
    for_each = var.website_configuration.error_document != null ? [1] : []
    content {
      key = var.website_configuration.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_configuration.redirect_all_requests_to != null ? [1] : []
    content {
      host_name = var.website_configuration.redirect_all_requests_to
    }
  }

  routing_rules = var.website_configuration.routing_rules
}

# Transfer Acceleration Configuration
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count  = var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  status = var.acceleration_status
}

# Request Payment Configuration
resource "aws_s3_bucket_request_payment_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  payer  = var.request_payer
}

# -----------------------------------------------------------------------------
# Bucket Policy (Enforce TLS + Optional Custom Statements)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "combined_policy" {
  statement {
    sid     = "EnforceTLSRequestsOnly"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = coalesce(statement.value.principals, [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = coalesce(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket     = aws_s3_bucket.main.id
  policy     = data.aws_iam_policy_document.combined_policy.json
  depends_on = [aws_s3_bucket_public_access_block.main]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the primary S3 bucket."
  value       = aws_s3_bucket.main.id
}

output "bucket_arn" {
  description = "The ARN of the primary S3 bucket."
  value       = aws_s3_bucket.main.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.main.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.main.bucket_regional_domain_name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption."
  value       = local.effective_kms_key_arn
}

output "log_bucket_id" {
  description = "The name of the dedicated logging bucket, if created."
  value       = local.create_log_bucket ? aws_s3_bucket.log_bucket[0].id : null
}

output "tags" {
  description = "Standardized map of tags applied to the bucket."
  value       = merge(local.all_tags, { Name = local.bucket_name })
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be created."
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "Name tag for the VPC and prefix for associated network resources."
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/18"
}

variable "az_count" {
  type        = number
  description = "Number of availability zones to use. If null, all available AZs in the region are used."
  default     = null
}

variable "enable_public_subnets" {
  type        = bool
  description = "Toggle creation of public subnets, internet gateway, and public route table."
  default     = true
}

variable "enable_private_subnets" {
  type        = bool
  description = "Toggle creation of private subnets and private route table."
  default     = true
}

variable "enable_nat_gateway" {
  type        = bool
  description = "Toggle creation of NAT Gateway. Requires public subnets to be enabled."
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name        = var.vpc_name
  all_azs     = data.aws_availability_zones.available.names
  num_azs     = var.az_count != null ? min(var.az_count, length(local.all_azs)) : length(local.all_azs)
  azs         = slice(local.all_azs, 0, local.num_azs)

  # NAT Gateway requires at least one public subnet and enable_nat_gateway set to true
  deploy_nat = var.enable_nat_gateway && var.enable_public_subnets && local.num_azs > 0
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count  = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-igw"
  }
}

# Public Subnets (assigned from first half of address space)
resource "aws_subnet" "public" {
  count                   = var.enable_public_subnets ? local.num_azs : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-public-${local.azs[count.index]}"
    Type = "Public"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  count  = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-public-rt"
  }
}

# Public Route to Internet Gateway
resource "aws_route" "public_internet_access" {
  count                  = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

# Associate Public Subnets with Public Route Table
resource "aws_route_table_association" "public" {
  count          = var.enable_public_subnets ? local.num_azs : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count  = local.deploy_nat ? 1 : 0
  domain = "vpc"

  tags = {
    Name = "${local.name}-nat-eip"
  }

  depends_on = [aws_internet_gateway.main]
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  count         = local.deploy_nat ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name}-nat-gw"
  }

  depends_on = [aws_internet_gateway.main]
}

# Private Subnets (assigned from second half of address space)
resource "aws_subnet" "private" {
  count                   = var.enable_private_subnets ? local.num_azs : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index + 8)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-private-${local.azs[count.index]}"
    Type = "Private"
  }
}

# Private Route Table
resource "aws_route_table" "private" {
  count  = var.enable_private_subnets && local.num_azs > 0 ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-private-rt"
  }
}

# Private Route to NAT Gateway (if NAT is deployed)
resource "aws_route" "private_nat_access" {
  count                  = var.enable_private_subnets && local.deploy_nat ? 1 : 0
  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[0].id
}

# Associate Private Subnets with Private Route Table
resource "aws_route_table_association" "private" {
  count          = var.enable_private_subnets ? local.num_azs : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Public Network ACL
resource "aws_network_acl" "public" {
  count      = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "${local.name}-public-nacl"
  }
}

resource "aws_network_acl_rule" "public_ingress_http" {
  count          = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  count          = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 110
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  count          = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 120
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_egress_tcp" {
  count          = var.enable_public_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 65535
}

# Private Network ACL
resource "aws_network_acl" "private" {
  count      = var.enable_private_subnets && local.num_azs > 0 ? 1 : 0
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.name}-private-nacl"
  }
}

resource "aws_network_acl_rule" "private_ingress_vpc_tcp" {
  count          = var.enable_private_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = aws_vpc.main.cidr_block
  from_port      = 80
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  count          = var.enable_private_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 110
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_tcp" {
  count          = var.enable_private_subnets && local.num_azs > 0 ? 1 : 0
  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 65535
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "List of public subnet IDs."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ip" {
  description = "The public IP of the NAT Gateway."
  value       = try(aws_eip.nat[0].public_ip, null)
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "aws_region" {
  description = "Configured AWS region."
  value       = var.aws_region
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "Base IPv4 CIDR block for the VPC"
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  type        = bool
  description = "Flag to enable Amazon-provided IPv6 CIDR assignment on the VPC"
  default     = true
}

variable "sn_details" {
  type = list(object({
    name      = string
    az_index  = number
    is_public = bool
  }))
  description = "List of subnet definitions across tiers and AZs"
  default = [
    { name = "web-subnet-a", az_index = 0, is_public = true },
    { name = "web-subnet-b", az_index = 1, is_public = true },
    { name = "web-subnet-c", az_index = 2, is_public = true },
    { name = "app-subnet-a", az_index = 0, is_public = false },
    { name = "app-subnet-b", az_index = 1, is_public = false },
    { name = "app-subnet-c", az_index = 2, is_public = false },
    { name = "db-subnet-a", az_index = 0, is_public = false },
    { name = "db-subnet-b", az_index = 1, is_public = false },
    { name = "db-subnet-c", az_index = 2, is_public = false },
    { name = "reserved-subnet-a", az_index = 0, is_public = false },
    { name = "reserved-subnet-b", az_index = 1, is_public = false },
    { name = "reserved-subnet-c", az_index = 2, is_public = false }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_hostnames             = true
  enable_dns_support               = true

  tags = {
    Name = "main-vpc"
  }
}

module "subnet_addrs_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block
  networks = [
    for subnet in var.sn_details : {
      name     = subnet.name
      new_bits = 4
    }
  ]
}

module "subnet_addrs_ipv6" {
  count   = var.is_ipv6_enabled ? 1 : 0
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.ipv6_cidr_block
  networks = [
    for subnet in var.sn_details : {
      name     = subnet.name
      new_bits = 8
    }
  ]
}

locals {
  subnets_map = {
    for idx, sn in var.sn_details : sn.name => {
      name            = sn.name
      az_name         = data.aws_availability_zones.available.names[sn.az_index]
      is_public       = sn.is_public
      cidr_block      = module.subnet_addrs_ipv4.network_cidr_blocks[sn.name]
      ipv6_cidr_block = var.is_ipv6_enabled ? module.subnet_addrs_ipv6[0].network_cidr_blocks[sn.name] : null
    }
  }
  public_subnets = {
    for name, sn in local.subnets_map : name => sn if sn.is_public
  }
}

resource "aws_subnet" "tiers" {
  for_each = local.subnets_map

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = each.value.cidr_block
  ipv6_cidr_block                 = each.value.ipv6_cidr_block
  availability_zone               = each.value.az_name
  assign_ipv6_address_on_creation = var.is_ipv6_enabled

  tags = {
    Name = each.value.name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  dynamic "route" {
    for_each = var.is_ipv6_enabled ? [1] : []
    content {
      ipv6_cidr_block = "::/0"
      gateway_id      = aws_internet_gateway.main.id
    }
  }

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.tiers[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Security group for web tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Security group for application tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Security group for database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

resource "aws_security_group_rule" "web_ingress_tls" {
  type              = "ingress"
  description       = "Allow inbound HTTPS from internet"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "web_ingress_ssh" {
  type              = "ingress"
  description       = "Allow inbound SSH only from VPC CIDR"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "web_egress_app_tls" {
  type                     = "egress"
  description              = "Allow outbound HTTPS to app tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  security_group_id        = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "app_ingress_web_tls" {
  type                     = "ingress"
  description              = "Allow inbound HTTPS from web tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.web_sg.id
  security_group_id        = aws_security_group.app_sg.id
}

resource "aws_security_group_rule" "app_egress_db_tls" {
  type                     = "egress"
  description              = "Allow outbound HTTPS to database tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.db_sg.id
  security_group_id        = aws_security_group.app_sg.id
}

resource "aws_security_group_rule" "db_ingress_app_tls" {
  type                     = "ingress"
  description              = "Allow inbound HTTPS from app tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  security_group_id        = aws_security_group.db_sg.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "s3_bucket_name" {
  type        = string
  description = "Name of the S3 bucket for canary artifacts"
  default     = "benchmark-canary-bucket-tf5x"
}

variable "s3_bucket_versioning_enabled" {
  type        = bool
  description = "Enable versioning on the canary S3 artifact bucket"
  default     = false
}

variable "enable_kms_key" {
  type        = bool
  description = "Toggle to create and use custom KMS key for encryption"
  default     = true
}

variable "sns_notification_email" {
  type        = string
  description = "Email recipient for canary alarm notifications"
  default     = "nobody@example.com"
}

variable "enable_success_percent_alarm" {
  type        = bool
  description = "Whether to provision success percentage metric alarms"
  default     = false
}

variable "canaries" {
  type = map(object({
    handler            = string
    schedule           = string
    s3_bucket          = optional(string)
    s3_key             = optional(string)
    s3_version         = optional(string)
    zip_file_path      = optional(string)
    subnet_ids         = optional(list(string))
    security_group_ids = optional(list(string))
  }))
  description = "Map of canary specifications"
  default = {
    "sample-check" = {
      handler            = "pageLoadBlueprint.handler"
      schedule           = "rate(5 minutes)"
      s3_bucket          = null
      s3_key             = null
      s3_version         = null
      zip_file_path      = null
      subnet_ids         = null
      security_group_ids = null
    }
  }
}

# -----------------------------------------------------------------------------
# Metadata / Identity Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Greenfield Network Infrastructure (VPC, Subnets, SG)
# -----------------------------------------------------------------------------
resource "aws_vpc" "canary_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-canary-vpc"
  }
}

resource "aws_subnet" "canary_subnet_a" {
  vpc_id            = aws_vpc.canary_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "benchmark-canary-subnet-a"
  }
}

resource "aws_subnet" "canary_subnet_b" {
  vpc_id            = aws_vpc.canary_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "benchmark-canary-subnet-b"
  }
}

resource "aws_security_group" "canary_sg" {
  name        = "benchmark-canary-sg"
  description = "Security group for VPC-based CloudWatch Synthetics canaries"
  vpc_id      = aws_vpc.canary_vpc.id

  egress {
    description = "Allow outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.canary_vpc.cidr_block]
  }

  tags = {
    Name = "benchmark-canary-sg"
  }
}

# -----------------------------------------------------------------------------
# KMS Encryption Resources
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy_doc" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarmsAndSynthetics"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    principals {
      type = "Service"
      identifiers = [
        "cloudwatch.amazonaws.com",
        "synthetics.amazonaws.com",
        "sns.amazonaws.com"
      ]
    }
  }
}

resource "aws_kms_key" "canary_kms_key" {
  count                   = var.enable_kms_key ? 1 : 0
  description             = "KMS Key for Canary artifacts, SNS notifications, and logs"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy_doc.json

  tags = {
    Name = "benchmark-canary-kms-key"
  }
}

resource "aws_kms_alias" "canary_kms_alias" {
  count         = var.enable_kms_key ? 1 : 0
  name          = "alias/benchmark-canary-key"
  target_key_id = aws_kms_key.canary_kms_key[0].key_id
}

# -----------------------------------------------------------------------------
# S3 Artifact Storage & Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "canary_artifacts" {
  bucket        = var.s3_bucket_name
  force_destroy = true

  tags = {
    Name = "benchmark-canary-artifacts"
  }
}

resource "aws_s3_bucket_public_access_block" "canary_artifacts_pab" {
  bucket                  = aws_s3_bucket.canary_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary_artifacts_encryption" {
  bucket = aws_s3_bucket.canary_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_key ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms_key ? aws_kms_key.canary_kms_key[0].arn : null
    }
    bucket_key_enabled = var.enable_kms_key ? true : false
  }
}

resource "aws_s3_bucket_versioning" "canary_artifacts_versioning" {
  bucket = aws_s3_bucket.canary_artifacts.id
  versioning_configuration {
    status = var.s3_bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_cors_configuration" "canary_artifacts_cors" {
  bucket = aws_s3_bucket.canary_artifacts.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# -----------------------------------------------------------------------------
# Random Pet & Execution IAM Role for Synthetics
# -----------------------------------------------------------------------------
resource "random_pet" "canary_role_prefix" {
  length    = 2
  separator = "-"
}

data "aws_iam_policy_document" "canary_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "canary_execution_role" {
  name_prefix        = "${random_pet.canary_role_prefix.id}-"
  assume_role_policy = data.aws_iam_policy_document.canary_assume_role.json
  description        = "Execution role for CloudWatch Synthetics VPC canaries"

  tags = {
    Name = "benchmark-canary-execution-role"
  }
}

data "aws_iam_policy_document" "canary_execution_policy_doc" {
  statement {
    sid    = "S3ArtifactBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject"
    ]
    resources = [
      "${aws_s3_bucket.canary_artifacts.arn}/*"
    ]
  }

  statement {
    sid    = "S3BucketLocationPermission"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.canary_artifacts.arn
    ]
  }

  statement {
    sid    = "CloudWatchMetrics"
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricData"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "cloudwatch:namespace"
      values   = ["CloudWatchSynthetics"]
    }
  }

  statement {
    sid    = "CloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/cwsyn-*"
    ]
  }

  statement {
    sid    = "EC2NetworkInterfaceManagement"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface"
    ]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.enable_kms_key ? [1] : []
    content {
      sid    = "KMSAccess"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey*"
      ]
      resources = [aws_kms_key.canary_kms_key[0].arn]
    }
  }
}

resource "aws_iam_policy" "canary_execution_policy" {
  name_prefix = "${random_pet.canary_role_prefix.id}-policy-"
  description = "Least privilege execution policy for CloudWatch Synthetics canaries"
  policy      = data.aws_iam_policy_document.canary_execution_policy_doc.json
}

resource "aws_iam_role_policy_attachment" "canary_execution_attach" {
  role       = aws_iam_role.canary_execution_role.name
  policy_arn = aws_iam_policy.canary_execution_policy.arn
}

# -----------------------------------------------------------------------------
# Amazon SNS Topic, Topic Policy & Email Subscription
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "canary_notifications" {
  name              = "benchmark-canary-topic"
  kms_master_key_id = var.enable_kms_key ? aws_kms_key.canary_kms_key[0].id : null

  tags = {
    Name = "benchmark-canary-topic"
  }
}

data "aws_iam_policy_document" "sns_topic_policy_doc" {
  statement {
    sid    = "DefaultAdminTopicAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish"
    ]
    resources = [aws_sns_topic.canary_notifications.arn]
  }

  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "SNS:Publish"
    ]
    resources = [aws_sns_topic.canary_notifications.arn]
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:aws:cloudwatch:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:alarm:*"]
    }
  }
}

resource "aws_sns_topic_policy" "canary_notifications_policy" {
  arn    = aws_sns_topic.canary_notifications.arn
  policy = data.aws_iam_policy_document.sns_topic_policy_doc.json
}

resource "aws_sns_topic_subscription" "email_subscription" {
  topic_arn = aws_sns_topic.canary_notifications.arn
  protocol  = "email"
  endpoint  = var.sns_notification_email
}

# -----------------------------------------------------------------------------
# Default Inline Canary Script Archive (Puppeteer Blueprint)
# -----------------------------------------------------------------------------
data "archive_file" "default_canary_zip" {
  type        = "zip"
  output_path = "${path.module}/default_canary.zip"

  source {
    content  = <<-EOF
      const synthetics = require('Synthetics');
      const log = require('SyntheticsLogger');

      const pageLoadBlueprint = async function () {
          const URL = "https://aws.amazon.com";
          let page = await synthetics.getPage();
          const response = await page.goto(URL, {waitUntil: ['load', 'networkidle0'], timeout: 30000});
          if (!response) {
              throw new Error("Failed to load page!");
          }
          let responseCode = response.status();
          log.info("Response code: " + responseCode);
          if (responseCode !== 200) {
              throw new Error("Failed with response code " + responseCode);
          }
      };

      exports.handler = async () => {
          return await pageLoadBlueprint();
      };
    EOF
    filename = "nodejs/node_modules/pageLoadBlueprint.js"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Synthetics Canaries
# -----------------------------------------------------------------------------
resource "aws_synthetics_canary" "vpc_canaries" {
  for_each             = var.canaries
  name                 = each.key
  artifact_s3_location = "s3://${aws_s3_bucket.canary_artifacts.bucket}/"
  execution_role_arn   = aws_iam_role.canary_execution_role.arn
  handler              = each.value.handler
  runtime_version      = "syn-nodejs-puppeteer-9.1"

  # Archive / Script configuration: inline zip or S3 reference
  zip_file          = each.value.s3_bucket == null ? (each.value.zip_file_path != null ? each.value.zip_file_path : data.archive_file.default_canary_zip.output_path) : null
  s3_bucket         = each.value.s3_bucket
  s3_key            = each.value.s3_key
  s3_version        = each.value.s3_version

  schedule {
    expression          = each.value.schedule
    duration_in_seconds = 0
  }

  run_config {
    timeout_in_seconds = 120
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids != null ? each.value.subnet_ids : [aws_subnet.canary_subnet_a.id, aws_subnet.canary_subnet_b.id]
    security_group_ids = each.value.security_group_ids != null ? each.value.security_group_ids : [aws_security_group.canary_sg.id]
  }

  start_canary = true

  tags = {
    Name = each.key
  }

  depends_on = [
    aws_iam_role_policy_attachment.canary_execution_attach,
    aws_s3_bucket_public_access_block.canary_artifacts_pab,
    aws_s3_bucket_server_side_encryption_configuration.canary_artifacts_encryption
  ]
}

# -----------------------------------------------------------------------------
# CloudWatch Metric Alarms (Failed & SuccessPercent)
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_metric_alarm" "canary_failed_alarm" {
  for_each            = var.canaries
  alarm_name          = "${each.key}-failed-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = "Failed"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarm triggered when canary ${each.key} detects 1 or more failures in a 60-second window"
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = each.key
  }

  alarm_actions = [aws_sns_topic.canary_notifications.arn]

  depends_on = [
    aws_synthetics_canary.vpc_canaries
  ]
}

resource "aws_cloudwatch_metric_alarm" "canary_success_percent_alarm" {
  for_each            = var.enable_success_percent_alarm ? var.canaries : {}
  alarm_name          = "${each.key}-success-percent-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Average"
  threshold           = 90
  alarm_description   = "Alarm notifying when canary ${each.key} success rate falls below 90 percent"
  treat_missing_data  = "breaching"

  dimensions = {
    CanaryName = each.key
  }

  ok_actions    = [aws_sns_topic.canary_notifications.arn]
  alarm_actions = [aws_sns_topic.canary_notifications.arn]

  depends_on = [
    aws_synthetics_canary.vpc_canaries
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create_vpc" {
  description = "Controls if VPC resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name prefix applied to all VPC resources."
  type        = string
  default     = "main"
}

variable "cidr_block" {
  description = "The CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Controls if the VPC has DNS hostname support."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Controls if the VPC has DNS support."
  type        = bool
  default     = true
}

variable "azs" {
  description = "A list of availability zone names or IDs in the region."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "A list of public subnet CIDR blocks."
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Explicit names for the public subnets."
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix to append to public subnet names."
  type        = string
  default     = "public"
}

variable "map_public_ip_on_launch" {
  description = "Specify true to indicate that instances launched into the public subnets should be assigned a public IP address."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway should be provisioned for public subnets."
  type        = bool
  default     = true
}

variable "private_subnets" {
  description = "A list of private subnet CIDR blocks."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit names for the private subnets."
  type        = list(string)
  default     = []
}

variable "private_subnet_suffix" {
  description = "Suffix to append to private subnet names."
  type        = string
  default     = "private"
}

variable "intra_subnets" {
  description = "A list of intra/isolated subnet CIDR blocks."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit names for the intra subnets."
  type        = list(string)
  default     = []
}

variable "intra_subnet_suffix" {
  description = "Suffix to append to intra subnet names."
  type        = string
  default     = "intra"
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways should be provisioned for private subnets."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_id = try(aws_vpc.this[0].id, "")

  resolved_azs = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names

  public_subnet_count  = var.create_vpc ? length(var.public_subnets) : 0
  private_subnet_count = var.create_vpc ? length(var.private_subnets) : 0
  intra_subnet_count   = var.create_vpc ? length(var.intra_subnets) : 0

  create_igw = var.create_vpc && var.create_igw && local.public_subnet_count > 0

  nat_gateway_count = var.create_vpc && var.enable_nat_gateway && local.public_subnet_count > 0 && local.private_subnet_count > 0 ? min(local.public_subnet_count, local.private_subnet_count) : 0
}

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.cidr_block
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    var.tags,
    {
      "Name" = var.name
    }
  )
}

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = length(regexall("^[a-z]{2}-", element(local.resolved_azs, count.index))) > 0 ? element(local.resolved_azs, count.index) : null
  availability_zone_id    = length(regexall("^[a-z]{2}-", element(local.resolved_azs, count.index))) == 0 ? element(local.resolved_azs, count.index) : null
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    var.tags,
    {
      "Name" = try(
        var.public_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.public_subnet_suffix, element(local.resolved_azs, count.index))
      )
    }
  )
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id               = local.vpc_id
  cidr_block           = var.private_subnets[count.index]
  availability_zone    = length(regexall("^[a-z]{2}-", element(local.resolved_azs, count.index))) > 0 ? element(local.resolved_azs, count.index) : null
  availability_zone_id = length(regexall("^[a-z]{2}-", element(local.resolved_azs, count.index))) == 0 ? element(local.resolved_azs, count.index) : null

  tags = merge(
    var.tags,
    {
      "Name" = try(
        var.private_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.private_subnet_suffix, element(local.resolved_azs, count.index))
      )
    }
  )
}

resource "aws_subnet" "intra" {
  count = local.intra_subnet_count

  vpc_id               = local.vpc_id
  cidr_block           = var.intra_subnets[count.index]
  availability_zone    = length(regexall("^[a-z]{2}-", element(local.resolved_azs, count.index))) > 0 ? element(local.resolved_azs, count.index) : null
  availability_zone_id = length(regexall("^[a-z]{2}-", element(local.resolved_azs, count.index))) == 0 ? element(local.resolved_azs, count.index) : null

  tags = merge(
    var.tags,
    {
      "Name" = try(
        var.intra_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.intra_subnet_suffix, element(local.resolved_azs, count.index))
      )
    }
  )
}

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      "Name" = format("%s-igw", var.name)
    }
  )
}

resource "aws_route_table" "public" {
  count = local.public_subnet_count > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      "Name" = format("%s-%s", var.name, var.public_subnet_suffix)
    }
  )
}

resource "aws_route" "public_internet_gateway" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(
    var.tags,
    {
      "Name" = format("%s-nat-eip-%d", var.name, count.index + 1)
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.tags,
    {
      "Name" = format("%s-nat-%d", var.name, count.index + 1)
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count = local.private_subnet_count

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      "Name" = try(
        var.private_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.private_subnet_suffix, element(local.resolved_azs, count.index))
      )
    }
  )
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count > 0 ? local.private_subnet_count : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index % local.nat_gateway_count].id
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table" "intra" {
  count = local.intra_subnet_count

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      "Name" = try(
        var.intra_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.intra_subnet_suffix, element(local.resolved_azs, count.index))
      )
    }
  )
}

resource "aws_route_table_association" "intra" {
  count = local.intra_subnet_count

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "public_subnets" {
  description = "List of IDs of public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnets" {
  description = "List of IDs of private subnets."
  value       = aws_subnet.private[*].id
}

output "intra_subnets" {
  description = "List of IDs of intra subnets."
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of IDs of private route tables."
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "List of IDs of intra route tables."
  value       = aws_route_table.intra[*].id
}

output "nat_gateway_ids" {
  description = "List of NAT Gateway IDs."
  value       = aws_nat_gateway.this[*].id
}

output "nat_eip_ids" {
  description = "List of Elastic IP allocation IDs assigned to NAT Gateways."
  value       = aws_eip.nat[*].id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "api_type" {
  type        = string
  default     = "http"
  description = "The type of API to deploy ('http' or 'rest')."
  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either 'http' or 'rest'."
  }
}

variable "api_name" {
  type        = string
  default     = "benchmark-api"
  description = "Name of the API Gateway."
}

variable "environment" {
  type        = string
  default     = "dev"
  description = "Deployment environment name."
}

variable "enable_vpc_link" {
  type        = bool
  default     = false
  description = "Flag to enable VPC link provisioning."
}

variable "enable_custom_domain" {
  type        = bool
  default     = false
  description = "Flag to enable custom domain configuration."
}

variable "domain_name" {
  type        = string
  default     = ""
  description = "Custom domain name for the API Gateway."
}

variable "enable_route53_alias" {
  type        = bool
  default     = false
  description = "Flag to create Route 53 alias record for custom domain."
}

variable "route53_zone_id" {
  type        = string
  default     = ""
  description = "Route 53 Hosted Zone ID for custom domain alias."
}

variable "enable_api_key" {
  type        = bool
  default     = false
  description = "Flag to enable API Key and Usage Plan for REST API."
}

variable "allowed_ip_cidrs" {
  type        = list(string)
  default     = []
  description = "List of allowed IP CIDRs for REST API resource policy."
}

variable "nlb_target_port" {
  type        = number
  default     = 443
  description = "Port for the REST API VPC Link NLB target group targeting internal ALB."
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  stage_name = "${var.environment}-stage"
  vpc_cidr   = "10.0.0.0/16"
  is_http    = var.api_type == "http"
  is_rest    = var.api_type == "rest"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.api_name}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.api_name}-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.api_name}-public-subnet-1"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.api_name}-public-subnet-2"
    Environment = var.environment
  }
}

resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.11.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "${var.api_name}-private-subnet-1"
    Environment = var.environment
  }
}

resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.12.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "${var.api_name}-private-subnet-2"
    Environment = var.environment
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name        = "${var.api_name}-nat-eip"
    Environment = var.environment
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_1.id

  tags = {
    Name        = "${var.api_name}-nat-gw"
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "${var.api_name}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name        = "${var.api_name}-private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "vpc_link" {
  name        = "${var.api_name}-vpc-link-sg"
  description = "Security group for VPC Link and internal load balancers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Allow inbound HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${var.api_name}-vpc-link-sg"
    Environment = var.environment
  }
}

resource "tls_private_key" "alb_self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb_self_signed" {
  private_key_pem = tls_private_key.alb_self_signed.private_key_pem

  subject {
    common_name  = "internal.alb.local"
    organization = "Internal Services"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb_cert" {
  private_key      = tls_private_key.alb_self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.alb_self_signed.cert_pem

  tags = {
    Name        = "${var.api_name}-alb-self-signed-cert"
    Environment = var.environment
  }
}

resource "aws_lb" "internal_alb" {
  name                       = "${var.api_name}-int-alb"
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.vpc_link.id]
  subnets                    = [aws_subnet.private_1.id, aws_subnet.private_2.id]

  tags = {
    Name        = "${var.api_name}-int-alb"
    Environment = var.environment
  }
}

resource "aws_lb_target_group" "alb_tg" {
  name        = "${var.api_name}-alb-tg"
  port        = 443
  protocol    = "HTTPS"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    enabled             = true
    path                = "/health"
    protocol            = "HTTPS"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name        = "${var.api_name}-alb-tg"
    Environment = var.environment
  }
}

resource "aws_lb_listener" "alb_listener" {
  load_balancer_arn = aws_lb.internal_alb.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb_cert.arn

  default_action {
    type = "fixed-response"
    fixed_response {
      content_type = "application/json"
      message_body = "{\"status\":\"ok\",\"service\":\"alb-backend\"}"
      status_code  = "200"
    }
  }
}

resource "aws_lb" "rest_nlb" {
  count              = local.is_rest && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = [aws_subnet.private_1.id, aws_subnet.private_2.id]

  tags = {
    Name        = "${var.api_name}-nlb"
    Environment = var.environment
  }
}

resource "aws_lb_target_group" "nlb_tg" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-nlb-tg"
  port        = var.nlb_target_port
  protocol    = "TCP"
  vpc_id      = aws_vpc.main.id
  target_type = "alb"

  health_check {
    enabled             = true
    protocol            = "HTTPS"
    port                = "traffic-port"
    path                = "/health"
    interval            = 30
    timeout             = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name        = "${var.api_name}-nlb-tg"
    Environment = var.environment
  }
}

resource "aws_lb_target_group_attachment" "nlb_alb_attachment" {
  count            = local.is_rest && var.enable_vpc_link ? 1 : 0
  target_group_arn = aws_lb_target_group.nlb_tg[0].arn
  target_id        = aws_lb.internal_alb.arn
  port             = var.nlb_target_port
}

resource "aws_lb_listener" "nlb_listener" {
  count             = local.is_rest && var.enable_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.rest_nlb[0].arn
  port              = var.nlb_target_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_tg[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest_link" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-rest-vpclink"
  description = "VPC Link for REST API"
  target_arns = [aws_lb.rest_nlb[0].arn]

  tags = {
    Name        = "${var.api_name}-rest-vpclink"
    Environment = var.environment
  }
}

resource "aws_apigatewayv2_vpc_link" "http_link" {
  count              = local.is_http && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-http-vpclink"
  security_group_ids = [aws_security_group.vpc_link.id]
  subnet_ids         = [aws_subnet.private_1.id, aws_subnet.private_2.id]

  tags = {
    Name        = "${var.api_name}-http-vpclink"
    Environment = var.environment
  }
}

data "archive_file" "authorizer_zip" {
  type        = "zip"
  output_path = "${path.module}/authorizer.zip"

  source {
    content  = <<-EOF
      exports.handler = async (event) => {
        const token = event.authorizationToken;
        const effect = token === 'allow-token' ? 'Allow' : 'Deny';
        return {
          principalId: 'user123',
          policyDocument: {
            Version: '2012-10-17',
            Statement: [
              {
                Action: 'execute-api:Invoke',
                Effect: effect,
                Resource: event.methodArn || '*'
              }
            ]
          },
          context: {
            scope: 'api:read'
          }
        };
      };
    EOF
    filename = "index.js"
  }
}

resource "aws_iam_role" "authorizer_role" {
  name = "${var.api_name}-authorizer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "${var.api_name}-authorizer-role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "authorizer_basic_execution" {
  role       = aws_iam_role.authorizer_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  filename         = data.archive_file.authorizer_zip.output_path
  function_name    = "${var.api_name}-authorizer"
  role             = aws_iam_role.authorizer_role.arn
  handler          = "index.handler"
  source_code_hash = data.archive_file.authorizer_zip.output_base64sha256
  runtime          = "nodejs20.x"

  tags = {
    Name        = "${var.api_name}-authorizer"
    Environment = var.environment
  }
}

resource "aws_iam_role" "apigw_invocation_role" {
  name = "${var.api_name}-apigw-invoke-authorizer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "${var.api_name}-apigw-invoke-authorizer-role"
    Environment = var.environment
  }
}

resource "aws_iam_policy" "apigw_invoke_authorizer_policy" {
  name        = "${var.api_name}-invoke-authorizer-policy"
  description = "Allows API Gateway to invoke authorizer Lambda"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "lambda:InvokeFunction"
        Effect   = "Allow"
        Resource = aws_lambda_function.authorizer.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_authorizer_attachment" {
  role       = aws_iam_role.apigw_invocation_role.name
  policy_arn = aws_iam_policy.apigw_invoke_authorizer_policy.arn
}

resource "aws_cloudwatch_log_group" "http_api" {
  count             = local.is_http ? 1 : 0
  name              = "/aws/v2/api/${var.api_name}-${var.environment}"
  retention_in_days = 30

  tags = {
    Name        = "${var.api_name}-http-log-group"
    Environment = var.environment
  }
}

resource "aws_apigatewayv2_api" "http_api" {
  count         = local.is_http ? 1 : 0
  name          = var.api_name
  protocol_type = "HTTP"

  tags = {
    Name        = var.api_name
    Environment = var.environment
  }
}

resource "aws_apigatewayv2_integration" "http_mock_integration" {
  count              = local.is_http ? 1 : 0
  api_id             = aws_apigatewayv2_api.http_api[0].id
  integration_type   = "HTTP_PROXY"
  integration_uri    = "https://${aws_lb.internal_alb.dns_name}"
  integration_method = "ANY"
  connection_type    = var.enable_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id      = var.enable_vpc_link ? aws_apigatewayv2_vpc_link.http_link[0].id : null
}

resource "aws_apigatewayv2_route" "http_route" {
  count     = local.is_http ? 1 : 0
  api_id    = aws_apigatewayv2_api.http_api[0].id
  route_key = "GET /items"
  target    = "integrations/${aws_apigatewayv2_integration.http_mock_integration[0].id}"
}

resource "aws_apigatewayv2_route" "http_proxy_route" {
  count     = local.is_http ? 1 : 0
  api_id    = aws_apigatewayv2_api.http_api[0].id
  route_key = "ANY /items/{proxy+}"
  target    = "integrations/${aws_apigatewayv2_integration.http_mock_integration[0].id}"
}

resource "aws_apigatewayv2_stage" "http_stage" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http_api[0].id
  name        = local.stage_name
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.http_api[0].arn
    format          = "{\"requestId\":\"$context.requestId\",\"ip\":\"$context.identity.sourceIp\",\"caller\":\"$context.identity.caller\",\"user\":\"$context.identity.user\",\"requestTime\":\"$context.requestTime\",\"httpMethod\":\"$context.httpMethod\",\"resourcePath\":\"$context.resourcePath\",\"status\":\"$context.status\",\"protocol\":\"$context.protocol\",\"responseLength\":\"$context.responseLength\"}"
  }

  tags = {
    Name        = "${var.api_name}-${local.stage_name}"
    Environment = var.environment
  }
}

resource "aws_acm_certificate" "custom_cert" {
  count             = local.is_http && var.enable_custom_domain && var.domain_name != "" ? 1 : 0
  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = {
    Name        = "${var.api_name}-cert"
    Environment = var.environment
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_domain_name" "custom_domain" {
  count       = local.is_http && var.enable_custom_domain && var.domain_name != "" ? 1 : 0
  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate.custom_cert[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = {
    Name        = "${var.api_name}-custom-domain"
    Environment = var.environment
  }
}

resource "aws_apigatewayv2_api_mapping" "http_mapping" {
  count       = local.is_http && var.enable_custom_domain && var.domain_name != "" ? 1 : 0
  api_id      = aws_apigatewayv2_api.http_api[0].id
  domain_name = aws_apigatewayv2_domain_name.custom_domain[0].id
  stage       = aws_apigatewayv2_stage.http_stage[0].id
}

resource "aws_route53_record" "api_alias" {
  count   = local.is_http && var.enable_custom_domain && var.enable_route53_alias && var.route53_zone_id != "" ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.custom_domain[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.custom_domain[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

data "aws_iam_policy_document" "rest_policy" {
  count = local.is_rest ? 1 : 0

  dynamic "statement" {
    for_each = length(var.allowed_ip_cidrs) > 0 ? [1] : []
    content {
      effect    = "Allow"
      actions   = ["execute-api:Invoke"]
      resources = ["arn:aws:execute-api:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "IpAddress"
        variable = "aws:SourceIp"
        values   = var.allowed_ip_cidrs
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.allowed_ip_cidrs) > 0 ? [1] : []
    content {
      effect    = "Deny"
      actions   = ["execute-api:Invoke"]
      resources = ["arn:aws:execute-api:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "NotIpAddress"
        variable = "aws:SourceIp"
        values   = var.allowed_ip_cidrs
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.allowed_ip_cidrs) == 0 ? [1] : []
    content {
      effect    = "Allow"
      actions   = ["execute-api:Invoke"]
      resources = ["arn:aws:execute-api:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }
    }
  }
}

resource "aws_api_gateway_rest_api" "rest_api" {
  count       = local.is_rest ? 1 : 0
  name        = var.api_name
  description = "Managed unified REST API"
  policy      = data.aws_iam_policy_document.rest_policy[0].json

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name        = var.api_name
    Environment = var.environment
  }
}

resource "aws_api_gateway_authorizer" "rest_authorizer" {
  count                  = local.is_rest ? 1 : 0
  name                   = "${var.api_name}-authorizer"
  rest_api_id           = aws_api_gateway_rest_api.rest_api[0].id
  authorizer_uri         = aws_lambda_function.authorizer.invoke_arn
  authorizer_credentials = aws_iam_role.apigw_invocation_role.arn
  type                   = "TOKEN"
  identity_source        = "method.request.header.Authorization"
}

resource "aws_api_gateway_resource" "items" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  parent_id   = aws_api_gateway_rest_api.rest_api[0].root_resource_id
  path_part   = "items"
}

resource "aws_api_gateway_resource" "item_id" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  parent_id   = aws_api_gateway_resource.items[0].id
  path_part   = "{itemId}"
}

resource "aws_api_gateway_method" "get_item" {
  count            = local.is_rest ? 1 : 0
  rest_api_id      = aws_api_gateway_rest_api.rest_api[0].id
  resource_id      = aws_api_gateway_resource.item_id[0].id
  http_method      = "GET"
  authorization    = "CUSTOM"
  authorizer_id    = aws_api_gateway_authorizer.rest_authorizer[0].id
  api_key_required = var.enable_api_key

  request_parameters = {
    "method.request.path.itemId" = true
  }
}

resource "aws_api_gateway_integration" "get_item_integration" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  resource_id = aws_api_gateway_resource.item_id[0].id
  http_method = aws_api_gateway_method.get_item[0].http_method
  type        = var.enable_vpc_link ? "HTTP" : "MOCK"

  integration_http_method = var.enable_vpc_link ? "GET" : null
  uri                     = var.enable_vpc_link ? "https://${aws_lb.internal_alb.dns_name}/items/{itemId}" : null
  connection_type         = var.enable_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id           = var.enable_vpc_link ? aws_api_gateway_vpc_link.rest_link[0].id : null

  request_parameters = var.enable_vpc_link ? {
    "integration.request.path.itemId" = "method.request.path.itemId"
  } : {}

  request_templates = !var.enable_vpc_link ? {
    "application/json" = "{\"statusCode\": 200}"
  } : {}
}

resource "aws_api_gateway_method_response" "get_item_200" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  resource_id = aws_api_gateway_resource.item_id[0].id
  http_method = aws_api_gateway_method.get_item[0].http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_item_integration_response" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  resource_id = aws_api_gateway_resource.item_id[0].id
  http_method = aws_api_gateway_method.get_item[0].http_method
  status_code = aws_api_gateway_method_response.get_item_200[0].status_code

  response_templates = !var.enable_vpc_link ? {
    "application/json" = "{\"message\": \"success\", \"itemId\": \"$input.params('itemId')\"}"
  } : {}

  depends_on = [
    aws_api_gateway_integration.get_item_integration
  ]
}

resource "aws_api_gateway_deployment" "rest_deployment" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.items[0].id,
      aws_api_gateway_resource.item_id[0].id,
      aws_api_gateway_method.get_item[0].id,
      aws_api_gateway_integration.get_item_integration[0].id,
      aws_api_gateway_integration_response.get_item_integration_response[0].id,
      data.aws_iam_policy_document.rest_policy[0].json
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration_response.get_item_integration_response
  ]
}

resource "aws_api_gateway_stage" "rest_stage" {
  count         = local.is_rest ? 1 : 0
  rest_api_id   = aws_api_gateway_rest_api.rest_api[0].id
  deployment_id = aws_api_gateway_deployment.rest_deployment[0].id
  stage_name    = local.stage_name

  tags = {
    Name        = "${var.api_name}-${local.stage_name}"
    Environment = var.environment
  }
}

resource "aws_api_gateway_api_key" "key" {
  count       = local.is_rest && var.enable_api_key ? 1 : 0
  name        = "${var.api_name}-api-key"
  description = "Managed API key for ${var.api_name}"
  enabled     = true

  tags = {
    Name        = "${var.api_name}-api-key"
    Environment = var.environment
  }
}

resource "aws_api_gateway_usage_plan" "usage_plan" {
  count       = local.is_rest && var.enable_api_key ? 1 : 0
  name        = "${var.api_name}-usage-plan"
  description = "Usage plan for ${var.api_name}"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest_api[0].id
    stage  = aws_api_gateway_stage.rest_stage[0].stage_name
  }

  quota_settings {
    limit  = 10000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 100
    rate_limit  = 50
  }

  tags = {
    Name        = "${var.api_name}-usage-plan"
    Environment = var.environment
  }
}

resource "aws_api_gateway_usage_plan_key" "main" {
  count         = local.is_rest && var.enable_api_key ? 1 : 0
  key_id        = aws_api_gateway_api_key.key[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.usage_plan[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count       = local.is_rest && var.enable_api_key ? 1 : 0
  name        = "/${var.environment}/${var.api_name}/api_key"
  description = "Secure API Gateway API Key"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.key[0].value

  tags = {
    Name        = "${var.api_name}-api-key-ssm"
    Environment = var.environment
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "trail_name" {
  type        = string
  description = "The name of the CloudTrail trail."
  default     = "organization-audit-trail"
}

variable "bucket_name" {
  type        = string
  description = "Explicit S3 bucket name for CloudTrail logs. If left blank, a dynamic name is generated."
  default     = ""
}

variable "bucket_force_destroy" {
  type        = bool
  description = "Whether to force destroy the S3 bucket even if it contains objects."
  default     = true
}

variable "bucket_versioning_enabled" {
  type        = bool
  description = "Whether to enable versioning on the CloudTrail S3 bucket."
  default     = false
}

variable "kms_deletion_window_in_days" {
  type        = number
  description = "Duration in days after which the KMS key is deleted."
  default     = 30
}

variable "log_retention_days" {
  type        = number
  description = "Number of days to retain logs in CloudWatch Logs."
  default     = 90
}

variable "include_global_service_events" {
  type        = bool
  description = "Whether to include global service events (such as IAM) in the trail."
  default     = true
}

variable "is_multi_region_trail" {
  type        = bool
  description = "Whether the trail applies to all regions."
  default     = true
}

variable "enable_logging" {
  type        = bool
  description = "Whether logging is enabled for the trail."
  default     = true
}

variable "is_organization_trail" {
  type        = bool
  description = "Whether this is an AWS Organizations trail."
  default     = false
}

variable "event_selector_read_write_type" {
  type        = string
  description = "Type of events to log (All, ReadOnly, WriteOnly)."
  default     = "All"
}

variable "include_management_events" {
  type        = bool
  description = "Whether to include management events in the event selector."
  default     = true
}

variable "data_resources" {
  type = list(object({
    type   = string
    values = list(string)
  }))
  description = "Data resources to log data events for (e.g., AWS::S3::Object, AWS::Lambda::Function)."
  default     = []
}

variable "insight_selectors" {
  type        = list(string)
  description = "List of insight types to enable (e.g., ApiCallRateInsight, ApiErrorRateInsight)."
  default     = []
}

variable "enable_sns_topic" {
  type        = bool
  description = "Whether to create and link a dedicated SNS topic for CloudTrail notifications."
  default     = false
}

variable "external_sns_topic_arn" {
  type        = string
  description = "Pre-existing SNS topic ARN to use if enable_sns_topic is false."
  default     = ""
}

variable "decrypt_role_arns" {
  type        = list(string)
  description = "List of IAM role ARNs permitted to decrypt CloudTrail logs using the KMS key."
  default     = []
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

resource "random_string" "bucket_suffix" {
  length  = 8
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
  partition   = data.aws_partition.current.partition
  bucket_name = var.bucket_name != "" ? var.bucket_name : "cloudtrail-logs-${local.account_id}-${local.region}-${random_string.bucket_suffix.result}"
  sns_topic_arn = var.enable_sns_topic ? aws_sns_topic.trail_notifications[0].arn : (
    var.external_sns_topic_arn != "" ? var.external_sns_topic_arn : null
  )
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudTrailEncryptLogs"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowCloudTrailDescribeKey"
    effect = "Allow"
    actions = [
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/cloudtrail/${var.trail_name}"]
    }
  }

  statement {
    sid    = "AllowS3Operations"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }

  dynamic "statement" {
    for_each = length(var.decrypt_role_arns) > 0 ? [1] : []
    content {
      sid    = "AllowDecryptionRoles"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:DescribeKey"
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.decrypt_role_arns
      }
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "Dedicated KMS customer managed key for CloudTrail log and event encryption"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/cloudtrail-${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = var.bucket_force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"]
    }
  }

  statement {
    sid       = "AWSCloudTrailWriteLogs"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.s3_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_logs]
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "/aws/cloudtrail/${var.trail_name}"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_to_cloudwatch" {
  name               = "cloudtrail-cloudwatch-role-${var.trail_name}"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
}

data "aws_iam_policy_document" "cloudtrail_to_cloudwatch" {
  statement {
    sid    = "AWSCloudTrailCreateLogStream"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream"
    ]
    resources = [
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
    ]
  }

  statement {
    sid    = "AWSCloudTrailPutLogEvents"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_to_cloudwatch" {
  name   = "cloudtrail-cloudwatch-policy"
  role   = aws_iam_role.cloudtrail_to_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_to_cloudwatch.json
}

resource "aws_sns_topic" "trail_notifications" {
  count             = var.enable_sns_topic ? 1 : 0
  name              = "cloudtrail-notifications-${var.trail_name}"
  kms_master_key_id = aws_kms_key.cloudtrail.id
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.enable_sns_topic ? 1 : 0

  statement {
    sid       = "AWSCloudTrailSNSPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.trail_notifications[0].arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"]
    }
  }
}

resource "aws_sns_topic_policy" "trail_notifications" {
  count  = var.enable_sns_topic ? 1 : 0
  arn    = aws_sns_topic.trail_notifications[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  sns_topic_name                = local.sns_topic_arn

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_to_cloudwatch.arn

  event_selector {
    read_write_type           = var.event_selector_read_write_type
    include_management_events = var.include_management_events

    dynamic "data_resource" {
      for_each = var.data_resources
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors
    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy.cloudtrail_to_cloudwatch
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_ebs_security" {
  type        = bool
  description = "Global toggle to enable EBS account-level security configurations."
  default     = true
}

variable "enable_ebs_encryption_by_default" {
  type        = bool
  description = "Flag to enable default EBS encryption for the target region."
  default     = true
}

variable "enable_ebs_snapshot_block_public_access" {
  type        = bool
  description = "Flag to enable blocking public access to EBS snapshots."
  default     = true
}

variable "snapshot_block_public_access_state" {
  type        = string
  description = "The state of EBS snapshot public access blocking. Valid values: block-all-sharing, block-new-sharing."
  default     = "block-all-sharing"

  validation {
    condition     = contains(["block-all-sharing", "block-new-sharing"], var.snapshot_block_public_access_state)
    error_message = "The snapshot_block_public_access_state must be either 'block-all-sharing' or 'block-new-sharing'."
  }
}

variable "target_region" {
  type        = string
  description = "Optional AWS region to apply settings to. Defaults to the provider's active region if null."
  default     = null
}

data "aws_region" "current" {}

locals {
  resolved_region = coalesce(var.target_region, data.aws_region.current.name)
}

resource "aws_ebs_encryption_by_default" "default" {
  count   = var.enable_ebs_security && var.enable_ebs_encryption_by_default ? 1 : 0
  enabled = true
}

resource "aws_ebs_snapshot_block_public_access" "default" {
  count = var.enable_ebs_security && var.enable_ebs_snapshot_block_public_access ? 1 : 0
  state = var.snapshot_block_public_access_state
}

output "resolved_region" {
  description = "The AWS region targeted for EBS security configurations."
  value       = local.resolved_region
}

output "ebs_encryption_by_default_enabled" {
  description = "Whether EBS encryption by default is enforced."
  value       = length(aws_ebs_encryption_by_default.default) > 0 ? aws_ebs_encryption_by_default.default[0].enabled : false
}

output "ebs_snapshot_block_public_access_state" {
  description = "The status of EBS snapshot public access blocking."
  value       = length(aws_ebs_snapshot_block_public_access.default) > 0 ? aws_ebs_snapshot_block_public_access.default[0].state : "unmanaged"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  type        = string
  description = "The name of the IAM deployment user"
  default     = "DeploymentUser"
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to all taggable resources"
  default     = {}
}

variable "s3_bucket_arns" {
  type        = list(string)
  description = "List of S3 bucket ARNs to grant deployment permissions to"
  default     = []
}

variable "s3_sub_paths" {
  type        = list(string)
  description = "List of sub-paths within target S3 buckets for object operations"
  default     = ["*"]
}

variable "lambda_function_arns" {
  type        = list(string)
  description = "List of Lambda function ARNs to grant deployment permissions to"
  default     = []
}

locals {
  s3_object_arns = flatten([
    for bucket_arn in var.s3_bucket_arns : [
      for sub_path in var.s3_sub_paths : (
        sub_path == "" ? bucket_arn : (
          sub_path == "*" ? "${bucket_arn}/*" : (
            startswith(sub_path, "/") ? "${bucket_arn}${sub_path}" : "${bucket_arn}/${sub_path}"
          )
        )
      )
    ]
  ])
}

resource "aws_iam_user" "deployment_user" {
  name = var.iam_user_name
  tags = var.tags
}

data "aws_iam_policy_document" "s3_deployment_policy" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  statement {
    sid    = "S3BucketListingAndLocation"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = var.s3_bucket_arns
  }

  statement {
    sid    = "S3ObjectDeploymentActions"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:DeleteObject"
    ]
    resources = local.s3_object_arns
  }
}

resource "aws_iam_policy" "s3_deployment_policy" {
  count       = length(var.s3_bucket_arns) > 0 ? 1 : 0
  name        = "${var.iam_user_name}-s3-deployment-policy"
  description = "Policy granting S3 deployment permissions for ${var.iam_user_name}"
  policy      = data.aws_iam_policy_document.s3_deployment_policy[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "s3_deployment_attachment" {
  count      = length(var.s3_bucket_arns) > 0 ? 1 : 0
  user       = aws_iam_user.deployment_user.name
  policy_arn = aws_iam_policy.s3_deployment_policy[0].arn
}

data "aws_iam_policy_document" "lambda_deployment_policy" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  statement {
    sid    = "LambdaFunctionCodeDeployment"
    effect = "Allow"
    actions = [
      "lambda:UpdateFunctionCode"
    ]
    resources = var.lambda_function_arns
  }
}

resource "aws_iam_policy" "lambda_deployment_policy" {
  count       = length(var.lambda_function_arns) > 0 ? 1 : 0
  name        = "${var.iam_user_name}-lambda-deployment-policy"
  description = "Policy granting Lambda code update permissions for ${var.iam_user_name}"
  policy      = data.aws_iam_policy_document.lambda_deployment_policy[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "lambda_deployment_attachment" {
  count      = length(var.lambda_function_arns) > 0 ? 1 : 0
  user       = aws_iam_user.deployment_user.name
  policy_arn = aws_iam_policy.lambda_deployment_policy[0].arn
}

output "deployment_user_name" {
  description = "Name of the created IAM deployment user"
  value       = aws_iam_user.deployment_user.name
}

output "deployment_user_arn" {
  description = "ARN of the created IAM deployment user"
  value       = aws_iam_user.deployment_user.arn
}

output "s3_deployment_policy_arn" {
  description = "ARN of the attached S3 deployment policy, if created"
  value       = try(aws_iam_policy.s3_deployment_policy[0].arn, null)
}

output "lambda_deployment_policy_arn" {
  description = "ARN of the attached Lambda deployment policy, if created"
  value       = try(aws_iam_policy.lambda_deployment_policy[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "custom_bucket_name" {
  type        = string
  description = "Optional custom name for the S3 static website bucket."
  default     = ""
}

variable "domain_name" {
  type        = string
  description = "Optional custom domain name for the CloudFront distribution."
  default     = ""
}

variable "route53_zone_id" {
  type        = string
  description = "Route 53 hosted zone ID for the custom domain. Required if domain_name is specified."
  default     = ""

  validation {
    condition     = var.domain_name == "" || var.route53_zone_id != ""
    error_message = "The route53_zone_id variable must be provided when domain_name is specified."
  }
}

variable "enable_versioning" {
  type        = bool
  description = "Enable S3 bucket versioning."
  default     = false
}

variable "enable_www_alias" {
  type        = bool
  description = "Enable www subdomain alias and wildcard SAN in ACM certificate."
  default     = false
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

locals {
  use_custom_domain = var.domain_name != ""
  resolved_bucket_name = coalesce(
    var.custom_bucket_name != "" ? var.custom_bucket_name : null,
    var.domain_name != "" ? replace(var.domain_name, ".", "-") : null,
    "webapp-template-${random_id.bucket_suffix.hex}"
  )
  aliases = local.use_custom_domain ? (
    var.enable_www_alias ? [var.domain_name, "www.${var.domain_name}"] : [var.domain_name]
  ) : []
  s3_origin_id = "S3-${local.resolved_bucket_name}"
}

data "aws_iam_policy_document" "kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudFrontServicePrincipal"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudfront_distribution.cdn.arn]
    }
  }
}

resource "aws_kms_key" "s3_key" {
  description             = "Customer managed KMS key for static website S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_policy.json
}

resource "aws_kms_alias" "s3_key_alias" {
  name          = "alias/${local.resolved_bucket_name}-key"
  target_key_id = aws_kms_key.s3_key.key_id
}

resource "aws_s3_bucket" "website_bucket" {
  bucket        = local.resolved_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "website_bucket" {
  bucket = aws_s3_bucket.website_bucket.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "website_bucket" {
  bucket = aws_s3_bucket.website_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "website_bucket" {
  bucket = aws_s3_bucket.website_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "website_bucket" {
  bucket = aws_s3_bucket.website_bucket.id
  policy = data.aws_iam_policy_document.s3_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.website_bucket]
}

data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid       = "AllowCloudFrontServicePrincipalReadOnly"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.website_bucket.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudfront_distribution.cdn.arn]
    }
  }
}

resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "${local.resolved_bucket_name}-oac"
  description                       = "OAC for ${local.resolved_bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_wafv2_web_acl" "cloudfront_waf" {
  name        = "${local.resolved_bucket_name}-waf"
  description = "CloudFront WAF for static website distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${replace(local.resolved_bucket_name, "-", "")}WafMetric"
    sampled_requests_enabled   = true
  }
}

data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

resource "aws_acm_certificate" "cert" {
  count = local.use_custom_domain ? 1 : 0

  domain_name               = var.domain_name
  subject_alternative_names = var.enable_www_alias ? ["*.${var.domain_name}"] : []
  validation_method         = "DNS"

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = local.use_custom_domain ? {
    for dvo in aws_acm_certificate.cert[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 60
  type            = each.value.type
  zone_id         = var.route53_zone_id
}

resource "aws_acm_certificate_validation" "cert" {
  count = local.use_custom_domain ? 1 : 0

  certificate_arn         = aws_acm_certificate.cert[0].arn
  validation_record_fqdns = [for r in aws_route53_record.cert_validation : r.fqdn]
}

resource "aws_cloudfront_distribution" "cdn" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_100"
  aliases             = local.aliases
  web_acl_id          = aws_wafv2_web_acl.cloudfront_waf.arn

  origin {
    domain_name              = aws_s3_bucket.website_bucket.bucket_regional_domain_name
    origin_id                = local.s3_origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
  }

  custom_error_response {
    error_caching_min_ttl = 10
    error_code            = 403
    response_code         = 404
    response_page_path    = "/index.html"
  }

  custom_error_response {
    error_caching_min_ttl = 10
    error_code            = 404
    response_code         = 404
    response_page_path    = "/index.html"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = !local.use_custom_domain
    acm_certificate_arn            = local.use_custom_domain ? aws_acm_certificate_validation.cert[0].certificate_arn : null
    ssl_support_method             = local.use_custom_domain ? "sni-only" : null
    minimum_protocol_version       = local.use_custom_domain ? "TLSv1.2_2021" : "TLSv1"
  }
}

resource "aws_route53_record" "apex" {
  count = local.use_custom_domain ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.cdn.domain_name
    zone_id                = aws_cloudfront_distribution.cdn.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "www" {
  count = local.use_custom_domain && var.enable_www_alias ? 1 : 0

  zone_id = var.route53_zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.cdn.domain_name
    zone_id                = aws_cloudfront_distribution.cdn.hosted_zone_id
    evaluate_target_health = false
  }
}

output "s3_bucket_name" {
  description = "Name of the static website S3 bucket."
  value       = aws_s3_bucket.website_bucket.id
}

output "s3_bucket_arn" {
  description = "ARN of the static website S3 bucket."
  value       = aws_s3_bucket.website_bucket.arn
}

output "cloudfront_distribution_id" {
  description = "ID of the CloudFront distribution."
  value       = aws_cloudfront_distribution.cdn.id
}

output "cloudfront_distribution_domain_name" {
  description = "Domain name of the CloudFront distribution."
  value       = aws_cloudfront_distribution.cdn.domain_name
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key for S3."
  value       = aws_kms_key.s3_key.arn
}

output "waf_web_acl_arn" {
  description = "ARN of the CloudFront WAFv2 Web ACL."
  value       = aws_wafv2_web_acl.cloudfront_waf.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cidr_base" {
  type        = string
  description = "Base CIDR prefix for the VPC (e.g. 10.20)"
  default     = "10.20"
}

variable "availability_zones" {
  type        = string
  description = "Comma-separated list of active availability zone names"
  default     = "us-east-1a,us-east-1b,us-east-1c"
}

variable "multi_az_nat_gateway" {
  type        = number
  description = "Flag to deploy multi-AZ NAT Gateways (1 to enable, 0 to disable)"
  default     = 1
}

variable "single_nat_gateway" {
  type        = number
  description = "Flag to deploy a single NAT Gateway across all AZs (1 to enable, 0 to disable)"
  default     = 0
}

variable "enable_s3_vpc_endpoint" {
  type        = bool
  description = "Controls whether an S3 VPC Gateway Endpoint is provisioned"
  default     = true
}

variable "default_tags" {
  type        = map(string)
  description = "Default global tags to apply to VPC network resources"
  default = {
    "Author"     = "Fairwinds"
    "Managed By" = "Terraform"
  }
}

locals {
  az_list = split(",", var.availability_zones)

  admin_cidr_suffixes      = [".0.0/21", ".8.0/21", ".16.0/21"]
  public_cidr_suffixes     = [".32.0/21", ".40.0/21", ".48.0/21"]
  private_prod_suffixes    = [".64.0/21", ".72.0/21", ".80.0/21"]
  private_working_suffixes = [".96.0/21", ".104.0/21", ".112.0/21"]

  private_rt_names = ["private_az1", "private_az2", "private_az3"]

  nat_gateway_count = var.multi_az_nat_gateway == 1 ? 3 : (var.single_nat_gateway == 1 ? 1 : 0)
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.cidr_base}.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.default_tags,
    {
      Name = "main"
    }
  )
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.default_tags,
    {
      Name = "vpc"
    }
  )
}

resource "aws_subnet" "admin" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.cidr_base}${local.admin_cidr_suffixes[count.index]}"
  availability_zone       = trimspace(local.az_list[count.index])
  map_public_ip_on_launch = false

  tags = merge(
    var.default_tags,
    {
      Name = "admin-${trimspace(local.az_list[count.index])}"
      Tier = "Admin"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.cidr_base}${local.public_cidr_suffixes[count.index]}"
  availability_zone       = trimspace(local.az_list[count.index])
  map_public_ip_on_launch = false

  tags = merge(
    var.default_tags,
    {
      Name = "public-${trimspace(local.az_list[count.index])}"
      Tier = "Public"
    }
  )
}

resource "aws_subnet" "private_production" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.cidr_base}${local.private_prod_suffixes[count.index]}"
  availability_zone       = trimspace(local.az_list[count.index])
  map_public_ip_on_launch = false

  tags = merge(
    var.default_tags,
    {
      Name = "private-prod-${trimspace(local.az_list[count.index])}"
      Tier = "PrivateProduction"
    }
  )
}

resource "aws_subnet" "private_working" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.cidr_base}${local.private_working_suffixes[count.index]}"
  availability_zone       = trimspace(local.az_list[count.index])
  map_public_ip_on_launch = false

  tags = merge(
    var.default_tags,
    {
      Name = "private-working-${trimspace(local.az_list[count.index])}"
      Tier = "PrivateWorking"
    }
  )
}

resource "aws_eip" "nat" {
  count  = local.nat_gateway_count
  domain = "vpc"

  tags = merge(
    var.default_tags,
    {
      Name = "nat-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_nat_gateway" "nat" {
  count         = local.nat_gateway_count
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.default_tags,
    {
      Name = "nat-${trimspace(local.az_list[count.index])}"
    }
  )

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(
    var.default_tags,
    {
      Name = "public"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = local.nat_gateway_count > 0 ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.nat[count.index % local.nat_gateway_count].id
    }
  }

  tags = merge(
    var.default_tags,
    {
      Name = local.private_rt_names[count.index]
    }
  )
}

resource "aws_route_table_association" "admin" {
  count          = 3
  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_production" {
  count          = 3
  subnet_id      = aws_subnet.private_production[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_working" {
  count          = 3
  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

data "aws_region" "current" {}

resource "aws_vpc_endpoint" "s3" {
  count             = var.enable_s3_vpc_endpoint ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource  = "*"
      }
    ]
  })

  tags = merge(
    var.default_tags,
    {
      Name = "s3-gateway-endpoint"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy infrastructure into."
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

variable "environment" {
  type        = string
  description = "Deployment environment name."
  default     = "production"
}

variable "github_organization" {
  type        = string
  description = "GitHub organization or account name permitted to assume the CI/CD deployment role."
  default     = "my-org"
}

variable "app_port" {
  type        = number
  description = "Port exposed by the web backend container application."
  default     = 80
}

variable "health_check_path" {
  type        = string
  description = "HTTP health check request path for the Application Load Balancer target group."
  default     = "/"
}

variable "db_name" {
  type        = string
  description = "Name of the default PostgreSQL database."
  default     = "mydb"
}

variable "db_username" {
  type        = string
  description = "Master username for PostgreSQL database bootstrapping."
  default     = "postgres"
}

variable "db_password" {
  type        = string
  description = "Master password for PostgreSQL database bootstrapping."
  default     = "postgres"
  sensitive   = true
}

locals {
  name_prefix = "${var.environment}-backend"
  vpc_cidr    = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-public-subnet-${count.index + 1}"
    Environment = var.environment
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "${local.name_prefix}-private-subnet-${count.index + 1}"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpce-sg"
  description = "Security group for private interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound HTTPS from within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound to within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-vpce-sg"
    Environment = var.environment
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name        = "${local.name_prefix}-vpce-ecr-api"
    Environment = var.environment
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name        = "${local.name_prefix}-vpce-ecr-dkr"
    Environment = var.environment
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.logs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name        = "${local.name_prefix}-vpce-logs"
    Environment = var.environment
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name        = "${local.name_prefix}-vpce-s3"
    Environment = var.environment
  }
}

resource "aws_ecr_repository" "app" {
  name                 = "${local.name_prefix}-app"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Name        = "${local.name_prefix}-ecr"
    Environment = var.environment
  }
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name  = "internal.backend.local"
    organization = "Internal Web Platform"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth"
  ]
}

resource "aws_acm_certificate" "alb" {
  private_key      = tls_private_key.alb.private_key_pem
  certificate_body = tls_self_signed_cert.alb.cert_pem

  tags = {
    Name        = "${local.name_prefix}-alb-cert"
    Environment = var.environment
  }
}

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for internal Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP ingress from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS ingress from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic strictly restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-alb-sg"
    Environment = var.environment
  }
}

resource "aws_security_group" "ecs" {
  name        = "${local.name_prefix}-ecs-tasks-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow traffic from ALB on all ports"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound traffic strictly restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-ecs-sg"
    Environment = var.environment
  }
}

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Security group for RDS PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL ingress strictly from ECS tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "Outbound traffic strictly restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-rds-sg"
    Environment = var.environment
  }
}

resource "aws_lb" "internal" {
  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true

  tags = {
    Name        = "${local.name_prefix}-internal-alb"
    Environment = var.environment
  }
}

resource "aws_lb_target_group" "app" {
  name        = "${local.name_prefix}-tg"
  port        = var.app_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    path                = var.health_check_path
    protocol            = "HTTP"
    port                = "traffic-port"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-399"
  }

  tags = {
    Name        = "${local.name_prefix}-tg"
    Environment = var.environment
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_db_subnet_group" "rds" {
  name        = "${local.name_prefix}-db-subnet-group"
  subnet_ids  = aws_subnet.private[*].id
  description = "RDS DB subnet group spanning private subnets"

  tags = {
    Name        = "${local.name_prefix}-db-subnet-group"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "${local.name_prefix}-rds-credentials"
  description             = "PostgreSQL master database credentials"
  recovery_window_in_days = 0

  tags = {
    Name        = "${local.name_prefix}-rds-secret"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
    database = var.db_name
  })
}

resource "aws_db_instance" "postgres" {
  identifier                  = "${local.name_prefix}-db"
  allocated_storage           = 20
  max_allocated_storage       = 50
  engine                      = "postgres"
  engine_version              = "15"
  instance_class              = "db.t4g.micro"
  db_name                     = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["database"]
  username                    = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["username"]
  password                    = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["password"]
  db_subnet_group_name        = aws_db_subnet_group.rds.name
  vpc_security_group_ids      = [aws_security_group.rds.id]
  storage_encrypted           = true
  multi_az                    = false
  publicly_accessible         = false
  skip_final_snapshot         = true
  allow_major_version_upgrade = false
  auto_minor_version_upgrade  = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "${local.name_prefix}-postgres"
    Environment = var.environment
  }
}

resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/${local.name_prefix}"
  retention_in_days = 30

  tags = {
    Name        = "${local.name_prefix}-logs"
    Environment = var.environment
  }
}

resource "aws_iam_role" "ecs_execution_role" {
  name = "${local.name_prefix}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "${local.name_prefix}-execution-role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "ecs_execution_standard" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task_role" {
  name = "${local.name_prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "${local.name_prefix}-task-role"
    Environment = var.environment
  }
}

resource "aws_iam_policy" "ecs_task_policy" {
  name        = "${local.name_prefix}-task-policy"
  description = "Policy for application container tasks to access specific AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect   = "Allow"
        Resource = aws_secretsmanager_secret.db_credentials.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_policy_attachment" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = aws_iam_policy.ecs_task_policy.arn
}

resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name        = "${local.name_prefix}-cluster"
    Environment = var.environment
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name = aws_ecs_cluster.main.name

  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base              = 0
  }

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
    base              = 0
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${local.name_prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution_role.arn
  task_role_arn            = aws_iam_role.ecs_task_role.arn

  container_definitions = jsonencode([
    {
      name      = "backend"
      image     = "public.ecr.aws/docker/library/nginx:latest"
      essential = true

      portMappings = [
        {
          containerPort = var.app_port
          hostPort      = var.app_port
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "POSTGRES_HOST"
          value = aws_db_instance.postgres.address
        },
        {
          name  = "POSTGRES_PORT"
          value = tostring(aws_db_instance.postgres.port)
        },
        {
          name  = "POSTGRES_DB"
          value = var.db_name
        },
        {
          name  = "POSTGRES_USER"
          value = var.db_username
        },
        {
          name  = "POSTGRES_PASSWORD"
          value = var.db_password
        },
        {
          name  = "DATABASE_URL"
          value = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.postgres.address}:${aws_db_instance.postgres.port}/${var.db_name}"
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "backend"
        }
      }
    }
  ])

  tags = {
    Name        = "${local.name_prefix}-task-def"
    Environment = var.environment
  }
}

resource "aws_ecs_service" "app" {
  name            = "${local.name_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base              = 0
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
    base              = 0
  }

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "backend"
    container_port   = var.app_port
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  tags = {
    Name        = "${local.name_prefix}-service"
    Environment = var.environment
  }

  depends_on = [
    aws_lb_listener.https,
    aws_iam_role_policy_attachment.ecs_execution_standard
  ]
}

resource "aws_appautoscaling_target" "ecs" {
  service_namespace  = "ecs"
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  min_capacity       = 2
  max_capacity       = 4
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "${local.name_prefix}-cpu-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    target_value       = 70.0
    scale_in_cooldown  = 60
    scale_out_cooldown = 60
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "${local.name_prefix}-memory-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
    target_value       = 70.0
    scale_in_cooldown  = 60
    scale_out_cooldown = 60
  }
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1", "1c58a3a8518e8759bf075b76b750d4f8d2649e30"]

  tags = {
    Name        = "${local.name_prefix}-github-oidc"
    Environment = var.environment
  }
}

resource "aws_iam_role" "github_actions" {
  name = "${local.name_prefix}-github-actions-deployer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "token.actions.githubusercontent.com:aud" = "sts.amazonaws.com"
          }
          StringLike = {
            "token.actions.githubusercontent.com:sub" = "repo:${var.github_organization}/*:*"
          }
        }
      }
    ]
  })

  tags = {
    Name        = "${local.name_prefix}-github-actions-role"
    Environment = var.environment
  }
}

resource "aws_iam_policy" "github_actions_cicd" {
  name        = "${local.name_prefix}-cicd-policy"
  description = "Permissions for GitHub Actions to build/push images and deploy to ECS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ECRAuth"
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken"]
        Resource = "*"
      },
      {
        Sid    = "ECRPushPull"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload"
        ]
        Resource = aws_ecr_repository.app.arn
      },
      {
        Sid    = "ECSDeployment"
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DeregisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:ListTaskDefinitions",
          "ecs:DescribeServices",
          "ecs:UpdateService"
        ]
        Resource = "*"
      },
      {
        Sid    = "IAMPassRole"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          aws_iam_role.ecs_execution_role.arn,
          aws_iam_role.ecs_task_role.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "github_actions_cicd_attach" {
  role       = aws_iam_role.github_actions.name
  policy_arn = aws_iam_policy.github_actions_cicd.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_tag" {
  type        = string
  description = "Cluster identifier tag used for naming and resource tagging"
  default     = "default"
}

variable "enable_key_rotation" {
  type        = bool
  description = "Enable automatic annual key rotation for the Vault KMS key"
  default     = false
}

variable "machine_roles" {
  type        = map(set(string))
  description = "Map of machine role names to sets of policy identifiers (e.g. read-tags, vault-kms, nomad-keys, consul-keys, vault-keys, client-keys)"
  default     = {}
}

locals {
  secret_names = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token"
  ])

  policy_arns = {
    "read-tags"   = aws_iam_policy.read_tags.arn
    "vault-kms"   = aws_iam_policy.vault_kms.arn
    "client-keys" = aws_iam_policy.client_keys.arn
    "nomad-keys"  = aws_iam_policy.nomad_keys.arn
    "consul-keys" = aws_iam_policy.consul_keys.arn
    "vault-keys"  = aws_iam_policy.vault_keys.arn
  }

  role_policy_attachments = flatten([
    for role_name, policies in var.machine_roles : [
      for policy_key in policies : {
        role_name  = role_name
        policy_key = policy_key
        policy_arn = lookup(local.policy_arns, policy_key, null)
      }
      if contains(keys(local.policy_arns), policy_key)
    ]
  ])
}

resource "aws_kms_key" "vault" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  deletion_window_in_days = 30
  enable_key_rotation     = var.enable_key_rotation

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_kms_alias" "vault" {
  name          = "alias/resinstack-vault-seal-${var.cluster_tag}"
  target_key_id = aws_kms_key.vault.key_id
}

resource "aws_secretsmanager_secret" "hashistack" {
  for_each = local.secret_names

  name                    = "resinstack-${each.key}-${var.cluster_tag}"
  recovery_window_in_days = 0

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_policy" "vault_kms" {
  name        = "resinstack-vault-kms-${var.cluster_tag}"
  description = "Allows unsealing Vault via AWS KMS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VaultKMSUnseal"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.vault.arn
      }
    ]
  })
}

resource "aws_iam_policy" "read_tags" {
  name        = "ResinStackReadTags"
  description = "Allows describing EC2 instances for cluster auto-discovery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EC2DescribeInstances"
        Effect   = "Allow"
        Action   = "ec2:DescribeInstances"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "client_keys" {
  name        = "resinstack-client-keys-${var.cluster_tag}"
  description = "Allows retrieving client secret values from Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ClientSecretsAccess"
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = [
          aws_secretsmanager_secret.hashistack["consul-agent-token"].arn,
          aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
          aws_secretsmanager_secret.hashistack["nomad-client-consul-token"].arn
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "nomad_keys" {
  name        = "resinstack-nomad-keys-${var.cluster_tag}"
  description = "Allows retrieving Nomad server secret values from Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "NomadServerSecretsAccess"
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = [
          aws_secretsmanager_secret.hashistack["consul-agent-token"].arn,
          aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
          aws_secretsmanager_secret.hashistack["nomad-gossip-key"].arn,
          aws_secretsmanager_secret.hashistack["nomad-server-consul-token"].arn,
          aws_secretsmanager_secret.hashistack["nomad-vault-token"].arn
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "consul_keys" {
  name        = "resinstack-consul-keys-${var.cluster_tag}"
  description = "Allows retrieving Consul server secret values from Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConsulServerSecretsAccess"
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = [
          aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "vault_keys" {
  name        = "resinstack-vault-keys-${var.cluster_tag}"
  description = "Allows retrieving Vault server secret values from Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VaultServerSecretsAccess"
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = [
          aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
          aws_secretsmanager_secret.hashistack["vault-consul-token"].arn
        ]
      }
    ]
  })
}

resource "aws_iam_role" "machine" {
  for_each = var.machine_roles

  name                 = "resinstack-${each.key}-${var.cluster_tag}"
  max_session_duration = 43200

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_instance_profile" "machine" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.machine[each.key].name

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_role_policy_attachment" "machine" {
  for_each = {
    for item in local.role_policy_attachments : "${item.role_name}.${item.policy_key}" => item
  }

  role       = aws_iam_role.machine[each.value.role_name].name
  policy_arn = each.value.policy_arn
}

output "vault_kms_key_id" {
  description = "Vault KMS auto-unseal key ID"
  value       = aws_kms_key.vault.key_id
}

output "vault_kms_key_arn" {
  description = "Vault KMS auto-unseal key ARN"
  value       = aws_kms_key.vault.arn
}

output "secret_names" {
  description = "Map of HashiStack secret logical keys to AWS Secrets Manager secret names"
  value       = { for k, v in aws_secretsmanager_secret.hashistack : k => v.name }
}

output "secret_arns" {
  description = "Map of HashiStack secret logical keys to AWS Secrets Manager secret ARNs"
  value       = { for k, v in aws_secretsmanager_secret.hashistack : k => v.arn }
}

output "machine_role_names" {
  description = "Map of machine role keys to their IAM role names"
  value       = { for k, v in aws_iam_role.machine : k => v.name }
}

output "machine_instance_profile_names" {
  description = "Map of machine role keys to their IAM instance profile names"
  value       = { for k, v in aws_iam_instance_profile.machine : k => v.name }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_prefix" {
  type        = string
  default     = "elluis_codes_limited_network"
  description = "Prefix used for naming and tagging network resources."
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "64.0.0.0/16"
  az_subnet_map = {
    az1 = {
      az_name        = data.aws_availability_zones.available.names[0]
      public_offset  = 11
      private_offset = 111
    }
    az2 = {
      az_name        = data.aws_availability_zones.available.names[1]
      public_offset  = 22
      private_offset = 122
    }
    az3 = {
      az_name        = data.aws_availability_zones.available.names[2]
      public_offset  = 33
      private_offset = 133
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment_prefix}-vpc"
    Environment = var.environment_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment_prefix}-igw"
    Environment = var.environment_prefix
  }
}

resource "aws_subnet" "public" {
  for_each = local.az_subnet_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value.public_offset)
  availability_zone       = each.value.az_name
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment_prefix}-public-subnet-${each.key}"
    Environment = var.environment_prefix
    Type        = "public"
  }
}

resource "aws_subnet" "private" {
  for_each = local.az_subnet_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value.private_offset)
  availability_zone       = each.value.az_name
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment_prefix}-private-subnet-${each.key}"
    Environment = var.environment_prefix
    Type        = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${var.environment_prefix}-public-rt"
    Environment = var.environment_prefix
  }
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  for_each = local.az_subnet_map

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name        = "${var.environment_prefix}-eip-${each.key}"
    Environment = var.environment_prefix
  }
}

resource "aws_nat_gateway" "main" {
  for_each = local.az_subnet_map

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = {
    Name        = "${var.environment_prefix}-nat-${each.key}"
    Environment = var.environment_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  for_each = local.az_subnet_map

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  lifecycle {
    ignore_changes = [route]
  }

  tags = {
    Name        = "${var.environment_prefix}-private-rt-${each.key}"
    Environment = var.environment_prefix
  }
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be provisioned."
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

variable "creation_token" {
  type        = string
  description = "Unique name used as reference when creating the Elastic File System to ensure idempotent file system creation."
  default     = "test-efs"
}

variable "performance_mode" {
  type        = string
  description = "The file system performance mode. Can be either generalPurpose or maxIO."
  default     = "generalPurpose"
}

variable "throughput_mode" {
  type        = string
  description = "Throughput mode for the file system. Valid values: bursting, provisioned, or elastic."
  default     = "bursting"
}

variable "provisioned_throughput_in_mibps" {
  type        = number
  description = "The throughput, measured in MiB/s, that you want to provision for a file system. Only applicable when throughput_mode is provisioned."
  default     = null
}

variable "transition_to_ia" {
  type        = string
  description = "Indicates how long it takes to transition files to the IA storage class. Valid values: AFTER_1_DAY, AFTER_7_DAYS, AFTER_14_DAYS, AFTER_30_DAYS, AFTER_60_DAYS, AFTER_90_DAYS."
  default     = "AFTER_30_DAYS"
}

variable "subnet_ids" {
  type        = list(string)
  description = "List of subnet IDs to deploy EFS mount targets into. If empty, greenfield VPC subnets will be used."
  default     = []
}

variable "security_group_ids" {
  type        = list(string)
  description = "List of security group IDs to assign to the EFS mount targets. If empty, the dedicated default security group will be used."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to all resources."
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

locals {
  vpc_cidr = "10.0.0.0/16"
  mount_subnets = length(var.subnet_ids) > 0 ? {
    for idx, id in var.subnet_ids : tostring(idx) => id
    } : {
    "a" = aws_subnet.private_a.id
    "b" = aws_subnet.private_b.id
  }
  target_security_group_ids = length(var.security_group_ids) > 0 ? var.security_group_ids : [
    aws_security_group.efs_mount_target.id
  ]
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.tags,
    {
      Name = "${var.creation_token}-vpc"
    }
  )
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(
    var.tags,
    {
      Name = "${var.creation_token}-private-a"
    }
  )
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(
    var.tags,
    {
      Name = "${var.creation_token}-private-b"
    }
  )
}

resource "aws_security_group" "efs_mount_target" {
  name        = "${var.creation_token}-mount-target-sg"
  description = "Security group for EFS mount targets allowing inbound NFS traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS inbound from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "NFS outbound response traffic within VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.creation_token}-mount-target-sg"
    }
  )
}

resource "aws_kms_key" "efs" {
  description             = "KMS key for Amazon EFS file system encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEFSUsage"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
            "kms:ViaService"    = "elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "${var.creation_token}-kms-key"
    }
  )
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${var.creation_token}-key"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "shared" {
  creation_token                  = var.creation_token
  encrypted                       = true
  kms_key_id                      = aws_kms_key.efs.arn
  performance_mode                = var.performance_mode
  throughput_mode                 = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null

  lifecycle_policy {
    transition_to_ia = var.transition_to_ia
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(
    var.tags,
    {
      Name = var.creation_token
    }
  )
}

resource "aws_efs_mount_target" "target" {
  for_each = local.mount_subnets

  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = each.value
  security_groups = local.target_security_group_ids
}

output "file_system_id" {
  description = "The ID of the provisioned EFS file system."
  value       = aws_efs_file_system.shared.id
}

output "file_system_arn" {
  description = "The ARN of the provisioned EFS file system."
  value       = aws_efs_file_system.shared.arn
}

output "file_system_dns_name" {
  description = "The DNS name of the provisioned EFS file system."
  value       = aws_efs_file_system.shared.dns_name
}

output "kms_key_arn" {
  description = "The ARN of the dedicated KMS key used to encrypt the EFS file system."
  value       = aws_kms_key.efs.arn
}

output "mount_target_ids" {
  description = "Map of mount target keys to their corresponding EFS mount target IDs."
  value       = { for k, v in aws_efs_mount_target.target : k => v.id }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  type        = string
  description = "The name of the IAM user for cert-manager"
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  type        = string
  description = "The Route 53 hosted zone ID for cert-manager DNS01 challenges"
  default     = "*"
}

resource "aws_iam_user" "cert_manager" {
  name = var.iam_user_name
  path = "/"

  tags = {
    Name = var.iam_user_name
  }
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
}

resource "aws_ssm_parameter" "access_key_id" {
  name        = "/cert-manager/access-key"
  description = "AWS IAM Access Key ID for cert-manager"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.id

  tags = {
    Name = "/cert-manager/access-key"
  }
}

resource "aws_ssm_parameter" "secret_access_key" {
  name        = "/cert-manager/secret-key"
  description = "AWS IAM Secret Access Key for cert-manager"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.secret

  tags = {
    Name = "/cert-manager/secret-key"
  }
}

data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    sid       = "GetChangeDetails"
    effect    = "Allow"
    actions   = ["route53:GetChange"]
    resources = ["arn:aws:route53:::change/*"]
  }

  statement {
    sid    = "ManageHostedZoneRecords"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets",
    ]
    resources = [
      var.hosted_zone_id == "*" ? "arn:aws:route53:::hostedzone/*" : "arn:aws:route53:::hostedzone/${var.hosted_zone_id}"
    ]
  }

  statement {
    sid       = "ListHostedZones"
    effect    = "Allow"
    actions   = ["route53:ListHostedZonesByName"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cert_manager_route53" {
  name        = "${var.iam_user_name}-route53"
  description = "IAM policy for cert-manager Route 53 DNS-01 ACME challenges"
  policy      = data.aws_iam_policy_document.cert_manager_route53.json

  tags = {
    Name = "${var.iam_user_name}-route53"
  }
}

output "iam_user_arn" {
  description = "The ARN of the IAM user created for cert-manager"
  value       = aws_iam_user.cert_manager.arn
}

output "iam_policy_arn" {
  description = "The ARN of the Route 53 IAM policy"
  value       = aws_iam_policy.cert_manager_route53.arn
}

output "access_key_ssm_parameter_name" {
  description = "The SSM Parameter Store name for the IAM Access Key ID"
  value       = aws_ssm_parameter.access_key_id.name
}

output "secret_key_ssm_parameter_name" {
  description = "The SSM Parameter Store name for the IAM Secret Access Key"
  value       = aws_ssm_parameter.secret_access_key.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "primary_region" {
  type        = string
  description = "The primary AWS region for GuardDuty and main resources."
  default     = "us-east-1"
}

variable "replica_region" {
  type        = string
  description = "The secondary AWS region for cross-region S3 replication."
  default     = "us-west-2"
}

variable "enable_guardduty" {
  type        = bool
  description = "Flag to enable or disable the GuardDuty detector."
  default     = true
}

variable "finding_publishing_frequency" {
  type        = string
  description = "Frequency of notifications for updated findings (FIFTEEN_MINUTES, ONE_HOUR, SIX_HOURS)."
  default     = "FIFTEEN_MINUTES"
}

variable "enable_s3_logs" {
  type        = bool
  description = "Enable S3 protection in GuardDuty."
  default     = true
}

variable "enable_kubernetes_audit_logs" {
  type        = bool
  description = "Enable Kubernetes audit logs in GuardDuty."
  default     = true
}

variable "enable_malware_protection" {
  type        = bool
  description = "Enable EC2 Malware Protection in GuardDuty."
  default     = true
}

variable "ebs_snapshot_retention" {
  type        = bool
  description = "Set EBS snapshot preservation on malware detection to RETENTION_WITH_FINDING if true, otherwise NO_RETENTION."
  default     = false
}

variable "enable_publishing_destination" {
  type        = bool
  description = "Flag to enable exporting GuardDuty findings to the primary S3 bucket."
  default     = true
}

variable "ip_sets" {
  type = map(object({
    activate = bool
    format   = string
    content  = string
  }))
  description = "Map of custom IP sets to create and associate with the GuardDuty detector."
  default = {
    trusted_ips = {
      activate = true
      format   = "TXT"
      content  = "10.0.0.0/8\n192.168.0.0/16\n"
    }
  }
}

variable "threat_intel_sets" {
  type = map(object({
    activate = bool
    format   = string
    content  = string
  }))
  description = "Map of threat intelligence sets to create and associate with the GuardDuty detector."
  default = {
    known_malicious = {
      activate = true
      format   = "TXT"
      content  = "198.51.100.1\n203.0.113.5\n"
    }
  }
}

variable "finding_filters" {
  type = map(object({
    action      = string
    rank        = number
    description = string
    criterion = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(string)
      greater_than_or_equal = optional(string)
      less_than             = optional(string)
      less_than_or_equal    = optional(string)
    }))
  }))
  description = "Custom finding filters to create in GuardDuty."
  default = {
    archive_low_severity = {
      action      = "ARCHIVE"
      rank        = 1
      description = "Filter and archive low severity informational findings"
      criterion = [
        {
          field     = "severity"
          less_than = "4"
        }
      ]
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id            = data.aws_caller_identity.current.account_id
  primary_region_name   = data.aws_region.current.name
  partition_name        = data.aws_partition.current.partition
  snapshot_preservation = var.ebs_snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"
  guardduty_slr_arn     = "arn:${local.partition_name}:iam::${local.account_id}:role/aws-service-role/guardduty.amazonaws.com/AWSServiceRoleForAmazonGuardDuty"
}

resource "terraform_data" "clean_existing_detector" {
  provisioner "local-exec" {
    command = <<-EOT
      for id in $(aws guardduty list-detectors --region ${var.primary_region} --query 'DetectorIds[]' --output text 2>/dev/null); do
        if [ -n "$id" ] && [ "$id" != "None" ]; then
          aws guardduty delete-detector --region ${var.primary_region} --detector-id "$id" || true
        fi
      done
    EOT
  }
}

resource "aws_kms_key" "primary" {
  description             = "Primary multi-region KMS key for GuardDuty findings export, threat intel sets, and access logs"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  multi_region            = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition_name}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowGuardDutyKeyAccess"
        Effect = "Allow"
        Principal = {
          AWS     = local.guardduty_slr_arn
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServerAccessLogging"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowS3ReplicationDecryption"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.s3_replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "primary" {
  name_prefix   = "alias/gd-primary-"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_replica_key" "replica" {
  provider                = aws.replica
  description             = "Secondary KMS replica key for GuardDuty cross-region S3 replication"
  primary_key_arn         = aws_kms_key.primary.arn
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootManagementReplica"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition_name}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ReplicationEncryption"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.s3_replication.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name_prefix   = "alias/gd-replica-"
  target_key_id = aws_kms_replica_key.replica.key_id
}

resource "aws_s3_bucket" "logging" {
  bucket_prefix = "gd-export-logging-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    bucket_key_enabled = true
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "logging" {
  bucket = aws_s3_bucket.logging.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsPolicy"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.logging.arn}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.primary.arn
          }
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "replica" {
  provider      = aws.replica
  bucket_prefix = "gd-export-replica-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_replica_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  name_prefix = "gd-s3-rep-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "s3_replication" {
  name_prefix = "gd-s3-rep-policy-"
  description = "Allows S3 replication with RTC and KMS encryption across regions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GetSourceBucketReplicationConfig"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.primary.arn
      },
      {
        Sid    = "GetSourceObjectsForReplication"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.primary.arn}/*"
      },
      {
        Sid    = "ReplicateDestinationObjects"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.replica.arn}/*"
      },
      {
        Sid    = "DecryptSourceKMS"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.primary.arn
      },
      {
        Sid    = "EncryptDestinationKMS"
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = aws_kms_replica_key.replica.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

resource "aws_s3_bucket" "primary" {
  bucket_prefix = "gd-export-primary-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "primary" {
  bucket        = aws_s3_bucket.primary.id
  target_bucket = aws_s3_bucket.logging.id
  target_prefix = "primary-bucket-logs/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGuardDutyBucketAccess"
        Effect = "Allow"
        Principal = {
          AWS     = local.guardduty_slr_arn
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.primary.arn
      },
      {
        Sid    = "AllowGuardDutyFindingsAndListsAccess"
        Effect = "Allow"
        Principal = {
          AWS     = local.guardduty_slr_arn
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "${aws_s3_bucket.primary.arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica
  ]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "GuardDutyExportRTCReplication"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Disabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.replica.arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

resource "aws_guardduty_detector" "primary" {
  depends_on                   = [terraform_data.clean_existing_detector]
  enable                       = var.enable_guardduty
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.enable_s3_logs
    }
    kubernetes {
      audit_logs {
        enable = var.enable_kubernetes_audit_logs
      }
    }
    malware_protection {
      scan_ec2_instance_with_findings {
        ebs_volumes {
          enable = var.enable_malware_protection
        }
      }
    }
  }
}

resource "terraform_data" "malware_scan_settings" {
  depends_on = [aws_guardduty_detector.primary]

  triggers_replace = [
    aws_guardduty_detector.primary.id,
    local.snapshot_preservation,
    local.primary_region_name
  ]

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --region ${local.primary_region_name} --detector-id ${aws_guardduty_detector.primary.id} --scan-resource-criteria '{\"Include\":{}}' --ebs-snapshot-preservation ${local.snapshot_preservation}"
  }
}

resource "aws_guardduty_publishing_destination" "primary" {
  count           = var.enable_publishing_destination ? 1 : 0
  detector_id     = aws_guardduty_detector.primary.id
  destination_arn = aws_s3_bucket.primary.arn
  kms_key_arn     = aws_kms_key.primary.arn

  depends_on = [
    aws_s3_bucket_policy.primary
  ]
}

resource "aws_s3_object" "ip_sets" {
  for_each = var.ip_sets

  bucket  = aws_s3_bucket.primary.id
  key     = "ip-sets/${each.key}.txt"
  content = each.value.content

  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.primary.arn
}

resource "aws_guardduty_ipset" "custom" {
  for_each = var.ip_sets

  activate    = each.value.activate
  detector_id = aws_guardduty_detector.primary.id
  format      = each.value.format
  location    = "https://s3.amazonaws.com/${aws_s3_bucket.primary.id}/${aws_s3_object.ip_sets[each.key].key}"
  name        = each.key

  depends_on = [
    aws_kms_key.primary,
    aws_s3_bucket_policy.primary,
    aws_s3_object.ip_sets
  ]
}

resource "aws_s3_object" "threat_intel_sets" {
  for_each = var.threat_intel_sets

  bucket  = aws_s3_bucket.primary.id
  key     = "threat-intel/${each.key}.txt"
  content = each.value.content

  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.primary.arn
}

resource "aws_guardduty_threatintelset" "custom" {
  for_each = var.threat_intel_sets

  activate    = each.value.activate
  detector_id = aws_guardduty_detector.primary.id
  format      = each.value.format
  location    = "https://s3.amazonaws.com/${aws_s3_bucket.primary.id}/${aws_s3_object.threat_intel_sets[each.key].key}"
  name        = each.key

  depends_on = [
    aws_kms_key.primary,
    aws_s3_bucket_policy.primary,
    aws_s3_object.threat_intel_sets
  ]
}

resource "aws_guardduty_filter" "custom" {
  for_each = var.finding_filters

  name        = each.key
  action      = each.value.action
  detector_id = aws_guardduty_detector.primary.id
  rank        = each.value.rank
  description = each.value.description

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criterion
      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  type        = string
  description = "Prefix to be used on all resource names"
  default     = "imputation-example"
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to all resources"
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
    Application = "EMR"
  }
}

# ------------------------------------------------------------------------------
# EMR Service Role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_service_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["elasticmapreduce.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_service_role" {
  name               = "${var.name_prefix}-emr-service-role"
  assume_role_policy = data.aws_iam_policy_document.emr_service_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_service_policy" {
  role       = aws_iam_role.emr_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEMRServicePolicy_v2"
}

# ------------------------------------------------------------------------------
# EMR EC2 Instance Profile Role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_ec2_role" {
  name               = "${var.name_prefix}-emr-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.emr_ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_ec2_policy" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_cloudwatch_policy" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_ssm_policy" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "emr_ec2_instance_profile" {
  name = "${var.name_prefix}-emr-instance-profile"
  role = aws_iam_role.emr_ec2_role.name
  tags = var.tags
}

# ------------------------------------------------------------------------------
# EMR Auto Scaling Role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_autoscaling_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "elasticmapreduce.amazonaws.com",
        "application-autoscaling.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role" "emr_autoscaling_role" {
  name               = "${var.name_prefix}-emr-autoscaling-role"
  assume_role_policy = data.aws_iam_policy_document.emr_autoscaling_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling_policy" {
  role       = aws_iam_role.emr_autoscaling_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforAutoScalingRole"
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "emr_service_role_arn" {
  description = "ARN of the EMR service IAM role"
  value       = aws_iam_role.emr_service_role.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service IAM role"
  value       = aws_iam_role.emr_service_role.name
}

output "emr_service_role_unique_id" {
  description = "Stable and unique string identifying the EMR service IAM role"
  value       = aws_iam_role.emr_service_role.unique_id
}

output "emr_ec2_role_arn" {
  description = "ARN of the EMR EC2 IAM role"
  value       = aws_iam_role.emr_ec2_role.arn
}

output "emr_ec2_role_name" {
  description = "Name of the EMR EC2 IAM role"
  value       = aws_iam_role.emr_ec2_role.name
}

output "emr_ec2_role_unique_id" {
  description = "Stable and unique string identifying the EMR EC2 IAM role"
  value       = aws_iam_role.emr_ec2_role.unique_id
}

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR Auto Scaling IAM role"
  value       = aws_iam_role.emr_autoscaling_role.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR Auto Scaling IAM role"
  value       = aws_iam_role.emr_autoscaling_role.name
}

output "emr_autoscaling_role_unique_id" {
  description = "Stable and unique string identifying the EMR Auto Scaling IAM role"
  value       = aws_iam_role.emr_autoscaling_role.unique_id
}

output "emr_instance_profile_arn" {
  description = "ARN of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2_instance_profile.arn
}

output "emr_instance_profile_name" {
  description = "Name of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2_instance_profile.name
}

output "emr_instance_profile_id" {
  description = "Unique ID of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2_instance_profile.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  description = "The name of the IAM user for API integration testing and monitoring."
  type        = string
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  description = "Optional ARN of a Cognito User Pool to allow AdminInitiateAuth."
  type        = string
  default     = ""
}

resource "aws_iam_user" "postman_user" {
  name = var.iam_user_name
  path = "/"
}

resource "aws_iam_access_key" "postman_key" {
  user = aws_iam_user.postman_user.name
}

resource "aws_iam_policy" "monitoring_api_read_only" {
  name        = "${var.iam_user_name}-monitoring-api-read-only"
  description = "Allows read-only access to API Gateway resources and CloudWatch metrics."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowApiGatewayAndCloudWatchRead"
        Effect = "Allow"
        Action = [
          "apigateway:GET",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "monitoring_api_read_only" {
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.monitoring_api_read_only.arn
}

resource "aws_iam_policy" "cognito_auth" {
  count       = var.cognito_user_pool_arn != "" ? 1 : 0
  name        = "${var.iam_user_name}-cognito-auth"
  description = "Allows AdminInitiateAuth on the specified Cognito User Pool."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCognitoAdminInitiateAuth"
        Effect = "Allow"
        Action = [
          "cognito-idp:AdminInitiateAuth"
        ]
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "cognito_auth" {
  count      = var.cognito_user_pool_arn != "" ? 1 : 0
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.cognito_auth[0].arn
}

output "iam_user_arn" {
  description = "The Amazon Resource Name (ARN) of the created IAM user."
  value       = aws_iam_user.postman_user.arn
}

output "iam_access_key_id" {
  description = "The access key ID for programmatic access."
  value       = aws_iam_access_key.postman_key.id
}

output "iam_access_key_secret" {
  description = "The secret access key for programmatic access."
  value       = aws_iam_access_key.postman_key.secret
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type        = string
  description = "The name of the Amazon EKS cluster"
  default     = "legion"
}

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json
}

resource "aws_iam_role_policy_attachment" "cluster_amazon_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "cluster_amazon_eks_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
  role       = aws_iam_role.eks_cluster.name
}

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "node_amazon_eks_worker_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "node_amazon_eks_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "node_amazon_ec2_container_registry_read_only" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.eks_node.name
}

data "aws_iam_policy_document" "cluster_autoscaler" {
  statement {
    sid    = "ClusterAutoscalerDescribeActions"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ClusterAutoscalerMutatingActions"
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "cluster_autoscaler" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "IAM policy for Cluster Autoscaler integration with EKS worker nodes"
  policy      = data.aws_iam_policy_document.cluster_autoscaler.json
}

resource "aws_iam_role_policy_attachment" "node_cluster_autoscaler" {
  policy_arn = aws_iam_policy.cluster_autoscaler.arn
  role       = aws_iam_role.eks_node.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC"
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "The CIDR block for the public subnet"
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  type        = string
  description = "The CIDR block for the private subnet"
  default     = "172.69.2.0/24"
}

variable "webserver_ingress_rules" {
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  description = "Dynamic ingress rules for the web server security group"
  default = [
    {
      description = "HTTP access"
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      description = "SSH access from VPC"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc_name"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "private_subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "webserver" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Web server security group"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.webserver_ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Database security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL/Aurora access from web server security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.webserver.id]
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "database_security_group"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "A map of tags to assign to the resources."
  type        = map(string)
  default     = {}
}

locals {
  controlplane_name = "aws_ccm_k8s_controlplane"
  worker_name       = "aws_ccm_k8s_worker"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "controlplane" {
  statement {
    sid    = "EC2DescribeAndNetworking"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
      "ec2:DescribeRouteTables",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVolumes",
      "ec2:DescribeVpcs",
      "ec2:CreateSecurityGroup",
      "ec2:CreateTags",
      "ec2:CreateRoute",
      "ec2:ModifyInstanceAttribute",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupEgress",
      "ec2:DeleteSecurityGroup",
      "ec2:DeleteRoute"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AutoScalingDescribe"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElasticLoadBalancingManagement"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSDescribeKey"
    effect = "Allow"
    actions = [
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CreateServiceLinkedRoleForELB"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["elasticloadbalancing.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "controlplane" {
  name        = local.controlplane_name
  description = "IAM policy for Kubernetes AWS Cloud Controller Manager control plane"
  policy      = data.aws_iam_policy_document.controlplane.json
  tags        = var.tags
}

resource "aws_iam_role" "controlplane" {
  name               = local.controlplane_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "controlplane" {
  role       = aws_iam_role.controlplane.name
  policy_arn = aws_iam_policy.controlplane.arn
}

resource "aws_iam_instance_profile" "controlplane" {
  name = local.controlplane_name
  role = aws_iam_role.controlplane.name
  tags = var.tags
}

data "aws_iam_policy_document" "worker" {
  statement {
    sid    = "EC2WorkerDescribe"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ECRAuthToken"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ECRReadOnlyPull"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "worker" {
  name        = local.worker_name
  description = "IAM policy for Kubernetes worker nodes to interact with EC2 and pull from ECR"
  policy      = data.aws_iam_policy_document.worker.json
  tags        = var.tags
}

resource "aws_iam_role" "worker" {
  name               = local.worker_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "worker" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker.arn
}

resource "aws_iam_instance_profile" "worker" {
  name = local.worker_name
  role = aws_iam_role.worker.name
  tags = var.tags
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "prefix" {
  type        = string
  default     = "awscademo-"
  description = "Prefix to apply to all resource names."
}

variable "tags" {
  type        = map(string)
  default = {
    Contact          = "security-team@example.com"
    DeploymentMethod = "Terraform"
    DeploymentDate   = "2024-01-01"
    TTL              = "Infinite"
  }
  description = "Default tags applied to supported resources."
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id   = data.aws_caller_identity.current.account_id
  partition    = data.aws_partition.current.partition
  admin_prefix = substr(var.prefix, 0, 31)
}

# -----------------------------------------------------------------------------
# Demo Users Group & Self-Management Policy
# -----------------------------------------------------------------------------
resource "aws_iam_group" "demo_users" {
  name = "${var.prefix}demo-users"
  path = "/"
}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid       = "AllowViewAccountInfo"
    effect    = "Allow"
    actions   = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowManageOwnSSHPublicKeys"
    effect = "Allow"
    actions = [
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:UploadSSHPublicKey"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowDeactivateOwnVirtualMFADeviceWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${var.prefix}self-management-policy"
  description = "Allows users to manage their own credentials and virtual MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

# -----------------------------------------------------------------------------
# Read-Only Users Group
# -----------------------------------------------------------------------------
resource "aws_iam_group" "read_only_users" {
  name = "${var.prefix}read-only-users"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "read_only_attachment" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/ReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# MFA Superadmin Group & Role
# -----------------------------------------------------------------------------
resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.prefix}mfa-superadmin"
  path = "/"
}

data "aws_iam_policy_document" "admin_role_assume" {
  statement {
    sid     = "AllowAccountRootAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin_role" {
  name_prefix          = local.admin_prefix
  description          = "Administrative role with MFA requirement for sensitive operations"
  assume_role_policy   = data.aws_iam_policy_document.admin_role_assume.json
  max_session_duration = 43200
  tags                 = var.tags
}

data "aws_iam_policy_document" "mfa_admin" {
  statement {
    sid       = "MFAAdminAccess"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "mfa_admin" {
  name        = "${var.prefix}mfa-admin-policy"
  description = "Grants full administrative access conditioned upon active MFA."
  policy      = data.aws_iam_policy_document.mfa_admin.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "admin_role_mfa_admin" {
  role       = aws_iam_role.admin_role.name
  policy_arn = aws_iam_policy.mfa_admin.arn
}

data "aws_iam_policy_document" "group_assume_admin_role" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin_role.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "group_assume_admin_role" {
  name        = "${var.prefix}assume-admin-role-policy"
  description = "Allows assuming the admin role with active MFA."
  policy      = data.aws_iam_policy_document.group_assume_admin_role.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "mfa_superadmin_assume_role" {
  group      = aws_iam_group.mfa_superadmin.name
  policy_arn = aws_iam_policy.group_assume_admin_role.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'cp' or 'org'"
  default     = "eg"
}

variable "environment" {
  type        = string
  description = "Environment, e.g. 'prod', 'staging', 'dev', 'mgmt'"
  default     = "mgmt"
}

variable "name" {
  type        = string
  description = "Solution name, e.g. 'iam' or 'auth'"
  default     = "access"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes (e.g. `['1']`)"
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`)"
  default     = {}
}

variable "admin_users" {
  type        = list(string)
  description = "List of IAM usernames to assign to the admin group"
  default     = []
}

variable "non_admin_users" {
  type        = list(string)
  description = "List of IAM usernames to assign to the non-admin group"
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  base_name_parts = compact([
    var.namespace,
    var.environment,
    var.name,
    join("-", var.attributes)
  ])
  base_id = join("-", local.base_name_parts)

  admin_group_name         = format("%s-admin", local.base_id)
  non_admin_group_name     = format("%s-non-admin", local.base_id)
  admin_role_name          = format("%s-admin-role", local.base_id)
  self_mgmt_policy_name    = format("%s-self-mgmt", local.base_id)
  assume_admin_policy_name = format("%s-assume-admin", local.base_id)

  common_tags = merge(
    var.tags,
    {
      Namespace   = var.namespace
      Environment = var.environment
      Name        = var.name
    }
  )
}

resource "aws_iam_group" "admin" {
  name = local.admin_group_name
}

resource "aws_iam_group" "non_admin" {
  name = local.non_admin_group_name
}

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0
  name  = "${local.admin_group_name}-membership"
  users = var.admin_users
  group = aws_iam_group.admin.name
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_users) > 0 ? 1 : 0
  name  = "${local.non_admin_group_name}-membership"
  users = var.non_admin_users
  group = aws_iam_group.non_admin.name
}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowViewAccountInfoAndMFA"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListVirtualMFADevices"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowManageOwnSSHPublicKeys"
    effect = "Allow"
    actions = [
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:UploadSSHPublicKey"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowCreateAndEnableOwnVirtualMFA"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowDeactivateOwnVirtualMFAOnlyWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = local.self_mgmt_policy_name
  description = "Allows IAM users to manage their own credentials, keys, and MFA with enforced MFA for device deactivation"
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid     = "RequireMFAToAssumeAdminRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = local.admin_role_name
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AdministratorAccess"
}

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid     = "AllowAssumeAdminRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      aws_iam_role.admin.arn
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = local.assume_admin_policy_name
  description = "Allows assuming the administrative IAM role, requiring active MFA"
  policy      = data.aws_iam_policy_document.assume_admin_role.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  name     = "dev-test"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-igw"
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-public-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-public-2"
  }
}

resource "aws_subnet" "private_app_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-private-app-1"
  }
}

resource "aws_subnet" "private_app_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-private-app-2"
  }
}

resource "aws_subnet" "private_data_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.21.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-private-data-1"
  }
}

resource "aws_subnet" "private_data_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.22.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-private-data-2"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name}-public-rt"
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-private-rt"
  }
}

resource "aws_route_table_association" "private_app_1" {
  subnet_id      = aws_subnet.private_app_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_app_2" {
  subnet_id      = aws_subnet.private_app_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_data_1" {
  subnet_id      = aws_subnet.private_data_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_data_2" {
  subnet_id      = aws_subnet.private_data_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "public" {
  name        = "${local.name}-public-sg"
  description = "Security group for public tier instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow SSH from within VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow HTTP from internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name}-public-sg"
  }
}

resource "aws_security_group" "private" {
  name        = "${local.name}-private-sg"
  description = "Security group for private tier instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name}-private-sg"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_suffix" {
  description = "Configurable suffix to append to all resource names"
  type        = string
  default     = ""
}

locals {
  name_prefix = "prod-ci-"
  role_name   = "${local.name_prefix}role${var.name_suffix}"
  policy_name = "${local.name_prefix}policy${var.name_suffix}"
  group_name  = "${local.name_prefix}group${var.name_suffix}"
  user_name   = "${local.name_prefix}user${var.name_suffix}"
}

data "aws_iam_policy_document" "role_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_iam_role" "ci_role" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.role_assume_role_policy.json
}

data "aws_iam_policy_document" "assume_ci_role_policy" {
  statement {
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.ci_role.arn]
  }
}

resource "aws_iam_policy" "ci_policy" {
  name   = local.policy_name
  policy = data.aws_iam_policy_document.assume_ci_role_policy.json
}

resource "aws_iam_group" "ci_group" {
  name = local.group_name
}

resource "aws_iam_group_policy_attachment" "ci_group_policy_attachment" {
  group      = aws_iam_group.ci_group.name
  policy_arn = aws_iam_policy.ci_policy.arn
}

resource "aws_iam_user" "ci_user" {
  name = local.user_name
}

resource "aws_iam_user_group_membership" "ci_user_membership" {
  user   = aws_iam_user.ci_user.name
  groups = [aws_iam_group.ci_group.name]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      ManagedBy = "Terraform"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "config_aggregator_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config_aggregator" {
  name               = "aws-config-aggregator-role"
  assume_role_policy = data.aws_iam_policy_document.config_aggregator_assume_role.json
}

resource "aws_iam_role_policy_attachment" "config_aggregator" {
  role       = aws_iam_role.config_aggregator.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSConfigRoleForOrganizations"
}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.config_aggregator
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  type        = string
  description = "Base name tag for the VPC and associated resources"
  default     = "benchmark-vpc"
}

variable "ssh_inbound" {
  type        = list(string)
  description = "CIDR blocks permitted for SSH inbound access"
  default     = ["10.0.0.0/16"]
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources"
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs              = data.aws_availability_zones.available.names
  az_count         = length(local.azs)
  public_subnets   = [for idx in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, idx)]
  private_subnets  = [for idx in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, idx + local.az_count)]
  default_name_tag = "${var.vpc_name}-Default"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.tags,
    {
      Name = var.vpc_name
    }
  )
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = local.default_name_tag
    }
  )
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  tags = merge(
    var.tags,
    {
      Name = local.default_name_tag
    }
  )
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-${local.azs[count.index]}"
      Tier = "public"
    }
  )
}

resource "aws_subnet" "private" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-${local.azs[count.index]}"
      Tier = "private"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-igw"
    }
  )
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-nat-eip"
    }
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-nat"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-rt"
    }
  )
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "public" {
  name_prefix = "${var.vpc_name}-public-sg-"
  description = "Public security group for web tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  description       = "Allow inbound HTTP from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  description       = "Allow inbound HTTPS from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh" {
  count             = length(var.ssh_inbound)
  security_group_id = aws_security_group.public.id
  description       = "Allow inbound SSH from restricted CIDR"
  cidr_ipv4         = var.ssh_inbound[count.index]
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  description       = "Allow outbound HTTP only within VPC CIDR"
  cidr_ipv4         = var.vpc_cidr
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  description       = "Allow outbound HTTPS only within VPC CIDR"
  cidr_ipv4         = var.vpc_cidr
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_security_group" "private" {
  name_prefix = "${var.vpc_name}-private-sg-"
  description = "Private security group for backend tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "private_http" {
  count             = local.az_count
  security_group_id = aws_security_group.private.id
  description       = "Allow inbound HTTP from public subnets"
  cidr_ipv4         = local.public_subnets[count.index]
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "private_https" {
  count             = local.az_count
  security_group_id = aws_security_group.private.id
  description       = "Allow inbound HTTPS from public subnets"
  cidr_ipv4         = local.public_subnets[count.index]
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "private_https" {
  security_group_id = aws_security_group.private.id
  description       = "Allow outbound HTTPS only within VPC CIDR"
  cidr_ipv4         = var.vpc_cidr
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [for s in aws_subnet.public : s.id]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-nacl"
    }
  )
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  count          = length(var.ssh_inbound)
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 200
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 210
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 220
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 110
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 120
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [for s in aws_subnet.private : s.id]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-nacl"
    }
  )
}

resource "aws_network_acl_rule" "private_ingress_http" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = local.public_subnets[count.index]
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = local.public_subnets[count.index]
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300
  egress         = false
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_private" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = local.private_subnets[count.index]
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_public" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300 + count.index
  egress         = true
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = local.public_subnets[count.index]
  from_port      = 1024
  to_port        = 65535
}

