terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Deployment environment prefix"
  default     = "dev"
}

variable "target_account_id" {
  type        = string
  description = "Target AWS Account ID hosting the cross-account role"
  default     = "123456789012"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.target_account_id))
    error_message = "The target_account_id must be a 12-digit AWS account ID."
  }
}

variable "target_role_name" {
  type        = string
  description = "Target IAM role name in the destination account allowed to read S3 software"
  default     = "s3-software-reader-role"
}

data "aws_partition" "current" {}

locals {
  name_prefix     = "${var.environment}-packer"
  target_role_arn = "arn:${data.aws_partition.current.partition}:iam::${var.target_account_id}:role/${var.target_role_name}"
}

data "aws_iam_policy_document" "packer_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "packer_builder" {
  name               = "${local.name_prefix}-builder-role"
  assume_role_policy = data.aws_iam_policy_document.packer_assume_role.json

  tags = {
    Environment = var.environment
    Name        = "${local.name_prefix}-builder-role"
    ManagedBy   = "Terraform"
  }
}

data "aws_iam_policy_document" "cross_account_assume" {
  statement {
    sid       = "AllowAssumeCrossAccountRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [local.target_role_arn]
  }
}

resource "aws_iam_policy" "cross_account_assume" {
  name        = "${local.name_prefix}-cross-account-assume-policy"
  description = "Allows the Packer builder instance to assume the target role in account ${var.target_account_id} for S3 access"
  policy      = data.aws_iam_policy_document.cross_account_assume.json

  tags = {
    Environment = var.environment
    Name        = "${local.name_prefix}-cross-account-assume-policy"
    ManagedBy   = "Terraform"
  }
}

resource "aws_iam_role_policy_attachment" "packer_cross_account_attach" {
  role       = aws_iam_role.packer_builder.name
  policy_arn = aws_iam_policy.cross_account_assume.arn
}

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${local.name_prefix}-builder-instance-profile"
  role = aws_iam_role.packer_builder.name

  tags = {
    Environment = var.environment
    Name        = "${local.name_prefix}-builder-instance-profile"
    ManagedBy   = "Terraform"
  }
}

output "packer_builder_role_arn" {
  description = "ARN of the IAM role used by the Packer builder"
  value       = aws_iam_role.packer_builder.arn
}

output "packer_builder_instance_profile_arn" {
  description = "ARN of the instance profile used by the Packer builder"
  value       = aws_iam_instance_profile.packer_builder.arn
}

output "packer_builder_instance_profile_name" {
  description = "Name of the instance profile used by the Packer builder"
  value       = aws_iam_instance_profile.packer_builder.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

variable "vpc_name" {
  type        = string
  description = "Name tag for the VPC"
  default     = "three-tier-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "three_tier_vpc" {
  cidr_block           = "10.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.three_tier_vpc.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.three_tier_vpc.id
  cidr_block              = "10.16.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "presentation-subnet"
  }
}

resource "aws_subnet" "application" {
  vpc_id                  = aws_vpc.three_tier_vpc.id
  cidr_block              = "10.16.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "application-subnet"
  }
}

resource "aws_subnet" "data" {
  vpc_id                  = aws_vpc.three_tier_vpc.id
  cidr_block              = "10.16.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "data-subnet"
  }
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.three_tier_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "presentation-rt"
  }
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# 1. IAM Role for Service Catalog Launch Constraint (test_role)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "service_catalog_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [
        "servicecatalog.amazonaws.com",
        "cloudformation.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name                 = "test_role"
  path                 = "/"
  assume_role_policy   = data.aws_iam_policy_document.service_catalog_assume_role.json
  max_session_duration = 3600

  tags = {
    Environment = "Testing"
    ManagedBy   = "Terraform"
    Purpose     = "ServiceCatalogLaunchConstraint"
  }
}

# Scoped Launch-Constraint Policy: CloudFormation, S3, SSM, and EC2 read/tag operations
data "aws_iam_policy_document" "launch_constraint" {
  statement {
    sid    = "CloudFormationStackOperations"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStacks",
      "cloudformation:GetTemplateSummary",
      "cloudformation:SetStackPolicy",
      "cloudformation:ValidateTemplate",
      "cloudformation:UpdateStack"
    ]
    resources = [
      "arn:${local.partition}:cloudformation:${local.region}:${local.account_id}:stack/SC-*/*"
    ]
  }

  statement {
    sid    = "ServiceCatalogS3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      "arn:${local.partition}:s3:::sc-catalog-*",
      "arn:${local.partition}:s3:::sc-catalog-*/*"
    ]
  }

  statement {
    sid    = "ParameterStoreReadOnly"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath"
    ]
    resources = [
      "arn:${local.partition}:ssm:${local.region}:${local.account_id}:parameter/servicecatalog/*"
    ]
  }

  statement {
    sid    = "EC2ScopedReadOnlyAndTagging"
    effect = "Allow"
    actions = [
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeImages",
      "ec2:CreateTags"
    ]
    resources = [
      "arn:${local.partition}:ec2:${local.region}:${local.account_id}:security-group/*",
      "arn:${local.partition}:ec2:${local.region}:${local.account_id}:subnet/*",
      "arn:${local.partition}:ec2:${local.region}:${local.account_id}:vpc/*",
      "arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*",
      "arn:${local.partition}:ec2:${local.region}::image/*"
    ]
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "ServiceCatalogLaunchConstraintPolicy"
  path        = "/"
  description = "Scoped launch constraint policy for Service Catalog provisioned products"
  policy      = data.aws_iam_policy_document.launch_constraint.json
}

resource "aws_iam_role_policy_attachment" "test_role_launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

# -----------------------------------------------------------------------------
# 2. IAM Group & End-User Policy for Service Catalog Testers
# -----------------------------------------------------------------------------
resource "aws_iam_group" "service_catalog_testers" {
  name = "service_catalog_testers"
  path = "/"
}

data "aws_iam_policy_document" "tester_permissions" {
  statement {
    sid    = "ServiceCatalogEndUserOperations"
    effect = "Allow"
    actions = [
      "servicecatalog:ListPortfolios",
      "servicecatalog:ListRecordHistory",
      "servicecatalog:ListLaunchPaths",
      "servicecatalog:DescribeProduct",
      "servicecatalog:DescribeProductView",
      "servicecatalog:DescribeProvisioningParameters",
      "servicecatalog:DescribeRecord",
      "servicecatalog:ScanProvisionedProducts",
      "servicecatalog:SearchProducts",
      "servicecatalog:SearchProductsAsAdmin"
    ]
    resources = [
      "arn:${local.partition}:servicecatalog:${local.region}:${local.account_id}:portfolio/*",
      "arn:${local.partition}:servicecatalog:${local.region}:${local.account_id}:product/*",
      "arn:${local.partition}:servicecatalog:${local.region}:${local.account_id}:provisioned-product/*"
    ]
  }

  statement {
    sid    = "ServiceCatalogProvisioningOperations"
    effect = "Allow"
    actions = [
      "servicecatalog:ProvisionProduct",
      "servicecatalog:TerminateProvisionedProduct",
      "servicecatalog:UpdateProvisionedProduct"
    ]
    resources = [
      "arn:${local.partition}:servicecatalog:${local.region}:${local.account_id}:product/*",
      "arn:${local.partition}:servicecatalog:${local.region}:${local.account_id}:provisioned-product/*"
    ]
  }
}

resource "aws_iam_policy" "service_catalog_tester" {
  name        = "ServiceCatalogTesterGroupPolicy"
  path        = "/"
  description = "Allows group members to view portfolios and provision Service Catalog artifacts"
  policy      = data.aws_iam_policy_document.tester_permissions.json
}

resource "aws_iam_group_policy_attachment" "tester_group_attachment" {
  group      = aws_iam_group.service_catalog_testers.name
  policy_arn = aws_iam_policy.service_catalog_tester.arn
}

# -----------------------------------------------------------------------------
# 3. IAM User, Credentials & Secrets Manager Storage
# -----------------------------------------------------------------------------
resource "aws_iam_user" "tester_user" {
  name          = "service_catalog_test_user"
  path          = "/"
  force_destroy = true

  tags = {
    Environment = "Testing"
    ManagedBy   = "Terraform"
  }
}

resource "random_password" "tester_password" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_iam_user_login_profile" "tester_profile" {
  user                    = aws_iam_user.tester_user.name
  password_reset_required = true

  lifecycle {
    ignore_changes = [
      password_length,
      password_reset_required,
      pgp_key
    ]
  }
}

resource "aws_secretsmanager_secret" "tester_credentials" {
  name                    = "service_catalog_test_user_credentials"
  description             = "Initial console password for the Service Catalog test user"
  recovery_window_in_days = 0

  tags = {
    Environment = "Testing"
    ManagedBy   = "Terraform"
  }
}

resource "aws_secretsmanager_secret_version" "tester_credentials_val" {
  secret_id = aws_secretsmanager_secret.tester_credentials.id
  secret_string = jsonencode({
    username = aws_iam_user.tester_user.name
    password = random_password.tester_password.result
  })
}

resource "aws_iam_user_group_membership" "tester_membership" {
  user = aws_iam_user.tester_user.name
  groups = [
    aws_iam_group.service_catalog_testers.name
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "test_role_arn" {
  description = "ARN of the Service Catalog launch-constraint role"
  value       = aws_iam_role.test_role.arn
}

output "iam_group_name" {
  description = "Name of the IAM group designated for Service Catalog testers"
  value       = aws_iam_group.service_catalog_testers.name
}

output "iam_user_name" {
  description = "Name of the console-enabled IAM user"
  value       = aws_iam_user.tester_user.name
}

output "tester_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret storing initial console credentials"
  value       = aws_secretsmanager_secret.tester_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      Datadog                 = "true"
      DatadogAgentlessScanner = "true"
    }
  }
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "max_az_count" {
  type        = number
  description = "Maximum number of Availability Zones to utilize"
  default     = 3
}

variable "enable_ssm_endpoints" {
  type        = bool
  description = "Flag to enable SSM interface VPC endpoints (ec2messages, ssmmessages, ssm)"
  default     = false
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name = "DatatogAgentlessScanner"
  az_count = min(length(data.aws_availability_zones.available.names), var.max_az_count)
  azs      = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  ssm_services = toset(["ssm", "ssmmessages", "ec2messages"])
}

resource "aws_vpc" "datadog_agentless_scanner" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name                    = local.vpc_name
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.datadog_agentless_scanner.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                    = "${local.vpc_name}-public-${local.azs[count.index]}"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_subnet" "private" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.datadog_agentless_scanner.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                    = "${local.vpc_name}-private-${local.azs[count.index]}"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.datadog_agentless_scanner.id

  tags = {
    Name                    = "${local.vpc_name}-igw"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.datadog_agentless_scanner.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name                    = "${local.vpc_name}-public-rt"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name                    = "${local.vpc_name}-nat-eip"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name                    = "${local.vpc_name}-nat"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.datadog_agentless_scanner.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name                    = "${local.vpc_name}-private-rt"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.datadog_agentless_scanner.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = {
    Name                    = "${local.vpc_name}-vpce-s3"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "${local.vpc_name}-vpce-sg-"
  description = "Security group for interface VPC endpoints permitting inbound HTTPS from VPC"
  vpc_id      = aws_vpc.datadog_agentless_scanner.id

  ingress {
    description = "Allow inbound HTTPS from within the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic to within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name                    = "${local.vpc_name}-vpce-sg"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.datadog_agentless_scanner.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name                    = "${local.vpc_name}-vpce-lambda"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.datadog_agentless_scanner.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name                    = "${local.vpc_name}-vpce-ebs"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  for_each            = var.enable_ssm_endpoints ? local.ssm_services : toset([])
  vpc_id              = aws_vpc.datadog_agentless_scanner.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name                    = "${local.vpc_name}-vpce-${each.value}"
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.datadog_agentless_scanner.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "The ID of the NAT Gateway"
  value       = aws_nat_gateway.main.id
}

output "vpc_endpoints_security_group_id" {
  description = "The ID of the Security Group used by the VPC Endpoints"
  value       = aws_security_group.vpc_endpoints.id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "enabled" {
  type        = bool
  default     = true
  description = "A global toggle to enable or disable the creation of resources in this module."
}

variable "create_sg" {
  type        = bool
  default     = true
  description = "Determines whether to create a new security group or manage rules on an existing one."
}

variable "security_group_id" {
  type        = string
  default     = null
  description = "The ID of an existing security group to attach rules to if create_sg is false."
}

variable "vpc_id" {
  type        = string
  default     = null
  description = "The VPC ID to associate with the security group. If omitted and create_sg is true, a fallback VPC is created."
}

variable "sg_description" {
  type        = string
  default     = "Managed security group"
  description = "Description of the created security group."
}

variable "name" {
  type        = string
  default     = "app"
  description = "Name for resources, passed to the labels module."
}

variable "environment" {
  type        = string
  default     = "prod"
  description = "Environment name, passed to the labels module."
}

variable "enable_prefix_list" {
  type        = bool
  default     = false
  description = "Flag to enable creation of an EC2 managed prefix list if none are supplied."
}

variable "prefix_list_address_family" {
  type        = string
  default     = "IPv4"
  description = "The address family for the managed prefix list (IPv4 or IPv6)."
}

variable "prefix_list_max_entries" {
  type        = number
  default     = 5
  description = "Maximum number of entries allowed in the managed prefix list."
}

variable "prefix_list_entries" {
  type = list(object({
    cidr        = string
    description = optional(string, null)
  }))
  default     = []
  description = "Initial CIDR entries to populate in the created managed prefix list."
}

variable "ingress_cidr_rules" {
  type = list(object({
    description = optional(string, null)
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default     = []
  description = "List of ingress rules using CIDR blocks."
}

variable "ingress_self_rules" {
  type = list(object({
    description = optional(string, null)
    from_port   = number
    to_port     = number
    protocol    = string
  }))
  default     = []
  description = "List of self-referencing ingress rules."
}

variable "ingress_source_sg_rules" {
  type = list(object({
    description              = optional(string, null)
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
  }))
  default     = []
  description = "List of ingress rules referencing source security group IDs."
}

variable "ingress_prefix_list_rules" {
  type = list(object({
    description     = optional(string, null)
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string), null)
  }))
  default     = []
  description = "List of ingress rules referencing prefix list IDs (defaults to created prefix list if omitted)."
}

variable "egress_cidr_rules" {
  type = list(object({
    description = optional(string, null)
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default     = []
  description = "List of egress rules using CIDR blocks."
}

variable "egress_self_rules" {
  type = list(object({
    description = optional(string, null)
    from_port   = number
    to_port     = number
    protocol    = string
  }))
  default     = []
  description = "List of self-referencing egress rules."
}

variable "egress_source_sg_rules" {
  type = list(object({
    description              = optional(string, null)
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
  }))
  default     = []
  description = "List of egress rules referencing source security group IDs."
}

variable "egress_prefix_list_rules" {
  type = list(object({
    description     = optional(string, null)
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string), null)
  }))
  default     = []
  description = "List of egress rules referencing prefix list IDs (defaults to created prefix list if omitted)."
}

# -----------------------------------------------------------------------------
# Standardized Labels Module
# -----------------------------------------------------------------------------
module "labels" {
  source      = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  enabled     = var.enabled
  name        = var.name
  environment = var.environment
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  create_vpc       = var.enabled && var.create_sg && var.vpc_id == null
  resolved_vpc_id  = local.create_vpc ? aws_vpc.fallback[0].id : var.vpc_id
  resolved_sg_id   = var.create_sg ? (length(aws_security_group.this) > 0 ? aws_security_group.this[0].id : null) : var.security_group_id
  created_pl_id    = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].id : null
  sg_name          = "${module.labels.id}-sg"
  prefix_list_name = "${module.labels.id}-prefix-list"
}

# -----------------------------------------------------------------------------
# Fallback VPC
# -----------------------------------------------------------------------------
resource "aws_vpc" "fallback" {
  count                = local.create_vpc ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    module.labels.tags,
    {
      Name = "${module.labels.id}-vpc"
    }
  )
}

# -----------------------------------------------------------------------------
# EC2 Managed Prefix List (Optional)
# -----------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.enable_prefix_list ? 1 : 0
  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(
    module.labels.tags,
    {
      Name = local.prefix_list_name
    }
  )
}

# -----------------------------------------------------------------------------
# Managed Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "this" {
  count       = var.enabled && var.create_sg ? 1 : 0
  name        = local.sg_name
  description = var.sg_description
  vpc_id      = local.resolved_vpc_id

  tags = merge(
    module.labels.tags,
    {
      Name = local.sg_name
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Standalone Ingress Rules
# -----------------------------------------------------------------------------
resource "aws_security_group_rule" "ingress_cidr" {
  for_each          = var.enabled ? { for idx, rule in var.ingress_cidr_rules : idx => rule } : {}
  type              = "ingress"
  security_group_id = local.resolved_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = each.value.description
}

resource "aws_security_group_rule" "ingress_self" {
  for_each          = var.enabled ? { for idx, rule in var.ingress_self_rules : idx => rule } : {}
  type              = "ingress"
  security_group_id = local.resolved_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = each.value.description
}

resource "aws_security_group_rule" "ingress_source_sg" {
  for_each                 = var.enabled ? { for idx, rule in var.ingress_source_sg_rules : idx => rule } : {}
  type                     = "ingress"
  security_group_id        = local.resolved_sg_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_security_group_id
  description              = each.value.description
}

resource "aws_security_group_rule" "ingress_prefix_list" {
  for_each          = var.enabled ? { for idx, rule in var.ingress_prefix_list_rules : idx => rule } : {}
  type              = "ingress"
  security_group_id = local.resolved_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = each.value.prefix_list_ids != null ? each.value.prefix_list_ids : (local.created_pl_id != null ? [local.created_pl_id] : [])
  description       = each.value.description
}

# -----------------------------------------------------------------------------
# Standalone Egress Rules
# -----------------------------------------------------------------------------
resource "aws_security_group_rule" "egress_cidr" {
  for_each          = var.enabled ? { for idx, rule in var.egress_cidr_rules : idx => rule } : {}
  type              = "egress"
  security_group_id = local.resolved_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = each.value.description
}

resource "aws_security_group_rule" "egress_self" {
  for_each          = var.enabled ? { for idx, rule in var.egress_self_rules : idx => rule } : {}
  type              = "egress"
  security_group_id = local.resolved_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = each.value.description
}

resource "aws_security_group_rule" "egress_source_sg" {
  for_each                 = var.enabled ? { for idx, rule in var.egress_source_sg_rules : idx => rule } : {}
  type                     = "egress"
  security_group_id        = local.resolved_sg_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_security_group_id
  description              = each.value.description
}

resource "aws_security_group_rule" "egress_prefix_list" {
  for_each          = var.enabled ? { for idx, rule in var.egress_prefix_list_rules : idx => rule } : {}
  type              = "egress"
  security_group_id = local.resolved_sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = each.value.prefix_list_ids != null ? each.value.prefix_list_ids : (local.created_pl_id != null ? [local.created_pl_id] : [])
  description       = each.value.description
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "security_group_id" {
  value       = local.resolved_sg_id
  description = "The effective security group ID managed by this configuration."
}

output "security_group_arn" {
  value       = length(aws_security_group.this) > 0 ? aws_security_group.this[0].arn : null
  description = "The ARN of the newly created security group (null if using an existing security group)."
}

output "vpc_id" {
  value       = local.resolved_vpc_id
  description = "The VPC ID utilized for the security group."
}

output "prefix_list_id" {
  value       = local.created_pl_id
  description = "The ID of the created managed prefix list, if enabled."
}

output "prefix_list_arn" {
  value       = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].arn : null
  description = "The ARN of the created managed prefix list, if enabled."
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "The name of the IAM role for CloudForecast ZeroWaste integration."
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  type        = string
  description = "The external ID used for cross-account STS AssumeRole authentication."
  default     = "benchmark-external-id"
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "CloudForecastAssumeRoleWithExternalId"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::656227328603:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

resource "aws_iam_role" "cloudforecast" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  description        = "Dedicated read-only IAM role for CloudForecast ZeroWaste cost optimization and waste monitoring."
}

# Policy 1: Common Metrics & Resource Tags
data "aws_iam_policy_document" "common_metrics_tags" {
  statement {
    sid    = "CloudWatchMetricsAndResourceTagsRead"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "tag:GetResources",
      "tag:GetTagKeys",
      "tag:GetTagValues"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "common_metrics_tags" {
  name   = "cloudforecast-common-metrics-tags"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.common_metrics_tags.json
}

# Policy 2: AWS Organizations
data "aws_iam_policy_document" "organizations" {
  statement {
    sid    = "OrganizationsRead"
    effect = "Allow"
    actions = [
      "organizations:DescribeAccount",
      "organizations:DescribeOrganization",
      "organizations:ListAccounts"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "organizations" {
  name   = "cloudforecast-organizations"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.organizations.json
}

# Policy 3: Elastic Load Balancing (ELB/ALB/NLB)
data "aws_iam_policy_document" "elasticloadbalancing" {
  statement {
    sid    = "ELBRead"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeLoadBalancerAttributes",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DescribeTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "elasticloadbalancing" {
  name   = "cloudforecast-elasticloadbalancing"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.elasticloadbalancing.json
}

# Policy 4: EBS Volumes and Snapshots
data "aws_iam_policy_document" "ebs" {
  statement {
    sid    = "EBSRead"
    effect = "Allow"
    actions = [
      "ec2:DescribeVolumes",
      "ec2:DescribeVolumesModifications",
      "ec2:DescribeVolumeStatus",
      "ec2:DescribeSnapshots",
      "ec2:DescribeSnapshotAttribute"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ebs" {
  name   = "cloudforecast-ebs"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.ebs.json
}

# Policy 5: EC2 Instances and Reservations
data "aws_iam_policy_document" "ec2" {
  statement {
    sid    = "EC2Read"
    effect = "Allow"
    actions = [
      "ec2:DescribeAddresses",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeImages",
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeRegions",
      "ec2:DescribeReservedInstances",
      "ec2:DescribeReservedInstancesOfferings",
      "ec2:DescribeTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ec2" {
  name   = "cloudforecast-ec2"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.ec2.json
}

# Policy 6: RDS Instances, Clusters, and Snapshots
data "aws_iam_policy_document" "rds" {
  statement {
    sid    = "RDSRead"
    effect = "Allow"
    actions = [
      "rds:DescribeDBClusters",
      "rds:DescribeDBClusterSnapshots",
      "rds:DescribeDBInstances",
      "rds:DescribeDBSnapshots",
      "rds:DescribeReservedDBInstances",
      "rds:DescribeReservedDBInstancesOfferings",
      "rds:ListTagsForResource"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "rds" {
  name   = "cloudforecast-rds"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.rds.json
}

# Policy 7: S3 Bucket Discovery and Metadata
data "aws_iam_policy_document" "s3" {
  statement {
    sid    = "S3ListBuckets"
    effect = "Allow"
    actions = [
      "s3:ListAllMyBuckets"
    ]
    resources = ["arn:aws:s3:::*"]
  }

  statement {
    sid    = "S3BucketMetadataRead"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation",
      "s3:GetBucketTagging",
      "s3:GetLifecycleConfiguration",
      "s3:ListBucket"
    ]
    resources = ["arn:aws:s3:::*"]
  }
}

resource "aws_iam_role_policy" "s3" {
  name   = "cloudforecast-s3"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.s3.json
}

# Policy 8: CloudWatch Logs
data "aws_iam_policy_document" "logs" {
  statement {
    sid    = "LogsRead"
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "logs" {
  name   = "cloudforecast-logs"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.logs.json
}

# Policy 9: AWS Support & Trusted Advisor
data "aws_iam_policy_document" "support" {
  statement {
    sid    = "SupportAndTrustedAdvisorRead"
    effect = "Allow"
    actions = [
      "support:DescribeSeverityLevels",
      "support:DescribeTrustedAdvisorChecks",
      "support:DescribeTrustedAdvisorCheckResult",
      "support:DescribeTrustedAdvisorCheckSummaries"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "support" {
  name   = "cloudforecast-support"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.support.json
}

# Policy 10: ElastiCache
data "aws_iam_policy_document" "elasticache" {
  statement {
    sid    = "ElastiCacheRead"
    effect = "Allow"
    actions = [
      "elasticache:DescribeCacheClusters",
      "elasticache:DescribeReplicationGroups",
      "elasticache:DescribeReservedCacheNodes",
      "elasticache:DescribeReservedCacheNodesOfferings",
      "elasticache:DescribeSnapshots",
      "elasticache:ListTagsForResource"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "elasticache" {
  name   = "cloudforecast-elasticache"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.elasticache.json
}

# Policy 11: DynamoDB
data "aws_iam_policy_document" "dynamodb" {
  statement {
    sid    = "DynamoDBRead"
    effect = "Allow"
    actions = [
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTable",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListBackups",
      "dynamodb:ListTables",
      "dynamodb:ListTagsOfResource"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "dynamodb" {
  name   = "cloudforecast-dynamodb"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.dynamodb.json
}

# Policy 12: Amazon Redshift
data "aws_iam_policy_document" "redshift" {
  statement {
    sid    = "RedshiftRead"
    effect = "Allow"
    actions = [
      "redshift:DescribeClusterSnapshots",
      "redshift:DescribeClusters",
      "redshift:DescribeReservedNodes",
      "redshift:DescribeReservedNodeOfferings",
      "redshift:DescribeTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "redshift" {
  name   = "cloudforecast-redshift"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.redshift.json
}

# Policy 13: Auto Scaling
data "aws_iam_policy_document" "autoscaling" {
  statement {
    sid    = "AutoScalingRead"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribePolicies",
      "autoscaling:DescribeScalingActivities",
      "autoscaling:DescribeTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "autoscaling" {
  name   = "cloudforecast-autoscaling"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.autoscaling.json
}

# Policy 14: Cost Explorer & Savings Plans
data "aws_iam_policy_document" "ce" {
  statement {
    sid    = "CostExplorerAndSavingsPlansRead"
    effect = "Allow"
    actions = [
      "ce:GetCostAndUsage",
      "ce:GetCostForecast",
      "ce:GetDimensionValues",
      "ce:GetReservationCoverage",
      "ce:GetReservationPurchaseRecommendation",
      "ce:GetReservationUtilization",
      "ce:GetRightsizingRecommendation",
      "ce:GetSavingsPlansCoverage",
      "ce:GetSavingsPlansPurchaseRecommendation",
      "ce:GetSavingsPlansUtilization",
      "savingsplans:DescribeSavingsPlans",
      "savingsplans:DescribeSavingsPlansOfferingRates",
      "savingsplans:DescribeSavingsPlansOfferings"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ce" {
  name   = "cloudforecast-ce"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.ce.json
}

# Policy 15: OpenSearch & Elasticsearch
data "aws_iam_policy_document" "opensearch" {
  statement {
    sid    = "OpenSearchRead"
    effect = "Allow"
    actions = [
      "es:DescribeDomain",
      "es:DescribeDomains",
      "es:DescribeElasticsearchDomain",
      "es:DescribeElasticsearchDomains",
      "es:DescribeReservedElasticsearchInstanceOfferings",
      "es:DescribeReservedElasticsearchInstances",
      "es:DescribeReservedInstances",
      "es:ListDomainNames",
      "es:ListTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "opensearch" {
  name   = "cloudforecast-opensearch"
  role   = aws_iam_role.cloudforecast.id
  policy = data.aws_iam_policy_document.opensearch.json
}

output "role_arn" {
  description = "The Amazon Resource Name (ARN) of the created CloudForecast ZeroWaste IAM role."
  value       = aws_iam_role.cloudforecast.arn
}

output "role_name" {
  description = "The name of the created CloudForecast ZeroWaste IAM role."
  value       = aws_iam_role.cloudforecast.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Input Variables
# ------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for provisioning resources."
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Target deployment environment identifier (e.g., dev, prod, staging)."
  default     = "dev"
}

variable "enable_database_dr_user" {
  type        = bool
  description = "Flag to enable conditional creation of the database disaster recovery IAM user."
  default     = false
}

variable "enable_data_exports_user" {
  type        = bool
  description = "Flag to enable conditional creation of the data exports IAM user."
  default     = false
}

variable "enable_packer_user" {
  type        = bool
  description = "Flag to enable conditional creation of the Packer image builder IAM user."
  default     = false
}

variable "s3_export_bucket_arn" {
  type        = string
  description = "ARN of the S3 bucket targeted for data exports."
  default     = "arn:aws:s3:::example-mattermost-data-exports"
}

variable "s3_monitoring_state_bucket_name" {
  type        = string
  description = "Bucket name storing monitoring state for the Packer builder workflow."
  default     = "example-mattermost-packer-monitoring-state"
}

variable "dedicated_server_role_name" {
  type        = string
  description = "IAM role name that Packer is authorized to pass (iam:PassRole) during provisioning."
  default     = "mattermost-server-packer-role"
}

variable "network_attachment_lambda_function_name" {
  type        = string
  description = "Name of the network attachment Lambda function managed during image building."
  default     = "bind-server-network-attachment"
}

# ------------------------------------------------------------------------------
# Local Values
# ------------------------------------------------------------------------------
locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  cost_report_user_name  = "mattermost-cost-report-${var.environment}"
  database_dr_user_name  = "mattermost-database-dr-${var.environment}"
  data_exports_user_name = "mattermost-data-exports-${var.environment}"
  packer_user_name       = "mattermost-packer-builder-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# ------------------------------------------------------------------------------
# 1. Cost Reporting IAM User & Policy (Mandatory)
# ------------------------------------------------------------------------------
resource "aws_iam_user" "cost_report" {
  name = local.cost_report_user_name
  path = "/service-users/"
  tags = local.common_tags
}

data "aws_iam_policy_document" "cost_report" {
  statement {
    sid       = "CostExplorerFullAccess"
    effect    = "Allow"
    actions   = ["ce:*"]
    resources = ["*"]
  }
}

resource "aws_iam_user_policy" "cost_report" {
  name   = "${local.cost_report_user_name}-policy"
  user   = aws_iam_user.cost_report.name
  policy = data.aws_iam_policy_document.cost_report.json
}

# ------------------------------------------------------------------------------
# 2. Database Disaster Recovery IAM User & Policy (Conditional)
# ------------------------------------------------------------------------------
resource "aws_iam_user" "database_dr" {
  count = var.enable_database_dr_user ? 1 : 0
  name  = local.database_dr_user_name
  path  = "/service-users/"
  tags  = local.common_tags
}

data "aws_iam_policy_document" "database_dr" {
  count = var.enable_database_dr_user ? 1 : 0

  statement {
    sid    = "RDSFullAccess"
    effect = "Allow"
    actions = [
      "rds:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSFullAccess"
    effect = "Allow"
    actions = [
      "kms:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SecretsManagerMultitenantClusterAccess"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
      "secretsmanager:ListSecretVersionIds"
    ]
    resources = [
      "arn:aws:secretsmanager:${local.region}:${local.account_id}:secret:rds-cluster-multitenant-*"
    ]
  }
}

resource "aws_iam_user_policy" "database_dr" {
  count  = var.enable_database_dr_user ? 1 : 0
  name   = "${local.database_dr_user_name}-policy"
  user   = aws_iam_user.database_dr[0].name
  policy = data.aws_iam_policy_document.database_dr[0].json
}

# ------------------------------------------------------------------------------
# 3. Data Exports IAM User & Policy (Conditional)
# ------------------------------------------------------------------------------
resource "aws_iam_user" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = local.data_exports_user_name
  path  = "/service-users/"
  tags  = local.common_tags
}

data "aws_iam_policy_document" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0

  statement {
    sid    = "DataExportBucketList"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      var.s3_export_bucket_arn
    ]
  }

  statement {
    sid    = "DataExportBucketObjectOps"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload"
    ]
    resources = [
      "${var.s3_export_bucket_arn}/*"
    ]
  }
}

resource "aws_iam_user_policy" "data_exports" {
  count  = var.enable_data_exports_user ? 1 : 0
  name   = "${local.data_exports_user_name}-policy"
  user   = aws_iam_user.data_exports[0].name
  policy = data.aws_iam_policy_document.data_exports[0].json
}

# ------------------------------------------------------------------------------
# 4. Packer Machine Image Builder IAM User & Policy (Conditional)
# ------------------------------------------------------------------------------
resource "aws_iam_user" "packer" {
  count = var.enable_packer_user ? 1 : 0
  name  = local.packer_user_name
  path  = "/service-users/"
  tags  = local.common_tags
}

data "aws_iam_policy_document" "packer" {
  count = var.enable_packer_user ? 1 : 0

  statement {
    sid    = "PackerEC2ImageOperations"
    effect = "Allow"
    actions = [
      "ec2:AttachVolume",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:CopyImage",
      "ec2:CreateImage",
      "ec2:CreateKeypair",
      "ec2:CreateSecurityGroup",
      "ec2:CreateSnapshot",
      "ec2:CreateTags",
      "ec2:CreateVolume",
      "ec2:DeleteKeyPair",
      "ec2:DeleteSecurityGroup",
      "ec2:DeleteSnapshot",
      "ec2:DeleteVolume",
      "ec2:DeregisterImage",
      "ec2:DescribeImageAttribute",
      "ec2:DescribeImages",
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeRegions",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSnapshots",
      "ec2:DescribeSubnets",
      "ec2:DescribeTags",
      "ec2:DescribeVolumes",
      "ec2:DescribeVpcs",
      "ec2:DetachVolume",
      "ec2:GetPasswordData",
      "ec2:ModifyImageAttribute",
      "ec2:ModifyInstanceAttribute",
      "ec2:ModifySnapshotAttribute",
      "ec2:RegisterImage",
      "ec2:RunInstances",
      "ec2:StopInstances",
      "ec2:TerminateInstances"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AutoScalingAndEventsAccess"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:UpdateAutoScalingGroup",
      "events:DescribeRule",
      "events:ListRuleNamesByTarget",
      "events:ListTargetsByRule"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMParametersReadAccess"
    effect = "Allow"
    actions = [
      "ssm:DescribeParameters",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath"
    ]
    resources = [
      "arn:aws:ssm:${local.region}:${local.account_id}:parameter/*"
    ]
  }

  statement {
    sid    = "IAMInspectInstanceProfiles"
    effect = "Allow"
    actions = [
      "iam:GetInstanceProfile",
      "iam:ListInstanceProfiles",
      "iam:GetRole",
      "iam:ListRoles"
    ]
    resources = [
      "arn:aws:iam::${local.account_id}:instance-profile/*",
      "arn:aws:iam::${local.account_id}:role/*"
    ]
  }

  statement {
    sid    = "S3MonitoringStateAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = [
      "arn:aws:s3:::${var.s3_monitoring_state_bucket_name}",
      "arn:aws:s3:::${var.s3_monitoring_state_bucket_name}/*"
    ]
  }

  statement {
    sid    = "LambdaNetworkAttachmentConfig"
    effect = "Allow"
    actions = [
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionConfiguration"
    ]
    resources = [
      "arn:aws:lambda:${local.region}:${local.account_id}:function:${var.network_attachment_lambda_function_name}"
    ]
  }

  statement {
    sid    = "PassRoleForDedicatedServer"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      "arn:aws:iam::${local.account_id}:role/${var.dedicated_server_role_name}"
    ]
  }
}

resource "aws_iam_user_policy" "packer" {
  count  = var.enable_packer_user ? 1 : 0
  name   = "${local.packer_user_name}-policy"
  user   = aws_iam_user.packer[0].name
  policy = data.aws_iam_policy_document.packer[0].json
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "ecr_repository_names" {
  type        = set(string)
  description = "Set of ECR repository names to create for HealthOmics container images"
  default     = ["omics-workflow-tool"]
}

variable "cross_account_ecr_account_ids" {
  type        = list(string)
  description = "List of external AWS account IDs to grant cross-account read access to ECR repositories"
  default     = []
}

variable "additional_read_only_bucket_arns" {
  type        = list(string)
  description = "List of ARNs for additional S3 buckets requiring read-only access by the user and HealthOmics service"
  default     = []
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  output_bucket_name = "tf-benchmark-omics-output-bucket"
  role_name          = "HealthOmicsRole"
  user_name          = "workbench-health-omics"
  service_policy     = "HealthOmicsServicePolicy"
  user_policy        = "HealthOmicsUserPolicy"

  additional_bucket_objects = [
    for arn in var.additional_read_only_bucket_arns : "${arn}/*"
  ]
}

resource "aws_kms_key" "omics_output" {
  description             = "Customer managed KMS key for HealthOmics output S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "omics_output" {
  name          = "alias/omics-output-key"
  target_key_id = aws_kms_key.omics_output.key_id
}

resource "aws_s3_bucket" "output" {
  bucket = local.output_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "output" {
  bucket = aws_s3_bucket.output.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output" {
  bucket = aws_s3_bucket.output.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.omics_output.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "output" {
  bucket = aws_s3_bucket.output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_ecr_repository" "repos" {
  for_each             = var.ecr_repository_names
  name                 = each.value
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

data "aws_iam_policy_document" "ecr_policy" {
  for_each = var.ecr_repository_names

  statement {
    sid    = "OmicsServicePull"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage"
    ]
  }

  dynamic "statement" {
    for_each = length(var.cross_account_ecr_account_ids) > 0 ? [1] : []
    content {
      sid    = "CrossAccountAccess"
      effect = "Allow"
      principals {
        type = "AWS"
        identifiers = [
          for account_id in var.cross_account_ecr_account_ids :
          "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"
        ]
      }
      actions = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage"
      ]
    }
  }
}

resource "aws_ecr_repository_policy" "repos" {
  for_each   = aws_ecr_repository.repos
  repository = each.value.name
  policy     = data.aws_iam_policy_document.ecr_policy[each.key].json
}

data "aws_iam_policy_document" "omics_assume_role" {
  statement {
    sid     = "OmicsServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "health_omics_role" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.omics_assume_role.json
}

data "aws_iam_policy_document" "health_omics_service" {
  statement {
    sid    = "OutputBucketAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.output.arn,
      "${aws_s3_bucket.output.arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = length(var.additional_read_only_bucket_arns) > 0 ? [1] : []
    content {
      sid    = "AdditionalBucketsReadOnly"
      effect = "Allow"
      actions = [
        "s3:ListBucket",
        "s3:GetObject"
      ]
      resources = concat(var.additional_read_only_bucket_arns, local.additional_bucket_objects)
    }
  }

  statement {
    sid    = "KmsAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [
      aws_kms_key.omics_output.arn
    ]
  }

  dynamic "statement" {
    for_each = length(aws_ecr_repository.repos) > 0 ? [1] : []
    content {
      sid    = "EcrPullAccess"
      effect = "Allow"
      actions = [
        "ecr:BatchGetImage",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchCheckLayerAvailability"
      ]
      resources = [for repo in aws_ecr_repository.repos : repo.arn]
    }
  }

  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*"
    ]
  }
}

resource "aws_iam_policy" "health_omics_service_policy" {
  name        = local.service_policy
  description = "Service policy for Amazon HealthOmics workflows"
  policy      = data.aws_iam_policy_document.health_omics_service.json
}

resource "aws_iam_role_policy_attachment" "service_policy_attach" {
  role       = aws_iam_role.health_omics_role.name
  policy_arn = aws_iam_policy.health_omics_service_policy.arn
}

resource "aws_iam_user" "health_omics_user" {
  name = local.user_name
}

resource "aws_iam_access_key" "health_omics_user_key" {
  user = aws_iam_user.health_omics_user.name
}

data "aws_iam_policy_document" "health_omics_user" {
  statement {
    sid    = "OmicsFullActions"
    effect = "Allow"
    actions = [
      "omics:*"
    ]
    resources = [
      "*"
    ]
  }

  statement {
    sid    = "PassRoleToOmicsService"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.health_omics_role.arn
    ]
  }

  statement {
    sid    = "OutputBucketReadOnly"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetObject"
    ]
    resources = [
      aws_s3_bucket.output.arn,
      "${aws_s3_bucket.output.arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = length(var.additional_read_only_bucket_arns) > 0 ? [1] : []
    content {
      sid    = "AdditionalBucketsReadOnly"
      effect = "Allow"
      actions = [
        "s3:ListBucket",
        "s3:GetObject"
      ]
      resources = concat(var.additional_read_only_bucket_arns, local.additional_bucket_objects)
    }
  }

  statement {
    sid    = "KmsDecryptOutputBucket"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      aws_kms_key.omics_output.arn
    ]
  }
}

resource "aws_iam_policy" "health_omics_user_policy" {
  name        = local.user_policy
  description = "User policy granting Omics service actions, pass-role, and read-only S3 access"
  policy      = data.aws_iam_policy_document.health_omics_user.json
}

resource "aws_iam_user_policy_attachment" "user_policy_attach" {
  user       = aws_iam_user.health_omics_user.name
  policy_arn = aws_iam_policy.health_omics_user_policy.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = var.default_tags
  }
}

variable "cluster_name" {
  type        = string
  description = "Name identifier for the ECS cluster and associated resources"
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type        = string
  description = "First two octets for the VPC CIDR block (e.g. 10.0)"
  default     = "10.0"
}

variable "default_tags" {
  type        = map(string)
  description = "Default tags to apply to all resources"
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.12.0/22",
    "${var.vpc_cidr_network_octets}.16.0/22",
    "${var.vpc_cidr_network_octets}.20.0/22"
  ]

  private_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.0.0/22",
    "${var.vpc_cidr_network_octets}.4.0/22",
    "${var.vpc_cidr_network_octets}.8.0/22"
  ]
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-ig"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.cluster_name}-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.cluster_name}-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.cluster_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.cluster_name}-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_ecs_cluster" "main" {
  name = "dit-paas-${var.cluster_name}-cluster"

  tags = {
    Name = "dit-paas-${var.cluster_name}-cluster"
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  type        = string
  default     = "benchmark-vpc"
  description = "The name of the VPC"
}

variable "vpc_cidr" {
  type        = string
  default     = "172.16.0.0/16"
  description = "The primary IPv4 CIDR block for the VPC"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  selected_azs = slice(data.aws_availability_zones.available.names, 0, 3)
  region       = data.aws_region.current.name
}

module "vpc" {
  source  = "cloudposse/vpc/aws"
  version = "2.2.0"

  name                             = var.vpc_name
  ipv4_primary_cidr_block          = var.vpc_cidr
  dns_hostnames_enabled            = true
  dns_support_enabled              = true
  assign_generated_ipv6_cidr_block = false
  default_security_group_deny_all  = true
}

module "dynamic_subnets" {
  source  = "cloudposse/dynamic-subnets/aws"
  version = "2.4.2"

  vpc_id              = module.vpc.vpc_id
  igw_id              = [module.vpc.igw_id]
  ipv4_cidr_block     = [var.vpc_cidr]
  availability_zones  = local.selected_azs
  nat_gateway_enabled = true
}

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for Interface VPC Endpoints"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Name = "vpc_endpoint_sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "vpc_endpoint_self_ingress_443" {
  security_group_id            = aws_security_group.vpc_endpoint_sg.id
  referenced_security_group_id = aws_security_group.vpc_endpoint_sg.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  description                  = "Allow self-referencing HTTPS ingress"
}

resource "aws_vpc_security_group_ingress_rule" "vpc_endpoint_cidr_ingress_443" {
  security_group_id = aws_security_group.vpc_endpoint_sg.id
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  description       = "Allow HTTPS ingress from VPC CIDR for container workloads"
}

resource "aws_vpc_security_group_egress_rule" "vpc_endpoint_self_egress_443" {
  security_group_id            = aws_security_group.vpc_endpoint_sg.id
  referenced_security_group_id = aws_security_group.vpc_endpoint_sg.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  description                  = "Allow self-referencing HTTPS egress"
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = distinct(concat(
    module.dynamic_subnets.public_route_table_ids,
    module.dynamic_subnets.private_route_table_ids,
    [module.vpc.vpc_default_route_table_id]
  ))

  tags = {
    Name = "${var.vpc_name}-s3-gw"
  }
}

locals {
  interface_endpoints = {
    ecr_dkr = "com.amazonaws.${local.region}.ecr.dkr"
    ecr_api = "com.amazonaws.${local.region}.ecr.api"
    logs    = "com.amazonaws.${local.region}.logs"
    ssm     = "com.amazonaws.${local.region}.ssm"
    kms     = "com.amazonaws.${local.region}.kms"
  }
}

resource "aws_vpc_endpoint" "interface_endpoints" {
  for_each = local.interface_endpoints

  vpc_id              = module.vpc.vpc_id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = module.dynamic_subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-endpoint"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "Name identifier for the VPC and associated resources."
  default     = "benchmark-vpc"
}

variable "cidr_block" {
  type        = string
  description = "The primary CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  type        = string
  description = "Tenancy of instances spin up within the VPC."
  default     = "default"
}

variable "enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames in the VPC."
  default     = true
}

variable "enable_dns_support" {
  type        = bool
  description = "Enable DNS support in the VPC."
  default     = true
}

variable "aws_interface_endpoints" {
  type        = set(string)
  description = "Set of standard AWS service names to deploy as interface endpoints."
  default     = ["logs"]
}

variable "gateway_endpoint_services" {
  type        = set(string)
  description = "Set of AWS service names to deploy as gateway endpoints."
  default     = ["s3", "dynamodb"]
}

variable "custom_endpoint_services" {
  type = map(object({
    service_name = string
    port         = number
  }))
  description = "Map of custom VPC endpoint services keyed by an identifier."
  default     = {}
}

variable "source_security_group_ids" {
  type        = list(string)
  description = "List of source security group IDs allowed to access VPC endpoints."
  default     = []
}

variable "route_table_ids" {
  type        = list(string)
  description = "List of route table IDs to associate with gateway endpoints."
  default     = []
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
  enable_ssm = contains(var.aws_interface_endpoints, "ssm")

  custom_sg_rules = flatten([
    for svc_key, svc in var.custom_endpoint_services : [
      for sg_id in var.source_security_group_ids : {
        key     = "${svc_key}_${sg_id}"
        port    = svc.port
        sg_id   = sg_id
      }
    ]
  ])
}

resource "aws_vpc" "main" {
  cidr_block           = var.cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default-restricted"
  }
}

resource "aws_subnet" "endpoint_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-endpoint-subnet"
  }
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 180

  tags = {
    Name = "/aws/vpc-flow-logs/${var.vpc_name}"
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc_flow_logs_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "vpc_flow_logs_policy_${var.vpc_name}"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs.arn,
          "${aws_cloudwatch_log_group.flow_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.vpc_flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for standard AWS interface endpoints in ${var.vpc_name}"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }
}

resource "aws_security_group_rule" "vpc_endpoints_ingress" {
  for_each                 = toset(var.source_security_group_ids)
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = each.value
  security_group_id        = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group_rule" "vpc_endpoints_egress" {
  for_each                 = toset(var.source_security_group_ids)
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = each.value
  security_group_id        = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group" "custom_endpoints" {
  name        = "vpc-custom-endpoints-${var.vpc_name}"
  description = "Security group for custom interface endpoints in ${var.vpc_name}"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-custom-endpoints-${var.vpc_name}"
  }
}

resource "aws_security_group_rule" "custom_endpoints_ingress" {
  for_each                 = { for rule in local.custom_sg_rules : rule.key => rule }
  type                     = "ingress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  source_security_group_id = each.value.sg_id
  security_group_id        = aws_security_group.custom_endpoints.id
}

resource "aws_security_group_rule" "custom_endpoints_egress" {
  for_each                 = { for rule in local.custom_sg_rules : rule.key => rule }
  type                     = "egress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  source_security_group_id = each.value.sg_id
  security_group_id        = aws_security_group.custom_endpoints.id
}

resource "aws_vpc_endpoint" "gateway" {
  for_each          = var.gateway_endpoint_services
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.${each.value}"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = var.route_table_ids

  tags = {
    Name = "${var.vpc_name}-gw-${each.value}"
  }
}

resource "aws_vpc_endpoint" "aws_interface" {
  for_each            = var.aws_interface_endpoints
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.endpoint_subnet.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.vpc_name}-interface-${each.value}"
  }
}

resource "aws_vpc_endpoint" "custom_interface" {
  for_each            = var.custom_endpoint_services
  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  subnet_ids          = [aws_subnet.endpoint_subnet.id]
  security_group_ids  = [aws_security_group.custom_endpoints.id]

  tags = {
    Name = "${var.vpc_name}-custom-${each.key}"
  }
}

resource "aws_iam_role" "ssm" {
  count = local.enable_ssm ? 1 : 0
  name  = "ssm_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count      = local.enable_ssm ? 1 : 0
  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.enable_ssm ? 1 : 0
  name  = "ssm_${var.vpc_name}"
  role  = aws_iam_role.ssm[0].name

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "project_name" {
  type        = string
  description = "Project name prefix used for resource identification and KMS aliases."
  default     = "baseline-sec"
}

variable "kms_key_rotation_period_in_days" {
  type        = number
  description = "The rotation period in days for the KMS customer-managed keys."
  default     = 90
}

variable "external_default_ebs_kms_key_arn" {
  type        = string
  description = "Optional external KMS key ARN to use as the account-level default EBS encryption key. If empty, uses the internal compute KMS key."
  default     = ""
}

variable "enable_imdsv2_enforcement" {
  type        = bool
  description = "Toggle to enforce account-level EC2 instance metadata defaults (IMDSv2 required)."
  default     = true
}

variable "imdsv2_http_put_response_hop_limit" {
  type        = number
  description = "The HTTP PUT response hop limit for IMDSv2 default configuration."
  default     = 1
}

variable "disable_ec2_serial_console_access" {
  type        = bool
  description = "Toggle to disable EC2 serial console access account-wide."
  default     = true
}

variable "enable_emr_block_public_access" {
  type        = bool
  description = "Toggle to enforce account-level EMR block public access configuration."
  default     = true
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  default_ebs_key_arn = var.external_default_ebs_kms_key_arn != "" ? var.external_default_ebs_kms_key_arn : aws_kms_key.compute.arn
}

# -----------------------------------------------------------------------------
# Compute KMS Key & Policies
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "compute_kms" {
  # Root full administration
  statement {
    sid       = "EnableRootIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  # EC2 Service Access scoped to local account
  statement {
    sid    = "AllowEC2ServiceCryptographicOperations"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # Auto Scaling Service Linked Role Access
  statement {
    sid    = "AllowAutoScalingServiceOperations"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"]
    }
  }

  # Auto Scaling Grant Creation
  statement {
    sid    = "AllowAutoScalingGrantCreation"
    effect = "Allow"
    actions = [
      "kms:CreateGrant"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"]
    }

    condition {
      test     = "Bool"
      variable = "kms:GrantIsForAWSResource"
      values   = ["true"]
    }
  }
}

resource "aws_kms_key" "compute" {
  description             = "KMS CMK for Compute Layer (EC2, Auto Scaling, EBS)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.compute_kms.json

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "${var.project_name}-compute-kms"
    Layer   = "compute"
    Project = var.project_name
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

# -----------------------------------------------------------------------------
# Account-level EBS Encryption Defaults
# -----------------------------------------------------------------------------
resource "aws_ebs_encryption_by_default" "account" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "account" {
  key_arn    = local.default_ebs_key_arn
  depends_on = [aws_ebs_encryption_by_default.account]
}

# -----------------------------------------------------------------------------
# Observability KMS Key & Policies
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "observability_kms" {
  # Root administration
  statement {
    sid       = "EnableRootIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  # CloudWatch Logs
  statement {
    sid    = "AllowCloudWatchLogsUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt*",
      "kms:Describe*",
      "kms:Encrypt*",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }

  # CloudTrail
  statement {
    sid    = "AllowCloudTrailUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # CloudWatch Alarms
  statement {
    sid    = "AllowCloudWatchAlarmsUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # SNS
  statement {
    sid    = "AllowSNSUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # SQS
  statement {
    sid    = "AllowSQSUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # EventBridge
  statement {
    sid    = "AllowEventBridgeUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "observability" {
  description             = "KMS CMK for Observability Layer (CloudWatch, Logs, CloudTrail, Alarms, SNS, SQS, Events)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.observability_kms.json

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "${var.project_name}-observability-kms"
    Layer   = "observability"
    Project = var.project_name
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

# -----------------------------------------------------------------------------
# Storage KMS Key & Policies
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "storage_kms" {
  # Root administration
  statement {
    sid       = "EnableRootIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  # S3 Service Usage
  statement {
    sid    = "AllowS3ServiceUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # AWS Config Delivery
  statement {
    sid    = "AllowAWSConfigServiceUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # CloudTrail Log Encryption
  statement {
    sid    = "AllowCloudTrailLogEncryption"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "storage" {
  description             = "KMS CMK for Storage Layer (S3, Config, CloudTrail Log Delivery)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.storage_kms.json

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "${var.project_name}-storage-kms"
    Layer   = "storage"
    Project = var.project_name
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

# -----------------------------------------------------------------------------
# Account-Level Public Sharing & Security Controls
# -----------------------------------------------------------------------------

# Block public sharing of AMIs
resource "aws_ec2_image_block_public_access" "block_ami_sharing" {
  state = "block-new-sharing"
}

# Block public sharing of EBS Snapshots
resource "aws_ebs_snapshot_block_public_access" "block_snapshot_sharing" {
  state = "block-all-sharing"
}

# Enforce IMDSv2 metadata defaults
resource "aws_ec2_instance_metadata_defaults" "enforce_imdsv2" {
  count                       = var.enable_imdsv2_enforcement ? 1 : 0
  http_tokens                 = "required"
  http_put_response_hop_limit = var.imdsv2_http_put_response_hop_limit
}

# Disable EC2 Serial Console access
resource "aws_ec2_serial_console_access" "disable_serial_console" {
  count   = var.disable_ec2_serial_console_access ? 1 : 0
  enabled = false
}

# Configure EMR Block Public Access
resource "aws_emr_block_public_access_configuration" "emr_bpa" {
  count                             = var.enable_emr_block_public_access ? 1 : 0
  block_public_security_group_rules = true
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "compute_kms_key_arn" {
  description = "ARN of the compute layer KMS customer-managed key."
  value       = aws_kms_key.compute.arn
}

output "compute_kms_key_alias" {
  description = "Alias of the compute layer KMS key."
  value       = aws_kms_alias.compute.name
}

output "observability_kms_key_arn" {
  description = "ARN of the observability layer KMS customer-managed key."
  value       = aws_kms_key.observability.arn
}

output "observability_kms_key_alias" {
  description = "Alias of the observability layer KMS key."
  value       = aws_kms_alias.observability.name
}

output "storage_kms_key_arn" {
  description = "ARN of the storage layer KMS customer-managed key."
  value       = aws_kms_key.storage.arn
}

output "storage_kms_key_alias" {
  description = "Alias of the storage layer KMS key."
  value       = aws_kms_alias.storage.name
}

output "default_ebs_kms_key_arn" {
  description = "The KMS key ARN set as the default EBS encryption key for the account."
  value       = aws_ebs_default_kms_key.account.key_arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "cluster_prefix" {
  description = "Resource prefix for all cluster components (5 to 8 characters)"
  type        = string
  default     = "bench"

  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "The cluster_prefix must be between 5 and 8 characters long."
  }
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "ssh_public_key" {
  description = "Optional public SSH key for instance authentication. If not provided, a key pair is generated dynamically."
  type        = string
  default     = null
}

variable "public_subnets" {
  description = "List of public subnet configurations"
  type = list(object({
    name_suffix = string
    az_index    = number
    netnum      = number
  }))
  default = [
    {
      name_suffix = "pub-a"
      az_index    = 0
      netnum      = 1
    },
    {
      name_suffix = "pub-b"
      az_index    = 1
      netnum      = 2
    }
  ]
}

variable "private_subnets" {
  description = "List of private subnet configurations"
  type = list(object({
    name_suffix = string
    az_index    = number
    netnum      = number
  }))
  default = [
    {
      name_suffix = "priv-a"
      az_index    = 0
      netnum      = 10
    },
    {
      name_suffix = "priv-b"
      az_index    = 1
      netnum      = 11
    }
  ]
}

variable "custom_ingress_rules" {
  description = "Custom ingress rules for the security group"
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      description = "Allow inbound SSH from internal test range"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.16.0.0/16"]
    }
  ]
}

variable "inventory_nodes" {
  description = "List of compute nodes to provision with storage and network options"
  type = list(object({
    name               = string
    instance_type      = string
    subnet_type        = string # "public" or "private"
    subnet_index       = number
    allocate_public_ip = bool
    root_volume_size   = number
    root_volume_type   = string
    secondary_volumes = list(object({
      device_name = string
      size_gb     = number
      type        = string
    }))
  }))
  default = [
    {
      name               = "node-master"
      instance_type      = "t3.medium"
      subnet_type        = "public"
      subnet_index       = 0
      allocate_public_ip = true
      root_volume_size   = 30
      root_volume_type   = "gp3"
      secondary_volumes = [
        {
          device_name = "/dev/xvdf"
          size_gb     = 50
          type        = "gp3"
        }
      ]
    },
    {
      name               = "node-worker"
      instance_type      = "t3.medium"
      subnet_type        = "private"
      subnet_index       = 0
      allocate_public_ip = false
      root_volume_size   = 30
      root_volume_type   = "gp3"
      secondary_volumes = [
        {
          device_name = "/dev/xvdg"
          size_gb     = 100
          type        = "gp3"
        }
      ]
    }
  ]
}

# -----------------------------------------------------------------------------
# Key Pair
# -----------------------------------------------------------------------------
resource "tls_private_key" "benchmark" {
  algorithm = "ED25519"
}

resource "aws_key_pair" "benchmark" {
  key_name   = "${var.cluster_prefix}-keypair"
  public_key = var.ssh_public_key != null ? var.ssh_public_key : tls_private_key.benchmark.public_key_openssh

  tags = {
    Name    = "${var.cluster_prefix}-keypair"
    Cluster = var.cluster_prefix
  }
}

# -----------------------------------------------------------------------------
# VPC and Networking
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name    = "${var.cluster_prefix}-vpc"
    Cluster = var.cluster_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "${var.cluster_prefix}-igw"
    Cluster = var.cluster_prefix
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnets)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, var.public_subnets[count.index].netnum)
  availability_zone       = data.aws_availability_zones.available.names[var.public_subnets[count.index].az_index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "${var.cluster_prefix}-${var.public_subnets[count.index].name_suffix}"
    Cluster = var.cluster_prefix
    Type    = "public"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnets)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, var.private_subnets[count.index].netnum)
  availability_zone       = data.aws_availability_zones.available.names[var.private_subnets[count.index].az_index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "${var.cluster_prefix}-${var.private_subnets[count.index].name_suffix}"
    Cluster = var.cluster_prefix
    Type    = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name    = "${var.cluster_prefix}-public-rt"
    Cluster = var.cluster_prefix
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnets)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = length(var.public_subnets)
  domain = "vpc"

  tags = {
    Name    = "${var.cluster_prefix}-nat-eip-${count.index}"
    Cluster = var.cluster_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = length(var.public_subnets)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name    = "${var.cluster_prefix}-natgw-${count.index}"
    Cluster = var.cluster_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnets)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index % length(var.public_subnets)].id
  }

  tags = {
    Name    = "${var.cluster_prefix}-private-rt-${count.index}"
    Cluster = var.cluster_prefix
  }
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnets)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "cluster" {
  name        = "${var.cluster_prefix}-cluster-sg"
  description = "Cluster security group for deployment and intra-cluster communication"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name    = "${var.cluster_prefix}-cluster-sg"
    Cluster = var.cluster_prefix
  }
}

resource "aws_vpc_security_group_ingress_rule" "self_all" {
  security_group_id            = aws_security_group.cluster.id
  description                  = "Self-referencing intra-group ingress"
  referenced_security_group_id = aws_security_group.cluster.id
  ip_protocol                  = "-1"

  tags = {
    Name = "${var.cluster_prefix}-ingress-self"
  }
}

resource "aws_vpc_security_group_ingress_rule" "custom" {
  count             = length(var.custom_ingress_rules)
  security_group_id = aws_security_group.cluster.id
  description       = var.custom_ingress_rules[count.index].description
  ip_protocol       = var.custom_ingress_rules[count.index].protocol
  from_port         = var.custom_ingress_rules[count.index].from_port
  to_port           = var.custom_ingress_rules[count.index].to_port
  cidr_ipv4         = var.custom_ingress_rules[count.index].cidr_blocks[0]

  tags = {
    Name = "${var.cluster_prefix}-custom-ingress-${count.index}"
  }
}

resource "aws_vpc_security_group_egress_rule" "vpc_internal" {
  security_group_id = aws_security_group.cluster.id
  description       = "Allow outbound traffic only strictly within VPC CIDR block"
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "-1"

  tags = {
    Name = "${var.cluster_prefix}-egress-vpc"
  }
}

# -----------------------------------------------------------------------------
# Compute Nodes (Inventory)
# -----------------------------------------------------------------------------
resource "aws_instance" "node" {
  count         = length(var.inventory_nodes)
  ami           = data.aws_ami.al2023.id
  instance_type = var.inventory_nodes[count.index].instance_type
  key_name      = aws_key_pair.benchmark.key_name
  ebs_optimized = true

  subnet_id = (
    var.inventory_nodes[count.index].subnet_type == "public"
    ? aws_subnet.public[var.inventory_nodes[count.index].subnet_index].id
    : aws_subnet.private[var.inventory_nodes[count.index].subnet_index].id
  )

  vpc_security_group_ids = [aws_security_group.cluster.id]

  root_block_device {
    volume_size           = var.inventory_nodes[count.index].root_volume_size
    volume_type           = var.inventory_nodes[count.index].root_volume_type
    encrypted             = true
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = {
    Name    = "${var.cluster_prefix}-${var.inventory_nodes[count.index].name}"
    Cluster = var.cluster_prefix
  }
}

# -----------------------------------------------------------------------------
# Optional Elastic IPs for Inventory Nodes
# -----------------------------------------------------------------------------
locals {
  public_ip_nodes = {
    for idx, node in var.inventory_nodes :
    node.name => idx if node.allocate_public_ip
  }
}

resource "aws_eip" "node_eip" {
  for_each = local.public_ip_nodes
  domain   = "vpc"

  tags = {
    Name    = "${var.cluster_prefix}-${each.key}-eip"
    Cluster = var.cluster_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_eip_association" "node_eip_assoc" {
  for_each      = local.public_ip_nodes
  instance_id   = aws_instance.node[each.value].id
  allocation_id = aws_eip.node_eip[each.key].id
}

# -----------------------------------------------------------------------------
# Secondary EBS Volumes & Attachments
# -----------------------------------------------------------------------------
locals {
  secondary_volumes = flatten([
    for node_idx, node in var.inventory_nodes : [
      for vol_idx, vol in node.secondary_volumes : {
        key          = "${node.name}-${vol_idx}"
        node_idx     = node_idx
        device_name  = vol.device_name
        size_gb      = vol.size_gb
        type         = vol.type
        subnet_type  = node.subnet_type
        subnet_index = node.subnet_index
      }
    ]
  ])
  secondary_volumes_map = {
    for vol in local.secondary_volumes : vol.key => vol
  }
}

resource "aws_ebs_volume" "secondary" {
  for_each = local.secondary_volumes_map

  availability_zone = (
    each.value.subnet_type == "public"
    ? aws_subnet.public[each.value.subnet_index].availability_zone
    : aws_subnet.private[each.value.subnet_index].availability_zone
  )
  size      = each.value.size_gb
  type      = each.value.type
  encrypted = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "${var.cluster_prefix}-${each.key}"
    Cluster = var.cluster_prefix
  }
}

resource "aws_volume_attachment" "secondary_attach" {
  for_each    = local.secondary_volumes_map
  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.secondary[each.key].id
  instance_id = aws_instance.node[each.value.node_idx].id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the provisioned VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "cluster_security_group_id" {
  description = "ID of the cluster security group"
  value       = aws_security_group.cluster.id
}

output "instance_ids" {
  description = "IDs of the provisioned inventory compute nodes"
  value       = { for idx, node in var.inventory_nodes : node.name => aws_instance.node[idx].id }
}

output "instance_public_ips" {
  description = "Allocated Elastic IPs for public compute nodes"
  value       = { for k, v in aws_eip.node_eip : k => v.public_ip }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for provisioning resources"
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "Name tag for the VPC and related resources"
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "List of 4 CIDR allocations for subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
}

variable "enable_private_subnets" {
  type        = bool
  description = "Toggles between 2 public + 2 private subnets (true) or 4 public subnets (false)"
  default     = true
}

variable "enable_nat_gateway" {
  type        = bool
  description = "Deploy redundant NAT Gateways across public subnets for private outbound traffic"
  default     = true
}

variable "enable_nat_instance" {
  type        = bool
  description = "Deploy redundant NAT EC2 instances across public subnets for private outbound traffic"
  default     = false
}

variable "enable_egress_only_igw" {
  type        = bool
  description = "Deploy an Egress-Only Internet Gateway for IPv6 traffic"
  default     = false
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "nat" {
  most_recent        = true
  include_deprecated = true
  owners             = ["amazon", "137112412989"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat*"]
  }
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress {
    protocol  = "-1"
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    protocol  = "-1"
    self      = true
    from_port = 0
    to_port   = 0
  }

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

resource "aws_security_group" "tls" {
  name        = "${var.vpc_name}-tls-sg"
  description = "Allow inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.main.id

  ingress {
    description      = "Inbound TLS from IPv4"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  egress {
    description = "Outbound TLS to internal VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-tls-sg"
  }
}

resource "aws_security_group" "nat_instance" {
  count       = var.enable_private_subnets && var.enable_nat_instance ? 1 : 0
  name        = "${var.vpc_name}-nat-instance-sg"
  description = "Security group for NAT EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP ingress from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTPS ingress from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow egress restricted to internal VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-nat-instance-sg"
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count                           = var.enable_private_subnets ? 2 : 4
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.subnet_cidrs[count.index]
  availability_zone               = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)

  tags = {
    Name = "${var.vpc_name}-public-subnet-${count.index + 1}"
    Type = "Public"
  }
}

resource "aws_subnet" "private" {
  count                           = var.enable_private_subnets ? 2 : 0
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.subnet_cidrs[count.index + 2]
  availability_zone               = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 2)

  tags = {
    Name = "${var.vpc_name}-private-subnet-${count.index + 1}"
    Type = "Private"
  }
}

# -----------------------------------------------------------------------------
# Public Routing
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Egress Infrastructure (NAT Gateways, NAT Instances, Egress-Only IGW)
# -----------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count  = var.enable_private_subnets && var.enable_nat_gateway ? 2 : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = var.enable_private_subnets && var.enable_nat_gateway ? 2 : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_instance" "nat" {
  count                  = var.enable_private_subnets && var.enable_nat_instance ? 2 : 0
  ami                    = data.aws_ami.nat.id
  instance_type          = "m1.small"
  subnet_id              = aws_subnet.public[count.index].id
  source_dest_check      = false
  vpc_security_group_ids = [aws_security_group.nat_instance[0].id]

  tags = {
    Name = "${var.vpc_name}-nat-instance-${count.index + 1}"
  }
}

resource "aws_egress_only_internet_gateway" "main" {
  count  = var.enable_private_subnets && var.enable_egress_only_igw ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-eigw"
  }
}

# -----------------------------------------------------------------------------
# Private Routing
# -----------------------------------------------------------------------------

resource "aws_route_table" "private" {
  count  = var.enable_private_subnets ? 2 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route" "private_nat_gateway" {
  count                  = var.enable_private_subnets && var.enable_nat_gateway ? 2 : 0
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route" "private_nat_instance" {
  count                  = var.enable_private_subnets && var.enable_nat_instance && !var.enable_nat_gateway ? 2 : 0
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_instance.nat[count.index].primary_network_interface_id
}

resource "aws_route" "private_ipv6_eigw" {
  count                       = var.enable_private_subnets && var.enable_egress_only_igw ? 2 : 0
  route_table_id              = aws_route_table.private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

resource "aws_route_table_association" "private" {
  count          = var.enable_private_subnets ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "environment" {
  type        = string
  description = "Deployment environment name"
  default     = "benchmark"
}

variable "primary_region" {
  type        = string
  description = "Primary AWS region"
  default     = "us-east-1"
}

variable "secondary_region" {
  type        = string
  description = "Secondary AWS region for disaster recovery"
  default     = "us-west-2"
}

variable "log_glacier_transition_days" {
  type        = number
  description = "Number of days before transitioning access logs to Glacier"
  default     = 7
}

variable "log_expiration_days" {
  type        = number
  description = "Number of days before expiring access logs"
  default     = 30
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

resource "random_id" "suffix" {
  byte_length = 4
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# KMS Keys & Aliases
# -----------------------------------------------------------------------------

resource "aws_kms_key" "primary_state" {
  description             = "KMS key for primary Terraform state bucket in ${var.primary_region}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = var.environment
    Region      = var.primary_region
  }
}

resource "aws_kms_alias" "primary_state" {
  name          = "alias/${var.environment}-state-key-${var.primary_region}-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.primary_state.key_id
}

resource "aws_kms_key" "secondary_state" {
  provider                = aws.secondary
  description             = "KMS key for secondary Terraform state bucket in ${var.secondary_region}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = var.environment
    Region      = var.secondary_region
  }
}

resource "aws_kms_alias" "secondary_state" {
  provider      = aws.secondary
  name          = "alias/${var.environment}-state-key-${var.secondary_region}-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.secondary_state.key_id
}

# -----------------------------------------------------------------------------
# Primary S3 Buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "logs" {
  bucket        = "${var.environment}-tfstate-logs-${local.account_id}-${var.primary_region}-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Environment = var.environment
    Role        = "AccessLogs"
    Region      = var.primary_region
  }
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "logs" {
  depends_on = [
    aws_s3_bucket_ownership_controls.logs,
    aws_s3_bucket_public_access_block.logs,
  ]

  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "transition-and-expire-access-logs"
    status = "Enabled"

    filter {}

    transition {
      days          = var.log_glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.log_expiration_days
    }

    noncurrent_version_transition {
      noncurrent_days = var.log_glacier_transition_days
      storage_class   = "GLACIER"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.log_expiration_days
    }
  }
}

resource "aws_s3_bucket" "state" {
  bucket        = "${var.environment}-tfstate-${local.account_id}-${var.primary_region}-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Environment = var.environment
    Role        = "StateStorage"
    Region      = var.primary_region
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary_state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "state-access-logs/"
}

# -----------------------------------------------------------------------------
# Secondary (Replica) S3 Buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "logs_replica" {
  provider      = aws.secondary
  bucket        = "${var.environment}-tfstate-logs-${local.account_id}-${var.secondary_region}-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Environment = var.environment
    Role        = "AccessLogsReplica"
    Region      = var.secondary_region
  }
}

resource "aws_s3_bucket_ownership_controls" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "logs_replica" {
  provider = aws.secondary
  depends_on = [
    aws_s3_bucket_ownership_controls.logs_replica,
    aws_s3_bucket_public_access_block.logs_replica,
  ]

  bucket = aws_s3_bucket.logs_replica.id
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_versioning" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  rule {
    id     = "transition-and-expire-replica-logs"
    status = "Enabled"

    filter {}

    transition {
      days          = var.log_glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.log_expiration_days
    }

    noncurrent_version_transition {
      noncurrent_days = var.log_glacier_transition_days
      storage_class   = "GLACIER"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.log_expiration_days
    }
  }
}

resource "aws_s3_bucket" "state_replica" {
  provider      = aws.secondary
  bucket        = "${var.environment}-tfstate-${local.account_id}-${var.secondary_region}-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Environment = var.environment
    Role        = "StateStorageReplica"
    Region      = var.secondary_region
  }
}

resource "aws_s3_bucket_public_access_block" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary_state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# S3 Bucket Policies for State Buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RestrictToAccount"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = local.account_id
          }
        }
      },
      {
        Sid       = "EnforceBucketOwnerFullControl"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_policy" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RestrictToAccount"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state_replica.arn,
          "${aws_s3_bucket.state_replica.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = local.account_id
          }
        }
      },
      {
        Sid       = "EnforceBucketOwnerFullControl"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.state_replica.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Replication IAM Role & Policies
# -----------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  name = "${var.environment}-s3-crr-role-${var.primary_region}-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = var.environment
    Role        = "Replication"
  }
}

resource "aws_iam_policy" "replication" {
  name        = "${var.environment}-s3-crr-policy-${var.primary_region}-${random_id.suffix.hex}"
  description = "IAM policy granting S3 permission to replicate state and logs across regions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.state.arn,
          aws_s3_bucket.logs.arn
        ]
      },
      {
        Sid    = "SourceObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectRetention",
          "s3:GetObjectLegalHold"
        ]
        Resource = [
          "${aws_s3_bucket.state.arn}/*",
          "${aws_s3_bucket.logs.arn}/*"
        ]
      },
      {
        Sid    = "DestinationObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "${aws_s3_bucket.state_replica.arn}/*",
          "${aws_s3_bucket.logs_replica.arn}/*"
        ]
      },
      {
        Sid    = "SourceKMSDecryption"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          aws_kms_key.primary_state.arn
        ]
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.primary_region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "DestinationKMSEncryption"
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = [
          aws_kms_key.secondary_state.arn
        ]
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.secondary_region}.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# -----------------------------------------------------------------------------
# Cross-Region Replication Configurations
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "state" {
  depends_on = [aws_s3_bucket_versioning.state]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "state-crr-rule"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.state_replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary_state.arn
      }

      access_control_translation {
        owner = "Destination"
      }

      account = local.account_id
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "logs" {
  depends_on = [aws_s3_bucket_versioning.logs]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "logs-crr-rule"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.logs_replica.arn
      storage_class = "STANDARD"

      access_control_translation {
        owner = "Destination"
      }

      account = local.account_id
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "Optional existing VPC ID to attach resources to. If empty, a new VPC is created."
  type        = string
  default     = ""
}

variable "name" {
  description = "Name prefix for VPC resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24"]
}

variable "database_subnet_cidrs" {
  description = "CIDR blocks for database subnets."
  type        = list(string)
  default     = ["10.0.30.0/24", "10.0.40.0/24"]
}

variable "existing_public_subnet_ids" {
  description = "List of existing public subnet IDs to use instead of creating new ones."
  type        = list(string)
  default     = []
}

variable "existing_private_subnet_ids" {
  description = "List of existing private subnet IDs to use instead of creating new ones."
  type        = list(string)
  default     = []
}

variable "existing_database_subnet_ids" {
  description = "List of existing database subnet IDs to use instead of creating new ones."
  type        = list(string)
  default     = []
}

variable "existing_nat_gateway_id" {
  description = "Optional existing NAT Gateway ID for private routing."
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "Optional existing Security Group ID for VPC interface endpoints."
  type        = string
  default     = ""
}

variable "vpc_endpoint_services" {
  description = "List of AWS service names for interface VPC endpoints."
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  create_vpc              = var.vpc_id == ""
  create_public_subnets   = length(var.existing_public_subnet_ids) == 0
  create_private_subnets  = length(var.existing_private_subnet_ids) == 0
  create_database_subnets = length(var.existing_database_subnet_ids) == 0
  create_nat_gateway      = var.existing_nat_gateway_id == "" && local.create_vpc
  create_endpoint_sg      = var.existing_security_group_id == ""

  vpc_id   = local.create_vpc ? aws_vpc.main[0].id : var.vpc_id
  vpc_cidr = var.vpc_cidr

  public_subnet_ids   = local.create_public_subnets ? aws_subnet.public[*].id : var.existing_public_subnet_ids
  private_subnet_ids  = local.create_private_subnets ? aws_subnet.private[*].id : var.existing_private_subnet_ids
  database_subnet_ids = local.create_database_subnets ? aws_subnet.database[*].id : var.existing_database_subnet_ids

  nat_gateway_id             = local.create_nat_gateway ? aws_nat_gateway.main[0].id : var.existing_nat_gateway_id
  endpoint_security_group_id = local.create_endpoint_sg ? aws_security_group.vpc_endpoints[0].id : var.existing_security_group_id
}

resource "aws_vpc" "main" {
  count                = local.create_vpc ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "public" {
  count                   = local.create_public_subnets ? length(var.public_subnet_cidrs) : 0
  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-public-${data.aws_availability_zones.available.names[count.index]}"
    Type = "public"
  }
}

resource "aws_subnet" "private" {
  count                   = local.create_private_subnets ? length(var.private_subnet_cidrs) : 0
  vpc_id                  = local.vpc_id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-private-${data.aws_availability_zones.available.names[count.index]}"
    Type = "private"
  }
}

resource "aws_subnet" "database" {
  count                   = local.create_database_subnets ? length(var.database_subnet_cidrs) : 0
  vpc_id                  = local.vpc_id
  cidr_block              = var.database_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-database-${data.aws_availability_zones.available.names[count.index]}"
    Type = "database"
  }
}

resource "aws_db_subnet_group" "main" {
  name        = "${lower(var.name)}-db-subnet-group"
  description = "Database subnet group for ${var.name}"
  subnet_ids  = local.database_subnet_ids

  tags = {
    Name = "${lower(var.name)}-db-subnet-group"
  }
}

resource "aws_internet_gateway" "main" {
  count  = local.create_vpc ? 1 : 0
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-igw"
  }
}

resource "aws_eip" "nat" {
  count  = local.create_nat_gateway ? 1 : 0
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-eip"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = local.create_nat_gateway ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = local.public_subnet_ids[0]

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  count  = local.create_public_subnets ? 1 : 0
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${var.name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.create_public_subnets ? length(local.public_subnet_ids) : 0
  subnet_id      = local.public_subnet_ids[count.index]
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count  = local.create_private_subnets ? 1 : 0
  vpc_id = local.vpc_id

  dynamic "route" {
    for_each = local.nat_gateway_id != "" ? [local.nat_gateway_id] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = route.value
    }
  }

  tags = {
    Name = "${var.name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.create_private_subnets ? length(local.private_subnet_ids) : 0
  subnet_id      = local.private_subnet_ids[count.index]
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table" "database" {
  count  = local.create_database_subnets ? 1 : 0
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-database-rt"
  }
}

resource "aws_route_table_association" "database" {
  count          = local.create_database_subnets ? length(local.database_subnet_ids) : 0
  subnet_id      = local.database_subnet_ids[count.index]
  route_table_id = aws_route_table.database[0].id
}

resource "aws_security_group" "vpc_endpoints" {
  count       = local.create_endpoint_sg ? 1 : 0
  name        = "${var.name}-vpc-endpoints"
  description = "Security group for VPC interface endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "Allow HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow outbound to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(var.vpc_endpoint_services)

  vpc_id              = local.vpc_id
  vpc_endpoint_type   = "Interface"
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_security_group_id]
  private_dns_enabled = each.value != "s3"

  tags = {
    Name = "${var.name}-endpoint-${replace(each.value, ".", "-")}"
  }
}

output "vpc_id" {
  description = "ID of the VPC used"
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = local.public_subnet_ids
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = local.private_subnet_ids
}

output "database_subnet_ids" {
  description = "IDs of the database subnets"
  value       = local.database_subnet_ids
}

output "db_subnet_group_name" {
  description = "Name of the RDS database subnet group"
  value       = aws_db_subnet_group.main.name
}

output "endpoint_security_group_id" {
  description = "ID of the security group attached to VPC endpoints"
  value       = local.endpoint_security_group_id
}

output "vpc_endpoint_ids" {
  description = "Map of interface VPC endpoint IDs"
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_shortcode" {
  type        = string
  description = "Application shortcode prefix for naming resources"
  default     = "bmk"
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.8.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.app_shortcode}-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.8.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.app_shortcode}-private-subnet"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.app_shortcode}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${var.app_shortcode}-vpce-sg"
  description = "Security group for VPC Interface Endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow TLS inbound from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.app_shortcode}-vpce-sg"
  }
}

resource "aws_security_group" "instance" {
  name        = "${var.app_shortcode}-instance-sg"
  description = "Security group for test EC2 instance"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow TLS outbound to VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.app_shortcode}-instance-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.app_shortcode}-vpce-ssm"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ec2messages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.app_shortcode}-vpce-ec2messages"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.app_shortcode}-vpce-ssmmessages"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.app_shortcode}-vpce-logs"
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "instance_permissions" {
  statement {
    sid    = "SSMAndMessagesAccess"
    effect = "Allow"
    actions = [
      "ssm:DescribeAssociation",
      "ssm:GetDeployablePatchSnapshotForInstance",
      "ssm:GetDocument",
      "ssm:DescribeDocument",
      "ssm:GetManifest",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:ListAssociations",
      "ssm:ListInstanceAssociations",
      "ssm:PutInventory",
      "ssm:PutComplianceItems",
      "ssm:PutConfigurePackageResult",
      "ssm:UpdateAssociationStatus",
      "ssm:UpdateInstanceAssociationStatus",
      "ssm:UpdateInstanceInformation",
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel",
      "ec2messages:AcknowledgeMessage",
      "ec2messages:DeleteMessage",
      "ec2messages:FailMessage",
      "ec2messages:GetEndpoint",
      "ec2messages:GetMessages",
      "ec2messages:SendReply"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:*:log-group:/aws/ssm/*",
      "arn:aws:logs:${data.aws_region.current.name}:*:log-group:/aws/ssm/*:log-stream:*"
    ]
  }

  statement {
    sid    = "KMSGenerateDataKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*"
    ]
    resources = [
      "arn:aws:kms:${data.aws_region.current.name}:*:key/*"
    ]
  }

  statement {
    sid    = "S3ObjectActions"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = [
      "arn:aws:s3:::*/*"
    ]
  }
}

resource "aws_iam_role" "instance" {
  name_prefix        = "${var.app_shortcode}-role-"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_policy" "instance" {
  name_prefix = "${var.app_shortcode}-policy-"
  description = "IAM policy granting permissions for SSM, CloudWatch Logs, KMS, and S3"
  policy      = data.aws_iam_policy_document.instance_permissions.json
}

resource "aws_iam_role_policy_attachment" "instance" {
  role       = aws_iam_role.instance.name
  policy_arn = aws_iam_policy.instance.arn
}

resource "aws_iam_instance_profile" "instance" {
  name_prefix = "${var.app_shortcode}-profile-"
  role        = aws_iam_role.instance.name
}

resource "aws_instance" "test" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = "t3.small"
  subnet_id            = aws_subnet.private.id
  iam_instance_profile = aws_iam_instance_profile.instance.name
  source_dest_check    = false

  vpc_security_group_ids = [aws_security_group.instance.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
  }

  tags = {
    Name = "${var.app_shortcode}-test-instance"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_cidr               = "10.0.0.0/16"
  public_subnet_cidrs    = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_subnet_cidrs   = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
  namespace_name         = "private-fargate-crowdnews.hands-on.cloud.local"
  service_discovery_name = "nginx"
  jumphost_static_ip     = "10.0.1.100"
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# --- VPC and Networking ---

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "fargate-private-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "fargate-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "fargate-private-subnet-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "fargate-nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "fargate-nat-gateway-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "fargate-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "fargate-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# --- VPC Endpoints ---

resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-sg"
  description = "Allow inbound HTTPS from VPC CIDR to VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "vpc-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "s3-gateway-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "ecr-dkr-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "logs-endpoint"
  }
}

resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "secretsmanager-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "kms-endpoint"
  }
}

# --- Service Discovery (Cloud Map) ---

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = local.namespace_name
  description = "Private DNS namespace for internal Fargate services"
  vpc         = aws_vpc.main.id
}

resource "aws_service_discovery_service" "main" {
  name = local.service_discovery_name

  dns_config {
    namespace_id   = aws_service_discovery_private_dns_namespace.main.id
    routing_policy = "MULTIVALUE"

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }
  }

  health_check_custom_config {
    failure_threshold = 1
  }
}

# --- ECR Repository ---

resource "aws_ecr_repository" "nginx" {
  name                 = "nginx-private-fargate"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Name = "nginx-private-fargate"
  }
}

# --- CloudWatch Log Group ---

resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/nginx-private-fargate"
  retention_in_days = 30

  tags = {
    Name = "nginx-private-fargate-logs"
  }
}

# --- ECS Cluster ---

resource "aws_ecs_cluster" "main" {
  name = "private-fargate-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name = "private-fargate-cluster"
  }
}

# --- IAM Roles for ECS ---

resource "aws_iam_role" "ecs_execution_role" {
  name = "nginx-fargate-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_role_policy" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy" "ecs_execution_inline" {
  name = "nginx-fargate-execution-inline"
  role = aws_iam_role.ecs_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.ecs.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_task_role" {
  name = "nginx-fargate-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_inline" {
  name = "nginx-fargate-task-inline"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "ssm:GetParameter",
          "ssm:GetParametersByPath"
        ]
        Resource = "arn:aws:ssm:${data.aws_region.current.name}:*:parameter/*"
      },
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:DiscoverInstances",
          "servicediscovery:GetInstance",
          "servicediscovery:ListInstances"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      }
    ]
  })
}

# --- ECS Task Definition and Security Group ---

resource "aws_security_group" "ecs_tasks" {
  name        = "nginx-fargate-tasks-sg"
  description = "Allow inbound HTTP from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "nginx-fargate-tasks-sg"
  }
}

resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx-private-service"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution_role.arn
  task_role_arn            = aws_iam_role.ecs_task_role.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "public.ecr.aws/nginx/nginx:latest"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])
}

# --- ECS Service ---

resource "aws_ecs_service" "nginx" {
  name            = "nginx-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.main.arn
    container_name = "nginx"
    container_port = 80
  }
}

# --- SSM Jumphost EC2 Instance ---

resource "aws_iam_role" "jumphost" {
  name = "ssm-jumphost-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "ssm-jumphost-instance-profile"
  role = aws_iam_role.jumphost.name
}

resource "aws_security_group" "jumphost" {
  name        = "ssm-jumphost-sg"
  description = "Security group for SSM Jumphost"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all inbound from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "ssm-jumphost-sg"
  }
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = [local.jumphost_static_ip]
  security_groups = [aws_security_group.jumphost.id]

  tags = {
    Name = "ssm-jumphost-eni"
  }
}

resource "aws_instance" "jumphost" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  root_block_device {
    encrypted = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }

  tags = {
    Name = "ssm-jumphost"
  }
}

# --- Output ---

output "curl_command" {
  description = "Curl command to query the NGINX service internally via Cloud Map private DNS"
  value       = "curl http://${local.service_discovery_name}.${local.namespace_name}"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "project" {
  type        = string
  description = "Project name identifier"
  default     = "benchmark"
}

variable "application" {
  type        = string
  description = "Application name identifier"
  default     = "compute"
}

variable "environment" {
  type        = string
  description = "Environment identifier (e.g. dev, prod)"
  default     = "dev"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "allocate_eip" {
  type        = bool
  description = "Toggle to allocate and associate a static Elastic IP with the instance ENI"
  default     = true
}

variable "enable_ssh_key" {
  type        = bool
  description = "Toggle to conditionally generate a TLS private key and AWS key pair"
  default     = false
}

variable "attach_ssm_managed_policy" {
  type        = bool
  description = "Toggle to conditionally attach the AWS managed AmazonSSMManagedInstanceCore policy"
  default     = true
}

variable "custom_routes" {
  type = list(object({
    destination_cidr_block = string
    gateway_id             = optional(string)
  }))
  description = "Optional list of additional routes to inject into the public route table"
  default     = []
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------

locals {
  selected_az = data.aws_availability_zones.available.names[0]
  name_prefix = "${var.project}-${var.application}-${var.environment}"
  az_suffix   = local.selected_az
  common_tags = {
    Project     = var.project
    Application = var.application
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.selected_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix}-subnet-public-${local.az_suffix}"
    AvailabilityZone = local.selected_az
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt-public"
  })
}

resource "aws_route" "custom" {
  count                  = length(var.custom_routes)
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = var.custom_routes[count.index].destination_cidr_block
  gateway_id             = var.custom_routes[count.index].gateway_id != null ? var.custom_routes[count.index].gateway_id : aws_internet_gateway.gw.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Security group for benchmark EC2 instance"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound HTTPS traffic restricted to internal VPC addresses"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound HTTP traffic restricted to internal VPC addresses"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

resource "aws_network_interface" "instance_nic" {
  subnet_id       = aws_subnet.public.id
  security_groups = [aws_security_group.instance.id]

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix}-eni-${local.az_suffix}"
    AvailabilityZone = local.selected_az
  })
}

resource "aws_eip" "instance_eip" {
  count             = var.allocate_eip ? 1 : 0
  domain            = "vpc"
  network_interface = aws_network_interface.instance_nic.id

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix}-eip-${local.az_suffix}"
    AvailabilityZone = local.selected_az
  })

  depends_on = [
    aws_internet_gateway.gw,
    aws_instance.benchmark
  ]
}

# -----------------------------------------------------------------------------
# Optional SSH Key Pair
# -----------------------------------------------------------------------------

resource "tls_private_key" "ssh" {
  count     = var.enable_ssh_key ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "generated_key" {
  count      = var.enable_ssh_key ? 1 : 0
  key_name   = "${local.name_prefix}-keypair"
  public_key = tls_private_key.ssh[0].public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-keypair"
  })
}

# -----------------------------------------------------------------------------
# IAM Identity & Policies
# -----------------------------------------------------------------------------

resource "aws_iam_role" "instance_role" {
  name = "${local.name_prefix}-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ssm.amazonaws.com"
          ]
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-role"
  })
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-policy"
  description = "SSM Session Manager policy granting control and data channel permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SSMDataAndControlChannels"
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMInstanceStatus"
        Effect = "Allow"
        Action = [
          "ssm:UpdateInstanceInformation"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMTelemetriesAndAssociation"
        Effect = "Allow"
        Action = [
          "ssm:GetDocument",
          "ssm:DescribeDocument",
          "ssm:GetDeployablePatchSnapshotForInstance",
          "ssm:GetParameters",
          "ssm:ListAssociations",
          "ssm:ListInstanceAssociations",
          "ssm:PutInventory",
          "ssm:PutComplianceItems",
          "ssm:PutConfigurePackageResult",
          "ssm:UpdateAssociationStatus",
          "ssm:UpdateInstanceAssociationStatus"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2MessagesChannels"
        Effect = "Allow"
        Action = [
          "ec2messages:AcknowledgeMessage",
          "ec2messages:DeleteMessage",
          "ec2messages:FailMessage",
          "ec2messages:GetEndpoint",
          "ec2messages:GetMessages",
          "ec2messages:SendReply"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-policy"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.instance_role.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  count      = var.attach_ssm_managed_policy ? 1 : 0
  role       = aws_iam_role.instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "instance_profile" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.instance_role.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-profile"
  })
}

# -----------------------------------------------------------------------------
# Compute (EC2 Instance)
# -----------------------------------------------------------------------------

resource "aws_instance" "benchmark" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.instance_profile.name
  key_name             = var.enable_ssh_key ? aws_key_pair.generated_key[0].key_name : null

  network_interface {
    network_interface_id = aws_network_interface.instance_nic.id
    device_index         = 0
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  volume_tags = merge(local.common_tags, {
    Name             = "${local.name_prefix}-root-vol-${local.az_suffix}"
    AvailabilityZone = local.selected_az
  })

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix}-ec2-${local.az_suffix}"
    AvailabilityZone = local.selected_az
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "ec2_instance_id" {
  description = "The ID of the EC2 benchmark instance"
  value       = aws_instance.benchmark.id
}

output "ec2_instance_arn" {
  description = "The ARN of the EC2 benchmark instance"
  value       = aws_instance.benchmark.arn
}

output "iam_role_id" {
  description = "The ID of the IAM role attached to the EC2 instance"
  value       = aws_iam_role.instance_role.id
}

output "iam_role_arn" {
  description = "The ARN of the IAM role attached to the EC2 instance"
  value       = aws_iam_role.instance_role.arn
}

output "iam_instance_profile_id" {
  description = "The ID of the IAM instance profile"
  value       = aws_iam_instance_profile.instance_profile.id
}

output "iam_instance_profile_arn" {
  description = "The ARN of the IAM instance profile"
  value       = aws_iam_instance_profile.instance_profile.arn
}

output "route_table_id" {
  description = "The ID of the public route table"
  value       = aws_route_table.public.id
}

output "route_table_arn" {
  description = "The ARN of the public route table"
  value       = aws_route_table.public.arn
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public.id
}

output "public_subnet_arn" {
  description = "The ARN of the public subnet"
  value       = aws_subnet.public.arn
}

output "elastic_ip" {
  description = "The Elastic IP address associated with the instance (if enabled)"
  value       = length(aws_eip.instance_eip) > 0 ? aws_eip.instance_eip[0].public_ip : null
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

locals {
  cluster_name = "demo-eks"
  vpc_cidr     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# VPC and Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name                     = "${local.cluster_name}-public-subnet"
    "kubernetes.io/role/elb" = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "${local.cluster_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.igw]

  tags = {
    Name = "${local.cluster_name}-nat"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.${count.index + 1}.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "${local.cluster_name}-private-subnet-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${local.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# KMS Key for EKS Secrets Encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "eks_secrets" {
  description             = "KMS Key for EKS cluster ${local.cluster_name} secrets encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEKSServiceUsage"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/eksClusterRole"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.cluster_name}-kms-key"
  }
}

resource "aws_kms_alias" "eks_secrets" {
  name          = "alias/${local.cluster_name}-secrets"
  target_key_id = aws_kms_key.eks_secrets.key_id
}

# -----------------------------------------------------------------------------
# IAM Role for EKS Control Plane
# -----------------------------------------------------------------------------

resource "aws_iam_role" "cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_eks" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role_policy_attachment" "cluster_vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role_policy" "cluster_kms" {
  name = "${local.cluster_name}-cluster-kms-policy"
  role = aws_iam_role.cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.eks_secrets.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# EKS Cluster Control Plane
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "demo_eks" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = "1.30"

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_eks,
    aws_iam_role_policy_attachment.cluster_vpc_resource_controller,
    aws_iam_role_policy.cluster_kms
  ]
}

# -----------------------------------------------------------------------------
# TLS Key Pair for Worker Nodes
# -----------------------------------------------------------------------------

resource "tls_private_key" "eks_kp" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_kp_pem" {
  content         = tls_private_key.eks_kp.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks_kp.public_key_openssh

  lifecycle {
    ignore_changes = [public_key]
  }
}

# -----------------------------------------------------------------------------
# Worker Node Security Group and Cluster Inter-communication Rules
# -----------------------------------------------------------------------------

resource "aws_security_group" "node" {
  name        = "${local.cluster_name}-node-sg"
  description = "Security group for all nodes in the cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-node-sg"
  }
}

resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.node.id
  description       = "Allow outbound traffic only within the VPC CIDR"
}

resource "aws_security_group_rule" "node_ingress_self" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_security_group.node.id
  description              = "Allow unrestricted internal communication between nodes"
}

resource "aws_security_group_rule" "node_ingress_cluster_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow cluster control plane to communicate with pods on 443"
}

resource "aws_security_group_rule" "node_ingress_cluster_kubelet" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow cluster control plane to communicate with pods on kubelet/workload ports"
}

resource "aws_security_group_rule" "node_egress_cluster_443" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow nodes to communicate with cluster API server on 443"
}

resource "aws_security_group_rule" "node_egress_cluster_kubelet" {
  type                     = "egress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Allow nodes to communicate with cluster control plane on ephemeral ports"
}

resource "aws_security_group_rule" "cluster_ingress_node_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  description              = "Allow pods to communicate with the cluster API Server"
}

resource "aws_security_group_rule" "cluster_ingress_node_kubelet" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  description              = "Allow pods to communicate with control plane services"
}

resource "aws_security_group_rule" "cluster_egress_node_443" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  description              = "Allow control plane to communicate with pods on 443"
}

resource "aws_security_group_rule" "cluster_egress_node_kubelet" {
  type                     = "egress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  description              = "Allow control plane to communicate with kubelet and pods"
}

# -----------------------------------------------------------------------------
# Worker Node IAM Role and Instance Profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "node_eks_worker" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_eks_cni" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.node.name
}

resource "aws_iam_instance_profile" "node" {
  name = "demo-eks-node-instance-profile"
  role = aws_iam_role.node.name
}

# -----------------------------------------------------------------------------
# Launch Template for Worker Nodes
# -----------------------------------------------------------------------------

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${aws_eks_cluster.demo_eks.version}/amazon-linux-2/recommended/image_id"
}

resource "aws_launch_template" "node" {
  name_prefix   = "${local.cluster_name}-lt-"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  iam_instance_profile {
    arn = aws_iam_instance_profile.node.arn
  }

  vpc_security_group_ids = [aws_security_group.node.id]

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOF
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh ${local.cluster_name} \
      --b64-cluster-ca ${aws_eks_cluster.demo_eks.certificate_authority[0].data} \
      --apiserver-endpoint ${aws_eks_cluster.demo_eks.endpoint}
    /opt/aws/bin/cfn-signal -e $? --stack eks-cluster-stack --resource NodeAutoScalingGroup --region ${data.aws_region.current.name}
  EOF
  )

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "${local.cluster_name}-worker-node"
    }
  }

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Settle Time Delay
# -----------------------------------------------------------------------------

resource "time_sleep" "wait_30_seconds" {
  depends_on      = [aws_launch_template.node]
  create_duration = "30s"
}

# -----------------------------------------------------------------------------
# CloudFormation Stack for Auto Scaling Group
# -----------------------------------------------------------------------------

resource "aws_cloudformation_stack" "eks_nodes" {
  name               = "eks-cluster-stack"
  timeout_in_minutes = 20
  depends_on         = [time_sleep.wait_30_seconds, aws_eks_cluster.demo_eks]
  template_body      = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "EKS Worker Nodes AutoScalingGroup managed by CloudFormation"
    Parameters = {
      LaunchTemplateId = {
        Type        = "String"
        Description = "Launch Template ID for the nodes"
      }
      LaunchTemplateVersion = {
        Type        = "String"
        Description = "Launch Template Version"
      }
      SubnetIds = {
        Type        = "List<AWS::EC2::Subnet::Id>"
        Description = "Private subnets for the AutoScalingGroup"
      }
      ClusterName = {
        Type        = "String"
        Description = "EKS cluster name"
      }
    }
    Resources = {
      NodeAutoScalingGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"
        Properties = {
          VPCZoneIdentifier = { "Ref" : "SubnetIds" }
          LaunchTemplate = {
            LaunchTemplateId = { "Ref" : "LaunchTemplateId" }
            Version          = { "Ref" : "LaunchTemplateVersion" }
          }
          MinSize         = "1"
          DesiredCapacity = "3"
          MaxSize         = "4"
          Tags = [
            {
              Key               = { "Fn::Sub" : "kubernetes.io/cluster/$${ClusterName}" }
              Value             = "owned"
              PropagateAtLaunch = true
            },
            {
              Key               = "Name"
              Value             = { "Fn::Sub" : "$${ClusterName}-asg-node" }
              PropagateAtLaunch = true
            }
          ]
        }
        CreationPolicy = {
          ResourceSignal = {
            Count   = 3
            Timeout = "PT15M"
          }
        }
        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
            WaitOnResourceSignals = true
          }
        }
      }
    }
    Outputs = {
      AutoScalingGroupId = {
        Description = "The ID of the Node AutoScalingGroup"
        Value       = { "Ref" : "NodeAutoScalingGroup" }
      }
    }
  })

  parameters = {
    LaunchTemplateId      = aws_launch_template.node.id
    LaunchTemplateVersion = tostring(aws_launch_template.node.latest_version)
    SubnetIds             = join(",", aws_subnet.private[*].id)
    ClusterName           = local.cluster_name
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "node_instance_role_arn" {
  description = "The ARN of the IAM role assigned to worker nodes"
  value       = aws_iam_role.node.arn
}

output "node_security_group_id" {
  description = "The security group ID assigned to worker nodes"
  value       = aws_security_group.node.id
}

output "auto_scaling_group_id" {
  description = "The Auto Scaling Group ID created by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_nodes.outputs["AutoScalingGroupId"]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "primary_region" {
  type        = string
  description = "The primary AWS region for Terraform remote state management."
  default     = "us-east-1"
}

variable "replica_region" {
  type        = string
  description = "The secondary AWS region for remote state disaster recovery replication."
  default     = "us-west-2"
}

variable "eks_stacks" {
  type = map(object({
    environment = string
    region      = string
  }))
  description = "Map of EKS stacks to configure state locking, IAM access, and backend definitions."
  default = {
    "eks-core-infra" = {
      environment = "production"
      region      = "us-east-1"
    }
    "eks-workloads-dev" = {
      environment = "development"
      region      = "us-east-1"
    }
    "eks-workloads-prod" = {
      environment = "production"
      region      = "us-east-1"
    }
  }
}

variable "common_tags" {
  type        = map(string)
  description = "Common baseline tags applied to all state management resources."
  default = {
    ManagedBy = "Terraform"
    Purpose   = "EKS Remote State Management"
    Security  = "High"
    DRReplica = "CrossRegion"
  }
}

# -----------------------------------------------------------------------------
# AWS Provider Configurations
# -----------------------------------------------------------------------------
provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

resource "random_id" "suffix" {
  byte_length = 4
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id          = data.aws_caller_identity.current.account_id
  partition           = data.aws_partition.current.partition
  primary_bucket_name = "tf-state-eks-${local.account_id}-${var.primary_region}-${random_id.suffix.hex}"
  replica_bucket_name = "tf-state-eks-${local.account_id}-${var.replica_region}-${random_id.suffix.hex}-replica"
}

# -----------------------------------------------------------------------------
# Primary Region KMS Key
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "primary_kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleDecryption"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }
  }
}

resource "aws_kms_key" "primary" {
  description             = "Custom KMS key for primary EKS Terraform remote state in ${var.primary_region}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.primary_kms_policy.json

  tags = merge(var.common_tags, {
    Name   = "kms-tf-state-primary-${random_id.suffix.hex}"
    Region = var.primary_region
  })
}

resource "aws_kms_alias" "primary" {
  name          = "alias/tf-state-eks-primary-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.primary.key_id
}

# -----------------------------------------------------------------------------
# Replica Region KMS Key
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "replica_kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }
  }
}

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "Custom KMS key for replica EKS Terraform remote state in ${var.replica_region}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms_policy.json

  tags = merge(var.common_tags, {
    Name   = "kms-tf-state-replica-${random_id.suffix.hex}"
    Region = var.replica_region
  })
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/tf-state-eks-replica-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.replica.key_id
}

# -----------------------------------------------------------------------------
# Replica S3 State Bucket (Secondary Region)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "replica" {
  provider      = aws.replica
  bucket        = local.replica_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.common_tags, {
    Name   = local.replica_bucket_name
    Region = var.replica_region
    Role   = "DRReplica"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "replica_ssl_deny" {
  provider   = aws.replica
  bucket     = aws_s3_bucket.replica.id
  depends_on = [aws_s3_bucket_public_access_block.replica]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Primary S3 State Bucket (Primary Region)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "primary" {
  bucket        = local.primary_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.common_tags, {
    Name   = local.primary_bucket_name
    Region = var.primary_region
    Role   = "PrimaryState"
  })
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "primary_ssl_deny" {
  bucket     = aws_s3_bucket.primary.id
  depends_on = [aws_s3_bucket_public_access_block.primary]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Replication IAM Role and S3 Replication Configuration
# -----------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  name_prefix = "tf-state-eks-repl-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ReplicationAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "tf-state-eks-replication-role"
  })
}

resource "aws_iam_role_policy" "replication" {
  name_prefix = "tf-state-eks-repl-pol-"
  role        = aws_iam_role.replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketReadPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn
        ]
      },
      {
        Sid    = "SourceBucketObjectReadPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Sid    = "DestinationBucketObjectReplication"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          "${aws_s3_bucket.replica.arn}/*"
        ]
      },
      {
        Sid    = "DecryptSourceKMS"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.primary.arn
        ]
      },
      {
        Sid    = "EncryptDestinationKMS"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.replica.arn
        ]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "replication" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica
  ]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-tfstate-objects"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Disabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }
}

# -----------------------------------------------------------------------------
# DynamoDB State Lock Tables
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "state_locks" {
  for_each     = var.eks_stacks
  name         = "tf-state-lock-${each.key}-${random_id.suffix.hex}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.common_tags, {
    Name        = "tf-state-lock-${each.key}-${random_id.suffix.hex}"
    StackName   = each.key
    Environment = each.value.environment
  })
}

# -----------------------------------------------------------------------------
# Granular IAM Policies per EKS Stack
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "stack_state_access" {
  for_each    = var.eks_stacks
  name        = "tf-state-access-${each.key}-${random_id.suffix.hex}"
  description = "Granular least-privilege IAM policy for ${each.key} remote state management"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ListBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.primary.arn
        ]
        Condition = {
          StringLike = {
            "s3:prefix" = [
              "eks-stacks/${each.key}/*"
            ]
          }
        }
      },
      {
        Sid    = "S3ObjectPrefixAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "${aws_s3_bucket.primary.arn}/eks-stacks/${each.key}/*"
        ]
      },
      {
        Sid    = "DynamoDBStateLockAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [
          aws_dynamodb_table.state_locks[each.key].arn
        ]
      },
      {
        Sid    = "KMSCryptographicOperations"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.primary.arn
        ]
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name        = "tf-state-access-${each.key}-${random_id.suffix.hex}"
    StackName   = each.key
    Environment = each.value.environment
  })
}

# -----------------------------------------------------------------------------
# Automated backend.tf File Generation
# -----------------------------------------------------------------------------
resource "local_file" "backend_configurations" {
  for_each = var.eks_stacks
  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.primary.bucket}"
        key            = "eks-stacks/${each.key}/terraform.tfstate"
        region         = "${var.primary_region}"
        dynamodb_table = "${aws_dynamodb_table.state_locks[each.key].name}"
        kms_key_id     = "${aws_kms_key.primary.arn}"
        encrypt        = true
      }
    }
  EOT

  file_permission = "0644"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  user_pool_name   = "box_things"
  user_pool_client = "box_things_client"
}

resource "aws_cognito_user_pool" "box_things" {
  name                     = local.user_pool_name
  alias_attributes         = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OFF"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  verification_message_template {
    default_email_option  = "CONFIRM_WITH_LINK"
    email_message_by_link = "Please click the link below to verify your email address: {##Click Here##}"
    email_subject_by_link = "Verify your email address"
  }

  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "email"
    required                 = true

    string_attribute_constraints {
      min_length = "1"
      max_length = "256"
    }
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = local.user_pool_client
  user_pool_id = aws_cognito_user_pool.box_things.id

  generate_secret = false

  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]

  callback_urls = ["https://example.com/callback"]
  logout_urls   = ["https://example.com/logout"]

  allowed_oauth_flows                  = ["code", "implicit"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  allowed_oauth_flows_user_pool_client = true
}

output "user_pool_id" {
  description = "The ID of the Cognito User Pool."
  value       = aws_cognito_user_pool.box_things.id
}

output "user_pool_arn" {
  description = "The ARN of the Cognito User Pool."
  value       = aws_cognito_user_pool.box_things.arn
}

output "user_pool_client_id" {
  description = "The ID of the Cognito User Pool Client."
  value       = aws_cognito_user_pool_client.box_things_client.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_users" {
  description = "Map of IAM users and their tags"
  type = map(object({
    owner = string
  }))
  default = {
    "dev1" = {
      owner = "Devel"
    }
    "dev2" = {
      owner = "Devel"
    }
    "guest" = {
      owner = "Guest"
    }
  }
}

resource "aws_iam_group" "ersia_devel_group" {
  name = "Ersia_Devel_Group"
  path = "/"
}

resource "aws_iam_group" "ersia_guest_group" {
  name = "Ersia_Guest_Group"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "ersia_devel_readonly" {
  group      = aws_iam_group.ersia_devel_group.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "ersia_guest_iam_readonly" {
  group      = aws_iam_group.ersia_guest_group.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user" "users" {
  for_each = var.iam_users

  name = each.key
  path = "/"

  tags = {
    Owner = each.value.owner
  }
}

resource "aws_iam_user_group_membership" "user_membership" {
  for_each = var.iam_users

  user = aws_iam_user.users[each.key].name
  groups = [
    each.value.owner == "Devel" ? aws_iam_group.ersia_devel_group.name : aws_iam_group.ersia_guest_group.name
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

# KMS Key for SQS Queue Encryption
resource "aws_kms_key" "sqs_key" {
  description             = "KMS Key for SQS queue ${random_pet.name.id}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow APIGateway Access"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.apigateway_role.arn
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/${random_pet.name.id}-sqs-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

# SQS Queue
resource "aws_sqs_queue" "queue" {
  name              = "${random_pet.name.id}-queue"
  kms_master_key_id = aws_kms_key.sqs_key.arn
}

# CloudWatch Log Group for Access Logging
resource "aws_cloudwatch_log_group" "api_logs" {
  name              = "/aws/apigateway/${random_pet.name.id}"
  retention_in_days = 1
}

# IAM Role for API Gateway
resource "aws_iam_role" "apigateway_role" {
  name = "${random_pet.name.id}-apigateway-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "apigateway_policy" {
  name        = "${random_pet.name.id}-apigateway-policy"
  description = "Allows API Gateway to publish to SQS and write logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sqs:SendMessage"
        ]
        Resource = aws_sqs_queue.queue.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.sqs_key.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.api_logs.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigateway_attach" {
  role       = aws_iam_role.apigateway_role.name
  policy_arn = aws_iam_policy.apigateway_policy.arn
}

# WebSocket API Gateway v2
resource "aws_apigatewayv2_api" "websocket_api" {
  name                       = random_pet.name.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# $connect Route (MOCK Integration)
resource "aws_apigatewayv2_integration" "connect_integration" {
  api_id           = aws_apigatewayv2_api.websocket_api.id
  integration_type = "MOCK"
  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
  template_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_integration_response" "connect_integration_response" {
  api_id                   = aws_apigatewayv2_api.websocket_api.id
  integration_id           = aws_apigatewayv2_integration.connect_integration.id
  integration_response_key = "/200/"
  response_templates = {
    "application/json" = ""
  }
}

resource "aws_apigatewayv2_route" "connect_route" {
  api_id                              = aws_apigatewayv2_api.websocket_api.id
  route_key                           = "$connect"
  target                              = "integrations/${aws_apigatewayv2_integration.connect_integration.id}"
  route_response_selection_expression = "$default"
}

resource "aws_apigatewayv2_route_response" "connect_route_response" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_id           = aws_apigatewayv2_route.connect_route.id
  route_response_key = "$default"
}

# $default Route (Direct SQS Integration via Action=SendMessage)
resource "aws_apigatewayv2_integration" "default_integration" {
  api_id               = aws_apigatewayv2_api.websocket_api.id
  integration_type     = "AWS"
  integration_method   = "POST"
  integration_uri      = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.queue.name}"
  credentials_arn      = aws_iam_role.apigateway_role.arn
  passthrough_behavior = "NEVER"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$util.urlEncode($input.body)"
  }
  template_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_integration_response" "default_integration_response" {
  api_id                   = aws_apigatewayv2_api.websocket_api.id
  integration_id           = aws_apigatewayv2_integration.default_integration.id
  integration_response_key = "/200/"
}

resource "aws_apigatewayv2_route" "default_route" {
  api_id                              = aws_apigatewayv2_api.websocket_api.id
  route_key                           = "$default"
  target                              = "integrations/${aws_apigatewayv2_integration.default_integration.id}"
  route_response_selection_expression = "$default"
}

resource "aws_apigatewayv2_route_response" "default_route_response" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_id           = aws_apigatewayv2_route.default_route.id
  route_response_key = "$default"
}

# $disconnect Route (Direct SQS Integration)
resource "aws_apigatewayv2_integration" "disconnect_integration" {
  api_id               = aws_apigatewayv2_api.websocket_api.id
  integration_type     = "AWS"
  integration_method   = "POST"
  integration_uri      = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.queue.name}"
  credentials_arn      = aws_iam_role.apigateway_role.arn
  passthrough_behavior = "NEVER"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client%20disconnected"
  }
  template_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_route" "disconnect_route" {
  api_id    = aws_apigatewayv2_api.websocket_api.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect_integration.id}"
}

# API Gateway Stage
resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.websocket_api.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format = jsonencode({
      requestId               = "$context.requestId"
      ip                      = "$context.identity.sourceIp"
      caller                  = "$context.identity.caller"
      user                    = "$context.identity.user"
      requestTime             = "$context.requestTime"
      eventType               = "$context.eventType"
      routeKey                = "$context.routeKey"
      status                  = "$context.status"
      connectionId            = "$context.connectionId"
      integrationErrorMessage = "$context.integrationErrorMessage"
    })
  }

  depends_on = [
    aws_apigatewayv2_route.connect_route,
    aws_apigatewayv2_route.default_route,
    aws_apigatewayv2_route.disconnect_route
  ]
}

output "websocket_endpoint_url" {
  description = "The WebSocket connection URL including the stage name"
  value       = aws_apigatewayv2_stage.dev.invoke_url
}

