terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Optional tags for IAM roles and policies"
}

data "aws_default_tags" "current" {}

data "aws_partition" "current" {}

locals {
  # Skip any input tags that match existing provider default tags identically
  effective_tags = {
    for k, v in var.tags : k => v
    if !contains(keys(data.aws_default_tags.current.tags), k) || lookup(data.aws_default_tags.current.tags, k, null) != v
  }
}

# 1. ECS Service Role: "ecs-role"
data "aws_iam_policy_document" "ecs_service_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_role" {
  name                  = "ecs-role"
  path                  = "/"
  assume_role_policy    = data.aws_iam_policy_document.ecs_service_assume_role.json
  force_detach_policies = true
  tags                  = local.effective_tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_attachment" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# 2. ECS Task Execution Role: "ecs-tasks-role"
data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_tasks_role" {
  name                  = "ecs-tasks-role"
  path                  = "/"
  assume_role_policy    = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  force_detach_policies = true
  tags                  = local.effective_tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_attachment" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# 3. EventBridge Role: "events-role"
data "aws_iam_policy_document" "events_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "events_role" {
  name                  = "events-role"
  path                  = "/"
  assume_role_policy    = data.aws_iam_policy_document.events_assume_role.json
  force_detach_policies = true
  tags                  = local.effective_tags
}

data "aws_iam_policy_document" "ecs_policy_doc" {
  statement {
    sid    = "ECSRunTask"
    effect = "Allow"
    actions = [
      "ecs:RunTask"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "PassTaskExecutionRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [aws_iam_role.ecs_tasks_role.arn]
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  path        = "/"
  description = "Policy allowing EventBridge to run ECS tasks and pass only the task execution role"
  policy      = data.aws_iam_policy_document.ecs_policy_doc.json
  tags        = local.effective_tags
}

resource "aws_iam_role_policy_attachment" "events_ecs_policy_attachment" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_cloudwatch_policy_attachment" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/CloudWatchLogsFullAccess"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

variable "primary_bucket_prefix" {
  type        = string
  description = "Prefix for the primary S3 bucket name"
  default     = "example1"
}

variable "secondary_bucket_prefix" {
  type        = string
  description = "Prefix for the secondary S3 bucket name"
  default     = "example2"
}

variable "mrap_name" {
  type        = string
  description = "Name of the S3 Multi-Region Access Point"
  default     = "example-mrap"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# ------------------------------------------------------------------------------
# KMS Keys & Aliases
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "primary_kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "secondary_kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "primary" {
  description             = "KMS key for primary S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.primary_kms_policy.json
}

resource "aws_kms_alias" "primary" {
  name_prefix   = "alias/${var.primary_bucket_prefix}-"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS key for secondary S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.secondary_kms_policy.json
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.secondary
  name_prefix   = "alias/${var.secondary_bucket_prefix}-"
  target_key_id = aws_kms_key.secondary.key_id
}

# ------------------------------------------------------------------------------
# Primary S3 Bucket (us-east-1)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  bucket_prefix = "${var.primary_bucket_prefix}-${data.aws_caller_identity.current.account_id}-"
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# Secondary S3 Bucket (us-west-2 / Control Plane Region)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "secondary" {
  provider      = aws.secondary
  bucket_prefix = "${var.secondary_bucket_prefix}-${data.aws_caller_identity.current.account_id}-"
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider   = aws.secondary
  bucket     = aws_s3_bucket.secondary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# S3 Replication IAM Role and Policies
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name_prefix        = "${var.primary_bucket_prefix}-repl-"
  assume_role_policy = data.aws_iam_policy_document.s3_assume_role.json
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "SourceBucketObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "DestinationBucketObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    sid    = "SourceKMSDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [aws_kms_key.primary.arn]
    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.*.amazonaws.com"]
    }
  }

  statement {
    sid    = "DestinationKMSEncrypt"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.secondary.arn]
    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.*.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "replication" {
  name_prefix = "${var.primary_bucket_prefix}-repl-"
  description = "IAM policy for S3 cross-region replication with SSE-KMS"
  policy      = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ------------------------------------------------------------------------------
# S3 Replication Configuration
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "primary_to_secondary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary
  ]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "replicate-all-kms"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Disabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

# ------------------------------------------------------------------------------
# S3 Multi-Region Access Point & Policy (Managed in us-west-2)
# ------------------------------------------------------------------------------

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.secondary

  depends_on = [
    aws_s3_bucket_public_access_block.primary,
    aws_s3_bucket_public_access_block.secondary,
    aws_s3_bucket_ownership_controls.primary,
    aws_s3_bucket_ownership_controls.secondary,
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_server_side_encryption_configuration.primary,
    aws_s3_bucket_server_side_encryption_configuration.secondary,
    aws_s3_bucket_acl.primary,
    aws_s3_bucket_acl.secondary,
    aws_s3_bucket_replication_configuration.primary_to_secondary
  ]

  details {
    name = var.mrap_name

    public_access_block {
      block_public_acls       = true
      block_public_policy     = true
      ignore_public_acls      = true
      restrict_public_buckets = true
    }

    region {
      bucket            = aws_s3_bucket.primary.id
      bucket_account_id = local.account_id
    }

    region {
      bucket            = aws_s3_bucket.secondary.id
      bucket_account_id = local.account_id
    }
  }

  timeouts {
    create = "15m"
    delete = "15m"
  }
}

data "aws_iam_policy_document" "mrap_policy" {
  statement {
    sid    = "AllowOwningAccountGetPut"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3control_multi_region_access_point.mrap.arn}/object/*"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap_policy" {
  provider = aws.secondary

  details {
    name   = aws_s3control_multi_region_access_point.mrap.details[0].name
    policy = data.aws_iam_policy_document.mrap_policy.json
  }

  timeouts {
    create = "15m"
    update = "15m"
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type        = string
  default     = "eg"
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'"
}

variable "environment" {
  type        = string
  default     = "ue1"
  description = "Environment, e.g. 'ue1', 'uw2', 'us-east-1'"
}

variable "stage" {
  type        = string
  default     = "prod"
  description = "Stage, e.g. 'prod', 'staging', 'dev'"
}

variable "name" {
  type        = string
  default     = "patch-manager"
  description = "Solution name, e.g. 'app' or 'patch-manager'"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes (e.g. `1`)"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`"
}

variable "scan_schedule" {
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
  description = "Cron schedule for the patch scan maintenance window"
}

variable "install_schedule" {
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
  description = "Cron schedule for the patch install maintenance window"
}

variable "window_duration" {
  type        = number
  default     = 3
  description = "Duration of the maintenance window in hours"
}

variable "window_cutoff" {
  type        = number
  default     = 1
  description = "Number of hours before the end of the maintenance window that SSM stops scheduling new tasks"
}

variable "max_concurrency" {
  type        = string
  default     = "20"
  description = "Maximum number of targets allowed to run this task in parallel"
}

variable "max_errors" {
  type        = string
  default     = "50"
  description = "Maximum number of errors allowed before this task stops being scheduled"
}

variable "scan_patch_group" {
  type        = string
  default     = "TOSCAN"
  description = "Patch group tag value targeted by the scan maintenance window"
}

variable "install_patch_group" {
  type        = string
  default     = "TOPATCH"
  description = "Patch group tag value targeted by the install maintenance window"
}

variable "install_reboot_option" {
  type        = string
  default     = "RebootIfNeeded"
  description = "Reboot option for the install patch task (e.g. RebootIfNeeded, NoReboot)"
}

variable "scan_s3_prefix" {
  type        = string
  default     = "scanning"
  description = "S3 bucket prefix where scan output logs will be stored"
}

variable "install_s3_prefix" {
  type        = string
  default     = "installing"
  description = "S3 bucket prefix where install output logs will be stored"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  name_parts = compact([
    var.namespace,
    var.environment,
    var.stage,
    var.name,
    join("-", var.attributes)
  ])
  id = lower(join("-", local.name_parts))

  base_tags = {
    "Namespace"   = var.namespace
    "Environment" = var.environment
    "Stage"       = var.stage
    "Name"        = local.id
  }

  tags = merge(local.base_tags, var.tags)

  s3_bucket_name = lower(join("-", compact([local.id, "patch-logs", data.aws_caller_identity.current.account_id])))
  iam_role_name  = "${local.id}-ssm-mw"
  kms_key_name   = "${local.id}-patch-logs-key"
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSSMServiceUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowMaintenanceWindowRoleUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.ssm_maintenance_window.arn]
    }
  }
}

resource "aws_kms_key" "patch_logs" {
  description             = "Customer managed KMS key for patch manager S3 logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = merge(local.tags, {
    "Name" = local.kms_key_name
  })
}

resource "aws_kms_alias" "patch_logs" {
  name          = "alias/${local.kms_key_name}"
  target_key_id = aws_kms_key.patch_logs.key_id
}

resource "aws_s3_bucket" "patch_logs" {
  bucket        = local.s3_bucket_name
  force_destroy = false

  tags = merge(local.tags, {
    "Name" = local.s3_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "patch_logs" {
  bucket = aws_s3_bucket.patch_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "patch_logs" {
  bucket = aws_s3_bucket.patch_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.patch_logs.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "patch_logs" {
  bucket                  = aws_s3_bucket.patch_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "patch_logs_policy" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.patch_logs.arn,
      "${aws_s3_bucket.patch_logs.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowAccountReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.patch_logs.arn,
      "${aws_s3_bucket.patch_logs.arn}/*"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSSMServiceLogging"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.patch_logs.arn,
      "${aws_s3_bucket.patch_logs.arn}/*"
    ]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "patch_logs" {
  bucket     = aws_s3_bucket.patch_logs.id
  policy     = data.aws_iam_policy_document.patch_logs_policy.json
  depends_on = [aws_s3_bucket_public_access_block.patch_logs]
}

data "aws_iam_policy_document" "ssm_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_maintenance_window" {
  name               = local.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.ssm_assume_role.json
  tags               = local.tags
}

data "aws_iam_policy_document" "ssm_mw_permissions" {
  statement {
    sid    = "SendCommandPermissions"
    effect = "Allow"
    actions = [
      "ssm:SendCommand",
      "ssm:CancelCommand",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations",
      "ssm:GetCommandInvocation"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:instance/*",
      "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.name}:*:document/AWS-RunPatchBaseline",
      "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"
    ]
  }

  statement {
    sid    = "S3LogOutputPermissions"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetBucketLocation",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.patch_logs.arn,
      "${aws_s3_bucket.patch_logs.arn}/*"
    ]
  }

  statement {
    sid    = "KmsLoggingKeyPermissions"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = [
      aws_kms_key.patch_logs.arn
    ]
  }
}

resource "aws_iam_policy" "ssm_maintenance_window" {
  name   = "${local.iam_role_name}-policy"
  policy = data.aws_iam_policy_document.ssm_mw_permissions.json
  tags   = local.tags
}

resource "aws_iam_role_policy_attachment" "ssm_maintenance_window" {
  role       = aws_iam_role.ssm_maintenance_window.name
  policy_arn = aws_iam_policy.ssm_maintenance_window.arn
}

resource "aws_iam_role_policy_attachment" "ssm_maintenance_window_aws_managed" {
  role       = aws_iam_role.ssm_maintenance_window.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonSSMMaintenanceWindowRole"
}

resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name             = "${local.id}-amazon-linux-2"
  description      = "Patch baseline for Amazon Linux 2 automatic patch remediation"
  operating_system = "AMAZON_LINUX_2"

  approved_patches_compliance_level    = "HIGH"
  approved_patches_enable_non_security = true

  approval_rule {
    approve_after_days  = 7
    compliance_level    = "HIGH"
    enable_non_security = true

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = local.tags
}

resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group
}

resource "aws_ssm_maintenance_window" "scan" {
  name        = "${local.id}-scan"
  description = "Weekly SSM maintenance window for vulnerability and patch scanning"
  schedule    = var.scan_schedule
  duration    = var.window_duration
  cutoff      = var.window_cutoff
  enabled     = true

  allow_unassociated_targets = false

  tags = merge(local.tags, {
    "Name" = "${local.id}-scan"
  })
}

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${local.id}-scan-targets"
  description   = "Targets instances assigned to the TOSCAN patch group"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = [var.scan_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.ssm_maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = aws_s3_bucket.patch_logs.id
      output_s3_key_prefix = var.scan_s3_prefix

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }
    }
  }
}

resource "aws_ssm_maintenance_window" "install" {
  name        = "${local.id}-install"
  description = "Weekly SSM maintenance window for patch installation and remediation"
  schedule    = var.install_schedule
  duration    = var.window_duration
  cutoff      = var.window_cutoff
  enabled     = true

  allow_unassociated_targets = false

  tags = merge(local.tags, {
    "Name" = "${local.id}-install"
  })
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${local.id}-install-targets"
  description   = "Targets instances assigned to the TOPATCH patch group"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = [var.install_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.ssm_maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = aws_s3_bucket.patch_logs.id
      output_s3_key_prefix = var.install_s3_prefix

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.install_reboot_option]
      }
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "notification_emails" {
  type        = list(string)
  description = "List of email addresses to receive management activity alerts"
  default     = ["alerts@example.com"]
}

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  region           = data.aws_region.current.name
  trail_name       = "monitor_account_activities"
  cloudtrail_arn   = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"
  s3_bucket_name   = "cloudtrail-monitor-management-event-logs-${local.account_id}"
  log_group_name   = "cloudtrail_to_cloudwatch_logs"
  metric_namespace = "management_activities"
  sns_topic_name   = "management-updates"

  metric_filters = {
    security_group_changes = {
      pattern     = "{($.eventName = AuthorizeSecurityGroupIngress) || ($.eventName = AuthorizeSecurityGroupEgress) || ($.eventName = RevokeSecurityGroupIngress) || ($.eventName = RevokeSecurityGroupEgress) || ($.eventName = CreateSecurityGroup) || ($.eventName = DeleteSecurityGroup)}"
      description = "Security group ingress, egress, creation, or deletion changes detected."
    }
    iam_user_changes = {
      pattern     = "{($.eventName = CreateUser) || ($.eventName = DeleteUser)}"
      description = "IAM user creation or deletion detected."
    }
    failed_console_logins = {
      pattern     = "{($.eventName = ConsoleLogin) && ($.errorMessage = \"Failed authentication\")}"
      description = "Failed AWS Management Console login attempts detected."
    }
    iam_group_role_user_policy_changes = {
      pattern     = "{($.eventName = PutGroupPolicy) || ($.eventName = DeleteGroupPolicy) || ($.eventName = PutRolePolicy) || ($.eventName = DeleteRolePolicy) || ($.eventName = PutUserPolicy) || ($.eventName = DeleteUserPolicy) || ($.eventName = AttachRolePolicy) || ($.eventName = DetachRolePolicy) || ($.eventName = AttachUserPolicy) || ($.eventName = DetachUserPolicy) || ($.eventName = AttachGroupPolicy) || ($.eventName = DetachGroupPolicy)}"
      description = "Inline or attached policy changes for IAM users, roles, or groups detected."
    }
    iam_policy_changes = {
      pattern     = "{($.eventName = CreatePolicy) || ($.eventName = DeletePolicy) || ($.eventName = CreatePolicyVersion) || ($.eventName = DeletePolicyVersion) || ($.eventName = SetDefaultPolicyVersion)}"
      description = "Customer-managed IAM policy creations, deletions, or version modifications detected."
    }
    iam_user_group_membership_changes = {
      pattern     = "{($.eventName = AddUserToGroup) || ($.eventName = RemoveUserFromGroup)}"
      description = "IAM user additions or removals to/from IAM groups detected."
    }
    iam_role_changes = {
      pattern     = "{($.eventName = CreateRole) || ($.eventName = DeleteRole)}"
      description = "IAM role creation or deletion detected."
    }
  }
}

# KMS Key for CloudTrail and S3 Bucket
resource "aws_kms_key" "cloudtrail" {
  description             = "Customer managed KMS key for CloudTrail and S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailDescribeKey"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "kms:DescribeKey"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailGenerateDataKey"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"
          }
        }
      },
      {
        Sid    = "AllowS3Operations"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/cloudtrail-monitor-key"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# KMS Key for SNS Topic
resource "aws_kms_key" "sns" {
  description             = "Customer managed KMS key for SNS management alerts topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchAlarmsToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-management-updates-key"
  target_key_id = aws_kms_key.sns.key_id
}

# S3 Bucket for CloudTrail Logs
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.s3_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket     = aws_s3_bucket.cloudtrail_logs.id
  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_logs]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.cloudtrail_arn
          }
        }
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"  = "bucket-owner-full-control"
            "aws:SourceArn" = local.cloudtrail_arn
          }
        }
      }
    ]
  })
}

# CloudWatch Logs Group and IAM Role for CloudTrail
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = 365
}

resource "aws_iam_role" "cloudtrail_to_cloudwatch" {
  name = "cloudtrail-to-cloudwatch-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudTrailAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "cloudtrail_to_cloudwatch" {
  name        = "cloudtrail-to-cloudwatch-logs-policy"
  description = "Allows CloudTrail to stream events to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudTrailLogsDelivery"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudtrail_to_cloudwatch" {
  role       = aws_iam_role.cloudtrail_to_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_to_cloudwatch.arn
}

# SNS Topic and Subscriptions
resource "aws_sns_topic" "management_updates" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic_policy" "management_updates" {
  arn = aws_sns_topic.management_updates.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchAlarmsPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.management_updates.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "email_subscribers" {
  for_each  = toset(var.notification_emails)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

# CloudTrail Trail
resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_to_cloudwatch.arn

  advanced_event_selector {
    name = "Log management events excluding KMS and RDS Data"

    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }

    field_selector {
      field = "eventSource"
      not_equals = [
        "kms.amazonaws.com",
        "rdsdata.amazonaws.com"
      ]
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy_attachment.cloudtrail_to_cloudwatch
  ]
}

# Metric Filters and Alarms
resource "aws_cloudwatch_log_metric_filter" "audit_filters" {
  for_each       = local.metric_filters
  name           = each.key
  pattern        = each.value.pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = each.key
    namespace = local.metric_namespace
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "audit_alarms" {
  for_each            = local.metric_filters
  alarm_name          = "${each.key}-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = each.key
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = each.value.description
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  treat_missing_data  = "notBreaching"

  depends_on = [aws_cloudwatch_log_metric_filter.audit_filters]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  type        = string
  description = "Optional prefix to be applied to resource names."
  default     = ""
}

variable "days_to_expiration" {
  type        = number
  description = "The number of days before certificate expiration to trigger a non-compliant evaluation."
  default     = 14

  validation {
    condition     = var.days_to_expiration > 0
    error_message = "The days_to_expiration parameter must be a positive integer."
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  prefix           = var.name_prefix != "" ? "${var.name_prefix}-" : ""
  rule_name        = "${local.prefix}acm-certificate-expiration-check"
  s3_bucket_name   = "${local.prefix}aws-config-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  config_role_name = "${local.prefix}aws-config-role"
}

resource "aws_kms_key" "config" {
  description             = "Customer-managed KMS key for AWS Config S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAWSConfigToEncryptData"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name = "${local.prefix}config-kms-key"
  }
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.prefix}aws-config-key"
  target_key_id = aws_kms_key.config.key_id
}

resource "aws_s3_bucket" "config_bucket" {
  bucket        = local.s3_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.s3_bucket_name
  }
}

resource "aws_s3_bucket_versioning" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "config_role" {
  name = local.config_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSConfigAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = local.config_role_name
  }
}

resource "aws_iam_role_policy_attachment" "config_role_policy" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_s3_bucket_policy" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSConfigBucketPermissionsCheck"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.config_bucket.arn
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AWSConfigBucketExistenceCheck"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.config_bucket.arn
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AWSConfigBucketDelivery"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.config_bucket.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/Config/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"      = "bucket-owner-full-control"
            "AWS:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_config_configuration_recorder" "main" {
  name     = "${local.prefix}config-recorder"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "${local.prefix}config-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config_bucket.id
  s3_kms_key_arn = aws_kms_key.config.arn

  depends_on = [
    aws_config_configuration_recorder.main,
    aws_s3_bucket_policy.config_bucket
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.main
  ]
}

resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name        = local.rule_name
  description = "Checks whether ACM Certificates in the account are marked for expiration within the specified number of days."

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  scope {
    compliance_resource_types = [
      "AWS::ACM::Certificate"
    ]
  }

  input_parameters = jsonencode({
    daysToExpiration = tostring(var.days_to_expiration)
  })

  depends_on = [
    aws_config_configuration_recorder_status.main
  ]

  tags = {
    Name = local.rule_name
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "pool" {
  name                     = "fiap-hackathon-cognito-pool"
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OFF"

  password_policy {
    minimum_length    = 8
    require_lowercase = false
    require_numbers   = false
    require_symbols   = false
    require_uppercase = false
  }

  schema {
    attribute_data_type = "String"
    name                = "name"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name            = "cognito-pool-client"
  user_pool_id    = aws_cognito_user_pool.pool.id
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  tenant_id   = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
  client_id   = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
  oidc_issuer = "https://sts.windows.net/${local.tenant_id}/"
  oidc_domain = "sts.windows.net/${local.tenant_id}/"
  # Standard Microsoft Entra ID / Azure AD root CA thumbprint
  thumbprints = ["626da5e0d30d1d1e81a600d0e9f963f893a11444"]
}

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = local.oidc_issuer
  client_id_list  = [local.client_id]
  thumbprint_list = local.thumbprints

  tags = {
    Name = "azure-ad-oidc-provider"
  }
}

resource "aws_iam_role" "sentinel_oidc_role" {
  name = "Sentinel-OIDC-Organizations-ReadOnly"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.azure_ad.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${local.oidc_domain}:aud" = local.client_id
          }
        }
      }
    ]
  })

  tags = {
    Name = "Sentinel-OIDC-Organizations-ReadOnly"
  }
}

resource "aws_iam_role_policy_attachment" "sentinel_organizations_readonly" {
  role       = aws_iam_role.sentinel_oidc_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_wildcard_test_role" {
  name               = "ec2-iam-policy-wildcard-test-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

data "aws_iam_policy_document" "allow_specific_cluster" {
  statement {
    sid       = "AllowAddRoleToSpecificDBCluster"
    effect    = "Allow"
    actions   = ["rds:AddRoleToDBCluster"]
    resources = ["arn:aws:rds:*:*:cluster:foo_cluster"]
  }
}

resource "aws_iam_role_policy" "allow_specific_cluster_policy" {
  name   = "allow-add-role-to-specific-cluster"
  role   = aws_iam_role.ec2_wildcard_test_role.id
  policy = data.aws_iam_policy_document.allow_specific_cluster.json
}

data "aws_iam_policy_document" "allow_wildcard_clusters" {
  statement {
    sid       = "AllowAddWildcardToAllClusters"
    effect    = "Allow"
    actions   = ["rds:Add*"]
    resources = ["arn:aws:rds:*:*:cluster:*"]
  }
}

resource "aws_iam_role_policy" "allow_wildcard_clusters_policy" {
  name   = "allow-add-wildcard-clusters"
  role   = aws_iam_role.ec2_wildcard_test_role.id
  policy = data.aws_iam_policy_document.allow_wildcard_clusters.json
}

data "aws_iam_policy_document" "deny_wildcard_clusters" {
  statement {
    sid       = "DenyAddWildcardToAllClusters"
    effect    = "Deny"
    actions   = ["rds:Add*"]
    resources = ["arn:aws:rds:*:*:cluster:*"]
  }
}

resource "aws_iam_role_policy" "deny_wildcard_clusters_policy" {
  name   = "deny-add-wildcard-clusters"
  role   = aws_iam_role.ec2_wildcard_test_role.id
  policy = data.aws_iam_policy_document.deny_wildcard_clusters.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Deployment environment name for resource naming"
  default     = "prod"
}

data "aws_caller_identity" "current" {}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  frontend_bucket_name = "s3-frontend-nft-maker-v2-${local.account_id}"
  state_bucket_name    = "near-frontend-${var.environment}-terraform-state-${local.account_id}"
  s3_origin_id         = "S3-${local.frontend_bucket_name}"
}

# -----------------------------------------------------------------------------
# Frontend KMS Key and Alias
# -----------------------------------------------------------------------------
resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend static hosting S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudFrontOAIDecrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.frontend.iam_arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/frontend-nft-maker-key"
  target_key_id = aws_kms_key.frontend.key_id
}

# -----------------------------------------------------------------------------
# Frontend S3 Bucket and Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = local.frontend_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# -----------------------------------------------------------------------------
# CloudFront Origin Access Identity and S3 Bucket Policy
# -----------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "OAI for frontend NFT Maker static site"
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontOAIReadAndList"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.frontend.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# WAFv2 Web ACL (CloudFront scoped, us-east-1)
# -----------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "frontend" {
  name        = "frontend-nft-maker-waf"
  description = "CloudFront WAF using AWS Managed Common Rule Set"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "FrontendWAFCommonRulesMetric"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "FrontendWAFWebACLMetric"
    sampled_requests_enabled   = true
  }
}

# -----------------------------------------------------------------------------
# CloudFront Distribution
# -----------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  web_acl_id          = aws_wafv2_web_acl.frontend.arn

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = local.s3_origin_id

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = local.s3_origin_id
    compress         = true

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 31536000

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = local.s3_origin_id
    compress         = true

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 31536000
    default_ttl            = 31536000
    max_ttl                = 31536000

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = local.s3_origin_id
    compress         = true

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 86400
    default_ttl            = 604800
    max_ttl                = 2592000

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# -----------------------------------------------------------------------------
# Terraform State Remote Backend: KMS Key and Alias
# -----------------------------------------------------------------------------
resource "aws_kms_key" "terraform_state" {
  description             = "KMS key for Terraform remote state S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/near-frontend-${var.environment}-state-key"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# -----------------------------------------------------------------------------
# Terraform State Remote Backend: S3 Bucket and Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Terraform State Remote Backend: DynamoDB Lock Table
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "terraform_locks" {
  name           = "near-frontend-terraform-state"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.89.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy network resources into."
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster for resource tagging and discovery."
  type        = string
  default     = "stackx"
}

variable "enable_database_subnets" {
  description = "Controls whether to create isolated database subnets and DB subnet group."
  type        = bool
  default     = false
}

variable "database_subnet_cidrs" {
  description = "IPv4 CIDR blocks for database subnets (one per AZ)."
  type        = list(string)
  default     = ["10.1.204.0/24", "10.1.205.0/24", "10.1.206.0/24"]
}

variable "enable_elasticache_subnets" {
  description = "Controls whether to create isolated ElastiCache subnets and subnet group."
  type        = bool
  default     = false
}

variable "elasticache_subnet_cidrs" {
  description = "IPv4 CIDR blocks for ElastiCache subnets (one per AZ)."
  type        = list(string)
  default     = ["10.1.208.0/24", "10.1.209.0/24", "10.1.210.0/24"]
}

variable "enable_intra_subnets" {
  description = "Controls whether to create isolated internal intra subnets with no internet routes."
  type        = bool
  default     = false
}

variable "intra_subnet_cidrs" {
  description = "IPv4 CIDR blocks for intra subnets (one per AZ)."
  type        = list(string)
  default     = ["10.1.212.0/24", "10.1.213.0/24", "10.1.214.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "stackx-network"
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs  = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
  private_subnet_cidrs = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]

  common_tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-eigw"
    }
  )
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_subnet_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name                     = "${local.name_prefix}-public-subnet-${count.index + 1}"
      "kubernetes.io/role/elb" = "1"
    }
  )
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_subnet_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 3)
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name                              = "${local.name_prefix}-private-subnet-${count.index + 1}"
      "kubernetes.io/role/internal-elb" = "1"
      "karpenter.sh/discovery"          = var.cluster_name
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat-eip-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat-gw-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt-${count.index + 1}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-s3-endpoint"
    }
  )
}

resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.database_subnet_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 6)
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-db-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "database" {
  count  = var.enable_database_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-db-rt"
    }
  )
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? 3 : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[0].id
}

resource "aws_db_subnet_group" "main" {
  count = var.enable_database_subnets ? 1 : 0

  name        = "${local.name_prefix}-db-subnet-group"
  description = "Database subnet group for ${local.name_prefix}"
  subnet_ids  = aws_subnet.database[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-db-subnet-group"
    }
  )
}

resource "aws_subnet" "elasticache" {
  count = var.enable_elasticache_subnets ? 3 : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.elasticache_subnet_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 9)
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-elasticache-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "elasticache" {
  count  = var.enable_elasticache_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-elasticache-rt"
    }
  )
}

resource "aws_route_table_association" "elasticache" {
  count = var.enable_elasticache_subnets ? 3 : 0

  subnet_id      = aws_subnet.elasticache[count.index].id
  route_table_id = aws_route_table.elasticache[0].id
}

resource "aws_elasticache_subnet_group" "main" {
  count = var.enable_elasticache_subnets ? 1 : 0

  name        = "${local.name_prefix}-cache-subnet-group"
  description = "ElastiCache subnet group for ${local.name_prefix}"
  subnet_ids  = aws_subnet.elasticache[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-cache-subnet-group"
    }
  )
}

resource "aws_subnet" "intra" {
  count = var.enable_intra_subnets ? 3 : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.intra_subnet_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 12)
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-intra-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "intra" {
  count  = var.enable_intra_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-intra-rt"
    }
  )
}

resource "aws_route_table_association" "intra" {
  count = var.enable_intra_subnets ? 3 : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[0].id
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  description = "List of IDs of the NAT Gateways."
  value       = aws_nat_gateway.main[*].id
}

output "s3_endpoint_id" {
  description = "The ID of the S3 VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.84.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  uid        = random_id.suffix.hex

  # S3 bucket naming per objective with uniqueness suffix to prevent collision on retry
  bucket_artefacts_name = "benchmark-glue-artefacts-${local.account_id}-${local.uid}"
  bucket_staging_name   = "benchmark-datalake-staging-${local.account_id}-${local.uid}"
  bucket_bronze_name    = "benchmark-datalake-bronze-${local.account_id}-${local.uid}"
  bucket_silver_name    = "benchmark-datalake-silver-${local.account_id}-${local.uid}"
  bucket_gold_name      = "benchmark-datalake-gold-${local.account_id}-${local.uid}"
  bucket_logs_name      = "benchmark-datalake-logs-${local.account_id}-${local.uid}"

  extrai_script_exists    = fileexists("${path.module}/glueClima/extraiDados.py")
  extrai_script_content   = local.extrai_script_exists ? file("${path.module}/glueClima/extraiDados.py") : "# Glue extraiDados script\nimport sys\nfrom awsglue.utils import getResolvedOptions\nprint('Running extraiDados')\n"

  transforma_script_exists  = fileexists("${path.module}/glueClima/transformaDados.py")
  transforma_script_content = local.transforma_script_exists ? file("${path.module}/glueClima/transformaDados.py") : "# Glue transformaDados script\nimport sys\nfrom awsglue.utils import getResolvedOptions\nprint('Running transformaDados')\n"

  lib_zip_exists = fileexists("${path.module}/glueClima/lib.zip")
  lib_zip_base64 = "UEsFBgAAAAAAAAAAAAAAAAAAAAAAAA==" # Standard base64 empty zip
}

# -----------------------------------------------------------------------------
# Customer-Managed KMS Key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "data_lake" {
  description             = "KMS key for weather data lake pipeline"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowGlueAndAthenaAccess"
        Effect = "Allow"
        Principal = {
          Service = [
            "glue.amazonaws.com",
            "athena.amazonaws.com"
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "data_lake" {
  name_prefix   = "alias/benchmark-datalake-key-"
  target_key_id = aws_kms_key.data_lake.key_id
}

# -----------------------------------------------------------------------------
# S3 Buckets
# -----------------------------------------------------------------------------

# Artefacts Bucket
resource "aws_s3_bucket" "artefacts" {
  bucket = local.bucket_artefacts_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
