  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# S3 Objects (Glue scripts from local glueClima folder or fallbacks)
# -----------------------------------------------------------------------------

resource "aws_s3_object" "extrai_dados_script" {
  bucket  = aws_s3_bucket.artefacts.id
  key     = "scripts/extraiDados.py"
  content = local.extrai_script_content
  etag    = md5(local.extrai_script_content)
}

resource "aws_s3_object" "transforma_dados_script" {
  bucket  = aws_s3_bucket.artefacts.id
  key     = "scripts/transformaDados.py"
  content = local.transforma_script_content
  etag    = md5(local.transforma_script_content)
}

resource "aws_s3_object" "lib_zip" {
  bucket         = aws_s3_bucket.artefacts.id
  key            = "dependencies/lib.zip"
  content_base64 = local.lib_zip_exists ? filebase64("${path.module}/glueClima/lib.zip") : local.lib_zip_base64
  etag           = md5(base64decode(local.lib_zip_exists ? filebase64("${path.module}/glueClima/lib.zip") : local.lib_zip_base64))
}

# -----------------------------------------------------------------------------
# Athena / Glue Catalog Database "silver"
# -----------------------------------------------------------------------------

resource "aws_glue_catalog_database" "silver" {
  name         = "silver_${local.uid}"
  location_uri = "s3://${aws_s3_bucket.silver.id}/"

  parameters = {
    "encryption"     = "SSE-KMS"
    "kms_key_id"     = aws_kms_key.data_lake.arn
    "kms_master_key" = aws_kms_key.data_lake.arn
  }

  create_table_default_permission {
    permissions = ["ALL"]
    principal {
      data_lake_principal_identifier = "IAM_ALLOWED_PRINCIPALS"
    }
  }
}

# -----------------------------------------------------------------------------
# IAM Role and Policy for AWS Glue
# -----------------------------------------------------------------------------

resource "aws_iam_role" "glue_job" {
  name_prefix = "bm-weather-glue-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "glue_job" {
  name_prefix = "bm-weather-glue-policy-"
  description = "Policy for AWS Glue weather data pipeline jobs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsAndMetrics"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      },
      {
        Sid    = "GlueCatalogAccess"
        Effect = "Allow"
        Action = [
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:GetTable",
          "glue:GetTables",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:CreateTable",
          "glue:UpdateTable",
          "glue:DeleteTable",
          "glue:BatchCreatePartition",
          "glue:BatchGetPartition"
        ]
        Resource = [
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:catalog",
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:database/${aws_glue_catalog_database.silver.name}",
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:database/default",
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:table/${aws_glue_catalog_database.silver.name}/*"
        ]
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
      },
      {
        Sid    = "KMSKeyAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.data_lake.arn
      },
      {
        Sid    = "S3DataLakeBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.artefacts.arn,
          aws_s3_bucket.staging.arn,
          aws_s3_bucket.bronze.arn,
          aws_s3_bucket.silver.arn,
          aws_s3_bucket.gold.arn,
          aws_s3_bucket.logs.arn
        ]
      },
      {
        Sid    = "S3DataLakeObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "${aws_s3_bucket.artefacts.arn}/*",
          "${aws_s3_bucket.staging.arn}/*",
          "${aws_s3_bucket.bronze.arn}/*",
          "${aws_s3_bucket.silver.arn}/*",
          "${aws_s3_bucket.gold.arn}/*",
          "${aws_s3_bucket.logs.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_job" {
  role       = aws_iam_role.glue_job.name
  policy_arn = aws_iam_policy.glue_job.arn
}

# -----------------------------------------------------------------------------
# AWS Glue Jobs
# -----------------------------------------------------------------------------

resource "aws_glue_job" "extrai_dados" {
  name              = "glue-job-extrai-dados-${local.uid}"
  role_arn          = aws_iam_role.glue_job.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880
  execution_class   = "STANDARD"

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.artefacts.id}/${aws_s3_object.extrai_dados_script.key}"
    python_version  = "3"
  }

  execution_property {
    max_concurrent_runs = 2
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.logs.id}/temporary/"
    "--job-language"                     = "python"
    "--job-bookmark-option"              = "job-bookmark-disable"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-spark-ui"                  = "true"
    "--spark-event-logs-path"            = "s3://${aws_s3_bucket.logs.id}/spark-events/"
  }
}

resource "aws_glue_job" "transforma_dados" {
  name              = "glue-job-transforma-dados-${local.uid}"
  role_arn          = aws_iam_role.glue_job.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880
  execution_class   = "STANDARD"

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.artefacts.id}/${aws_s3_object.transforma_dados_script.key}"
    python_version  = "3"
  }

  execution_property {
    max_concurrent_runs = 2
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.logs.id}/temporary/"
    "--job-language"                     = "python"
    "--job-bookmark-option"              = "job-bookmark-disable"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-spark-ui"                  = "true"
    "--spark-event-logs-path"            = "s3://${aws_s3_bucket.logs.id}/spark-events/"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.artefacts.id}/${aws_s3_object.lib_zip.key}"
    "--datalake-formats"                 = "iceberg"
  }
}

# -----------------------------------------------------------------------------
# AWS Step Functions Orchestration
# -----------------------------------------------------------------------------

resource "aws_iam_role" "step_functions" {
  name_prefix = "bm-weather-sfn-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "step_functions" {
  name_prefix = "bm-weather-sfn-policy-"
  description = "IAM policy for Step Functions to run Glue jobs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageGlueJobRuns"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_functions" {
  role       = aws_iam_role.step_functions.name
  policy_arn = aws_iam_policy.step_functions.arn
}

resource "aws_sfn_state_machine" "pipeline" {
  name_prefix = "bm-weather-pipeline-"
  role_arn    = aws_iam_role.step_functions.arn

  definition = jsonencode({
    Comment = "Scheduled weather-data lake pipeline running Glue extraction and transformation"
    StartAt = "ExtractWeatherData"
    States = {
      ExtractWeatherData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"           = "Sao Paulo"
            "--staging_bucket" = "s3://${aws_s3_bucket.staging.id}"
            "--api_key"        = "PLACEHOLDER_API_KEY"
          }
        }
        Next = "TransformWeatherData"
      }
      TransformWeatherData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket"  = "s3://${aws_s3_bucket.staging.id}"
            "--bronze_bucket"   = "s3://${aws_s3_bucket.bronze.id}"
            "--silver_bucket"   = "s3://${aws_s3_bucket.silver.id}"
            "--translation_key" = "PLACEHOLDER_TRANSLATION_KEY"
          }
        }
        End = true
      }
    }
  })
}

# -----------------------------------------------------------------------------
# Amazon EventBridge Hourly Trigger
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eventbridge" {
  name_prefix = "bm-weather-evt-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "eventbridge" {
  name_prefix = "bm-weather-evt-policy-"
  description = "IAM policy for EventBridge to trigger Step Functions state machine"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartStateMachineExecution"
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = aws_sfn_state_machine.pipeline.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eventbridge" {
  role       = aws_iam_role.eventbridge.name
  policy_arn = aws_iam_policy.eventbridge.arn
}

resource "aws_cloudwatch_event_rule" "hourly_pipeline" {
  name_prefix         = "bm-weather-hourly-"
  description         = "Triggers weather data pipeline Step Functions state machine hourly"
  schedule_expression = "rate(1 hour)"
}

resource "aws_cloudwatch_event_target" "step_functions" {
  rule     = aws_cloudwatch_event_rule.hourly_pipeline.name
  arn      = aws_sfn_state_machine.pipeline.arn
  role_arn = aws_iam_role.eventbridge.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "repository_name" {
  type        = string
  description = "GitHub repository name"
  default     = "static-website-repo"
}

variable "repository_owner" {
  type        = string
  description = "GitHub repository owner (user or organization)"
  default     = "example-owner"
}

variable "branch_name" {
  type        = string
  description = "GitHub repository branch name"
  default     = "master"
}

variable "github_oauth_token_placeholder" {
  type        = string
  description = "Placeholder value for GitHub OAuth Token"
  default     = "CHANGE_ME_GITHUB_TOKEN"
  sensitive   = true
}

variable "github_webhook_secret_placeholder" {
  type        = string
  description = "Placeholder value for GitHub Webhook Secret"
  default     = "CHANGE_ME_WEBHOOK_SECRET_123456"
  sensitive   = true
}

variable "codestar_connection_arn" {
  type        = string
  description = "Optional CodeStar connection ARN. If supplied, CodePipeline uses CodeStarSourceConnection instead of GitHub v1."
  default     = ""
}

variable "enable_artifact_bucket_logging" {
  type        = bool
  description = "Enable access logging for the pipeline artifact bucket"
  default     = false
}

variable "enable_pipeline_notifications" {
  type        = bool
  description = "Enable SNS notifications for pipeline state changes"
  default     = false
}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  account_id         = data.aws_caller_identity.current.account_id
  partition          = data.aws_partition.current.partition
  region             = data.aws_region.current.name
  target_bucket_name = "benchmark-cicd-target-${local.account_id}"
  use_codestar       = var.codestar_connection_arn != ""
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCodeBuildAndPipelineKmsUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type = "AWS"
      identifiers = [
        aws_iam_role.codebuild_role.arn,
        aws_iam_role.codepipeline_role.arn
      ]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsAndCloudFront"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]
    principals {
      type = "Service"
      identifiers = [
        "logs.${local.region}.amazonaws.com",
        "cloudfront.amazonaws.com"
      ]
    }
  }
}

resource "aws_kms_key" "pipeline_key" {
  description             = "Customer managed KMS key for static site pipeline and target bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "pipeline_key_alias" {
  name          = "alias/benchmark-cicd-pipeline-key"
  target_key_id = aws_kms_key.pipeline_key.key_id
}

# -----------------------------------------------------------------------------
# Target S3 Bucket (Static Site Hosting via CloudFront)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "target_bucket" {
  bucket = local.target_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "target_bucket" {
  bucket                  = aws_s3_bucket.target_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "target_bucket" {
  bucket = aws_s3_bucket.target_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target_bucket" {
  bucket = aws_s3_bucket.target_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# -----------------------------------------------------------------------------
# Optional Artifact Access Logging Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "artifact_logs_bucket" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = "benchmark-cicd-artifact-logs-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_logs_bucket" {
  count                   = var.enable_artifact_bucket_logging ? 1 : 0
  bucket                  = aws_s3_bucket.artifact_logs_bucket[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "artifact_logs_bucket" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_logs_bucket[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_logs_bucket" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_logs_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# -----------------------------------------------------------------------------
# Artifact S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "artifact_bucket" {
  bucket = "benchmark-cicd-artifacts-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_bucket" {
  bucket                  = aws_s3_bucket.artifact_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "artifact_bucket" {
  bucket = aws_s3_bucket.artifact_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_bucket" {
  bucket = aws_s3_bucket.artifact_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "artifact_bucket" {
  count         = var.enable_artifact_bucket_logging ? 1 : 0
  bucket        = aws_s3_bucket.artifact_bucket.id
  target_bucket = aws_s3_bucket.artifact_logs_bucket[0].id
  target_prefix = "artifact-access-logs/"
}

resource "aws_s3_bucket_policy" "artifact_bucket_tls_enforce" {
  bucket = aws_s3_bucket.artifact_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifact_bucket.arn,
          "${aws_s3_bucket.artifact_bucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# WAFv2 Web ACL for CloudFront
# -----------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "benchmark_site_waf" {
  name        = "benchmark-cicd-site-waf"
  description = "WAFv2 Web ACL for static website CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "benchmarkCicdSiteWafMetric"
    sampled_requests_enabled   = true
  }
}

# -----------------------------------------------------------------------------
# CloudFront Distribution & Origin Access Control
# -----------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "benchmark-cicd-target-oac"
  description                       = "OAC for static website target bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "site_distribution" {
  origin {
    domain_name              = aws_s3_bucket.target_bucket.bucket_regional_domain_name
    origin_id                = "S3-${aws_s3_bucket.target_bucket.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_100"
  web_acl_id          = aws_wafv2_web_acl.benchmark_site_waf.arn

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.target_bucket.id}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_s3_bucket_policy" "target_bucket_policy" {
  bucket = aws_s3_bucket.target_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontServicePrincipalReadOnly"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.target_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site_distribution.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# SSM Parameters for GitHub Integration
# -----------------------------------------------------------------------------
resource "aws_ssm_parameter" "github_oauth_token" {
  name        = "/benchmark-cicd/github/oauth-token"
  description = "Personal access token for GitHub integration"
  type        = "SecureString"
  value       = var.github_oauth_token_placeholder
  key_id      = aws_kms_key.pipeline_key.arn
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/benchmark-cicd/github/webhook-secret"
  description = "Secret used to authenticate GitHub webhook requests"
  type        = "SecureString"
  value       = var.github_webhook_secret_placeholder
  key_id      = aws_kms_key.pipeline_key.arn
}

# -----------------------------------------------------------------------------
# Optional SNS Topic for Notifications
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "pipeline_notifications" {
  count             = var.enable_pipeline_notifications ? 1 : 0
  name              = "benchmark-cicd-pipeline-notifications"
  kms_master_key_id = aws_kms_key.pipeline_key.arn
}

# -----------------------------------------------------------------------------
# CodeBuild IAM Role and Policy
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_role" {
  name = "benchmark-cicd-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "benchmark-cicd-codebuild-policy"
  description = "Scoped policy for CodeBuild project"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*"
        ]
      },
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.artifact_bucket.arn,
          "${aws_s3_bucket.artifact_bucket.arn}/*"
        ]
      },
      {
        Sid    = "TargetBucketDeployAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.target_bucket.arn,
          "${aws_s3_bucket.target_bucket.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.pipeline_key.arn
        ]
      },
      {
        Sid    = "CloudFrontInvalidationAccess"
        Effect = "Allow"
        Action = [
          "cloudfront:CreateInvalidation"
        ]
        Resource = [
          aws_cloudfront_distribution.site_distribution.arn
        ]
      },
      {
        Sid    = "SSMParameterAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "ssm:GetParameter"
        ]
        Resource = [
          aws_ssm_parameter.github_oauth_token.arn,
          aws_ssm_parameter.github_webhook_secret.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# -----------------------------------------------------------------------------
# CodeBuild Project
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "site_build" {
  name          = "benchmark-cicd-site-build"
  description   = "Builds the static website and syncs artifacts to S3 target bucket"
  build_timeout = 5
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target_bucket.bucket
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.site_distribution.id
    }

    environment_variable {
      name  = "INVALIDATE_CACHE"
      value = "true"
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = <<-EOT
      version: 0.2
      phases:
        build:
          commands:
            - echo "Building static website..."
            - if [ ! -f index.html ]; then echo "<h1>Welcome to Static Site</h1>" > index.html; fi
        post_build:
          commands:
            - echo "Syncing to S3 bucket $TARGET_BUCKET..."
            - aws s3 sync . s3://$TARGET_BUCKET/ --exclude "*" --include "*.html" --include "*.css" --include "*.js" --include "*.png" --include "*.jpg" --include "*.svg"
            - |
              if [ "$INVALIDATE_CACHE" = "true" ]; then
                echo "Creating CloudFront invalidation for distribution $CLOUDFRONT_DISTRIBUTION_ID..."
                aws cloudfront create-invalidation --distribution-id $CLOUDFRONT_DISTRIBUTION_ID --paths "/*"
              fi
      artifacts:
        files:
          - '**/*'
    EOT
  }
}

# -----------------------------------------------------------------------------
# CodePipeline IAM Role and Policy
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_role" {
  name = "benchmark-cicd-codepipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
      }
    ]
  })
}

data "aws_iam_policy_document" "codepipeline_policy_doc" {
  statement {
    sid    = "S3ArtifactBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.artifact_bucket.arn,
      "${aws_s3_bucket.artifact_bucket.arn}/*"
    ]
  }

  statement {
    sid    = "KMSKeyAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = [
      aws_kms_key.pipeline_key.arn
    ]
  }

  statement {
    sid    = "CodeBuildAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild"
    ]
    resources = [
      aws_codebuild_project.site_build.arn
    ]
  }

  dynamic "statement" {
    for_each = local.use_codestar ? [1] : []
    content {
      sid       = "CodeStarConnectionAccess"
      effect    = "Allow"
      actions   = ["codestar-connections:UseConnection"]
      resources = [var.codestar_connection_arn]
    }
  }

  dynamic "statement" {
    for_each = var.enable_pipeline_notifications ? [1] : []
    content {
      sid       = "SNSPublishAccess"
      effect    = "Allow"
      actions   = ["sns:Publish"]
      resources = [aws_sns_topic.pipeline_notifications[0].arn]
    }
  }
}

resource "aws_iam_policy" "codepipeline_policy" {
  name        = "benchmark-cicd-codepipeline-policy"
  description = "Scoped policy for CodePipeline"
  policy      = data.aws_iam_policy_document.codepipeline_policy_doc.json
}

resource "aws_iam_role_policy_attachment" "codepipeline_attachment" {
  role       = aws_iam_role.codepipeline_role.name
  policy_arn = aws_iam_policy.codepipeline_policy.arn
}

# -----------------------------------------------------------------------------
# CodePipeline Pipeline
# -----------------------------------------------------------------------------
resource "aws_codepipeline" "site_pipeline" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.artifact_bucket.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.pipeline_key.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = local.use_codestar ? "AWS" : "ThirdParty"
      provider         = local.use_codestar ? "CodeStarSourceConnection" : "GitHub"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = local.use_codestar ? {
        ConnectionArn    = var.codestar_connection_arn
        FullRepositoryId = "${var.repository_owner}/${var.repository_name}"
        BranchName       = var.branch_name
      } : {
        Owner                = var.repository_owner
        Repo                 = var.repository_name
        Branch               = var.branch_name
        OAuthToken           = var.github_oauth_token_placeholder
        PollForSourceChanges = "false"
      }
    }
  }

  stage {
    name = "Build"

    action {
      name            = "Build"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      input_artifacts = ["source_output"]
      version         = "1"

      configuration = {
        ProjectName = aws_codebuild_project.site_build.name
      }
    }
  }
}

# -----------------------------------------------------------------------------
# GitHub Webhook (Enabled when using GitHub v1 OAuth integration)
# -----------------------------------------------------------------------------
resource "aws_codepipeline_webhook" "github_webhook" {
  count           = local.use_codestar ? 0 : 1
  name            = "benchmark-cicd-github-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.site_pipeline.name

  authentication_configuration {
    secret_token = var.github_webhook_secret_placeholder
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.branch_name}"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "create_vpc" {
  description = "Controls whether VPC and related network resources should be created."
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name tag of the VPC."
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "The IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "A tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_support" {
  description = "Controls whether DNS resolution is supported for the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Controls whether DNS hostnames are enabled in the VPC."
  type        = bool
  default     = false
}

variable "single_nat_gateway" {
  description = "Should be true if you want to provision a single shared NAT Gateway across all private networks."
  type        = bool
  default     = true
}

variable "one_nat_gateway_per_az" {
  description = "Should be true if you want only one NAT Gateway per availability zone. Requires single_nat_gateway to be false."
  type        = bool
  default     = false
}

variable "subnets" {
  description = "List of subnet group definitions. Each item defines a logical group of subnets, their class (public, private, intra), CIDRs mapped per availability zone, and optional database/elasticache subnet group inclusion."
  type = list(object({
    name                   = string
    class                  = string # "public", "private", or "intra"
    cidrs_by_az            = map(string)
    include_in_db_group    = optional(bool, false)
    include_in_elasticache = optional(bool, false)
  }))
  default = []

  validation {
    condition = alltrue([
      for s in var.subnets : contains(["public", "private", "intra"], s.class)
    ])
    error_message = "Subnet class must be one of: 'public', 'private', or 'intra'."
  }
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Local Values & Processing
# -----------------------------------------------------------------------------
locals {
  available_azs = data.aws_availability_zones.available.names

  flattened_subnets = {
    for item in flatten([
      for s in var.subnets : [
        for az, cidr in s.cidrs_by_az : {
          key                    = "${s.name}-${az}"
          group_name             = s.name
          class                  = s.class
          az                     = contains(local.available_azs, az) ? az : az
          cidr                   = cidr
          include_in_db_group    = coalesce(s.include_in_db_group, false)
          include_in_elasticache = coalesce(s.include_in_elasticache, false)
        }
      ]
    ]) : item.key => item if var.create_vpc
  }

  public_subnets  = { for k, v in local.flattened_subnets : k => v if v.class == "public" }
  private_subnets = { for k, v in local.flattened_subnets : k => v if v.class == "private" }
  intra_subnets   = { for k, v in local.flattened_subnets : k => v if v.class == "intra" }

  db_subnets          = { for k, v in local.flattened_subnets : k => v if v.include_in_db_group }
  elasticache_subnets = { for k, v in local.flattened_subnets : k => v if v.include_in_elasticache }

  create_igw = var.create_vpc && length(local.public_subnets) > 0

  # Determine NAT Gateway availability zones
  nat_gateway_azs = (
    var.create_vpc && length(local.public_subnets) > 0 && length(local.private_subnets) > 0 ? (
      var.single_nat_gateway ? [tolist(toset([for s in local.public_subnets : s.az]))[0]] : (
        var.one_nat_gateway_per_az ? tolist(toset([for s in local.public_subnets : s.az])) : []
      )
    ) : []
  )

  # Pick a public subnet in each NAT Gateway AZ
  nat_gateway_subnets = {
    for az in local.nat_gateway_azs : az => [
      for k, s in local.public_subnets : k if s.az == az
    ][0]
  }

  # Map AZ to the specific NAT Gateway index/key to route through
  private_az_to_nat_az = {
    for s in local.private_subnets : s.az => (
      var.single_nat_gateway ? local.nat_gateway_azs[0] : (
        contains(local.nat_gateway_azs, s.az) ? s.az : local.nat_gateway_azs[0]
      )
    ) if length(local.nat_gateway_azs) > 0
  }

  # Distinct AZs for private route tables
  private_route_table_azs = toset([for s in local.private_subnets : s.az])
}

# -----------------------------------------------------------------------------
# VPC Resource
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count = var.create_vpc ? 1 : 0

  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = var.instance_tenancy
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = false

  tags = merge(
    var.tags,
    {
      "Name" = var.vpc_name
    }
  )
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-igw"
    }
  )
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "this" {
  for_each = local.flattened_subnets

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = each.value.class == "public"

  tags = merge(
    var.tags,
    {
      "Name"  = "${var.vpc_name}-${each.value.group_name}-${each.value.az}"
      "Class" = each.value.class
      "Group" = each.value.group_name
    }
  )
}

# -----------------------------------------------------------------------------
# Elastic IPs and NAT Gateways
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  for_each = toset(local.nat_gateway_azs)

  domain = "vpc"

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-eip-nat-${each.value}"
    }
  )
}

resource "aws_nat_gateway" "this" {
  for_each = toset(local.nat_gateway_azs)

  allocation_id = aws_eip.nat[each.value].id
  subnet_id     = aws_subnet.this[local.nat_gateway_subnets[each.value]].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-nat-${each.value}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Route Tables: Public
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  count = length(local.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      "Name"  = "${var.vpc_name}-public"
      "Class" = "public"
    }
  )
}

resource "aws_route" "public_internet_access" {
  count = length(local.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

# -----------------------------------------------------------------------------
# Route Tables: Private
# -----------------------------------------------------------------------------
resource "aws_route_table" "private" {
  for_each = local.private_route_table_azs

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      "Name"  = "${var.vpc_name}-private-${each.value}"
      "Class" = "private"
    }
  )
}

resource "aws_route" "private_nat_access" {
  for_each = {
    for az in local.private_route_table_azs : az => local.private_az_to_nat_az[az]
    if contains(keys(local.private_az_to_nat_az), az)
  }

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.value].id
}

# -----------------------------------------------------------------------------
# Route Tables: Intra
# -----------------------------------------------------------------------------
resource "aws_route_table" "intra" {
  count = length(local.intra_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      "Name"  = "${var.vpc_name}-intra"
      "Class" = "intra"
    }
  )
}

# -----------------------------------------------------------------------------
# Route Table Associations
# -----------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[each.value.az].id
}

resource "aws_route_table_association" "intra" {
  for_each = local.intra_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

# -----------------------------------------------------------------------------
# Subnet Groups (Database & ElastiCache)
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "database" {
  count = length(local.db_subnets) > 0 ? 1 : 0

  name        = "${var.vpc_name}-db-subnet-group"
  description = "Database subnet group for ${var.vpc_name}"
  subnet_ids  = [for k, s in local.db_subnets : aws_subnet.this[k].id]

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-db-subnet-group"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_subnet_group" "elasticache" {
  count = length(local.elasticache_subnets) > 0 ? 1 : 0

  name        = "${var.vpc_name}-elasticache-subnet-group"
  description = "ElastiCache subnet group for ${var.vpc_name}"
  subnet_ids  = [for k, s in local.elasticache_subnets : aws_subnet.this[k].id]

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-elasticache-subnet-group"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "availability_zones" {
  description = "List of availability zones available in the region."
  value       = data.aws_availability_zones.available.names
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.main[0].id, null)
}

output "vpc_arn" {
  description = "The ARN of the VPC."
  value       = try(aws_vpc.main[0].arn, null)
}

output "vpc_cidr_block" {
  description = "The primary CIDR block of the VPC."
  value       = try(aws_vpc.main[0].cidr_block, null)
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "nat_gateway_ids" {
  description = "Map of AZ to NAT Gateway IDs."
  value       = { for k, v in aws_nat_gateway.this : k => v.id }
}

output "nat_gateway_public_ips" {
  description = "Map of AZ to NAT Gateway Elastic IP addresses."
  value       = { for k, v in aws_eip.nat : k => v.public_ip }
}

output "subnets_by_name" {
  description = "Map of subnet group name to list of subnet IDs."
  value = {
    for group in toset([for s in local.flattened_subnets : s.group_name]) :
    group => [
      for k, s in local.flattened_subnets : aws_subnet.this[k].id if s.group_name == group
    ]
  }
}

output "subnets_by_class" {
  description = "Map of subnet class to list of subnet IDs."
  value = {
    public  = [for k, s in local.public_subnets : aws_subnet.this[k].id]
    private = [for k, s in local.private_subnets : aws_subnet.this[k].id]
    intra   = [for k, s in local.intra_subnets : aws_subnet.this[k].id]
  }
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "Map of AZ to private route table IDs."
  value       = { for k, v in aws_route_table.private : k => v.id }
}

output "intra_route_table_id" {
  description = "The ID of the intra route table."
  value       = try(aws_route_table.intra[0].id, null)
}

output "db_subnet_group_name" {
  description = "The name of the database subnet group."
  value       = try(aws_db_subnet_group.database[0].name, null)
}

output "db_subnet_group_arn" {
  description = "The ARN of the database subnet group."
  value       = try(aws_db_subnet_group.database[0].arn, null)
}

output "elasticache_subnet_group_name" {
  description = "The name of the ElastiCache subnet group."
  value       = try(aws_elasticache_subnet_group.elasticache[0].name, null)
}

output "elasticache_subnet_group_arn" {
  description = "The ARN of the ElastiCache subnet group."
  value       = try(aws_elasticache_subnet_group.elasticache[0].arn, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  role_name             = "ec2-ssm-association"
  instance_profile_name = "ec2-s3-ssm-association"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_ssm_association" {
  name               = local.role_name
