  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "sqs_key" {
  description             = "Customer managed KMS key for aggregation-lambda-dead-letter-queue encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "aggregation-lambda-dlq-key"
  }
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/aggregation-lambda-dlq-key"
  target_key_id = aws_kms_key.sqs_key.arn
}

resource "aws_sqs_queue" "dlq" {
  name                      = "aggregation-lambda-dead-letter-queue"
  message_retention_seconds = 1209600
  kms_master_key_id         = aws_kms_key.sqs_key.arn

  tags = {
    Name = "aggregation-lambda-dead-letter-queue"
  }
}

