terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

locals {
  arn_prefix = "arn:${data.aws_partition.current.partition}:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# --- Create Backup Role and Policy ---

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid    = "DynamoDBCreateBackup"
    effect = "Allow"
    actions = [
      "dynamodb:CreateBackup"
    ]
    resources = [
      "${local.arn_prefix}:table/*"
    ]
  }

  statement {
    sid    = "DynamoDBDescribeBackup"
    effect = "Allow"
    actions = [
      "dynamodb:DescribeBackup"
    ]
    resources = [
      "${local.arn_prefix}:table/*/backup/*"
    ]
  }
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creating DynamoDB backups"
  policy      = data.aws_iam_policy_document.create_ddb_backup.json
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

# --- Remove Backup Role and Policy ---

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

data "aws_iam_policy_document" "remove_ddb_backup" {
  statement {
    sid    = "DynamoDBListBackups"
    effect = "Allow"
    actions = [
      "dynamodb:ListBackups"
    ]
    resources = [
      "*"
    ]
  }

  statement {
    sid    = "DynamoDBManageBackup"
    effect = "Allow"
    actions = [
      "dynamodb:DeleteBackup",
      "dynamodb:DescribeBackup"
    ]
    resources = [
      "${local.arn_prefix}:table/*/backup/*"
    ]
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deleting DynamoDB backups"
  policy      = data.aws_iam_policy_document.remove_ddb_backup.json
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

# --- Shared Lambda Logging Policy ---

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "CloudWatchLogsWrite"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/*"
    ]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared CloudWatch Logs write policy for Lambda functions"
  policy      = data.aws_iam_policy_document.lambda_logging.json
}

resource "aws_iam_role_policy_attachment" "create_role_lambda_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_role_lambda_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# --- Outputs ---

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role for creating DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role for creating DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role for removing DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role for removing DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.name
}

