terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  github_oidc_issuer_url = "https://token.actions.githubusercontent.com"
  github_oidc_audience   = "sts.amazonaws.com"
  github_issuer_hostpath = "token.actions.githubusercontent.com"

  # Flatten policy attachments for each optional role defined
  role_policy_attachments = flatten([
    for role_key, role_cfg in var.github_roles : [
      for policy_arn in lookup(role_cfg, "managed_policy_arns", []) : {
        role_key   = role_key
        policy_arn = policy_arn
      }
    ]
  ])
}

# --- Variables ---

variable "published_github_thumbprints" {
  type        = list(string)
  description = "Known published SHA-1 CA thumbprints for GitHub Actions OIDC."
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f8d73a8276"
  ]
}

variable "github_roles" {
  type = map(object({
    role_description      = optional(string, "GitHub Actions federated role")
    max_session_duration  = optional(number, 3600)
    repo_claims           = list(string) # List of sub claims, e.g. ["repo:octocat/hello-world:ref:refs/heads/main"]
    managed_policy_arns   = optional(list(string), [])
    inline_policy         = optional(string, null)
  }))
  description = "Optional map of IAM roles to create for GitHub Actions federation. Defaults to empty so no roles are created."
  default     = {}
}

variable "tags" {
  type        = map(string)
  description = "Tags applied to all supported resources."
  default = {
    Terraform   = "true"
    Environment = "production"
  }
}

# --- Data Sources ---

data "tls_certificate" "github_actions" {
  url = local.github_oidc_issuer_url
}

# --- Resources ---

# IAM OpenID Connect Provider for GitHub Actions
resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = local.github_oidc_issuer_url
  client_id_list  = [local.github_oidc_audience]
  thumbprint_list = distinct(concat(
    [for cert in data.tls_certificate.github_actions.certificates : cert.sha1_fingerprint],
    var.published_github_thumbprints
  ))

  tags = merge(
    var.tags,
    {
      Name = "github-actions-oidc-provider"
    }
  )
}

# Optional GitHub-Federated IAM Roles
resource "aws_iam_role" "github_actions" {
  for_each = var.github_roles

  name                 = each.key
  description          = each.value.role_description
  max_session_duration = each.value.max_session_duration

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github_actions.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${local.github_issuer_hostpath}:aud" = local.github_oidc_audience
          }
          StringLike = {
            "${local.github_issuer_hostpath}:sub" = each.value.repo_claims
          }
        }
      }
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = each.key
    }
  )
}

# Optional Inline Policies for Federated Roles
resource "aws_iam_role_policy" "github_actions" {
  for_each = {
    for k, v in var.github_roles : k => v
    if v.inline_policy != null
  }

  name   = "${each.key}-inline"
  role   = aws_iam_role.github_actions[each.key].id
  policy = each.value.inline_policy
}

# Optional Managed Policy Attachments for Federated Roles
resource "aws_iam_role_policy_attachment" "github_actions" {
  for_each = {
    for item in local.role_policy_attachments : "${item.role_key}.${item.policy_arn}" => item
  }

  role       = aws_iam_role.github_actions[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

# --- Outputs ---

output "openid_connect_provider_arn" {
  description = "The ARN of the GitHub Actions IAM OpenID Connect provider."
  value       = aws_iam_openid_connect_provider.github_actions.arn
}

output "openid_connect_provider_url" {
  description = "The URL of the GitHub Actions IAM OpenID Connect provider."
  value       = aws_iam_openid_connect_provider.github_actions.url
}

output "github_federated_role_arns" {
  description = "Map of role names to their corresponding IAM role ARNs."
  value       = { for k, v in aws_iam_role.github_actions : k => v.arn }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "projectvpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "projectvpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.projectvpc.id

  tags = {
    Name = "projectvpc-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "projectvpc-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "projectvpc-private-subnet"
  }
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "projectvpc-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = "projectvpc-nat-gw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "projectvpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "projectvpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

