terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "The name of the IAM role for GitHub Actions."
  default     = "github-actions-oidc-role"
}

variable "github_repositories" {
  type        = list(string)
  description = "Allowed GitHub repository patterns for the OIDC sub condition (e.g. repo:octocat/hello-world:*)."
  default     = []
}

data "tls_certificate" "github" {
  url = "https://token.actions.githubusercontent.com"
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [data.tls_certificate.github.certificates[0].sha1_fingerprint]
}

data "aws_iam_policy_document" "github_actions_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = length(var.github_repositories) > 0 ? var.github_repositories : ["repo:*"]
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.github_actions_assume_role.json
}

output "arn" {
  description = "ARN of the IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "name" {
  description = "Name of the IAM role."
  value       = aws_iam_role.github_actions.name
}

output "path" {
  description = "Path of the IAM role."
  value       = aws_iam_role.github_actions.path
}

output "unique_id" {
  description = "Unique ID of the IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "force_mfa" {
  # Statement 1: Allow users to view basic account information
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListAccountAliases"
    ]
    resources = ["*"]
  }

  # Statement 2: Allow users to manage their own password without MFA
  statement {
    sid    = "AllowManageOwnPassword"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
  }

  # Statement 3: Allow users to view their own MFA devices and list all virtual MFA devices
  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
  }

  # Statement 4: Allow users to enable their own virtual MFA device
  statement {
    sid    = "AllowEnableOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
  }

  # Statement 5: Allow MFA deactivation and broader self-management only when authenticated with MFA
  statement {
    sid    = "AllowDeactivateMFADeviceAndManageAccessWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # Statement 6: Block all other IAM actions if not signed in with MFA
  statement {
    sid    = "BlockMostAccessUnlessSignedInWithMFA"
    effect = "Deny"
    not_actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:GetUser",
      "iam:ListAccountAliases",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
      "iam:ChangePassword"
    ]
    resources = ["*"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows IAM users to view basic account information and manage their own credentials and MFA device, while requiring MFA for sensitive actions and broader access."
  policy      = data.aws_iam_policy_document.force_mfa.json
}

output "policy_arn" {
  description = "The ARN of the managed force MFA IAM policy."
  value       = aws_iam_policy.managed_force_mfa_policy.arn
}

output "policy_name" {
  description = "The name of the managed force MFA IAM policy."
  value       = aws_iam_policy.managed_force_mfa_policy.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

