# IAM Groups
# -----------------------------------------------------------------------------
resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

# -----------------------------------------------------------------------------
# IAM Users
# -----------------------------------------------------------------------------
resource "aws_iam_user" "billing_user" {
  name          = "Billing"
  force_destroy = true
}

resource "aws_iam_user" "admin_user" {
  name          = "Admin"
  force_destroy = true
}

resource "aws_iam_user" "suport_user" {
  name          = "Suport"
  force_destroy = true
}

# -----------------------------------------------------------------------------
# IAM User Login Profiles
# -----------------------------------------------------------------------------
resource "aws_iam_user_login_profile" "billing_login" {
  user                    = aws_iam_user.billing_user.name
  password_length         = 8
  password_reset_required = true

  lifecycle {
    ignore_changes = [password_reset_required]
  }
}

resource "aws_iam_user_login_profile" "admin_login" {
  user                    = aws_iam_user.admin_user.name
  password_length         = 8
  password_reset_required = true

  lifecycle {
    ignore_changes = [password_reset_required]
  }
}

resource "aws_iam_user_login_profile" "suport_login" {
  user                    = aws_iam_user.suport_user.name
  password_length         = 8
  password_reset_required = true

  lifecycle {
    ignore_changes = [password_reset_required]
  }
}

# -----------------------------------------------------------------------------
# Group Memberships
# -----------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "billing_membership" {
  user   = aws_iam_user.billing_user.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin_membership" {
  user   = aws_iam_user.admin_user.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport_membership" {
  user   = aws_iam_user.suport_user.name
  groups = [aws_iam_group.suport_group.name]
}

# -----------------------------------------------------------------------------
# Policies and Attachments
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Provides read-only access to billing, usage, budgets, cost reports, and pricing information"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingReadOnlyAccess"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "budgets:ViewBudget",
          "ce:Get*",
          "ce:Describe*",
          "cur:Describe*",
          "pricing:Describe*",
          "pricing:Get*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "billing_attachment" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin_attachment" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Provides read-only describe, get, and list access to EC2, S3, CloudWatch, and RDS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SupportReadOnlyAccess"
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "rds:Describe*",
          "rds:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "suport_attachment" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "billing_username" {
  description = "IAM username for the billing user"
  value       = aws_iam_user.billing_user.name
}

output "billing_password" {
  description = "Initial console password for the billing user"
  value       = aws_iam_user_login_profile.billing_login.password
  sensitive   = true
}

output "admin_username" {
  description = "IAM username for the admin user"
  value       = aws_iam_user.admin_user.name
}

output "admin_password" {
  description = "Initial console password for the admin user"
  value       = aws_iam_user_login_profile.admin_login.password
  sensitive   = true
}

output "suport_username" {
  description = "IAM username for the support user"
  value       = aws_iam_user.suport_user.name
}

output "suport_password" {
  description = "Initial console password for the support user"
  value       = aws_iam_user_login_profile.suport_login.password
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "shared-storage-test"
}

resource "random_uuid" "efs_token" {}

resource "aws_efs_file_system" "shared_storage" {
  creation_token   = "${local.name_prefix}-${random_uuid.efs_token.result}"
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"
  encrypted        = true

  tags = {
    Name        = "${local.name_prefix}-efs"
    Environment = "testing"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "shared_storage_backup_policy" {
  file_system_id = aws_efs_file_system.shared_storage.id

  backup_policy {
    status = "ENABLED"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  pipeline_bucket_obj = "arn:${data.aws_partition.current.partition}:s3:::nlp-pipeline-bucket/*"
}

resource "aws_kms_key" "terraform_state" {
  description             = "KMS key for Terraform remote state S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "glue_service_role" {
  name = "glue-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_service_role" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_s3_access" {
  name = "glue-nlp-bucket-access"
  role = aws_iam_role.glue_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = local.pipeline_bucket_obj
      }
    ]
  })
}

resource "aws_iam_role" "comprehend_service_role" {
  name = "comprehend-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "comprehend.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "comprehend_s3_access" {
  name = "comprehend-nlp-bucket-access"
  role = aws_iam_role.comprehend_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = local.pipeline_bucket_obj
      }
    ]
  })
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_inline_policy" {
  name = "lambda-pipeline-policy"
  role = aws_iam_role.lambda_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3PipelineBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = local.pipeline_bucket_obj
      },
      {
        Sid    = "DynamoDBNLPResultsWrite"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:UpdateItem"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/NLPResults"
      },
      {
        Sid    = "StepFunctionsStartExecution"
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:states:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:stateMachine:YourStateMachineName"
      }
    ]
  })
}

resource "aws_iam_role" "step_functions_service_role" {
  name = "step-functions-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_inline_policy" {
  name = "step-functions-pipeline-policy"
  role = aws_iam_role.step_functions_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "InvokeLambdaFunctions"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:*"
      },
      {
        Sid    = "StartGlueJobRuns"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:glue:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:job/*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      managedBy   = "terraform"
      application = "demo"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  bucket_name = "demo-artifact-store-${local.account_id}"
  ecr_repo    = "zenml-kubernetes"

  common_tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

# KMS Key for Artifact Store SSE-KMS
resource "aws_kms_key" "zenml_artifacts" {
  description             = "Customer managed KMS key for ZenML S3 artifact store encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "zenml_artifacts" {
  name          = "alias/zenml-artifact-store"
  target_key_id = aws_kms_key.zenml_artifacts.key_id
}

# S3 Artifact Store Bucket
resource "aws_s3_bucket" "zenml_artifacts" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = local.common_tags
}

resource "aws_s3_bucket_ownership_controls" "zenml_artifacts" {
  bucket = aws_s3_bucket.zenml_artifacts.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "zenml_artifacts" {
  depends_on = [aws_s3_bucket_ownership_controls.zenml_artifacts]

  bucket = aws_s3_bucket.zenml_artifacts.id
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "zenml_artifacts" {
  bucket = aws_s3_bucket.zenml_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "zenml_artifacts" {
  bucket = aws_s3_bucket.zenml_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.zenml_artifacts.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# ECR Repository
resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = local.ecr_repo
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags
}

# ZenML Stack Configuration File
resource "local_file" "zenml_stack" {
  filename = "${path.module}/zenml-stack.yaml"
  content  = <<-EOT
    zenml_version: "0.12.0"
    stack_name: "aws-zenml-stack"
    components:
      artifact_store:
        flavor: "s3"
        name: "s3_artifact_store"
        configuration:
          path: "s3://${aws_s3_bucket.zenml_artifacts.bucket}"
      container_registry:
        flavor: "default"
        name: "aws_container_registry"
        configuration:
          uri: "${local.account_id}.dkr.ecr.${local.region}.amazonaws.com"
      secrets_manager:
        flavor: "aws"
        name: "aws_secrets_manager"
        configuration:
          region_name: "${local.region}"
  EOT
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name_prefix        = "nim-ecs_task_execution-"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_managed_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_secretsmanager_secret" "repo_secret" {
  name_prefix = "nim-reposecret-"
}

resource "aws_secretsmanager_secret_version" "repo_secret_version" {
  secret_id = aws_secretsmanager_secret.repo_secret.id
  secret_string = jsonencode({
    username = "AWS"
    password = ""
  })
}

data "aws_iam_policy_document" "ecs_task_access_secrets" {
  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      aws_secretsmanager_secret.repo_secret.arn
    ]
  }
}

resource "aws_iam_role_policy" "ecs_task_access_secrets_policy" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.ecs_task_execution_role.id
  policy = data.aws_iam_policy_document.ecs_task_access_secrets.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "ou_paths" {
  description = "List of slash-delimited OU path hierarchies up to 5 levels deep (e.g., ['Core/Security/Prod', 'Workloads/Dev'])"
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for p in var.ou_paths : length(split("/", trim(p, "/"))) <= 5 && length(split("/", trim(p, "/"))) >= 1
    ])
    error_message = "All OU paths must contain between 1 and 5 levels separated by forward slashes."
  }
}

locals {
  # Normalize paths by trimming leading/trailing slashes and splitting into elements
  normalized_paths = [
    for p in var.ou_paths : [
      for seg in split("/", trim(p, "/")) : trimspace(seg)
    ]
  ]

  # Level 1 OUs: Unique top-level OU names
  level_1_ous = toset(distinct([
    for segs in local.normalized_paths : segs[0]
    if length(segs) >= 1
  ]))

  # Level 2 OUs: key is "L1/L2", name is "L2", parent_key is "L1"
  level_2_ous = {
    for segs in local.normalized_paths :
    join("/", slice(segs, 0, 2)) => {
      name       = segs[1]
      parent_key = segs[0]
    }
    if length(segs) >= 2
  }

  # Level 3 OUs: key is "L1/L2/L3", name is "L3", parent_key is "L1/L2"
  level_3_ous = {
    for segs in local.normalized_paths :
    join("/", slice(segs, 0, 3)) => {
      name       = segs[2]
      parent_key = join("/", slice(segs, 0, 2))
    }
    if length(segs) >= 3
  }

  # Level 4 OUs: key is "L1/L2/L3/L4", name is "L4", parent_key is "L1/L2/L3"
  level_4_ous = {
    for segs in local.normalized_paths :
    join("/", slice(segs, 0, 4)) => {
      name       = segs[3]
      parent_key = join("/", slice(segs, 0, 3))
    }
    if length(segs) >= 4
  }

  # Level 5 OUs: key is "L1/L2/L3/L4/L5", name is "L5", parent_key is "L1/L2/L3/L4"
  level_5_ous = {
    for segs in local.normalized_paths :
    join("/", slice(segs, 0, 5)) => {
      name       = segs[4]
      parent_key = join("/", slice(segs, 0, 4))
    }
    if length(segs) >= 5
  }
}

resource "aws_organizations_organization" "org" {
  feature_set = "ALL"
  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]
}

resource "aws_organizations_organizational_unit" "level_1" {
  for_each  = local.level_1_ous
  name      = each.value
  parent_id = aws_organizations_organization.org.roots[0].id
}

resource "aws_organizations_organizational_unit" "level_2" {
  for_each  = local.level_2_ous
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_1[each.value.parent_key].id
}

resource "aws_organizations_organizational_unit" "level_3" {
  for_each  = local.level_3_ous
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_2[each.value.parent_key].id
}

resource "aws_organizations_organizational_unit" "level_4" {
  for_each  = local.level_4_ous
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_3[each.value.parent_key].id
}

resource "aws_organizations_organizational_unit" "level_5" {
  for_each  = local.level_5_ous
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_4[each.value.parent_key].id
}

output "organization_id" {
  description = "The unique identifier (ID) of the AWS Organization"
  value       = aws_organizations_organization.org.id
}

output "organization_arn" {
  description = "The Amazon Resource Name (ARN) of the AWS Organization"
  value       = aws_organizations_organization.org.arn
}

output "organization_root_id" {
  description = "The identifier (ID) of the AWS Organization root container"
  value       = aws_organizations_organization.org.roots[0].id
}

output "organizational_units" {
  description = "Map of all created Organizational Unit paths to their AWS OU IDs"
  value = merge(
    { for path, ou in aws_organizations_organizational_unit.level_1 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_2 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_3 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_4 : path => ou.id },
    { for path, ou in aws_organizations_organizational_unit.level_5 : path => ou.id }
  )
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name          = "swe-vpc"
    ResourceGroup = "default"
  }
}

resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  # Ingress: Deny SSH from anywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 10
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  # Ingress: Deny RDP from anywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 20
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  # Ingress: Allow all traffic from the VPC's own CIDR
  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.swe_vpc.cidr_block
    from_port  = 0
    to_port    = 0
  }

  # Egress: Allow all outbound traffic to the VPC CIDR
  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.swe_vpc.cidr_block
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "swe-vpc-default_acl"
  }
}

resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  tags = {
    Name = "swe-vpc-default_sg"
  }
}

resource "aws_security_group_rule" "allow_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
}

resource "aws_security_group_rule" "allow_icmp_echo" {
  type              = "ingress"
  from_port         = 8
  to_port           = 0
  protocol          = "icmp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
}

