# Outputs
# ---------------------------------------------------------

output "vpc_dev_id" {
  description = "The ID of the development VPC"
  value       = aws_vpc.vpc_dev.id
}

output "vpc_rec_id" {
  description = "The ID of the recette VPC"
  value       = aws_vpc.vpc_rec.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type        = string
  default     = "eg"
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'"
}

variable "environment" {
  type        = string
  default     = "use1"
  description = "Environment, e.g. 'uw2', 'us-west-2', OR 'use1' for us-east-1"
}

variable "stage" {
  type        = string
  default     = "prod"
  description = "Stage, e.g. 'prod', 'staging', 'dev', OR 'test'"
}

variable "name" {
  type        = string
  default     = "guardduty"
  description = "Solution name, e.g. 'app' or 'guardduty'"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes (e.g. `1`)"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`"
}

variable "enable_notifications" {
  type        = bool
  default     = false
  description = "Enable SNS notifications and EventBridge rule for GuardDuty findings"
}

variable "finding_publishing_frequency" {
  type        = string
  default     = null
  description = "The frequency of notifications sent for subsequent finding occurrences. If null, uses AWS service default (SIX_HOURS)"
}

locals {
  name_parts = compact(concat(
    [var.namespace, var.environment, var.stage, var.name],
    var.attributes
  ))
  id = lower(join("-", local.name_parts))

  default_tags = {
    Namespace   = var.namespace
    Environment = var.environment
    Stage       = var.stage
    Name        = local.id
  }

  tags = merge(local.default_tags, var.tags)
}

resource "aws_guardduty_detector" "detector" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = false
    }
  }

  tags = local.tags
}

resource "aws_sns_topic" "guardduty_notifications" {
  count             = var.enable_notifications ? 1 : 0
  name              = "${local.id}-findings"
  kms_master_key_id = "alias/aws/sns"
  tags              = local.tags
}

resource "aws_sns_topic_policy" "guardduty_notifications" {
  count  = var.enable_notifications ? 1 : 0
  arn    = aws_sns_topic.guardduty_notifications[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.enable_notifications ? 1 : 0

  statement {
    sid    = "AllowEventBridgePublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    resources = [
      aws_sns_topic.guardduty_notifications[0].arn
    ]
    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values = [
        aws_cloudwatch_event_rule.guardduty_findings[0].arn
      ]
    }
  }
}

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  count       = var.enable_notifications ? 1 : 0
  name        = "${local.id}-findings-rule"
  description = "Capture Amazon GuardDuty finding events"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = local.tags
}

resource "aws_cloudwatch_event_target" "guardduty_findings_sns" {
  count     = var.enable_notifications ? 1 : 0
  rule      = aws_cloudwatch_event_rule.guardduty_findings[0].name
  target_id = "SendToSNS"
  arn       = aws_sns_topic.guardduty_notifications[0].arn
}

output "guardduty_detector_id" {
  description = "The ID of the GuardDuty detector"
  value       = aws_guardduty_detector.detector.id
}

output "guardduty_detector_arn" {
  description = "The ARN of the GuardDuty detector"
  value       = aws_guardduty_detector.detector.arn
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic for GuardDuty findings notifications if enabled"
  value       = try(aws_sns_topic.guardduty_notifications[0].arn, null)
}

output "event_rule_arn" {
  description = "The ARN of the EventBridge rule for GuardDuty findings notifications if enabled"
  value       = try(aws_cloudwatch_event_rule.guardduty_findings[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "random_string" "suffix" {
  length  = 6
  upper   = false
  special = false
  numeric = true
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAWSBackupToUseKey"
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "backup_key" {
  description             = "KMS key for AWS Backup vault encryption - ${local.prefix}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "${local.prefix}-kms-key"
  }
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/${local.prefix}-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

resource "aws_backup_vault" "vault" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "${local.prefix}-backup-vault"
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "${local.prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_policy_attach" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "plan" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = "cron(0 12 * * ? *)"

    recovery_point_tags = {
      Name = "${local.prefix}-recovery-point"
    }
  }

  tags = {
    Name = "${local.prefix}-backup-plan"
  }
}

resource "aws_backup_selection" "selection" {
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.plan.id
  iam_role_arn = aws_iam_role.backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  app_name = "coop-tweets"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_cognito_user_pool" "coop_tweets" {
  name = local.app_name

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
    require_lowercase = false
  }
}

resource "aws_cognito_user_pool_domain" "coop_tweets_domain" {
  domain       = "coop-tweets-domain"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

resource "aws_cognito_user_pool_client" "coop_tweets_client" {
  name         = local.app_name
  user_pool_id = aws_cognito_user_pool.coop_tweets.id

  generate_secret = false
  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH"
  ]
}

resource "aws_cognito_identity_pool" "coop_tweets" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.coop_tweets_client.id
    provider_name           = aws_cognito_user_pool.coop_tweets.endpoint
    server_side_token_check = false
  }
}

data "aws_iam_policy_document" "cognito_authenticated_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.coop_tweets.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "cognito_unauthenticated_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.coop_tweets.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "cognito_authenticated" {
  name               = "coop-tweets_cognito_auth_role"
  assume_role_policy = data.aws_iam_policy_document.cognito_authenticated_trust.json
}

resource "aws_iam_role" "cognito_unauthenticated" {
  name               = "coop-tweets_cognito_unauth_role"
  assume_role_policy = data.aws_iam_policy_document.cognito_unauthenticated_trust.json
}

data "aws_iam_policy_document" "cognito_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents"
    ]
    resources = [
      "arn:aws:mobileanalytics:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:apps/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "cognito-sync:*"
    ]
    resources = [
      "arn:aws:cognito-sync:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypools/${aws_cognito_identity_pool.coop_tweets.id}"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "cognito-identity:*"
    ]
    resources = [
      "arn:aws:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.coop_tweets.id}"
    ]
  }
}

resource "aws_iam_policy" "authenticated" {
  name        = "cognito_kibana_auth_coop-tweets"
  description = "Cognito Kibana auth policy for coop-tweets"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_policy" "unauthenticated" {
  name        = "cognito_kibana_unauth_coop-tweets"
  description = "Cognito Kibana unauth policy for coop-tweets"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_role_policy_attachment" "authenticated" {
  role       = aws_iam_role.cognito_authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

resource "aws_iam_role_policy_attachment" "unauthenticated" {
  role       = aws_iam_role.cognito_unauthenticated.name
  policy_arn = aws_iam_policy.unauthenticated.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets.id

  roles = {
    authenticated   = aws_iam_role.cognito_authenticated.arn
    unauthenticated = aws_iam_role.cognito_unauthenticated.arn
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_s3_export" {
  type        = bool
  default     = false
  description = "Controls whether to create S3 bucket and export GuardDuty findings."
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
}

# KMS Key for GuardDuty findings encryption
data "aws_iam_policy_document" "kms_guardduty" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowGuardDutyKeyUsage"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:aws:guardduty:${local.region}:${local.account_id}:detector/*"]
    }
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "KMS key used to encrypt GuardDuty findings exports"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_guardduty.json
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

# GuardDuty Detector
resource "aws_guardduty_detector" "primary" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

# Optional S3 Export Resources
resource "aws_s3_bucket" "findings" {
  count         = var.enable_s3_export ? 1 : 0
  bucket_prefix = "guardduty-findings-${local.account_id}-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.guardduty.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "findings_bucket_policy" {
  count = var.enable_s3_export ? 1 : 0

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.guardduty.arn]
    }
  }

  statement {
    sid       = "DenyNonSSLRequests"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.findings[0].arn,
      "${aws_s3_bucket.findings[0].arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "findings" {
  count      = var.enable_s3_export ? 1 : 0
  bucket     = aws_s3_bucket.findings[0].id
  policy     = data.aws_iam_policy_document.findings_bucket_policy[0].json
  depends_on = [aws_s3_bucket_public_access_block.findings]
}

resource "aws_guardduty_publishing_destination" "s3" {
  count            = var.enable_s3_export ? 1 : 0
  detector_id      = aws_guardduty_detector.primary.id
  destination_arn  = aws_s3_bucket.findings[0].arn
  kms_key_arn      = aws_kms_key.guardduty.arn
  destination_type = "S3"

  depends_on = [aws_s3_bucket_policy.findings]
}

# EventBridge Rule for GuardDuty Findings
resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  name        = "guardduty-finding-events"
  description = "Matches all Amazon GuardDuty Finding events"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "kms_key" {
  description             = "Customer managed KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket" "this" {
  bucket_prefix = "app-bucket-"
  force_destroy = true

  tags = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_acl" "this" {
  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

variable "billing_full_access_users" {
  type        = list(string)
  description = "List of IAM usernames to assign to the billing-full-access group."
  default     = []
}

variable "billing_view_access_users" {
  type        = list(string)
  description = "List of IAM usernames to assign to the billing-view-access group."
  default     = []
}

data "aws_iam_policy_document" "mfa_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "BillingFullAccess"
    effect = "Allow"
    actions = [
      "aws-portal:*Billing*",
      "aws-portal:*PaymentMethods*",
      "aws-portal:*Usage*",
      "account:GetAccountInformation",
      "account:GetContactInformation",
      "account:ListRegions",
      "account:PutAccountInformation",
      "account:PutContactInformation",
      "budgets:*",
      "ce:*",
      "cur:*",
      "freetier:*",
      "invoicing:*",
      "payments:*",
      "tax:*"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "BillingViewAccess"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewPaymentMethods",
      "aws-portal:ViewUsage",
      "account:GetAccountInformation",
      "account:GetContactInformation",
      "account:ListRegions",
      "budgets:Describe*",
      "budgets:View*",
      "ce:Describe*",
      "ce:Get*",
      "ce:List*",
      "cur:Describe*",
      "freetier:Get*",
      "invoicing:Get*",
      "invoicing:List*",
      "payments:Get*",
      "payments:List*",
      "tax:Get*",
      "tax:List*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Customer managed policy allowing full access to AWS billing, usage, payment methods, and budgets"
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "Customer managed policy allowing read-only access to AWS billing, usage, payment methods, and budgets"
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  path               = "/"
  description        = "IAM role for full billing management conditioned on MFA"
  assume_role_policy = data.aws_iam_policy_document.mfa_assume_role.json
}

resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  path               = "/"
  description        = "IAM role for view-only billing access conditioned on MFA"
  assume_role_policy = data.aws_iam_policy_document.mfa_assume_role.json
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    sid       = "AssumeBillingFullAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    sid       = "AssumeBillingViewAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  path        = "/"
  description = "Allows group members to assume the billing-full-access role"
  policy      = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  path        = "/"
  description = "Allows group members to assume the billing-view-access role"
  policy      = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

resource "aws_iam_group_policy_attachment" "billing_full_access" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group_policy_attachment" "billing_view_access" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

resource "aws_iam_group_membership" "billing_full_access" {
  count = length(var.billing_full_access_users) > 0 ? 1 : 0
  name  = "billing-full-access-membership"
  group = aws_iam_group.billing_full_access.name
  users = var.billing_full_access_users
}

resource "aws_iam_group_membership" "billing_view_access" {
  count = length(var.billing_view_access_users) > 0 ? 1 : 0
  name  = "billing-view-access-membership"
  group = aws_iam_group.billing_view_access.name
  users = var.billing_view_access_users
}

output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access IAM role"
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access IAM role"
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access IAM group"
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access IAM group"
  value       = aws_iam_group.billing_view_access.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

resource "random_pet" "name" {
  prefix = "cognito"
  length = 2
}

resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = false
  special = false
}

locals {
  base_name        = random_pet.name.id
  user_pool_name   = replace(local.base_name, "-", "_")
  sms_role_name    = "${local.base_name}-sms-role"
  auth_role_name   = "${local.base_name}-signed-users-role"
  unauth_role_name = "${local.base_name}-anonymous-users-role"
  partition        = data.aws_partition.current.partition
  region           = data.aws_region.current.name
  account_id       = data.aws_caller_identity.current.account_id
}

data "aws_iam_policy_document" "sms_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cognito-idp.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.sms_external_id.result]
    }
  }
}

resource "aws_iam_role" "sms_role" {
  name               = local.sms_role_name
  assume_role_policy = data.aws_iam_policy_document.sms_assume_role.json
}

data "aws_iam_policy_document" "sms_publish" {
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "sms_publish" {
  name        = "${local.base_name}-sms-policy"
  description = "Allows Cognito to publish SMS messages via SNS"
  policy      = data.aws_iam_policy_document.sms_publish.json
}

resource "aws_iam_role_policy_attachment" "sms_publish" {
  role       = aws_iam_role.sms_role.name
  policy_arn = aws_iam_policy.sms_publish.arn
}

resource "aws_cognito_user_pool" "pool" {
  name                     = local.user_pool_name
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]

  sms_configuration {
    external_id    = random_string.sms_external_id.result
    sns_caller_arn = aws_iam_role.sms_role.arn
  }

  schema {
    attribute_data_type      = "String"
    name                     = "email"
    required                 = true
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "phone_number"
    required                 = false
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "profile_user_id"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "profile_email"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "given_name"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "family_name"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "gender"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "age"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "persona"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name         = "${local.base_name}-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

resource "aws_cognito_identity_pool" "identity_pool" {
  identity_pool_name               = replace(local.base_name, "-", " ")
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.pool.endpoint
    server_side_token_check = false
  }
}

data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "unauthenticated_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = local.auth_role_name
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json
}

resource "aws_iam_role" "unauthenticated" {
  name               = local.unauth_role_name
  assume_role_policy = data.aws_iam_policy_document.unauthenticated_assume_role.json
}

data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "cognito-identity:GetId",
      "cognito-identity:GetCredentialsForIdentity",
      "cognito-identity:GetOpenIdToken"
    ]
    resources = [
      "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "cognito-sync:DescribeDataset",
      "cognito-sync:ListDatasets",
      "cognito-sync:ListRecords",
      "cognito-sync:QueryRecords",
      "cognito-sync:SubscribeToDataset",
      "cognito-sync:UnsubscribeFromDataset",
      "cognito-sync:UpdateRecords"
    ]
    resources = [
      "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}/*"
    ]
  }
}

resource "aws_iam_policy" "authenticated" {
  name        = "${local.base_name}-signed-users-policy"
  description = "Scoped permissions for authenticated identities"
  policy      = data.aws_iam_policy_document.authenticated_permissions.json
}

resource "aws_iam_role_policy_attachment" "authenticated" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

data "aws_iam_policy_document" "unauthenticated_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "cognito-identity:GetId",
      "cognito-identity:GetCredentialsForIdentity",
      "cognito-identity:GetOpenIdToken"
    ]
    resources = [
      "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}"
    ]
  }
}

resource "aws_iam_policy" "unauthenticated" {
  name        = "${local.base_name}-anonymous-users-policy"
  description = "Scoped permissions for unauthenticated identities"
  policy      = data.aws_iam_policy_document.unauthenticated_permissions.json
}

resource "aws_iam_role_policy_attachment" "unauthenticated" {
  role       = aws_iam_role.unauthenticated.name
  policy_arn = aws_iam_policy.unauthenticated.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "identity_pool_roles" {
  identity_pool_id = aws_cognito_identity_pool.identity_pool.id

  roles = {
    "authenticated"   = aws_iam_role.authenticated.arn
    "unauthenticated" = aws_iam_role.unauthenticated.arn
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "${terraform.workspace}-batch"
  vpc_cidr    = "192.168.0.0/16"
  common_tags = {
    Name        = "${terraform.workspace}-batch"
    Environment = terraform.workspace
  }
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-ecs-hvm-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# KMS Key for S3 Bucket Encryption
resource "aws_kms_key" "batch" {
  description             = "KMS key for Batch results bucket - ${local.name_prefix}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "batch" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.batch.key_id
}

# S3 Results Bucket
resource "aws_s3_bucket" "results" {
  bucket = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.batch.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Network Resources
resource "aws_vpc" "batch" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = local.common_tags
}

resource "aws_internet_gateway" "batch" {
  vpc_id = aws_vpc.batch.id

  tags = local.common_tags
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.batch.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-public-subnet"
    Environment = terraform.workspace
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.batch.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-private-subnet"
    Environment = terraform.workspace
  }
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.batch]

  tags = {
    Name        = "${local.name_prefix}-nat-eip"
    Environment = terraform.workspace
  }
}

resource "aws_nat_gateway" "batch" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = local.common_tags

  depends_on = [aws_internet_gateway.batch]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.batch.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.batch.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = terraform.workspace
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.batch.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.batch.id
  }

  tags = {
    Name        = "${local.name_prefix}-private-rt"
    Environment = terraform.workspace
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# Security Group
resource "aws_security_group" "batch" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Batch compute environment instances"
  vpc_id      = aws_vpc.batch.id

  egress {
    description = "Allow HTTPS to VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = local.common_tags
}

# IAM Roles and Policies
resource "aws_iam_role" "batch_service" {
  name = "${local.name_prefix}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
}

resource "aws_iam_role" "ecs_instance" {
  name = "${local.name_prefix}-ecs-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_instance" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_policy" "ecs_s3_policy" {
  name        = "ecs_s3_policy"
  description = "Permissions for ECS instances to interact with S3 and KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3GeneralReadList"
        Effect = "Allow"
        Action = [
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation"
        ]
        Resource = "arn:aws:s3:::*"
      },
      {
        Sid    = "S3ResultsBucketOperations"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          aws_s3_bucket.results.arn,
          "${aws_s3_bucket.results.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = aws_kms_key.batch.arn
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_s3" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3_policy.arn
}

resource "aws_iam_instance_profile" "batch" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = local.common_tags
}

# AWS Batch Resources
resource "aws_batch_compute_environment" "batch" {
  compute_environment_name = local.name_prefix
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    min_vcpus           = 0
    max_vcpus           = 4
    instance_type       = ["optimal"]
    image_id            = data.aws_ami.ecs_al2023.id
    instance_role       = aws_iam_instance_profile.batch.arn

    subnets = [
      aws_subnet.private.id
    ]

    security_group_ids = [
      aws_security_group.batch.id
    ]

    tags = local.common_tags
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.batch_service]
}

resource "aws_batch_job_queue" "batch" {
  name     = "${local.name_prefix}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    order               = 1
    compute_environment = aws_batch_compute_environment.batch.arn
  }

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
  user_name   = "endpoint-backup"
  policy_name = "endpoint-backup-bucket-read-write-access"
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = local.bucket_name
  object_lock_enabled = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "endpoint_backup_bucket_policy" {
  statement {
    sid    = "S3ServerAccessLogsDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]
  }

  statement {
    sid    = "EnforceTLSRequestsOnly"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "EnforceTLSVersion"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceLockOver90Days"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObjectRetention",
      "s3:PutObject"
    ]

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket     = aws_s3_bucket.endpoint_backup.id
  policy     = data.aws_iam_policy_document.endpoint_backup_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

resource "aws_iam_user" "endpoint_backup" {
  name = local.user_name
}

data "aws_iam_policy_document" "endpoint_backup_user_policy" {
  statement {
    sid    = "BucketListAndLocationAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation"
    ]
    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid    = "ObjectReadWriteRetentionAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObject",
      "s3:PutObjectRetention",
      "s3:PutObjectLegalHold",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:RestoreObject"
    ]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "AwsManagedKmsS3KeyAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:kms:*:${data.aws_caller_identity.current.account_id}:alias/aws/s3"
    ]
  }
}

resource "aws_iam_policy" "endpoint_backup_rw" {
  name        = local.policy_name
  description = "Grant read, write, delete, version, retention, and restore access to the endpoint backup bucket and KMS permissions."
  policy      = data.aws_iam_policy_document.endpoint_backup_user_policy.json
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_rw.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --- Variables ---

variable "unity_uds_distribution_callback_urls" {
  type        = list(string)
  description = "Callback URLs for unity-uds-distribution-user-pool-client"
  default     = ["https://api.example.com/uds/oauth2/callback"]
}

variable "unity_uds_distribution_logout_urls" {
  type        = list(string)
  description = "Logout URLs for unity-uds-distribution-user-pool-client"
  default     = ["https://api.example.com/uds/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  type        = list(string)
  description = "Callback URLs for localhost-jupyterhub-user-pool-client"
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  type        = list(string)
  description = "Logout URLs for localhost-jupyterhub-user-pool-client"
  default     = ["http://localhost:8000/hub/logout"]
}

variable "unity_app_to_app_callback_urls" {
  type        = list(string)
  description = "Callback URLs for unity-app-to-app-client-user-pool-client"
  default     = ["https://api.example.com/app/oauth2/callback"]
}

variable "unity_app_to_app_logout_urls" {
  type        = list(string)
  description = "Logout URLs for unity-app-to-app-client-user-pool-client"
  default     = ["https://api.example.com/app/logout"]
}

variable "uads_jupyter_dev_callback_urls" {
  type        = list(string)
  description = "Callback URLs for uads-jupyter-development-client-user-pool-client"
  default     = ["https://uads-dev.example.com/hub/oauth_callback"]
}

variable "uads_jupyter_dev_logout_urls" {
  type        = list(string)
  description = "Logout URLs for uads-jupyter-development-client-user-pool-client"
  default     = ["https://uads-dev.example.com/hub/logout"]
}

variable "hysds_ui_callback_urls" {
  type        = list(string)
  description = "Callback URLs for hysds-ui-client-user-pool-client"
  default     = ["https://hysds-ui.example.com/oauth2/callback"]
}

variable "hysds_ui_logout_urls" {
  type        = list(string)
  description = "Logout URLs for hysds-ui-client-user-pool-client"
  default     = ["https://hysds-ui.example.com/logout"]
}

variable "localhost_hysds_ui_callback_urls" {
  type        = list(string)
  description = "Callback URLs for localhost-hysds-ui-client-user-pool-client"
  default     = ["http://localhost:3000/oauth2/callback"]
}

variable "localhost_hysds_ui_logout_urls" {
  type        = list(string)
  description = "Logout URLs for localhost-hysds-ui-client-user-pool-client"
  default     = ["http://localhost:3000/logout"]
}

# --- Cognito User Pool ---

resource "aws_cognito_user_pool" "pool" {
  name = "unity-shared-services-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = true
    invite_message_template {
      email_message = "Welcome to Unity! Your username is {username} and your temporary password is {####}."
      email_subject = "Your Unity Temporary Credentials"
      sms_message   = "Welcome to Unity! Your username is {username} and your temporary password is {####}."
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }
}

# --- SSM Parameter for User Pool ID ---

resource "aws_ssm_parameter" "user_pool_id" {
  name        = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
  description = "SSM Parameter storing the Cognito User Pool ID for Unity Shared Services"
  type        = "String"
  value       = aws_cognito_user_pool.pool.id
}

# --- Cognito Hosted UI Domain ---

resource "aws_cognito_user_pool_domain" "main" {
  domain       = "unity-shared-services-test"
  user_pool_id = aws_cognito_user_pool.pool.id
}

# --- App Clients ---

# 1. unity-uds-distribution-user-pool-client (secret: true, default auth flows)
resource "aws_cognito_user_pool_client" "unity_uds_distribution" {
  name         = "unity-uds-distribution-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.unity_uds_distribution_callback_urls
  logout_urls                          = var.unity_uds_distribution_logout_urls
}

# 2. localhost-jupyterhub-user-pool-client (secret: true, default auth flows)
resource "aws_cognito_user_pool_client" "localhost_jupyterhub" {
  name         = "localhost-jupyterhub-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.localhost_jupyterhub_callback_urls
  logout_urls                          = var.localhost_jupyterhub_logout_urls
}

# 3. unity-app-to-app-client-user-pool-client (secret: true, no username/password auth)
resource "aws_cognito_user_pool_client" "unity_app_to_app" {
  name         = "unity-app-to-app-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.unity_app_to_app_callback_urls
  logout_urls                          = var.unity_app_to_app_logout_urls

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_CUSTOM_AUTH"
  ]
}

# 4. uads-jupyter-development-client-user-pool-client (secret: true, no username/password auth)
resource "aws_cognito_user_pool_client" "uads_jupyter_dev" {
  name         = "uads-jupyter-development-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.uads_jupyter_dev_callback_urls
  logout_urls                          = var.uads_jupyter_dev_logout_urls

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_CUSTOM_AUTH"
  ]
}

# 5. hysds-ui-client-user-pool-client (secret: false)
resource "aws_cognito_user_pool_client" "hysds_ui" {
  name         = "hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.hysds_ui_callback_urls
  logout_urls                          = var.hysds_ui_logout_urls
}

# 6. localhost-hysds-ui-client-user-pool-client (secret: false)
resource "aws_cognito_user_pool_client" "localhost_hysds_ui" {
  name         = "localhost-hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.localhost_hysds_ui_callback_urls
  logout_urls                          = var.localhost_hysds_ui_logout_urls
}

# --- Cognito User Groups ---

resource "aws_cognito_user_group" "unity_admin" {
  name         = "Unity_Admin"
  user_pool_id = aws_cognito_user_pool.pool.id
  description  = "Administrator group for Unity platform"
  precedence   = 1
}

resource "aws_cognito_user_group" "unity_viewer" {
  name         = "Unity_Viewer"
  user_pool_id = aws_cognito_user_pool.pool.id
  description  = "Viewer group for Unity platform"
  precedence   = 10
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_name" {
  type        = string
  description = "Application name used for naming and resource tagging"
  default     = "terraform"
}

variable "environment" {
  type        = string
  description = "Deployment environment name"
  default     = "testing"
}

variable "enable_tgw_attachment" {
  type        = bool
  description = "Optional flag to enable Transit Gateway attachment"
  default     = false
}

variable "transit_gateway_id" {
  type        = string
  description = "Transit Gateway ID to attach to, required if enable_tgw_attachment is true"
  default     = null
}

variable "enable_ipv6_egress" {
  type        = bool
  description = "Optional flag to enable IPv6 egress routing"
  default     = false
}

locals {
  name_prefix = "${var.app_name}-${var.environment}"
  common_tags = {
    App         = var.app_name
    Environment = var.environment
  }
  public_subnets = [
    { cidr = "10.0.10.0/24", az_index = 0 },
    { cidr = "10.0.20.0/24", az_index = 1 },
    { cidr = "10.0.30.0/24", az_index = 2 }
  ]
  private_subnets = [
    { cidr = "10.0.11.0/24", az_index = 0 },
    { cidr = "10.0.22.0/24", az_index = 1 },
    { cidr = "10.0.33.0/24", az_index = 2 }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_hostnames             = false
  enable_dns_support               = true
  assign_generated_ipv6_cidr_block = var.enable_ipv6_egress

  tags = merge(local.common_tags, {
    Name = "vpc-${local.name_prefix}"
  })
}

resource "aws_subnet" "public" {
  count                           = length(local.public_subnets)
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_subnets[count.index].cidr
  availability_zone               = data.aws_availability_zones.available.names[local.public_subnets[count.index].az_index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(local.common_tags, {
    Name = "subnet-${local.name_prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count                           = length(local.private_subnets)
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_subnets[count.index].cidr
  availability_zone               = data.aws_availability_zones.available.names[local.private_subnets[count.index].az_index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(local.common_tags, {
    Name = "subnet-${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "igw-${local.name_prefix}"
  })
}

resource "aws_egress_only_internet_gateway" "main" {
  count  = var.enable_ipv6_egress ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "eigw-${local.name_prefix}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "rt-${local.name_prefix}-public"
  })
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "eip-${local.name_prefix}-nat"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "nat-${local.name_prefix}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "rt-${local.name_prefix}-private"
  })
}

resource "aws_route" "private_ipv6_egress" {
  count                       = var.enable_ipv6_egress ? 1 : 0
  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count              = var.enable_tgw_attachment && var.transit_gateway_id != null ? 1 : 0
  transit_gateway_id = var.transit_gateway_id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "tgw-attachment-${local.name_prefix}"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "db-subnet-${local.name_prefix}"
  subnet_ids  = aws_subnet.private[*].id
  description = "Database subnet group spanning private subnets for ${var.app_name} in ${var.environment}"

  tags = merge(local.common_tags, {
    Name = "db-subnet-${local.name_prefix}"
  })
}

output "vpc_id" {
  description = "The ID of the created VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The IPv4 CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "vpc_default_security_group_id" {
  description = "The ID of the default security group for the VPC"
  value       = aws_vpc.main.default_security_group_id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "The ID of the NAT Gateway"
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "The Elastic IP address associated with the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

output "db_subnet_group_name" {
  description = "The name of the database subnet group"
  value       = aws_db_subnet_group.main.name
}

output "db_subnet_group_arn" {
  description = "The ARN of the database subnet group"
  value       = aws_db_subnet_group.main.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  repositories = toset([
    "gitops-apps",
    "gitops-platform",
    "gitops-addons"
  ])
  iam_user_name = "gitops-bridge-gitops"
  policy_name   = "gitops-bridge-gitops"
}

# -----------------------------------------------------------------------------
# CodeCommit Repositories
# -----------------------------------------------------------------------------
resource "aws_codecommit_repository" "gitops_repos" {
  for_each        = local.repositories
  repository_name = each.value
  description     = "GitOps repository for ${each.value}"
}

# -----------------------------------------------------------------------------
# TLS RSA Key Generation
# -----------------------------------------------------------------------------
resource "tls_private_key" "gitops_ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# -----------------------------------------------------------------------------
# IAM User and SSH Key Configuration
# -----------------------------------------------------------------------------
resource "aws_iam_user" "gitops_bridge" {
  name = local.iam_user_name
}

resource "aws_iam_user_ssh_key" "gitops_bridge_ssh_key" {
  username   = aws_iam_user.gitops_bridge.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops_ssh_key.public_key_openssh
}

# -----------------------------------------------------------------------------
# IAM Least-Privilege Policy for CodeCommit
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "codecommit_access" {
  statement {
    sid    = "CodeCommitRepoAccess"
    effect = "Allow"
    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush"
    ]
    resources = [
      for repo in aws_codecommit_repository.gitops_repos : repo.arn
    ]
  }
}

resource "aws_iam_policy" "gitops_bridge_policy" {
  name        = local.policy_name
  description = "IAM policy granting Git pull and push access to GitOps CodeCommit repositories"
  policy      = data.aws_iam_policy_document.codecommit_access.json
}

resource "aws_iam_user_policy_attachment" "gitops_bridge_attachment" {
  user       = aws_iam_user.gitops_bridge.name
  policy_arn = aws_iam_policy.gitops_bridge_policy.arn
}

# -----------------------------------------------------------------------------
# Secrets Manager Storage
# -----------------------------------------------------------------------------
resource "random_string" "secret_suffix" {
  length  = 5
  upper   = false
  special = false
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name                    = "codecommit-key-${random_string.secret_suffix.result}"
  description             = "SSH private key for gitops-bridge-gitops CodeCommit user"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "ssh_private_key_version" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.gitops_ssh_key.private_key_pem
}

# -----------------------------------------------------------------------------
# Local SSH Key and Config Files
# -----------------------------------------------------------------------------
resource "local_sensitive_file" "private_key_file" {
  content         = tls_private_key.gitops_ssh_key.private_key_pem
  filename        = pathexpand("~/.ssh/gitops_ssh.pem")
  file_permission = "0600"
}

resource "local_file" "ssh_config_file" {
  content = <<-EOT
Host git-codecommit.*.amazonaws.com
    User ${aws_iam_user_ssh_key.gitops_bridge_ssh_key.ssh_public_key_id}
    IdentityFile ~/.ssh/gitops_ssh.pem
  EOT
  filename        = pathexpand("~/.ssh/config")
  file_permission = "0600"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "public_key" {
  type        = string
  description = "Optional public SSH key content for the EC2 key pair. If not supplied, a valid key pair is automatically generated."
  default     = null
}

variable "extra_ebs_volumes" {
  type = map(object({
    device_name           = string
    size                  = number
    type                  = optional(string, "gp3")
    encrypted             = optional(bool, true)
    kms_key_id            = optional(string)
    delete_on_termination = optional(bool, false)
  }))
  description = "Optional extra EBS volumes to create and attach to the instance"
  default     = {}
}

variable "extra_network_interfaces" {
  type = map(object({
    device_index        = number
    subnet_id           = optional(string)
    private_ips         = optional(list(string))
    security_groups     = optional(list(string))
    description         = optional(string)
    allocate_elastic_ip = optional(bool, true)
  }))
  description = "Optional additional network interfaces to attach to the instance"
  default     = {}
}

locals {
  vpc_cidr      = "10.70.0.0/16"
  subnet_cidr   = "10.70.0.0/24"
  key_name      = "benchmark-d8bc612be4e0-key"
  instance_name = "benchmark-instance"
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_ami" "ubuntu_22_04" {
  most_recent = true
  owners      = ["099720109477"] # Canonical

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "tls_private_key" "benchmark" {
  algorithm = "ED25519"
}

resource "aws_kms_key" "ebs" {
  description             = "Dedicated KMS key for EBS encryption on benchmark instance"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEC2AndServiceRolesToUseKey"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AllowAttachmentPersistentResources"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "kms:GrantIsForAWSResource" = "true"
          }
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name = "benchmark-ebs-kms-key"
  }
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/benchmark-ebs-key"
  target_key_id = aws_kms_key.ebs.key_id
}

resource "aws_vpc" "benchmark" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_internet_gateway" "benchmark" {
  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-igw"
  }
}

resource "aws_subnet" "benchmark" {
  vpc_id                  = aws_vpc.benchmark.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-subnet"
  }
}

resource "aws_route_table" "benchmark" {
  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.benchmark.id
  }

  tags = {
    Name = "benchmark-route-table"
  }
}

resource "aws_route_table_association" "benchmark" {
  subnet_id      = aws_subnet.benchmark.id
  route_table_id = aws_route_table.benchmark.id
}

resource "aws_security_group" "benchmark" {
  name        = "benchmark-sg"
  description = "Dedicated security group allowing egress only to VPC CIDR with no ingress by default"
  vpc_id      = aws_vpc.benchmark.id

  egress {
    description = "Allow egress strictly to the VPC CIDR block"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "benchmark-sg"
  }
}

resource "aws_key_pair" "benchmark" {
  key_name   = local.key_name
  public_key = var.public_key != null ? var.public_key : tls_private_key.benchmark.public_key_openssh

  tags = {
    Name = local.key_name
  }
}

resource "aws_iam_role" "benchmark" {
  name = "benchmark-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "benchmark-instance-role"
  }
}

resource "aws_iam_instance_profile" "benchmark" {
  name = "benchmark-instance-profile"
  role = aws_iam_role.benchmark.name
}

resource "aws_instance" "benchmark" {
  ami                    = data.aws_ami.ubuntu_22_04.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.benchmark.id
  vpc_security_group_ids = [aws_security_group.benchmark.id]
  key_name               = aws_key_pair.benchmark.key_name
  iam_instance_profile   = aws_iam_instance_profile.benchmark.name
  monitoring             = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = 10
    volume_type           = "gp2"
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = true
  }

  tags = {
    Name = local.instance_name
  }
}

resource "aws_eip" "benchmark" {
  domain   = "vpc"
  instance = aws_instance.benchmark.id

  depends_on = [aws_internet_gateway.benchmark]

  tags = {
    Name = "benchmark-eip"
  }
}

resource "aws_cloudwatch_metric_alarm" "reboot_on_status_check_failed" {
  alarm_name          = "benchmark-instance-status-check-reboot"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 5
  metric_name         = "StatusCheckFailed_Instance"
  namespace           = "AWS/EC2"
  period              = 60
  statistic           = "Maximum"
  threshold           = 1
  alarm_description   = "Reboot instance benchmark-instance when StatusCheckFailed_Instance >= 1 for 5 consecutive periods"
  alarm_actions       = ["arn:aws:automate:${data.aws_region.current.name}:ec2:reboot"]

  dimensions = {
    InstanceId = aws_instance.benchmark.id
  }
}

resource "aws_ebs_volume" "extra" {
  for_each          = var.extra_ebs_volumes
  availability_zone = data.aws_availability_zones.available.names[0]
  size              = each.value.size
  type              = each.value.type
  encrypted         = each.value.encrypted
  kms_key_id        = each.value.kms_key_id != null ? each.value.kms_key_id : aws_kms_key.ebs.arn

  tags = {
    Name = "benchmark-extra-ebs-${each.key}"
  }
}

resource "aws_volume_attachment" "extra" {
  for_each    = var.extra_ebs_volumes
  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.extra[each.key].id
  instance_id = aws_instance.benchmark.id
}

resource "aws_network_interface" "extra" {
  for_each        = var.extra_network_interfaces
  subnet_id       = each.value.subnet_id != null ? each.value.subnet_id : aws_subnet.benchmark.id
  private_ips     = each.value.private_ips
  security_groups = each.value.security_groups != null ? each.value.security_groups : [aws_security_group.benchmark.id]
  description     = each.value.description

  attachment {
    instance     = aws_instance.benchmark.id
    device_index = each.value.device_index
  }

  tags = {
    Name = "benchmark-extra-nic-${each.key}"
  }
}

resource "aws_eip" "extra" {
  for_each = {
    for k, v in var.extra_network_interfaces : k => v
    if v.allocate_elastic_ip
  }

  domain = "vpc"

  depends_on = [aws_internet_gateway.benchmark]

  tags = {
    Name = "benchmark-extra-eip-${each.key}"
  }
}

resource "aws_eip_association" "extra" {
  for_each = {
    for k, v in var.extra_network_interfaces : k => v
    if v.allocate_elastic_ip
  }

  network_interface_id = aws_network_interface.extra[each.key].id
  allocation_id        = aws_eip.extra[each.key].id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-east-2"
}

provider "aws" {
  alias  = "replica1"
  region = "us-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  common_tags = {
    Env = "dev"
  }
}

# -----------------------------------------------------------------------------
# Import Blocks for Pre-created Resources from Previous Partial Apply
# -----------------------------------------------------------------------------

# KMS Aliases
import {
  to = aws_kms_alias.source1
  id = "alias/sourcekey1"
}

import {
  to = aws_kms_alias.source2
  id = "alias/sourcekey2"
}

import {
  to = aws_kms_alias.replica1
  id = "alias/replicakey1"
}

import {
  to = aws_kms_alias.replica2
  id = "alias/replicakey2"
}

# IAM Role
import {
  to = aws_iam_role.replication
  id = "s3-cross-region-replication-role"
}

# IAM Policy
import {
  to = aws_iam_policy.replication
  id = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:policy/s3-cross-region-replication-policy"
}

# Source 1 Buckets
import {
  to = aws_s3_bucket.source_log1a
  id = "log1a.veerum-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_s3_bucket.source_log1b
  id = "log1b.veerum-${data.aws_caller_identity.current.account_id}"
}

