# KMS Key Policy document
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

# -----------------------------------------------------------------------------
# KMS Keys & Aliases
# -----------------------------------------------------------------------------

# Source Region 1 KMS Key (us-east-1)
resource "aws_kms_key" "source1" {
  description             = "Customer managed key for source region 1 log buckets"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

# Source Region 2 KMS Key (us-east-2)
resource "aws_kms_key" "source2" {
  provider                = aws.source2
