# -----------------------------------------------------------------------------
# IAM Role and Policy for S3 Replication
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_assume_role" {
  statement {
    sid     = "S3ReplicationAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.s3_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.source_log1a.arn,
      aws_s3_bucket.source_log1b.arn,
      aws_s3_bucket.source_log2a.arn,
      aws_s3_bucket.source_log2b.arn
    ]
  }

  statement {
    sid    = "SourceBucketObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = [
      "${aws_s3_bucket.source_log1a.arn}/*",
      "${aws_s3_bucket.source_log1b.arn}/*",
      "${aws_s3_bucket.source_log2a.arn}/*",
      "${aws_s3_bucket.source_log2b.arn}/*"
    ]
  }

  statement {
    sid    = "DestinationBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersionTagging"
    ]
    resources = [
      "${aws_s3_bucket.replica1_log1a.arn}/*",
      "${aws_s3_bucket.replica1_log1b.arn}/*",
      "${aws_s3_bucket.replica1_log2a.arn}/*",
      "${aws_s3_bucket.replica1_log2b.arn}/*",
      "${aws_s3_bucket.replica2_log1a.arn}/*",
      "${aws_s3_bucket.replica2_log1b.arn}/*",
      "${aws_s3_bucket.replica2_log2a.arn}/*",
      "${aws_s3_bucket.replica2_log2b.arn}/*"
    ]
  }

  statement {
    sid    = "SourceKMSDecryption"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn
    ]
  }

  statement {
    sid    = "DestinationKMSEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey"
    ]
    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Allows S3 to perform cross-region replication and handle KMS encryption/decryption"
  policy      = data.aws_iam_policy_document.replication.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# -----------------------------------------------------------------------------
# S3 Replication Configurations
# -----------------------------------------------------------------------------

# Replication configuration for Source 1: log1a
resource "aws_s3_bucket_replication_configuration" "source_log1a" {
  bucket = aws_s3_bucket.source_log1a.id
  role   = aws_iam_role.replication.arn

  depends_on = [
    aws_s3_bucket_versioning.source_log1a,
    aws_iam_role_policy_attachment.replication
  ]

  rule {
    id       = "ReplicateToReplica1"
    priority = 1
    status   = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1_log1a.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id       = "ReplicateToReplica2"
    priority = 2
    status   = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2_log1a.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }
}

