# Replication configuration for Source 2: log2b
resource "aws_s3_bucket_replication_configuration" "source_log2b" {
  provider = aws.source2
  bucket   = aws_s3_bucket.source_log2b.id
  role     = aws_iam_role.replication.arn

  depends_on = [
