terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Providers
# -----------------------------------------------------------------------------
provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.export_replica_region
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  account_id     = data.aws_caller_identity.current.account_id
  region         = data.aws_region.current.name
  partition      = data.aws_partition.current.partition
  replica_region = var.export_replica_region

  common_tags = {
    Repository = var.repository_url
    ManagedBy  = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "repository_url" {
  type        = string
  description = "The repository URL to tag resources with."
  default     = "https://github.com/terraform-aws-modules/terraform-aws-guardduty"
}

variable "enable_findings_export" {
  type        = bool
  description = "Controls whether to create and configure findings export to an S3 bucket with cross-region replication and KMS encryption."
  default     = false
}

variable "export_replica_region" {
  type        = string
  description = "AWS region for the replicated GuardDuty findings S3 bucket."
  default     = "us-west-2"
}

variable "findings_filters" {
  type = map(object({
    description = optional(string)
    action      = string
    rank        = number
    criterion = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(number)
      greater_than_or_equal = optional(number)
      less_than             = optional(number)
      less_than_or_equal    = optional(number)
    }))
  }))
  description = "Map of findings filters to create."
  default     = {}
}

variable "ip_sets" {
  type = map(object({
    activate = bool
    format   = string
    location = string
  }))
  description = "Map of trusted IP sets to create."
  default     = {}
}

variable "threat_intel_sets" {
  type = map(object({
    activate = bool
    format   = string
    location = string
  }))
  description = "Map of Threat Intelligence sets to create."
  default     = {}
}

variable "enable_malware_protection_plan" {
  type        = bool
  description = "Controls whether to create a GuardDuty Malware Protection plan for an S3 bucket."
  default     = false
}

variable "malware_protection_plan_bucket_name" {
  type        = string
  description = "Name of the target S3 bucket to protect with the Malware Protection plan."
  default     = ""
}

variable "malware_protection_plan_object_prefixes" {
  type        = list(string)
  description = "Object prefixes to include in the Malware Protection plan scan."
  default     = []
}

# -----------------------------------------------------------------------------
# GuardDuty Detector
# -----------------------------------------------------------------------------
resource "aws_guardduty_detector" "primary" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# GuardDuty Detector Features
# -----------------------------------------------------------------------------
resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
}

# -----------------------------------------------------------------------------
# EBS Malware Scan Settings (Disable Snapshot Retention)
# -----------------------------------------------------------------------------
resource "terraform_data" "malware_scan_settings" {
  triggers_replace = [
    aws_guardduty_detector.primary.id
  ]

  provisioner "local-exec" {
    command     = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.primary.id} --ebs-snapshot-preservation NO_RETENTION --region ${local.region}"
    interpreter = ["/bin/sh", "-c"]
  }

  depends_on = [
    aws_guardduty_detector_feature.ebs_malware_protection
  ]
}

# -----------------------------------------------------------------------------
# GuardDuty Findings Filters (Optional)
# -----------------------------------------------------------------------------
resource "aws_guardduty_filter" "findings_filter" {
  for_each = var.findings_filters

  name        = each.key
  detector_id = aws_guardduty_detector.primary.id
  description = each.value.description
  action      = each.value.action
  rank        = each.value.rank

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criterion
      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# GuardDuty Trusted IP Sets (Optional)
# -----------------------------------------------------------------------------
resource "aws_guardduty_ipset" "trusted_ip_set" {
  for_each = var.ip_sets

  name        = each.key
  detector_id = aws_guardduty_detector.primary.id
  activate    = each.value.activate
  format      = each.value.format
  location    = each.value.location

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# GuardDuty Threat Intelligence Sets (Optional)
# -----------------------------------------------------------------------------
resource "aws_guardduty_threatintelset" "threat_intel_set" {
  for_each = var.threat_intel_sets

  name        = each.key
  detector_id = aws_guardduty_detector.primary.id
  activate    = each.value.activate
  format      = each.value.format
  location    = each.value.location

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# GuardDuty Malware Protection Plan for S3 (Optional)
# -----------------------------------------------------------------------------
resource "aws_iam_role" "guardduty_malware_protection" {
  count = var.enable_malware_protection_plan ? 1 : 0

  name_prefix = "guardduty-malware-protection-"
  description = "IAM role assumed by GuardDuty Malware Protection plan for S3"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "malware-protection-plan.guardduty.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "guardduty_malware_protection" {
  count = var.enable_malware_protection_plan ? 1 : 0

  name_prefix = "guardduty-malware-protection-policy-"
  role        = aws_iam_role.guardduty_malware_protection[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject*",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:PutObjectTagging"
        ]
        Resource = [
          "arn:${local.partition}:s3:::${var.malware_protection_plan_bucket_name}",
          "arn:${local.partition}:s3:::${var.malware_protection_plan_bucket_name}/*"
        ]
      }
    ]
  })
}

resource "aws_guardduty_malware_protection_plan" "s3_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  role = aws_iam_role.guardduty_malware_protection[0].arn

  protected_resource {
    s3_bucket {
      bucket_name     = var.malware_protection_plan_bucket_name
      object_prefixes = length(var.malware_protection_plan_object_prefixes) > 0 ? var.malware_protection_plan_object_prefixes : null
    }
  }

  actions {
    tagging {
      status = "ENABLED"
    }
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Findings Export: KMS Key (Primary Region)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "guardduty_export_primary" {
  count = var.enable_findings_export ? 1 : 0

  description             = "KMS key for encrypting GuardDuty findings in primary S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRootManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowGuardDutyUsage"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Encrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "guardduty_export_primary" {
  count = var.enable_findings_export ? 1 : 0

  name          = "alias/guardduty-findings-primary"
  target_key_id = aws_kms_key.guardduty_export_primary[0].key_id
}

# -----------------------------------------------------------------------------
# Findings Export: S3 Access Logging Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket_prefix = "guardduty-findings-access-logs-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket                  = aws_s3_bucket.access_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Findings Export: Replication Target S3 Bucket (Secondary Region)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  count    = var.enable_findings_export ? 1 : 0

  bucket_prefix = "guardduty-findings-replica-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    TargetRegion = local.replica_region
  })
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  count    = var.enable_findings_export ? 1 : 0

  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  count    = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  count    = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# -----------------------------------------------------------------------------
# Findings Export: S3 Replication IAM Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  count = var.enable_findings_export ? 1 : 0

  name_prefix = "guardduty-s3-replication-"
  description = "IAM role for replicating GuardDuty findings across S3 buckets"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_findings_export ? 1 : 0

  name_prefix = "guardduty-s3-replication-policy-"
  role        = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary[0].arn
        ]
      },
      {
        Sid    = "SourceBucketObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "${aws_s3_bucket.primary[0].arn}/*"
        ]
      },
      {
        Sid    = "DestinationBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          "${aws_s3_bucket.replica[0].arn}/*"
        ]
      },
      {
        Sid    = "SourceBucketKMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          aws_kms_key.guardduty_export_primary[0].arn
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Findings Export: Primary S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "primary" {
  count = var.enable_findings_export ? 1 : 0

  bucket_prefix = "guardduty-findings-primary-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "primary" {
  count = var.enable_findings_export ? 1 : 0

  bucket                  = aws_s3_bucket.primary[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "primary" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "primary" {
  count = var.enable_findings_export ? 1 : 0

  bucket        = aws_s3_bucket.primary[0].id
  target_bucket = aws_s3_bucket.access_logs[0].id
  target_prefix = "primary-findings-logs/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.guardduty_export_primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "ReplicateGuardDutyFindings"
    status = "Enabled"

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica
  ]
}

resource "aws_s3_bucket_policy" "primary_findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGuardDutyGetBucketLocation"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action   = "s3:GetBucketLocation"
        Resource = aws_s3_bucket.primary[0].arn
      },
      {
        Sid    = "AllowGuardDutyPutObject"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.primary[0].arn}/*"
      },
      {
        Sid    = "DenyUnencryptedObjectUploads"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.primary[0].arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid    = "DenyIncorrectKmsKey"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.primary[0].arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.guardduty_export_primary[0].arn
          }
        }
      },
      {
        Sid    = "DenyNonSecureTransport"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.primary[0].arn,
          "${aws_s3_bucket.primary[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# GuardDuty Publishing Destination (Export to S3)
# -----------------------------------------------------------------------------
resource "aws_guardduty_publishing_destination" "s3_destination" {
  count = var.enable_findings_export ? 1 : 0

  detector_id     = aws_guardduty_detector.primary.id
  destination_arn = aws_s3_bucket.primary[0].arn
  kms_key_arn     = aws_kms_key.guardduty_export_primary[0].arn

  destination_type = "S3"

  depends_on = [
    aws_s3_bucket_policy.primary_findings
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "guardduty_detector_id" {
  description = "The ID of the GuardDuty detector."
  value       = aws_guardduty_detector.primary.id
}

output "guardduty_detector_arn" {
  description = "The ARN of the GuardDuty detector."
  value       = aws_guardduty_detector.primary.arn
}

output "primary_export_bucket_arn" {
  description = "The ARN of the primary S3 bucket for GuardDuty findings export, if enabled."
  value       = try(aws_s3_bucket.primary[0].arn, null)
}

output "replica_export_bucket_arn" {
  description = "The ARN of the replica S3 bucket for GuardDuty findings export, if enabled."
  value       = try(aws_s3_bucket.replica[0].arn, null)
}

output "export_kms_key_arn" {
  description = "The ARN of the KMS key used for encrypting GuardDuty findings in the primary bucket, if enabled."
  value       = try(aws_kms_key.guardduty_export_primary[0].arn, null)
}

output "malware_protection_plan_arn" {
  description = "The ARN of the GuardDuty Malware Protection plan for S3, if enabled."
  value       = try(aws_guardduty_malware_protection_plan.s3_plan[0].arn, null)
}
